export const CARDS = [
  // ============ PUB QUIZ (existing 15 + new 60 = 75) ============
  { id: 'pq1', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "This country has won Eurovision more times than any other.", fact: "Ireland has won the Eurovision Song Contest 7 times — 1970, 1980, 1987, 1992, 1993, 1994, and 1996. Sweden is tied with 7 wins as of 2023. Ireland's three consecutive wins (1992–94) remain unmatched.", tip: "🧠 Ireland & Sweden lead Eurovision with 7 wins each. Ireland's hat-trick (1992–94) is the all-time record." },
  { id: 'pq2', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The world's best-selling music artist of all time is not The Beatles.", fact: "Michael Jackson's Thriller (1982) is the best-selling album of all time at 66–70 million copies. The Beatles hold the record for best-selling band (~600 million records). Elvis Presley holds the record for most singles sold.", tip: "🧠 Best-selling album: Thriller. Best-selling band: Beatles. Most singles: Elvis. Three different records." },
  { id: 'pq3', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Mount Everest is not the closest point on Earth to outer space.", fact: "Mount Chimborazo in Ecuador is the point on Earth's surface furthest from Earth's centre — and therefore closest to space — because Earth bulges at the equator. Everest is the highest above sea level (8,849m) but Chimborazo wins by ~2km of Earth-radius advantage.", tip: "🧠 Everest = highest above sea level. Chimborazo = furthest from Earth's centre. Two different records." },
  { id: 'pq4', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "This is the only country in the world with a non-rectangular flag.", fact: "Nepal is the only country with a non-quadrilateral flag. It's a double-pennant shape — two stacked triangles — making it unique among all 195 national flags. All other countries use rectangles or squares.", tip: "🧠 Nepal = only non-rectangular flag. The shape is a double-pennant. Perfect pub quiz gotcha." },
  { id: 'pq5', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The Great Wall of China is not visible from space — this is one of history's most persistent myths.", fact: "The Great Wall is too narrow (5–8 metres wide) to be seen from orbit with the naked eye. Chinese astronaut Yang Liwei confirmed this in 2003. City lights and highways are actually visible from low orbit.", tip: "🧠 Great Wall from space = myth. It's wide enough to walk on but invisible at orbital distance." },
  { id: 'pq6', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "This tiny creature kills more humans every year than every large predator combined.", fact: "The mosquito kills approximately 725,000 people per year — the world's deadliest animal to humans. It transmits malaria, dengue, yellow fever, and Zika. Sharks kill fewer than 10 people per year.", tip: "🧠 Deadliest animal: mosquito (725,000/yr). Humans second (~475,000). Sharks: fewer than 10." },
  { id: 'pq7', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Shakespeare invented over 1,700 words you still use every single day.", fact: "William Shakespeare coined or first recorded over 1,700 English words including 'bedroom', 'lonely', 'generous', 'swagger', 'uncomfortable', 'luggage', and 'eyeball'. He wrote 37 plays and 154 sonnets.", tip: "🧠 Shakespeare invented: bedroom, lonely, generous, swagger, eyeball, luggage. Next time you swagger, thank him." },
  { id: 'pq8', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The Eiffel Tower is measurably taller in summer than in winter.", fact: "The Eiffel Tower grows up to 15cm taller in summer due to thermal expansion. Built in 1889 by Gustave Eiffel for the Paris World's Fair, it was originally intended to be demolished after 20 years. It was saved because it made a useful radio antenna.", tip: "🧠 Eiffel Tower: built 1889, grows 15cm in summer, was meant to be torn down. Radio saved it." },
  { id: 'pq9', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Cleopatra lived closer in time to the Moon landing than to the construction of the Great Pyramid.", fact: "Cleopatra VII ruled around 50 BC. The Great Pyramid was built around 2560 BC — 2,500 years before her. The Moon landing was 1969 AD — only ~2,000 years after Cleopatra. The pyramids are ancient even by ancient standards.", tip: "🧠 Pyramid → Cleopatra: 2,500 years. Cleopatra → Moon landing: ~2,000 years." },
  { id: 'pq10', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A day on Venus is longer than a year on Venus.", fact: "Venus rotates so slowly that one Venusian day (243 Earth days) is longer than its year (225 Earth days). Venus also rotates backwards — the Sun rises in the west and sets in the east. It's the hottest planet despite Mercury being closer to the Sun.", tip: "🧠 Venus: day longer than year, Sun rises in the west, hottest planet. Three facts in one planet." },
  { id: 'pq11', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The shortest war in history lasted less time than a football match.", fact: "The Anglo-Zanzibar War of 27 August 1896 lasted between 38 and 45 minutes — the shortest recorded war in history. Britain shelled the Sultan of Zanzibar's palace and won in under an hour. The Hundred Years' War actually lasted 116 years.", tip: "🧠 Shortest war: Anglo-Zanzibar, 1896, ~40 minutes. Longest: Hundred Years' War (116 years)." },
  { id: 'pq12', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Honey found in Egyptian tombs 3,000 years old is still perfectly edible.", fact: "Honey never spoils when sealed and kept dry. Its low moisture, acidic pH, and natural hydrogen peroxide make it inhospitable to bacteria. Other foods with indefinite shelf life include salt, pure vanilla extract, white rice, and hard liquor.", tip: "🧠 Honey = infinite shelf life. Also: salt, white rice, hard liquor. All last forever if stored properly." },
  { id: 'pq13', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Russia spans 11 time zones — the most of any country on Earth.", fact: "Russia covers 11 time zones and ~17.1 million km², making it the world's largest country. When it's 6am in Kaliningrad, it's already 5pm in Kamchatka. Canada is second largest but spans only 6 time zones.", tip: "🧠 Russia: largest country, 11 time zones. Canada: second largest, 6 time zones." },
  { id: 'pq14', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The inventor of the telephone never called his wife or his mother — both were deaf.", fact: "Alexander Graham Bell patented the telephone in 1876. His mother and wife Mabel were both deaf, which drove his obsession with sound and communication. Bell considered the telephone an intrusion and refused to have one in his personal study.", tip: "🧠 Bell = telephone, 1876. Deaf family motivated him. Ironically disliked his own invention." },
  { id: 'pq15', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "This is the world's oldest airline, still flying today under its original name.", fact: "KLM Royal Dutch Airlines, founded in October 1919, is the world's oldest airline still operating under its original name. Qantas (Australia, 1920) is the second oldest.", tip: "🧠 Oldest airline: KLM, 1919, Netherlands. Second: Qantas, 1920, Australia." },
  { id: 'pq16', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Bananas are botanically classified as berries — but strawberries are not.", fact: "Botanically, a berry is a fruit produced from a single flower's ovary. Bananas, grapes, tomatoes and watermelons all qualify. Strawberries and raspberries are 'aggregate fruits' — formed from multiple ovaries, so they don't make the cut.", tip: "🧠 Bananas = berries. Strawberries = not berries. Botany doesn't care what you call things." },
  { id: 'pq17', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Australia is wider than the Moon.", fact: "Australia is approximately 4,000 km wide east to west. The Moon's diameter is about 3,474 km. So yes — Australia is wider than the Moon, though obviously much less massive.", tip: "🧠 Australia: ~4,000 km wide. Moon: 3,474 km diameter. Australia wins by ~500 km." },
  { id: 'pq18', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Octopuses have three hearts and blue blood.", fact: "Octopuses have three hearts: two pump blood through the gills, one pumps it through the body. Their blood is blue because it uses copper-based hemocyanin instead of iron-based hemoglobin to carry oxygen — more efficient in cold, low-oxygen water.", tip: "🧠 Octopus: 3 hearts, blue blood (copper, not iron), 9 brains (one central + one per arm)." },
  { id: 'pq19', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The dot over a lowercase 'i' or 'j' has an actual name.", fact: "It's called a 'tittle'. The word comes from the Latin 'titulus' meaning 'inscription' or 'label'. The dot was added in medieval manuscripts to distinguish 'i' from neighbouring vertical strokes.", tip: "🧠 The dot on 'i' or 'j' = tittle. Latin titulus. Pub quiz gold." },
  { id: 'pq20', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Wombats produce cube-shaped poo — and we've only just figured out why.", fact: "Wombats are the only animals on Earth that produce cube-shaped faeces. The shape is created by the elasticity of their intestinal walls, which contract in patterns that form flat sides. Cubes don't roll, helping wombats mark territory effectively.", tip: "🧠 Wombat poo = cubes. Intestinal walls shape it. Cubes don't roll = better territory markers." },
  { id: 'pq21', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "There are more possible chess games than atoms in the observable universe.", fact: "The Shannon number estimates ~10¹²⁰ possible chess games. The observable universe contains ~10⁸⁰ atoms. Chess has 40 orders of magnitude more possible games than there are atoms in everything we can see.", tip: "🧠 Chess games: 10¹²⁰. Atoms in universe: 10⁸⁰. Chess wins by 40 zeros." },
  { id: 'pq22', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Pineapples take about two years to grow a single fruit.", fact: "A pineapple plant takes 18–24 months to produce its first fruit. After harvesting, it can produce another one — but it takes another year. Each plant produces only one pineapple at a time.", tip: "🧠 One pineapple = ~2 years of growing. One plant = one fruit at a time. That's why they're not cheap." },
  { id: 'pq23', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The Wright Brothers' first flight could have fit inside a Boeing 747.", fact: "The Wright Brothers' first powered flight on 17 December 1903 lasted 12 seconds and covered 37 metres. A Boeing 747's wingspan alone is 68 metres — so their entire first flight would have fit inside the wingspan of a modern jumbo jet.", tip: "🧠 First flight: 37m. 747 wingspan: 68m. The whole first flight fits inside a wing." },
  { id: 'pq24', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Iceland has no McDonald's — and hasn't since 2009.", fact: "McDonald's pulled out of Iceland in 2009 after the financial crisis made imports too expensive. The last burger ever sold in Iceland is on display in a museum — and it has barely decomposed in over 15 years.", tip: "🧠 No McDonald's in Iceland since 2009. The last burger is in a museum, still looking fresh." },
  { id: 'pq25', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The Olympic flag's five rings represent something people often guess wrong.", fact: "The five Olympic rings represent the five inhabited continents (the Americas count as one), not specific countries. The colours — blue, yellow, black, green, red on white — were chosen because every national flag in 1913 contained at least one of them.", tip: "🧠 5 rings = 5 continents (Americas counts as one). Colours = at least one in every flag in 1913." },
  { id: 'pq26', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The unicorn is Scotland's national animal.", fact: "Scotland's national animal is the unicorn — chosen because in Celtic mythology unicorns symbolised purity, power, and innocence. It has been a Scottish heraldic symbol since the 12th century. Scotland is fond of unusual choices.", tip: "🧠 Scotland's national animal = unicorn. Mythical, but officially official." },
  { id: 'pq27', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "There's a country with no rivers at all.", fact: "Saudi Arabia has no permanent rivers — the only large country in this position. It relies on desalination for most fresh water. Bahrain, Kuwait, Qatar, the UAE, Oman, Yemen and the Vatican City are also river-free.", tip: "🧠 No rivers: Saudi Arabia (largest), plus most Gulf states and Vatican City." },
  { id: 'pq28', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The Hawaiian alphabet has only 13 letters.", fact: "The Hawaiian alphabet contains 13 letters: 5 vowels (a, e, i, o, u) and 8 consonants (h, k, l, m, n, p, w, plus the glottal stop ʻokina). Compare to English with 26.", tip: "🧠 Hawaiian: 13 letters. Words like 'Honolulu' and 'aloha' use the limited consonant set." },
  { id: 'pq29', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Cows have best friends — and stress out when separated.", fact: "Studies have shown cows form close social bonds with specific other cows, behave more calmly when paired with their preferred companion, and show physiological stress markers when separated from them.", tip: "🧠 Cows have best friends. Separating them measurably stresses them out. Heart rates rise." },
  { id: 'pq30', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Africa is the only continent in all four hemispheres.", fact: "Africa straddles the equator (north + south hemispheres) and the Prime Meridian (east + west hemispheres) — making it the only continent in all four hemispheres. Most maps don't make this obvious.", tip: "🧠 Africa = all 4 hemispheres. Equator + Prime Meridian both cross it." },
  { id: 'pq31', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The Statue of Liberty was originally meant to be brown.", fact: "The Statue of Liberty is made of copper and was originally a shiny reddish-brown when unveiled in 1886. It oxidised over decades, turning green by 1920. The green coating (patina) actually protects the copper from further corrosion.", tip: "🧠 Liberty: born brown copper, turned green by 1920. The patina protects the metal underneath." },
  { id: 'pq32', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "There's only one letter that doesn't appear in any U.S. state name.", fact: "The letter Q is the only one that doesn't appear in the name of any U.S. state. Every other letter shows up at least once across the 50 names. Pub quiz favourite.", tip: "🧠 Letter missing from all 50 US state names: Q." },
  { id: 'pq33', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Sharks existed before trees — by about 50 million years.", fact: "Sharks evolved around 450 million years ago. Trees didn't appear until about 390 million years ago. Sharks also predate Saturn's rings, the North Star, and Mount Everest.", tip: "🧠 Sharks: 450M years old. Trees: 390M. Sharks beat trees by 50 million years." },
  { id: 'pq34', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "France has been at war on more days of recorded history than any other country.", fact: "Studies of military history rank France as having fought in more wars than any other modern state — over 180 major conflicts. The 'cheese-eating surrender monkeys' stereotype is wildly inaccurate historically.", tip: "🧠 France = most-fought country in history. Stereotype = wrong. Napoleon alone covered a lot." },
  { id: 'pq35', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The world's largest desert is not in Africa.", fact: "Antarctica is the largest desert on Earth at ~14 million km². A desert is defined by precipitation, not temperature — Antarctica gets less than 200mm/year. The Sahara is the largest hot desert at ~9 million km².", tip: "🧠 Largest desert: Antarctica (cold). Largest hot desert: Sahara. Deserts are defined by rain, not heat." },
  { id: 'pq36', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "There are more trees on Earth than stars in the Milky Way.", fact: "Earth has approximately 3 trillion trees. The Milky Way contains an estimated 100–400 billion stars. Earth's tree count exceeds the high estimate of Milky Way stars by roughly 7-fold.", tip: "🧠 Trees on Earth: ~3 trillion. Milky Way stars: ~100–400 billion. Trees win." },
  { id: 'pq37', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The 'real' Mona Lisa was kept in a French king's bathroom.", fact: "Leonardo da Vinci sold the Mona Lisa to King Francis I of France around 1518. It was hung in the king's private bathroom at Fontainebleau. It later moved to Versailles, then Napoleon's bedroom, before settling in the Louvre after the French Revolution.", tip: "🧠 Mona Lisa was once a bathroom decoration for a French king. The Louvre came much later." },
  { id: 'pq38', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Polar bears have black skin under all that white fur.", fact: "Polar bear skin is black — it absorbs heat better. Their fur is actually colourless and translucent; it scatters light to look white. Underneath: black skin, transparent hairs, brilliant camouflage.", tip: "🧠 Polar bears: black skin, see-through fur. The white look is just light scattering." },
  { id: 'pq39', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The longest place name in the world has 85 letters.", fact: "Taumatawhakatangihangakoauauotamateaturipukakapikimaungahoronukupokaiwhenuakitanatahu — a hill in New Zealand — has 85 letters. It's a Maori name meaning 'the place where Tamatea climbed and played his flute to his loved one'.", tip: "🧠 Longest official place name: 85 letters, New Zealand hill. Pronouncing it = a sport in itself." },
  { id: 'pq40', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "There's a town in Norway where the Sun doesn't rise for two months.", fact: "Tromsø, Norway, sits inside the Arctic Circle. From late November to mid-January, the Sun doesn't rise above the horizon — polar night. In summer it doesn't set for weeks — the midnight Sun.", tip: "🧠 Above the Arctic Circle: months of darkness in winter, months of daylight in summer." },
  { id: 'pq41', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Vatican City has more popes per square kilometre than any country has of anything.", fact: "Vatican City covers 0.49 km² and is home to one Pope. That's a population density of 2 popes per km² — the highest concentration of any head of state on Earth, by an absurd margin.", tip: "🧠 Vatican: smallest country (0.49 km²), one Pope. Most pope-dense nation on the planet." },
  { id: 'pq42', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Bubble wrap was originally invented to be wallpaper.", fact: "In 1957, engineers Alfred Fielding and Marc Chavannes tried to create a textured plastic wallpaper. It flopped. They then pitched it as greenhouse insulation — also a flop. Finally IBM used it to ship the new IBM 1401 computer in 1960. Bubble wrap was born.", tip: "🧠 Bubble wrap: failed wallpaper → failed insulation → packaging hit. Third time lucky." },
  { id: 'pq43', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Mr Potato Head was the first toy ever advertised on television.", fact: "Mr Potato Head debuted in 1952 and became the first toy advertised directly to children on TV (rather than to parents). The campaign tripled sales overnight and changed toy marketing forever.", tip: "🧠 First toy advertised on TV directly to kids: Mr Potato Head (1952)." },
  { id: 'pq44', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The Sun is whiter than you think — atmosphere is the only reason it looks yellow.", fact: "The Sun emits all visible wavelengths roughly equally — making it actually white. Earth's atmosphere scatters blue light more than red, so what reaches our eyes is biased toward yellow/orange. Astronauts in space see a white Sun.", tip: "🧠 Real Sun colour: white. Yellow is what's left after the atmosphere scatters out the blue." },
  { id: 'pq45', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The Library of Congress has so many books, the shelves stretch over 1,300 km.", fact: "The Library of Congress (US) holds ~170 million items on shelves stretching ~1,349 km — longer than the distance from London to Edinburgh and back. It receives ~12,000 new items per day.", tip: "🧠 LoC: 170M items, ~1,350 km of shelves, 12,000 new items every day." },
  { id: 'pq46', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Bees have to visit about 2 million flowers to make a single pound of honey.", fact: "To produce one pound (~450g) of honey, bees visit roughly 2 million flowers and fly about 90,000 km — more than twice around the Earth. A single worker bee makes about 1/12 of a teaspoon of honey in her entire life.", tip: "🧠 1 lb honey = 2M flowers + 90,000 km flown. One bee's lifetime output = 1/12 tsp." },
  { id: 'pq47', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "There's a country where the Coca-Cola formula is rumoured to be different.", fact: "In Mexico, Coca-Cola is sweetened with cane sugar instead of high-fructose corn syrup used in the US. Many drinkers claim 'Mexican Coke' tastes noticeably better. Glass bottles also help preserve carbonation and flavour.", tip: "🧠 Mexican Coke = cane sugar. US Coke = corn syrup. Glass bottle, cleaner taste." },
  { id: 'pq48', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The longest English word without a vowel is also one of the shortest words.", fact: "'Rhythms' (7 letters) is the longest commonly used English word with no traditional vowels (a, e, i, o, u). The 'y' here functions as a vowel substitute. 'Crwth' (5 letters, a Welsh stringed instrument) is also vowel-free.", tip: "🧠 Longest no-vowel word in common English: 'rhythms'. The 'y' is doing all the work." },
  { id: 'pq49', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Saturn would float in water — if you had a bathtub big enough.", fact: "Saturn's average density is 0.687 g/cm³ — less than water's 1.0 g/cm³. So in theory, Saturn would float. Of course you'd need a tub with a diameter of 120,000 km — and the planet would shed a Moon-sized chunk by tidal forces.", tip: "🧠 Saturn: less dense than water. Theoretically floats. Practically: where do you find that bathtub?" },
  { id: 'pq50', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Croatia gave the world the necktie.", fact: "The modern necktie evolved from neck cloths worn by Croatian soldiers in 17th-century French service. King Louis XIV admired the look. The French word 'cravate' comes from 'Croate' (Croatian). Croatia celebrates Cravat Day on 18 October.", tip: "🧠 Necktie origin: Croatian soldiers in France. 'Cravate' = 'Croate'. Cravat Day: Oct 18." },
  { id: 'pq51', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The capital of Australia was chosen as a compromise between two rivals.", fact: "Sydney and Melbourne both wanted to be Australia's capital. Neither would accept the other, so in 1908 they agreed to build a new city, Canberra, halfway between them. It officially became the capital in 1927.", tip: "🧠 Canberra = compromise capital. Sydney vs Melbourne couldn't agree, so neither won." },
  { id: 'pq52', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Shakespeare and Cervantes died on the same day — but not the same date.", fact: "Both William Shakespeare and Miguel de Cervantes (author of Don Quixote) died on 23 April 1616. But England used the Julian calendar and Spain the Gregorian — so the actual days were 10 days apart. Same date, different days.", tip: "🧠 Shakespeare & Cervantes: same death date, different actual days. Calendar reform was patchy." },
  { id: 'pq53', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Hot water can freeze faster than cold water — a phenomenon named after a schoolboy.", fact: "The Mpemba effect: under certain conditions, hot water freezes faster than cold water. Named after Tanzanian student Erasto Mpemba in the 1960s, it's been observed for centuries (Aristotle noted it) but is still not fully explained.", tip: "🧠 Mpemba effect: hot water can freeze faster. Aristotle saw it. Schoolboy Mpemba got the credit." },
  { id: 'pq54', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "There's a country whose name means 'Land of Silver'.", fact: "Argentina takes its name from the Latin 'argentum' meaning silver. Early European explorers believed (incorrectly) the region was rich in silver. The Río de la Plata literally means 'River of Silver'.", tip: "🧠 Argentina = 'land of silver' in Latin. The silver was a colonial myth, the name stuck." },
  { id: 'pq55', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Penguins propose to mates with a pebble.", fact: "Male Gentoo and Adélie penguins search beaches for the perfect smooth pebble, then present it to a desired female. If she accepts, they place it in their nest together — a courtship ritual that pairs many penguins for life.", tip: "🧠 Penguin proposal = perfect pebble. Accept = mate for life. Romance in the Antarctic." },
  { id: 'pq56', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Albert Einstein was offered the presidency of Israel — and turned it down.", fact: "In 1952, Israel's first president Chaim Weizmann died. Israel offered the presidency to Einstein, the world's most famous Jew. He politely declined, saying he lacked the natural aptitude and experience to deal with people.", tip: "🧠 Einstein was offered the Israeli presidency in 1952. He said no thanks." },
  { id: 'pq57', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "A 'jiffy' is an actual scientific unit of time.", fact: "In physics, a jiffy is the time light takes to travel one fermi (a unit roughly the size of a proton) — about 3 × 10⁻²⁴ seconds. In computing, it usually means a tick of the system clock (1/100 second).", tip: "🧠 Physics jiffy: 3×10⁻²⁴ seconds. Computer jiffy: 1/100 second. The casual jiffy: anyone's guess." },
  { id: 'pq58', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "There's only one country whose name begins with 'O'.", fact: "Oman is the only country whose English name starts with 'O'. It's located on the southeastern coast of the Arabian Peninsula. Historic, oil-rich, and frequently overlooked in geography quizzes.", tip: "🧠 Only country starting with 'O': Oman." },
  { id: 'pq59', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The Earth has more than one Moon — kind of.", fact: "Earth's only permanent natural satellite is the Moon. But Earth occasionally captures small near-Earth asteroids — 'mini-moons' — that orbit briefly before drifting away. Examples: 2006 RH120 and 2020 CD3.", tip: "🧠 One real Moon. Occasional 'mini-moons' get caught in orbit for a few months at a time." },
  { id: 'pq60', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Antarctica is the only continent without reptiles or snakes.", fact: "Antarctica is too cold for reptiles or snakes — they're cold-blooded and can't survive its sub-zero climate. The largest land animal native to Antarctica is the wingless midge, just 6mm long.", tip: "🧠 Antarctica: zero snakes, zero reptiles. Largest native land animal: a 6mm midge." },
  { id: 'pq61', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Greenland sharks can live for over 400 years.", fact: "The Greenland shark is the longest-living vertebrate on Earth. Scientists have estimated lifespans of 250–500 years using eye lens dating. They reach sexual maturity at around 150 years old. Some living today were swimming when Galileo was alive.", tip: "🧠 Greenland sharks: 400+ years. Reproduce at 150. Some alive today predate the Industrial Revolution." },
  { id: 'pq62', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The first product Sony ever made was a rice cooker.", fact: "Sony was founded in 1946 in war-ravaged Tokyo. Their first consumer product was an electric rice cooker — which mostly burned the rice. They pivoted to electronics, eventually launching the iconic transistor radio in 1955.", tip: "🧠 Sony's first product: a rice cooker. It didn't work well. They moved on." },
  { id: 'pq63', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Norway once knighted a penguin.", fact: "King Penguin Sir Nils Olav III is a real, knighted penguin in Edinburgh Zoo. He serves as Colonel-in-Chief of the Norwegian King's Guard. Each promotion comes with a formal ceremony attended by hundreds of soldiers. He was knighted in 2008.", tip: "🧠 Sir Nils Olav: knighted penguin, Norwegian King's Guard, Edinburgh Zoo. Fully ceremonial." },
  { id: 'pq64', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "There's a country with no official capital city.", fact: "Nauru, the world's third-smallest country, has no official capital. The government offices are in Yaren District, often listed as the de facto capital — but it has no legal status as one.", tip: "🧠 Nauru: no official capital. Yaren is unofficial. Smallest republic in the world." },
  { id: 'pq65', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The microwave was invented by accident — by a chocolate bar in someone's pocket.", fact: "Percy Spencer was working with radar magnetrons at Raytheon in 1945 when a chocolate bar in his pocket melted. He realised microwaves cooked food and patented the microwave oven. The first commercial unit (1947) was 1.8m tall and weighed 340kg.", tip: "🧠 Microwave invented by accident, 1945, melted chocolate bar in pocket. First model: huge." },
  { id: 'pq66', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The fastest land animal can't sustain its top speed for more than 30 seconds.", fact: "The cheetah can hit ~100 km/h, but only for 20–30 seconds before overheating. Their bodies generate heat faster than they can dissipate it. After a sprint they need 30+ minutes to recover before they can run again.", tip: "🧠 Cheetah: 100 km/h, but only ~30 seconds. After: 30 min of panting recovery." },
  { id: 'pq67', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Coca-Cola once briefly contained actual cocaine.", fact: "From 1886 to 1903, Coca-Cola contained trace amounts of cocaine derived from coca leaves. The company switched to 'spent' coca leaves (with cocaine extracted) in 1903 due to growing concerns. Coca leaf extract is still used today — without the cocaine.", tip: "🧠 Coca-Cola had real cocaine 1886–1903. The 'coca' part is still real coca leaf — minus the active drug." },
  { id: 'pq68', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "There are more public libraries in the US than McDonald's restaurants.", fact: "The US has approximately 17,000 public libraries (including branches) and around 13,500 McDonald's locations. So when you're in America, you're statistically closer to a library than to a Big Mac.", tip: "🧠 US public libraries: 17,000. McDonald's: 13,500. Libraries win." },
  { id: 'pq69', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "There's a Buddhist temple in Thailand built entirely from beer bottles.", fact: "Wat Pa Maha Chedi Kaew (Temple of a Million Bottles) in Sisaket, Thailand, is built from over 1.5 million Heineken and Chang beer bottles. Started in 1984 to clean up litter, monks expanded the project for decades.", tip: "🧠 Million-bottle temple in Thailand: Heineken green + Chang brown. Built from rubbish, on purpose." },
  { id: 'pq70', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Pencils can write in zero gravity. NASA didn't need a special pen.", fact: "While the famous 'Space Pen' (developed privately, sold to NASA for ~$2.95 each) does work in zero gravity, US astronauts initially used pencils. Soviets used grease pencils. The myth that NASA spent millions developing a pen while Russians used pencils is wrong.", tip: "🧠 Space Pen: real, but not a NASA-funded billion-dollar mistake. Both sides used pencils early on." },
  { id: 'pq71', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The smallest country in Asia is so small you can walk across it in 30 minutes.", fact: "The Maldives, by area, is Asia's smallest country (~298 km²) — but the actual smallest by population is Brunei, much larger physically. Walking across any single Maldivian island takes well under an hour; the country is just spread across 1,200 islands.", tip: "🧠 Smallest Asian country by area: Maldives. Spread across 1,200 islands but tiny in total." },
  { id: 'pq72', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The Olympic gold medal contains very little gold.", fact: "Olympic gold medals are mostly silver — typically 92.5% silver with just 6 grams of gold plating (about 1.2%). The last solid-gold Olympic medals were awarded in Stockholm 1912.", tip: "🧠 Olympic 'gold' medal: mostly silver, 6g of gold. Solid gold last given in 1912." },
  { id: 'pq73', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Genghis Khan's empire was so large, he is now an ancestor to 1 in 200 men alive.", fact: "Genetic studies estimate that approximately 8% of men in the former Mongol Empire region — about 0.5% of all men globally, or 1 in 200 — descend in a direct male line from Genghis Khan or his close male relatives.", tip: "🧠 Genghis Khan: 1 in 200 men alive descend from his male line. Empire built genealogy too." },
  { id: 'pq74', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "There's a colour in the rainbow most people forget.", fact: "The seven colours of the rainbow (Newton's classification): red, orange, yellow, green, blue, indigo, violet. Indigo is the one most people forget. Mnemonic: ROY G BIV.", tip: "🧠 Rainbow: ROY G BIV. The forgotten one: Indigo (the I)." },
  { id: 'pq75', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "There's an animal so dangerous it's killed more Australians than sharks, snakes, and spiders combined.", fact: "Horses kill more Australians per year than sharks, snakes, and spiders combined — through riding accidents and falls. Around 20 deaths a year. The country's deadliest reputation lies more with bees and horses than crocs.", tip: "🧠 Australia's deadliest animal stat: horses. Beats sharks, snakes and spiders combined." },

  // ============ SCIENCE (existing 10 + new 18 = 28) ============
  { id: 's1', cat: 'science', emoji: '⚗️', subject: 'Science — Chemistry', diff: 1, hook: "Everything you've ever touched is made of the same basic stuff.", fact: "All matter is made of atoms. Atoms bond to form molecules. Water (H₂O) is two hydrogen atoms bonded to one oxygen atom. There are 118 known elements in the periodic table.", tip: "🧠 H₂O: 2 Hydrogen + 1 Oxygen. The number after the letter = how many atoms of that element." },
  { id: 's2', cat: 'science', emoji: '⚡', subject: 'Science — Electricity', diff: 2, hook: "Your phone charger uses this law every second of every charge.", fact: "Ohm's Law: Voltage (V) = Current (I) × Resistance (R). Voltage is the push (volts). Current is the flow of electrons (amps). Resistance opposes the flow (ohms). Double resistance = half the current.", tip: "🧠 Water pipe: voltage = pressure, current = flow rate, resistance = pipe width. V=IR always." },
  { id: 's3', cat: 'science', emoji: '🧲', subject: 'Science — Magnetism', diff: 1, hook: "Earth itself is a giant magnet — and that's why navigation has worked for centuries.", fact: "Opposite magnetic poles attract; like poles repel — always. Earth has a magnetic north and south pole, slightly offset from geographic poles. A compass needle aligns with Earth's magnetic field. No magnet ever has only one pole.", tip: "🧠 Cut a magnet in half: you get two smaller magnets each with north and south. Monopoles don't exist." },
  { id: 's4', cat: 'science', emoji: '🌡️', subject: 'Science — Heat', diff: 2, hook: "The Sun heats Earth from 150 million km away — here's the mechanism.", fact: "Heat transfers three ways: conduction (direct contact — metal spoon in soup), convection (fluid movement — hot air rising), and radiation (electromagnetic waves — sunlight through space). Only radiation works in a vacuum.", tip: "🧠 CCR: Conduction=Contact, Convection=Currents, Radiation=Remote. Only radiation works in space." },
  { id: 's5', cat: 'science', emoji: '🧪', subject: 'Science — pH', diff: 1, hook: "Lemon juice and bleach are both liquids — but complete chemical opposites.", fact: "pH runs 0–14. Below 7 = acid (lemon ≈ 2, coffee ≈ 5). Above 7 = alkali (baking soda ≈ 9, bleach ≈ 13). Pure water = neutral 7. Human blood is maintained at pH 7.4 — even 0.1 deviation causes serious illness.", tip: "🧠 pH 7 = neutral. Stomach acid = pH 1.5. Blood = 7.4. Your body defends these numbers fiercely." },
  { id: 's6', cat: 'science', emoji: '🔬', subject: 'Science — Biology', diff: 1, hook: "Every living thing started as a single cell — from bacteria to blue whales.", fact: "All living organisms are made of cells. Plant cells have a rigid wall and chloroplasts enabling photosynthesis. Animal cells have neither. All cells contain DNA. The human body contains ~37 trillion cells.", tip: "🧠 37 trillion cells in your body. Plants have walls. Animals don't. Chloroplasts = why plants are green." },
  { id: 's7', cat: 'science', emoji: '🌊', subject: 'Science — Light & Sound', diff: 2, hook: "You always see lightning before hearing thunder — even though both happen simultaneously.", fact: "Light travels at ~300,000 km/s and needs no medium. Sound travels at 343 m/s through air and cannot travel through space. Every 3 seconds between lightning and thunder = ~1 km distance.", tip: "🧠 3 seconds = 1 km away. Count the gap, divide by 3. Works every time." },
  { id: 's8', cat: 'science', emoji: '🌍', subject: 'Science — Gravity', diff: 1, hook: "It holds you to the floor, the Moon in orbit, and galaxies together.", fact: "Gravity is an attractive force between any two objects with mass. Earth's gravity pulls at 9.8 m/s² downward. The Moon's gravity is 1/6 of Earth's — why astronauts bounce. Gravity is the weakest fundamental force but acts across unlimited range.", tip: "🧠 Moon gravity = 1/6 Earth. 80kg on Earth = 13kg on Moon. Same mass, different weight." },
  { id: 's9', cat: 'science', emoji: '🧬', subject: 'Science — DNA', diff: 2, hook: "Every cell contains a 2-metre instruction manual folded into a space you can't see.", fact: "Human DNA is ~2 metres long when uncoiled, yet fits inside a cell nucleus just 6 micrometres wide. It contains ~3 billion base pairs. You share 99.9% of DNA with every other human — and 60% with a banana.", tip: "🧠 You share 99.9% DNA with all humans. 60% with a banana. The 0.1% = all human diversity." },
  { id: 's10', cat: 'science', emoji: '🌌', subject: 'Science — Universe', diff: 2, hook: "The universe is 13.8 billion years old — but 93 billion light-years wide. Both are true.", fact: "The universe is 13.8 billion years old. But it's 93 billion light-years wide because space itself expanded faster than light during early inflation. There are an estimated 2 trillion galaxies, each with hundreds of billions of stars.", tip: "🧠 Age: 13.8 billion years. Width: 93 billion light-years. Space expands faster than light travels." },
  { id: 's11', cat: 'science', emoji: '☢️', subject: 'Science — Radioactivity', diff: 2, hook: "Bananas are slightly radioactive — every single one.", fact: "Bananas contain potassium-40, a naturally radioactive isotope. The dose is tiny (~0.1 microsieverts per banana) — completely harmless. The 'banana equivalent dose' is sometimes used to explain radiation exposure intuitively.", tip: "🧠 Bananas = mildly radioactive. Used as a casual unit: the 'banana equivalent dose'." },
  { id: 's12', cat: 'science', emoji: '❄️', subject: 'Science — States of Matter', diff: 1, hook: "Most people learn 3 states of matter. There are at least 4 — possibly more.", fact: "Classic states: solid, liquid, gas. The fourth — plasma — is the most common in the universe (stars, lightning, neon signs). Bose-Einstein condensate, Fermionic condensate, and quark-gluon plasma are exotic additional states discovered in labs.", tip: "🧠 4th state: plasma (stars, lightning). Bonus exotic states exist but only in labs." },
  { id: 's13', cat: 'science', emoji: '🦠', subject: 'Science — Viruses', diff: 2, hook: "Scientists still debate whether viruses are technically alive.", fact: "Viruses can't reproduce or metabolise on their own — they need a living host cell. They lack the basic machinery of life. Most biologists classify them as 'biological entities' rather than living organisms.", tip: "🧠 Viruses: not quite alive, not quite dead. They borrow life from your cells." },
  { id: 's14', cat: 'science', emoji: '🌀', subject: 'Science — Entropy', diff: 3, hook: "There's a law of physics that says everything must eventually fall apart.", fact: "The Second Law of Thermodynamics states that entropy (disorder) in a closed system always increases over time. This is why heat flows from hot to cold, eggs don't unscramble, and time appears to move forward. Disorder always wins eventually.", tip: "🧠 Entropy = disorder. Always increases. Why eggs don't unscramble. Why time has a direction." },
  { id: 's15', cat: 'science', emoji: '⚛️', subject: 'Science — Atoms', diff: 2, hook: "Atoms are 99.9999999% empty space.", fact: "An atom's nucleus contains nearly all its mass but occupies a vanishingly small volume — like a marble in the middle of a football stadium. The 'solidness' you feel from any object is purely electromagnetic force pushing back on your fingertips.", tip: "🧠 Atoms = mostly empty. What feels solid = electromagnetic repulsion, not actual contact." },
  { id: 's16', cat: 'science', emoji: '💧', subject: 'Science — Water', diff: 1, hook: "Water has a very strange property that makes life possible.", fact: "Unlike most substances, water is densest at 4°C — not when frozen. That's why ice floats. If ice sank, lakes would freeze solid from the bottom up and aquatic life couldn't survive winter.", tip: "🧠 Water densest at 4°C. Ice floats. This single quirk = aquatic life surviving winter." },
  { id: 's17', cat: 'science', emoji: '🌈', subject: 'Science — Light', diff: 1, hook: "White light contains every colour you've ever seen.", fact: "White light is a mix of all visible wavelengths. A prism splits it into the visible spectrum (red to violet). Beyond visible light: infrared (used in remotes), ultraviolet (sunburn), microwaves, X-rays, gamma rays.", tip: "🧠 White light = all colours mixed. Prism splits them. Same physics behind rainbows." },
  { id: 's18', cat: 'science', emoji: '🌪️', subject: 'Science — Weather', diff: 2, hook: "A single thunderstorm can release more energy than an atomic bomb.", fact: "An average thunderstorm releases ~10¹⁵ joules of energy — comparable to 10–20 Hiroshima bombs. Most of this is dissipated as heat. Lightning is a tiny fraction of the total energy.", tip: "🧠 Average thunderstorm: energy of 10–20 atomic bombs. Lightning is just the visible part." },
  { id: 's19', cat: 'science', emoji: '🐝', subject: 'Science — Animal Vision', diff: 2, hook: "Bees see colours that don't exist for you.", fact: "Bees see ultraviolet light, which humans can't. Many flowers have UV patterns invisible to us — landing strips guiding bees to nectar. To a bee, what looks like a plain yellow flower has glowing arrows pointing inward.", tip: "🧠 Bees see UV. Flowers have hidden UV patterns. Whole conversations happen above your visible spectrum." },
  { id: 's20', cat: 'science', emoji: '🌑', subject: 'Science — Black Holes', diff: 3, hook: "Time literally slows down near a black hole — not metaphorically.", fact: "General relativity predicts time dilates near massive objects. Near a black hole's event horizon, time effectively slows to a near-stop relative to a distant observer. This was depicted (accurately, with consultants) in the film Interstellar.", tip: "🧠 Time bends near gravity. Near a black hole: time crawls. Interstellar got the physics right." },
  { id: 's21', cat: 'science', emoji: '🧊', subject: 'Science — Cryogenics', diff: 2, hook: "There's a temperature so cold no atom can move — and we know exactly what it is.", fact: "Absolute zero (−273.15°C / 0 Kelvin) is the theoretical lowest temperature, where all atomic motion stops. Scientists can get within billionths of a degree but never reach it — the third law of thermodynamics forbids it.", tip: "🧠 Absolute zero = −273.15°C = 0 K. Coldest possible. Unreachable, even in theory." },
  { id: 's22', cat: 'science', emoji: '🪨', subject: 'Science — Geology', diff: 1, hook: "Diamonds are not actually the hardest natural substance.", fact: "Diamonds long held the title of hardest natural material, but newer materials surpass them. Wurtzite boron nitride is ~18% harder, and lonsdaleite (a meteorite-formed diamond variant) is up to 58% harder than regular diamond.", tip: "🧠 Diamond ≠ hardest anymore. Wurtzite boron nitride and lonsdaleite both beat it." },
  { id: 's23', cat: 'science', emoji: '🌬️', subject: 'Science — Air', diff: 1, hook: "The air you breathe is mostly not what you think it is.", fact: "Earth's atmosphere is ~78% nitrogen, ~21% oxygen, ~0.9% argon, ~0.04% CO₂ (and rising). Many people assume oxygen is the bulk — it's actually the second most common gas, by a big margin.", tip: "🧠 Air = 78% nitrogen + 21% oxygen. The other 1% is mostly argon, with traces of CO₂." },
  { id: 's24', cat: 'science', emoji: '🐙', subject: 'Science — Camouflage', diff: 2, hook: "Octopuses can change colour — but they can't see colour themselves.", fact: "Octopuses are colour-blind, yet they perfectly match their environment's colours. Researchers think they may detect colour through specialised photoreceptors in their skin — essentially 'seeing' colour with their entire body.", tip: "🧠 Octopuses: colour-blind eyes, possibly colour-sensing skin. They see with their whole body." },
  { id: 's25', cat: 'science', emoji: '🌋', subject: 'Science — Volcanoes', diff: 2, hook: "Most of Earth's volcanoes are hidden underwater.", fact: "Roughly 80% of all volcanic activity on Earth happens underwater along mid-ocean ridges. The largest volcano on Earth — Tamu Massif (Pacific) — is also underwater and was only confirmed in 2013.", tip: "🧠 Most volcanoes are underwater. Largest one (Tamu Massif) only discovered in 2013." },
  { id: 's26', cat: 'science', emoji: '🦴', subject: 'Science — Evolution', diff: 1, hook: "Whales evolved from a small four-legged land animal that walked into the sea.", fact: "Whales descend from Pakicetus, a wolf-sized hoofed mammal that lived ~50 million years ago. Over millions of years, its descendants returned to water — limbs became flippers, nostrils migrated to the top of the head (becoming a blowhole).", tip: "🧠 Whales evolved from land mammals. Closest living relative: hippos. They came back to the ocean." },
  { id: 's27', cat: 'science', emoji: '🌪️', subject: 'Science — Pressure', diff: 2, hook: "There's a real reason your ears pop in lifts and on planes.", fact: "Air pressure decreases with altitude. Trapped air in your middle ear must equalise with outside pressure via the Eustachian tube. The 'pop' = air rushing through. Yawning or swallowing helps it open.", tip: "🧠 Ear pop = pressure equalising. Yawn or swallow to open the Eustachian tube faster." },
  { id: 's28', cat: 'science', emoji: '🧲', subject: 'Science — Lightning', diff: 2, hook: "A bolt of lightning is hotter than the surface of the Sun.", fact: "A lightning bolt reaches ~30,000°C — about 5 times hotter than the Sun's surface (~5,500°C). The rapid heating expands the air explosively, creating the shock wave we hear as thunder.", tip: "🧠 Lightning: 30,000°C. Sun's surface: 5,500°C. Lightning wins by 5x." },

  // ============ HISTORY (existing 8 + new 20 = 28) ============
  { id: 'h1', cat: 'history', emoji: '⚔️', subject: 'History — WW1', diff: 1, hook: "One bullet in Sarajevo in 1914 dragged the entire world into war.", fact: "World War One (1914–1918) was triggered by the assassination of Archduke Franz Ferdinand on 28 June 1914. The real causes were rival alliances, imperial competition, and arms races. Around 20 million people died.", tip: "🧠 The assassination was the spark. The powder keg — alliances, empire, rivalry — was already built." },
  { id: 'h2', cat: 'history', emoji: '🏛️', subject: 'History — Ancient Rome', diff: 1, hook: "Rome ruled the world for over 1,000 years and we still live inside its legacy.", fact: "Rome was a republic for ~500 years before becoming an Empire in 27 BC under Augustus. The Western Empire fell in 476 AD. Rome gave the world roads, concrete, aqueducts, Roman law, the Latin alphabet, and our 12-month calendar.", tip: "🧠 Republic → Empire: 27 BC. 'Calendar', 'senate', 'virus', 'justice' all come from Latin." },
  { id: 'h3', cat: 'history', emoji: '🌍', subject: 'History — Cold War', diff: 2, hook: "The most dangerous standoff in history — not a single direct shot was fired.", fact: "The Cold War (1947–1991) pitted the USA against the USSR. They never fought directly but competed through proxy wars (Korea, Vietnam), nuclear arms racing, and the Space Race. The Cuban Missile Crisis of 1962 brought the world within minutes of nuclear war.", tip: "🧠 Cuban Missile Crisis = closest to nuclear war. Cold = no direct combat. Proxy wars = fighting through other countries." },
  { id: 'h4', cat: 'history', emoji: '🎨', subject: 'History — Renaissance', diff: 1, hook: "It began in one Italian city and rewrote the intellectual history of all Europe.", fact: "The Renaissance ('rebirth') began in Florence, Italy in the 14th century. The Medici banking family funded artists and scientists. Leonardo da Vinci, Michelangelo, Galileo, and Raphael all emerged from this era.", tip: "🧠 Renaissance = rebirth. Florence. Medici funded it. Da Vinci was artist AND scientist AND engineer." },
  { id: 'h5', cat: 'history', emoji: '🧭', subject: 'History — Exploration', diff: 1, hook: "He was trying to reach Asia. He found a continent he didn't know existed.", fact: "In 1492, Columbus — sailing for Spain — reached the Caribbean. He believed he'd found Asia and called the locals 'Indians'. The Americas were named after Amerigo Vespucci, who confirmed it was a new continent.", tip: "🧠 Columbus: thought it was Asia. Vespucci: realised it was new. America named after Amerigo, not Columbus." },
  { id: 'h6', cat: 'history', emoji: '💣', subject: 'History — WW2', diff: 1, hook: "The deadliest conflict in human history lasted just six years.", fact: "WW2 (1939–1945) killed 70–85 million people — ~3% of world population. It ended in Europe on VE Day (8 May 1945) and in the Pacific on VJ Day (15 Aug 1945) after atomic bombs hit Hiroshima (6 Aug) and Nagasaki (9 Aug).", tip: "🧠 VE Day = May 8. VJ Day = Aug 15. Hiroshima = Aug 6. Nagasaki = Aug 9." },
  { id: 'h7', cat: 'history', emoji: '🚀', subject: 'History — Space Race', diff: 1, hook: "On 20 July 1969, a human stood on another world for the very first time.", fact: "Apollo 11 landed on the Moon on 20 July 1969. Neil Armstrong was first on the surface; Buzz Aldrin followed minutes later. Michael Collins orbited above and never landed — the most overlooked astronaut in history.", tip: "🧠 Armstrong first. Aldrin second. Collins orbited — never landed. The forgotten third astronaut." },
  { id: 'h8', cat: 'history', emoji: '👩‍💻', subject: 'History — Famous Firsts', diff: 2, hook: "The world's first computer programmer wrote code in the 1840s — a century before computers existed.", fact: "Ada Lovelace (1815–1852) wrote the first algorithm intended for a machine — Babbage's proposed Analytical Engine. She was the daughter of poet Lord Byron. The programming language 'Ada' is named after her.", tip: "🧠 Ada Lovelace = first programmer, 1840s. Daughter of Lord Byron. The language 'Ada' is named after her." },
  { id: 'h9', cat: 'history', emoji: '🏰', subject: 'History — Middle Ages', diff: 2, hook: "The Middle Ages weren't called that until centuries after they ended.", fact: "The term 'Middle Ages' was coined by Renaissance scholars who saw their own time as a glorious revival, with the period in between (roughly 500–1500 AD) as a 'middle' gap. People living through it had no idea they were in the 'middle' of anything.", tip: "🧠 'Middle Ages' = label invented by Renaissance scholars retroactively. No medieval person knew the term." },
  { id: 'h10', cat: 'history', emoji: '⚖️', subject: 'History — Magna Carta', diff: 2, hook: "An English document from 1215 is still cited in courts around the world today.", fact: "The Magna Carta (1215) was a peace agreement forced on King John by rebellious barons. It established that the king is not above the law. Most clauses have been repealed, but its principles inspired the US Constitution and modern democracies.", tip: "🧠 Magna Carta: 1215, England. King not above law. DNA of modern democracy and US Constitution." },
  { id: 'h11', cat: 'history', emoji: '🛕', subject: 'History — Ancient Egypt', diff: 1, hook: "The pyramid builders weren't slaves — they were paid workers.", fact: "Modern archaeology shows the Great Pyramids were built by paid Egyptian workers, not slaves. They received bread, beer, meat, and medical care. Skeletons show evidence of healed injuries — meaning workers received expensive treatment.", tip: "🧠 Pyramid builders: paid workers, not slaves. Bread, beer, and even healthcare." },
  { id: 'h12', cat: 'history', emoji: '🛡️', subject: 'History — Vikings', diff: 1, hook: "Vikings did not wear horned helmets — that was a 19th-century opera invention.", fact: "Archaeology has never produced a horned Viking helmet. The image was popularised by costume designer Carl Emil Doepler for Wagner's 1876 Ring Cycle opera. Real Viking helmets were simple iron caps.", tip: "🧠 Horned Viking helmets: invented for opera, 1876. Real helmets: plain iron, no horns." },
  { id: 'h13', cat: 'history', emoji: '🏯', subject: 'History — Samurai', diff: 2, hook: "Samurai existed for over 700 years and were finally outlawed in the 19th century.", fact: "The samurai class ruled Japan from the 12th century. After the Meiji Restoration (1868), Japan modernised and abolished the samurai class in 1876, banning them from carrying swords. Many became civil servants, soldiers, or businessmen.", tip: "🧠 Samurai: 12th century to 1876. Meiji Restoration ended them. Sword ban marked the formal end." },
  { id: 'h14', cat: 'history', emoji: '🗽', subject: 'History — American Revolution', diff: 1, hook: "America's Declaration of Independence was actually signed mostly in August, not July 4th.", fact: "The Continental Congress voted for independence on 2 July 1776 and approved the final wording on 4 July. But most signatures were added on 2 August. John Adams predicted 2 July — not 4 July — would be celebrated forever. He was wrong.", tip: "🧠 July 4: text approved. Aug 2: most signatures. John Adams expected the wrong day to win." },
  { id: 'h15', cat: 'history', emoji: '🎭', subject: 'History — French Revolution', diff: 2, hook: "Marie Antoinette never said 'let them eat cake'.", fact: "The famous quote was attributed to a 'great princess' in Rousseau's Confessions, written when Marie Antoinette was just 9 years old and not yet in France. Her actual words and views were far more sympathetic toward the poor than legend allows.", tip: "🧠 'Let them eat cake' = not Marie Antoinette. Rousseau quoted an unnamed princess years earlier." },
  { id: 'h16', cat: 'history', emoji: '🇨🇳', subject: 'History — Imperial China', diff: 2, hook: "The Great Wall was actually a series of walls built over 2,000 years.", fact: "Construction began in the 7th century BC. The 'Great Wall' is many separate walls, fortifications, and watchtowers built and rebuilt by different dynasties — most famously the Ming Dynasty (1368–1644). Total length: ~21,000 km.", tip: "🧠 Great Wall: 2,000+ years of building. Most surviving sections are Ming Dynasty (post-1368)." },
  { id: 'h17', cat: 'history', emoji: '👑', subject: 'History — British Monarchy', diff: 2, hook: "Queen Elizabeth II ruled longer than any other British monarch — by a wide margin.", fact: "Elizabeth II reigned from 6 February 1952 to 8 September 2022 — 70 years and 214 days. The previous record holder was Queen Victoria (63 years, 216 days). Elizabeth II met every US President since Truman except LBJ.", tip: "🧠 Elizabeth II: 70 years on the throne. Met every US President from Truman to Biden — except LBJ." },
  { id: 'h18', cat: 'history', emoji: '☢️', subject: 'History — Atomic Age', diff: 2, hook: "The Manhattan Project employed 130,000 people — and almost nobody knew the goal.", fact: "The US Manhattan Project (1942–46) employed ~130,000 workers across multiple secret cities. Most workers had no idea they were building atomic weapons until news of Hiroshima broke. Total cost in modern terms: ~$30 billion.", tip: "🧠 Manhattan Project: 130,000 workers, most unaware they were making nuclear bombs." },
  { id: 'h19', cat: 'history', emoji: '⚓', subject: 'History — Titanic', diff: 1, hook: "The Titanic sent distress signals using a brand new technology — and it saved hundreds.", fact: "The Titanic sank on 15 April 1912. Wireless telegraphy (Marconi's invention) was new — and Titanic's CQD/SOS signals reached the RMS Carpathia, which rescued 705 survivors. Without wireless, all 2,224 aboard might have perished.", tip: "🧠 Titanic, 1912. Wireless saved 705. Without Marconi's tech, the death toll would've been total." },
  { id: 'h20', cat: 'history', emoji: '🏛️', subject: 'History — Greek Origins', diff: 2, hook: "The word 'democracy' is over 2,500 years old.", fact: "Democracy began in Athens around 508 BC under reformer Cleisthenes. The word combines 'demos' (people) and 'kratos' (rule). Athenian democracy excluded women, slaves, and foreigners — but the principle of citizen rule reshaped governance forever.", tip: "🧠 Democracy = 'people-rule' in Greek. Born in Athens, 508 BC. Imperfect, but the foundation." },
  { id: 'h21', cat: 'history', emoji: '🌍', subject: 'History — Decolonisation', diff: 2, hook: "Half the world's countries gained independence in the past 80 years.", fact: "Before WW2, much of the world was under European colonial rule. India gained independence in 1947, triggering a wave. Africa saw 17 nations gain independence in 1960 alone — 'the Year of Africa'. Most modern borders are post-1945.", tip: "🧠 1960 = 'Year of Africa', 17 new nations. Most current borders postdate WW2." },
  { id: 'h22', cat: 'history', emoji: '🗿', subject: 'History — Easter Island', diff: 2, hook: "The famous Easter Island heads have buried bodies underneath them.", fact: "The Moai statues of Easter Island, long thought to be just heads, actually have full torsos buried beneath the soil. Excavations beginning in 2010 revealed the bodies, often covered in ancient petroglyphs.", tip: "🧠 Easter Island Moai: not just heads. Full bodies buried underground, with petroglyphs." },
  { id: 'h23', cat: 'history', emoji: '✉️', subject: 'History — Postal Service', diff: 1, hook: "The world's first postage stamp was issued in 1840 — and is still legally valid.", fact: "The Penny Black, issued in the UK on 1 May 1840, was the world's first adhesive postage stamp. It's technically still valid for postage in Britain, though using one would be financially mad — pristine examples are worth thousands.", tip: "🧠 Penny Black: 1840 UK, first stamp ever. Technically still valid. Don't use one." },
  { id: 'h24', cat: 'history', emoji: '🏆', subject: 'History — Olympics', diff: 2, hook: "The Olympics were banned for nearly 1,500 years.", fact: "The ancient Olympic Games began in 776 BC and ran every 4 years. Roman Emperor Theodosius I banned them in 393 AD as pagan. They weren't held again until 1896, when Pierre de Coubertin revived them in Athens.", tip: "🧠 Olympics: started 776 BC, banned 393 AD, revived 1896. A 1,500-year gap." },
  { id: 'h25', cat: 'history', emoji: '🌐', subject: 'History — Berlin Wall', diff: 1, hook: "The Berlin Wall stood for 28 years — and fell because of a press conference mistake.", fact: "On 9 November 1989, an East German official mistakenly announced new travel rules took effect 'immediately' (rather than the next day). Crowds gathered at the Wall demanding to cross. Confused guards opened the gates. The Wall, built 1961, fell that night.", tip: "🧠 Berlin Wall fell, 9 Nov 1989. Cause: press-conference mix-up that brought thousands to the gates." },
  { id: 'h26', cat: 'history', emoji: '💌', subject: 'History — Unsent Letters', diff: 2, hook: "Lincoln's most famous speech wasn't even the main event that day.", fact: "Lincoln's Gettysburg Address (19 Nov 1863) lasted just 2 minutes (272 words). The main speaker, Edward Everett, spoke for 2 hours beforehand. Everett's speech is forgotten. Lincoln's became one of the most quoted speeches in history.", tip: "🧠 Gettysburg Address: 2 minutes, 272 words. Main act spoke for 2 hours. Everyone remembers Lincoln." },
  { id: 'h27', cat: 'history', emoji: '🐎', subject: 'History — Pony Express', diff: 2, hook: "The legendary Pony Express only operated for 18 months.", fact: "The Pony Express ran mail from Missouri to California, 1860–1861. It cut delivery times from weeks to ~10 days. The transcontinental telegraph (Oct 1861) made it instantly obsolete. It folded after 18 months and was a financial disaster.", tip: "🧠 Pony Express: famous, romantic, lasted only 18 months. Telegraph made it obsolete." },
  { id: 'h28', cat: 'history', emoji: '🛕', subject: 'History — Library of Alexandria', diff: 2, hook: "The Library of Alexandria didn't burn down in a single dramatic event.", fact: "The Great Library of Alexandria's destruction was not one event — it declined over centuries. Multiple fires, political turmoil, religious conflict, and gradual neglect under Roman and Byzantine rule erased it. The exact end date is unknown.", tip: "🧠 Library of Alexandria: died gradually over centuries. No single fire ended it. Slow decline." },

  // ============ GEOGRAPHY (existing 6 + new 20 = 26) ============
  { id: 'geo1', cat: 'geo', emoji: '🌍', subject: 'Geography — Continents', diff: 1, hook: "Most people name 5 easily. The last two always trip someone up.", fact: "7 continents: Africa, Antarctica, Asia, Australia/Oceania, Europe, North America, South America. Asia is largest (44M km²) and most populated (60% of world population). Antarctica has zero permanent residents.", tip: "🧠 Memory: Eat An Apple As A Night Snack → Europe, Antarctica, Asia, Africa, Australia, N.America, S.America." },
  { id: 'geo2', cat: 'geo', emoji: '🌊', subject: 'Geography — Oceans', diff: 1, hook: "One ocean is larger than every piece of land on Earth put together.", fact: "5 oceans: Pacific (largest — bigger than all land combined), Atlantic, Indian, Southern, Arctic (smallest). Together they cover ~71% of Earth. The Pacific contains more than half of all ocean water.", tip: "🧠 Size order: Pacific, Atlantic, Indian, Southern, Arctic. Mnemonic: PAISA." },
  { id: 'geo3', cat: 'geo', emoji: '⛰️', subject: 'Geography — Mountains', diff: 2, hook: "The tallest mountain depends entirely on how you measure it.", fact: "Everest (8,849m) = highest above sea level. Mauna Kea in Hawaii = tallest base to summit (~10,200m, mostly underwater). Chimborazo in Ecuador = furthest from Earth's centre. Three records, three mountains.", tip: "🧠 Everest: altitude. Mauna Kea: total height. Chimborazo: from Earth's core. All three are correct." },
  { id: 'geo4', cat: 'geo', emoji: '🌐', subject: 'Geography — Navigation', diff: 1, hook: "Every GPS system runs on a coordinate grid invented centuries before satellites.", fact: "Latitude = east–west lines measuring north/south from the equator (0°). Longitude = north–south lines from the Prime Meridian in Greenwich, London (0°). Together they pinpoint any location on Earth.", tip: "🧠 Lat = flat/horizontal. Long = tall/vertical (pole to pole). Equator = 0° lat. Greenwich = 0° long." },
  { id: 'geo5', cat: 'geo', emoji: '🌋', subject: 'Geography — Geology', diff: 2, hook: "The ground beneath your feet is moving right now — just very slowly.", fact: "Earth's crust is divided into ~15 major tectonic plates drifting a few cm per year. Plates colliding = mountains. Plates separating = rift valleys and volcanoes. Plates sliding = earthquakes. The Himalayas grow ~5mm per year.", tip: "🧠 Collide = mountains. Separate = rifts. Slide = earthquakes. Three boundary types, three outcomes." },
  { id: 'geo6', cat: 'geo', emoji: '🗺️', subject: 'Geography — Rivers', diff: 2, hook: "Two great rivers hold two different world records.", fact: "The Nile (≈6,650km) is generally the world's longest river. The Amazon (≈6,400km) carries ~20% of all freshwater entering the world's oceans — more than the next 7 largest rivers combined.", tip: "🧠 Nile = longest. Amazon = most water volume (20% of global river discharge)." },
  { id: 'geo7', cat: 'geo', emoji: '🏝️', subject: 'Geography — Islands', diff: 2, hook: "Greenland is the world's largest island — but it's smaller than it looks on most maps.", fact: "Greenland (~2.16 million km²) is the largest island. The Mercator projection used in most maps makes it look bigger than Africa, but Africa is actually 14 times larger. Australia is classified as a continent, not an island.", tip: "🧠 Greenland: largest island, 2.16M km². On flat maps it looks huge — Africa is actually 14x bigger." },
  { id: 'geo8', cat: 'geo', emoji: '🏜️', subject: 'Geography — Deserts', diff: 1, hook: "Antarctica is the world's largest desert — yes, really.", fact: "A desert is defined by precipitation, not heat. Antarctica receives less than 200mm of rain or snow per year — making it Earth's largest desert at ~14 million km². The Sahara (9 million km²) is only the largest hot desert.", tip: "🧠 Largest desert = Antarctica (cold). Largest hot desert = Sahara. Defined by rainfall, not temperature." },
  { id: 'geo9', cat: 'geo', emoji: '🌎', subject: 'Geography — Country Sizes', diff: 1, hook: "Russia is so big it touches every other country in the top 5 by size.", fact: "Top 5 largest countries by area: Russia (17.1M km²), Canada (10M), USA (9.8M), China (9.6M), Brazil (8.5M). Russia alone covers 11% of Earth's land. The smallest country is Vatican City at 0.49 km².", tip: "🧠 Top 5: Russia, Canada, USA, China, Brazil. Russia alone = 11% of all land on Earth." },
  { id: 'geo10', cat: 'geo', emoji: '🌆', subject: 'Geography — Capitals', diff: 2, hook: "Some countries have more than one capital — and at least one has three.", fact: "South Africa has 3 capitals: Pretoria (executive), Cape Town (legislative), and Bloemfontein (judicial). Bolivia has 2 (Sucre and La Paz). Many countries have a separate ceremonial vs administrative capital.", tip: "🧠 South Africa = 3 capitals (Pretoria, Cape Town, Bloemfontein). Splitting power across cities." },
  { id: 'geo11', cat: 'geo', emoji: '🌐', subject: 'Geography — Equator', diff: 1, hook: "Only 13 countries are crossed by the equator.", fact: "13 countries lie on the equator: Ecuador, Colombia, Brazil, São Tomé and Príncipe, Gabon, Republic of Congo, DR Congo, Uganda, Kenya, Somalia, Maldives, Indonesia, and Kiribati. Several others lie just above or below it.", tip: "🧠 13 equator countries. 'Ecuador' is named after the equator itself." },
  { id: 'geo12', cat: 'geo', emoji: '🇻🇦', subject: 'Geography — Microstates', diff: 2, hook: "The world's smallest country is roughly the size of a golf course.", fact: "Vatican City covers just 0.49 km² (about 121 acres) — the world's smallest sovereign state. Other tiny countries: Monaco (2 km²), Nauru (21 km²), Tuvalu (26 km²), San Marino (61 km²).", tip: "🧠 Smallest: Vatican (0.49 km²). Top 5: Vatican, Monaco, Nauru, Tuvalu, San Marino." },
  { id: 'geo13', cat: 'geo', emoji: '🏔️', subject: 'Geography — Himalayas', diff: 2, hook: "The Himalayas were created by India crashing into Asia — and they're still rising.", fact: "About 50 million years ago, the Indian tectonic plate collided with the Eurasian plate. The collision pushed up the Himalayas, which are still rising about 5mm per year. Mount Everest grows roughly half a metre per century.", tip: "🧠 Himalayas: born from India hitting Asia ~50M years ago. Still growing 5mm/year." },
  { id: 'geo14', cat: 'geo', emoji: '🏖️', subject: 'Geography — Coastlines', diff: 2, hook: "Canada has more coastline than every other country combined.", fact: "Canada has approximately 202,080 km of coastline — more than the next ten countries combined. Most of it is along Arctic islands, much of it inaccessible. Indonesia is second at 54,716 km.", tip: "🧠 Longest coastline: Canada (202,000 km). More than next 10 countries combined." },
  { id: 'geo15', cat: 'geo', emoji: '🏞️', subject: 'Geography — Lakes', diff: 1, hook: "The world's largest lake is technically a sea — but only by name.", fact: "The Caspian Sea (between Europe and Asia) covers ~371,000 km² — the world's largest enclosed body of water. It's called a 'sea' historically, but technically it's a lake (no ocean connection). Lake Superior is the largest freshwater lake.", tip: "🧠 Caspian: world's largest lake (called a 'sea'). Lake Superior: largest freshwater." },
  { id: 'geo16', cat: 'geo', emoji: '🌫️', subject: 'Geography — Climate', diff: 2, hook: "There's a town in Russia where it's so cold, thermometers stop working.", fact: "Oymyakon, Siberia, is the coldest permanently inhabited place on Earth. Recorded lows: −67.7°C. Standard mercury thermometers freeze (mercury freezes at −38.8°C). Cars are kept running 24/7 in winter — turning them off can mean they never start again.", tip: "🧠 Oymyakon, Russia: −67.7°C. Mercury freezes. Cars are never switched off in winter." },
  { id: 'geo17', cat: 'geo', emoji: '🌅', subject: 'Geography — Time Zones', diff: 1, hook: "The first country to see sunrise each day is one of the smallest.", fact: "Kiribati (Pacific Ocean) deliberately moved its date line in 1995 so the entire country shares the same date. Its eastern islands now see the sunrise first each day, ahead of every other country.", tip: "🧠 First sunrise of the day: Kiribati. They moved the date line specifically to claim it." },
  { id: 'geo18', cat: 'geo', emoji: '⛲', subject: 'Geography — Waterfalls', diff: 2, hook: "The world's tallest waterfall has water that turns to mist before reaching the ground.", fact: "Angel Falls in Venezuela is the world's tallest uninterrupted waterfall at 979 metres. Its water often evaporates or vaporises into mist before hitting the river below — especially in the dry season.", tip: "🧠 Tallest waterfall: Angel Falls, Venezuela, 979m. Water turns to mist mid-fall." },
  { id: 'geo19', cat: 'geo', emoji: '🪨', subject: 'Geography — Rocks', diff: 2, hook: "Australia's Uluru is mostly underground — the visible part is just the tip.", fact: "Uluru (Ayers Rock) rises 348m above the surrounding plain. But geologists estimate the rock extends ~2.5 km below ground — making the visible portion only about 1/8 of the whole massif.", tip: "🧠 Uluru: visible 348m, hidden ~2.5 km below. The rock is an iceberg." },
  { id: 'geo20', cat: 'geo', emoji: '🌳', subject: 'Geography — Rainforests', diff: 1, hook: "The Amazon produces around 20% of Earth's atmospheric oxygen.", fact: "The Amazon Rainforest covers ~5.5 million km² across nine countries (mostly Brazil). It contains an estimated 390 billion trees and ~10% of all known species on Earth. Often called 'the lungs of the planet'.", tip: "🧠 Amazon: ~20% of world's oxygen, 10% of all species, 9 countries. Lungs of the planet." },
  { id: 'geo21', cat: 'geo', emoji: '🗻', subject: 'Geography — Volcanic Islands', diff: 2, hook: "Hawaii is moving away from the US at about 7cm per year.", fact: "The Pacific tectonic plate (which carries the Hawaiian Islands) drifts northwest at ~7 cm/year — about the speed your fingernails grow. New Hawaiian islands are also forming over a stationary 'hotspot' beneath the Pacific.", tip: "🧠 Hawaii drifts NW at 7 cm/year. The hotspot stays still — new islands keep being created." },
  { id: 'geo22', cat: 'geo', emoji: '🌫️', subject: 'Geography — Cities', diff: 2, hook: "Tokyo is the world's largest metropolitan area — by a huge margin.", fact: "Greater Tokyo's metropolitan population is approximately 37 million people — the largest in the world. That's more than the entire population of Canada. Delhi (~31M) and Shanghai (~28M) are 2nd and 3rd.", tip: "🧠 Tokyo metro: 37M. Bigger than the population of Canada. Top 3: Tokyo, Delhi, Shanghai." },
  { id: 'geo23', cat: 'geo', emoji: '⛓️', subject: 'Geography — Borders', diff: 2, hook: "China and Russia each border 14 countries — the most of any nation.", fact: "China and Russia are tied for most international borders, each touching 14 different countries. China borders: Mongolia, Russia, North Korea, Vietnam, Laos, Myanmar, India, Bhutan, Nepal, Pakistan, Afghanistan, Tajikistan, Kyrgyzstan, Kazakhstan.", tip: "🧠 Most borders: China and Russia, both with 14 neighbours each." },
  { id: 'geo24', cat: 'geo', emoji: '🛤️', subject: 'Geography — Longest Road', diff: 1, hook: "There's a road that stretches from northern Alaska to the bottom of South America.", fact: "The Pan-American Highway runs ~30,000 km from Prudhoe Bay (Alaska) to Ushuaia (Argentina) — one of the longest road systems in the world. There's one short break: the impassable 'Darién Gap' jungle in Panama/Colombia.", tip: "🧠 Pan-American Highway: ~30,000 km. One gap: the Darién jungle between Panama and Colombia." },
  { id: 'geo25', cat: 'geo', emoji: '🏗️', subject: 'Geography — Tallest Building', diff: 1, hook: "The Burj Khalifa is so tall, you can watch the sunset twice on the same day.", fact: "The Burj Khalifa in Dubai stands 828m tall — the world's tallest building. People at the top see the Sun set later than people on the ground. By taking a fast elevator down after sunset, you can technically see it set again.", tip: "🧠 Burj Khalifa: 828m. Watch sunset, take the lift down, watch it again. Two sunsets in one day." },
  { id: 'geo26', cat: 'geo', emoji: '🌊', subject: 'Geography — Mariana Trench', diff: 2, hook: "The deepest point on Earth is deeper than Mount Everest is tall.", fact: "The Mariana Trench in the Pacific reaches ~10,994m at Challenger Deep — over 2 km deeper than Everest is tall (8,849m). Pressure there is 1,000 times atmospheric — like having a small SUV pressing on every cm² of your body.", tip: "🧠 Mariana Trench: 10,994m deep. 2km more than Everest is tall. Pressure: extreme." },

  // ============ HUMAN BODY (existing 8 + new 18 = 26) ============
  { id: 'b1', cat: 'body', emoji: '🫀', subject: 'Body — Heart', diff: 1, hook: "It has never once stopped beating in your entire life.", fact: "The heart beats ~100,000 times/day, 35 million/year, 2.5 billion in a lifetime. It pushes blood through ~100,000km of vessels. The left side pumps oxygenated blood to the body; the right pumps deoxygenated blood to the lungs.", tip: "🧠 Left = oxygenated OUT to body. Right = deoxygenated IN from body → lungs. Left = Life." },
  { id: 'b2', cat: 'body', emoji: '🧠', subject: 'Body — Brain', diff: 2, hook: "Your brain is cross-wired: left controls right, right controls left — always.", fact: "~86 billion neurons in the brain. Left hemisphere controls the right side of the body and handles language. Right hemisphere controls the left side and handles creativity. The brain uses ~20% of your body's total energy.", tip: "🧠 Left brain = right body + language. Right brain = left body + creativity. 20% of your energy." },
  { id: 'b3', cat: 'body', emoji: '🫁', subject: 'Body — Lungs', diff: 1, hook: "Your two lungs are deliberately different sizes — not a design flaw.", fact: "Right lung = 3 lobes. Left lung = 2 lobes — smaller to make room for the heart. At rest: ~15 breaths/minute, ~6 litres/minute, over 8,000 litres/day. Gas exchange happens in ~480 million tiny alveoli.", tip: "🧠 Right = 3 lobes. Left = 2 (heart takes space). 480 million alveoli unfolded = tennis court." },
  { id: 'b4', cat: 'body', emoji: '🦴', subject: 'Body — Bones', diff: 1, hook: "You had more bones as a baby — they fused as you grew.", fact: "Adults = 206 bones. Babies = ~270 (fuse by age 25). Bones are living tissue — they constantly rebuild and produce blood cells in marrow. Femur = longest and strongest. Stapes in the ear = smallest at 3mm.", tip: "🧠 206 adult bones. 270 at birth. Femur = longest. Stapes = smallest. Bone is stronger than steel by weight." },
  { id: 'b5', cat: 'body', emoji: '🩸', subject: 'Body — Blood', diff: 1, hook: "That red stuff is doing four completely different jobs simultaneously.", fact: "Blood = red cells (carry O₂) + white cells (fight infection) + platelets (clot wounds) + plasma (transport nutrients). Adults have ~5 litres. Red cells live 120 days. Your body makes 2 million new red cells every second.", tip: "🧠 Red = oxygen. White = defence. Platelets = plug leaks. Plasma = the river. 2M new red cells/second." },
  { id: 'b6', cat: 'body', emoji: '👁️', subject: 'Body — Eyes', diff: 2, hook: "The image your eye sends your brain right now is upside-down.", fact: "Eyes distinguish ~10 million colours. The retina captures images inverted; the brain flips them instantly. Each eye has a blind spot where the optic nerve connects — the brain fills this gap seamlessly.", tip: "🧠 Blind spot test: close one eye, focus ahead, slowly move a finger from the side — it disappears." },
  { id: 'b7', cat: 'body', emoji: '🦠', subject: 'Body — Microbiome', diff: 2, hook: "You are outnumbered — bacteria cells match your human cells in number.", fact: "Your gut contains ~38 trillion bacteria — equal to your total human cell count. These bacteria aid digestion, produce vitamins K and B12, regulate immunity, and influence mood via the gut-brain axis.", tip: "🧠 38 trillion gut bacteria = your human cell count. Gut health affects mood. Antibiotics kill the good too." },
  { id: 'b8', cat: 'body', emoji: '😴', subject: 'Body — Sleep', diff: 1, hook: "You spend a third of your life unconscious — and you'd die faster without it than without food.", fact: "Humans need 7–9 hours of sleep. During sleep: the brain consolidates memories, tissue repairs, and the glymphatic system flushes toxic waste including Alzheimer's-linked proteins. REM sleep handles emotional processing.", tip: "🧠 Sleep clears brain toxins. You die faster without sleep than food. REM = emotional health." },
  { id: 'b9', cat: 'body', emoji: '👅', subject: 'Body — Tongue', diff: 1, hook: "Your tongue is the strongest muscle for its size — but the 'taste map' you learned in school is a myth.", fact: "The famous diagram showing different taste areas of the tongue (sweet at the tip, bitter at the back) is wrong. All taste buds detect all five basic tastes. The myth came from a mistranslated 1901 German study.", tip: "🧠 Tongue 'taste map' = myth. All taste buds taste everything." },
  { id: 'b10', cat: 'body', emoji: '🧬', subject: 'Body — Cells', diff: 2, hook: "Almost every cell in your body has been replaced in the past few years.", fact: "Skin cells last ~2-4 weeks. Stomach lining: 5 days. Red blood cells: 4 months. Liver cells: ~150 days. Skeleton: ~10 years. The major exception: most neurons in the brain stay with you for life.", tip: "🧠 Most cells replace themselves regularly. Brain neurons mostly don't. You're a living renovation site." },
  { id: 'b11', cat: 'body', emoji: '👃', subject: 'Body — Smell', diff: 2, hook: "Smell is the sense most strongly linked to memory.", fact: "Olfactory signals travel directly to the brain's amygdala and hippocampus — the emotion and memory centres — bypassing the thalamus. That's why a familiar scent can instantly trigger vivid memories. Other senses don't have this direct route.", tip: "🧠 Smell skips the thalamus and goes straight to memory + emotion. Why scents trigger flashbacks." },
  { id: 'b12', cat: 'body', emoji: '🦷', subject: 'Body — Teeth', diff: 1, hook: "Tooth enamel is the hardest substance your body produces — but cannot heal itself.", fact: "Tooth enamel is harder than bone. Once damaged, it cannot regenerate (unlike bone or skin). The body has no mechanism to rebuild enamel — which is why cavities require dental fillings rather than healing on their own.", tip: "🧠 Enamel: harder than bone, doesn't heal. Cavities = permanent without dental work." },
  { id: 'b13', cat: 'body', emoji: '💪', subject: 'Body — Muscles', diff: 1, hook: "Smiling uses fewer muscles than frowning.", fact: "A genuine smile uses about 12 facial muscles. A frown uses about 11. So actually frowning uses *fewer* muscles — but the popular wisdom got it backwards. Either way, your facial muscles are very active throughout the day.", tip: "🧠 Smile vs frown: nearly equal effort. The 'smile uses less' myth is the wrong way around." },
  { id: 'b14', cat: 'body', emoji: '👂', subject: 'Body — Hearing', diff: 2, hook: "The smallest bones in your body are inside your ear — and they make hearing possible.", fact: "Three tiny bones — malleus (hammer), incus (anvil), and stapes (stirrup) — sit in the middle ear. They amplify sound vibrations from the eardrum to the inner ear. The stapes is the smallest bone in the body at ~3mm.", tip: "🧠 Hammer, anvil, stirrup — the ossicles. Stapes is the smallest bone in the body." },
  { id: 'b15', cat: 'body', emoji: '🤧', subject: 'Body — Sneezing', diff: 1, hook: "A single sneeze can travel up to 160 km/h.", fact: "Sneezes can reach speeds of 100–160 km/h and project droplets up to 8 metres. They're a reflex triggered by irritation in the nasal lining. You can't sneeze with your eyes open — the reflex closes them automatically.", tip: "🧠 Sneeze speed: ~160 km/h, projects 8m. Eyes always close — automatic reflex." },
  { id: 'b16', cat: 'body', emoji: '🫥', subject: 'Body — Skin', diff: 2, hook: "Your skin is your largest organ — and you shed about 500 million cells from it every day.", fact: "Skin is the body's largest organ — adults have ~1.6–2 m² of it. You shed roughly 500 million skin cells daily — about 0.5–1 kg per year. Most household dust is largely shed human skin.", tip: "🧠 Skin: largest organ, sheds 500M cells/day. Dust = mostly you." },
  { id: 'b17', cat: 'body', emoji: '😅', subject: 'Body — Sweat', diff: 1, hook: "Humans are exceptional sweaters — and that's why we conquered the planet.", fact: "Humans have ~2-4 million sweat glands and can produce up to 2-4 litres of sweat per hour. This makes us extraordinary endurance athletes — we can outrun almost any animal over very long distances by simply not overheating.", tip: "🧠 Sweat = our superpower. Persistence hunting: humans run prey to exhaustion via temperature regulation." },
  { id: 'b18', cat: 'body', emoji: '🦷', subject: 'Body — Saliva', diff: 2, hook: "You produce enough saliva in your lifetime to fill a small swimming pool.", fact: "Adults produce ~1–1.5 litres of saliva daily. Over a lifetime, that's roughly 25,000–30,000 litres — enough to fill a 4x6m above-ground swimming pool. Saliva contains digestive enzymes and antibacterial agents.", tip: "🧠 Lifetime saliva: ~25,000+ litres. Enough for a small swimming pool." },
  { id: 'b19', cat: 'body', emoji: '🧠', subject: 'Body — Memory', diff: 2, hook: "Your brain has effectively unlimited storage — there's no 'full' state.", fact: "Estimates suggest the brain can store ~2.5 petabytes (2.5 million gigabytes) of information. To fill it, you'd have to record TV continuously for 300 years. The bottleneck is encoding and retrieval, not capacity.", tip: "🧠 Brain capacity: ~2.5 petabytes. The problem is finding what you stored, not running out of space." },
  { id: 'b20', cat: 'body', emoji: '🧬', subject: 'Body — Genetics', diff: 2, hook: "You inherit your mitochondrial DNA only from your mother.", fact: "Mitochondria — the energy factories in your cells — have their own DNA, separate from the nuclear DNA in the cell core. Mitochondrial DNA passes only from mother to child. Scientists trace human ancestry through it back to 'Mitochondrial Eve' ~150,000 years ago.", tip: "🧠 Mitochondrial DNA: mother only. Traces back to Mitochondrial Eve ~150,000 years ago." },
  { id: 'b21', cat: 'body', emoji: '👶', subject: 'Body — Babies', diff: 1, hook: "Newborns can't see colour for the first few weeks of life.", fact: "Newborn vision is limited to about 20–40 cm — roughly the distance from a feeding parent's face. Colour vision develops gradually over the first 4–6 months. Their world starts in blurry monochrome and expands quickly.", tip: "🧠 Newborns: blurry, mostly monochrome. Colour kicks in around 4 months." },
  { id: 'b22', cat: 'body', emoji: '🎵', subject: 'Body — Vocal Cords', diff: 2, hook: "Your voice is unique — like a fingerprint, no two are exactly alike.", fact: "Vocal cords vary in length, thickness, and tension between individuals. Combined with skull shape, throat anatomy, and mouth size, they produce voiceprints unique enough to be used for biometric identification.", tip: "🧠 Voiceprints: as unique as fingerprints. Used in biometric ID systems." },
  { id: 'b23', cat: 'body', emoji: '🦷', subject: 'Body — Wisdom Teeth', diff: 1, hook: "Many humans no longer grow wisdom teeth — evolution is removing them.", fact: "An estimated 35% of people are now born without one or more wisdom teeth. Modern diets need less heavy chewing, and our jaws have shrunk over millennia, making the third molars often unnecessary or impacted.", tip: "🧠 ~35% of people born missing 1+ wisdom teeth. Evolution mid-removal." },
  { id: 'b24', cat: 'body', emoji: '👀', subject: 'Body — Tears', diff: 2, hook: "Different types of tears have different chemical compositions.", fact: "Three tear types: basal (constant lubrication), reflex (triggered by irritants like onions), and emotional (from crying). Emotional tears contain higher levels of stress hormones — possibly a literal way to flush stress out.", tip: "🧠 3 tear types: basal, reflex, emotional. Emotional tears have extra stress hormones." },
  { id: 'b25', cat: 'body', emoji: '🩺', subject: 'Body — Liver', diff: 2, hook: "Your liver can regenerate itself — it's the only internal organ that can.", fact: "If up to 70% of the liver is removed (or destroyed), it can regenerate to its original size in weeks to months. This unique ability allows live liver donations — donor regrows the missing portion fully.", tip: "🧠 Liver: only internal organ that regrows. Lose 70%, get it back. Enables live transplants." },
  { id: 'b26', cat: 'body', emoji: '🎂', subject: 'Body — Aging', diff: 2, hook: "You started aging the moment you were born — but the rate isn't fixed.", fact: "Aging is driven by accumulated cellular damage, telomere shortening, and decreased repair efficiency. Lifestyle factors (diet, exercise, sleep, stress) measurably alter biological age — your 'real' age can be years older or younger than your birthday suggests.", tip: "🧠 Biological age ≠ chronological age. Lifestyle can shift it years in either direction." },

  // ============ GRAMMAR (existing 5 + new 20 = 25) ============
  { id: 'g1', cat: 'grammar', emoji: '✍️', subject: 'Grammar — Apostrophes', diff: 1, hook: "One tiny mark that millions of people use wrong every single day.", fact: "Apostrophes do two jobs: possession (Sarah's bag) and contractions (don't = do not). Never for plurals. 'It's' always means 'it is'. 'Its' without apostrophe is the possessive form.", tip: "🧠 Before writing an apostrophe: ownership or shortening? No to both = no apostrophe." },
  { id: 'g2', cat: 'grammar', emoji: '📝', subject: "Grammar — Their/There/They're", diff: 1, hook: "Three words, one sound, three completely different meanings.", fact: "Their = belonging to them. There = a location. They're = they are. Test: say 'they are' out loud. If it works, use they're. If it breaks, choose their or there based on ownership vs location.", tip: "🧠 They're → replace with 'they are'. Works = they're. Doesn't = their (ownership) or there (place)." },
  { id: 'g3', cat: 'grammar', emoji: '💬', subject: 'Grammar — Active vs Passive', diff: 2, hook: "Professional writers default to one of these. Weak writing defaults to the other.", fact: "Active voice: subject performs the action — direct and strong. 'The dog bit the man.' Passive voice: subject receives the action — wordier. 'The man was bitten by the dog.' Passive also hides responsibility: 'Mistakes were made.'", tip: "🧠 Zombie test: add 'by zombies' after the verb. Works = passive. Rewrite as active." },
  { id: 'g4', cat: 'grammar', emoji: '❓', subject: 'Grammar — Who vs Whom', diff: 3, hook: "Even confident native speakers get this wrong.", fact: "'Who' = subject (performs action). 'Whom' = object (receives action). Trick: substitute 'he' or 'him'. If 'he' fits → use who. If 'him' fits → use whom. Who/he = subjects. Whom/him = objects.", tip: "🧠 He = who. Him = whom. Whom and Him both end in M — the memory trick that always works." },
  { id: 'g5', cat: 'grammar', emoji: '📖', subject: 'Grammar — Semicolons', diff: 2, hook: "The most misunderstood punctuation mark in English.", fact: "A semicolon joins two complete, related sentences without a conjunction. 'I was exhausted; I went straight to bed.' Both sides must work as standalone sentences. Never use it between incomplete and complete clauses.", tip: "🧠 Semicolon = soft stop. Both sides = complete sentences. Test: read each side alone. Both work? Use it." },
  { id: 'g6', cat: 'grammar', emoji: '🔠', subject: 'Grammar — Affect vs Effect', diff: 2, hook: "One is a verb, one is a noun — usually.", fact: "Affect = verb (to influence). 'Coffee affects my sleep.' Effect = noun (the result). 'The effect was immediate.' Memory trick: A is for Action (affect = verb), E is for End result (effect = noun).", tip: "🧠 Affect = Action (verb). Effect = End result (noun). Works 95% of the time." },
  { id: 'g7', cat: 'grammar', emoji: '✏️', subject: 'Grammar — Oxford Comma', diff: 1, hook: "One missing comma cost a US dairy company $5 million.", fact: "The Oxford (or serial) comma goes before 'and' in a list: 'apples, oranges, and pears'. In 2018, Oakhurst Dairy in Maine paid $5M after a missing Oxford comma made overtime law ambiguous in a labour contract.", tip: "🧠 Oxford comma: the one before 'and' in a list. Skip it at your peril — it has cost millions in court." },
  { id: 'g8', cat: 'grammar', emoji: '👉', subject: "Grammar — Your/You're", diff: 1, hook: "Two of the most-confused words on the internet.", fact: "Your = belonging to you ('your phone'). You're = you are ('you're late'). Test: replace with 'you are'. If it makes sense, use 'you're'. If not, use 'your'.", tip: "🧠 'You're' = 'you are'. If you can't replace it with 'you are', it's 'your'." },
  { id: 'g9', cat: 'grammar', emoji: '✒️', subject: 'Grammar — Less vs Fewer', diff: 2, hook: "Supermarket signs get this wrong constantly.", fact: "Less = uncountable (less water, less time). Fewer = countable (fewer bottles, fewer minutes). 'Ten items or less' should technically be 'ten items or fewer' — items can be counted.", tip: "🧠 Can you count it? Use FEWER. Can't count it? Use LESS." },
  { id: 'g10', cat: 'grammar', emoji: '➡️', subject: 'Grammar — Then vs Than', diff: 1, hook: "One is about time, the other is about comparison.", fact: "Then = sequence/time ('first this, then that'). Than = comparison ('bigger than, faster than'). They sound similar but mean very different things.", tip: "🧠 Then = time. Than = comparison. Both have the right vowel for the word." },
  { id: 'g11', cat: 'grammar', emoji: '👀', subject: 'Grammar — Lay vs Lie', diff: 3, hook: "Possibly the most-confused verb pair in English.", fact: "Lie = recline, no object ('I lie down'). Lay = to place something ('I lay the book down'). Past tense: lay/laid. The trickiest part: the past tense of 'lie' is 'lay' — making it doubly confusing.", tip: "🧠 Lie = no object (you lie down). Lay = needs an object (you lay something down)." },
  { id: 'g12', cat: 'grammar', emoji: '🧩', subject: 'Grammar — Compound Words', diff: 1, hook: "Some of the longest words in English are just smaller words glued together.", fact: "Compound words combine two or more words into one. Closed: 'notebook'. Hyphenated: 'mother-in-law'. Open: 'high school'. German is famous for extremely long compounds — single words containing whole sentences worth of meaning.", tip: "🧠 Compound = words glued together. Closed, hyphenated, or open. German makes it an art." },
  { id: 'g13', cat: 'grammar', emoji: '🔁', subject: 'Grammar — Homophones', diff: 1, hook: "Words that sound identical but mean completely different things.", fact: "Homophones sound the same but differ in spelling and meaning. Examples: to/too/two, where/wear, see/sea, knight/night. English has thousands of them — leading to most spelling errors.", tip: "🧠 Homophones: same sound, different meaning. To/too/two might be the trickiest trio." },
  { id: 'g14', cat: 'grammar', emoji: '✂️', subject: 'Grammar — Contractions', diff: 1, hook: "The apostrophe in a contraction shows you a letter has been removed.", fact: "Contractions shorten two words by replacing a letter (or two) with an apostrophe. Don't = do not. Can't = cannot. I'm = I am. Won't is the rule-breaker — short for 'will not', from old English 'wonnot'.", tip: "🧠 Contractions: apostrophe replaces missing letters. 'Won't' is the historic outlier." },
  { id: 'g15', cat: 'grammar', emoji: '👈', subject: 'Grammar — Me vs I', diff: 2, hook: "'My friend and I' isn't always correct — sometimes it should be 'my friend and me'.", fact: "Quick test: drop the other person from the sentence. 'My friend and I went' → 'I went' ✓. 'She gave it to my friend and I' → 'She gave it to I' ✗. Should be 'me'. Use I as subject, me as object.", tip: "🧠 Drop the other person. Does 'I' or 'me' sound right alone? That's your answer." },
  { id: 'g16', cat: 'grammar', emoji: '⏰', subject: 'Grammar — Tenses', diff: 2, hook: "English has 12 distinct tenses — most native speakers can't name them all.", fact: "English has 12 tenses across past, present, future and 4 aspects (simple, continuous, perfect, perfect continuous). Examples: 'I will have been working' = future perfect continuous. Most languages have far fewer.", tip: "🧠 12 English tenses. Most natives use them correctly without ever naming them." },
  { id: 'g17', cat: 'grammar', emoji: '🤔', subject: 'Grammar — Double Negatives', diff: 2, hook: "In English, two negatives make a positive — but in many other languages they don't.", fact: "Standard English considers double negatives non-standard ('I don't know nothing' technically = 'I know something'). But in Spanish, French, and many other languages, double negatives are required and reinforce negation.", tip: "🧠 English: 2 negatives = positive (formally). Spanish/French: 2 negatives = stronger negative." },
  { id: 'g18', cat: 'grammar', emoji: '📐', subject: 'Grammar — Adjective Order', diff: 3, hook: "There's a strict order for adjectives in English — you follow it without realising.", fact: "English adjectives follow a strict order: opinion → size → age → shape → colour → origin → material → purpose. 'A lovely small old round red Italian wooden dining table.' Reorder them and it sounds wrong, even if you can't say why.", tip: "🧠 Adjective order: Opinion-Size-Age-Shape-Colour-Origin-Material-Purpose. Native speakers know it instinctively." },
  { id: 'g19', cat: 'grammar', emoji: '🎯', subject: 'Grammar — Ending in Prepositions', diff: 2, hook: "The 'rule' against ending sentences with prepositions is a myth.", fact: "The 'don't end in a preposition' rule was invented by 17th-century English writers trying to make English look more like Latin. It's not a real grammatical rule. Churchill allegedly mocked it: 'This is the sort of nonsense up with which I will not put.'", tip: "🧠 Ending sentences with prepositions = perfectly fine. The 'rule' is a 400-year-old myth." },
  { id: 'g20', cat: 'grammar', emoji: '✏️', subject: "Grammar — i.e. vs e.g.", diff: 2, hook: "Two Latin abbreviations everyone confuses.", fact: "i.e. = 'id est' = 'that is' (used to clarify). e.g. = 'exempli gratia' = 'for example' (used to give examples). Memory: e.g. = Examples Given. i.e. = In Effect, this means.", tip: "🧠 e.g. = Examples Given. i.e. = In Essence. Different jobs entirely." },
  { id: 'g21', cat: 'grammar', emoji: '✂️', subject: "Grammar — Split Infinitives", diff: 3, hook: "Star Trek's 'to boldly go' breaks an old rule that wasn't really a rule.", fact: "Splitting an infinitive (placing a word between 'to' and the verb, e.g. 'to boldly go') was once frowned on. Modern linguists agree it's perfectly fine in English. The 'rule' came from imitating Latin, where infinitives literally can't be split.", tip: "🧠 'To boldly go' = grammatically fine. Old Latin-imitation rule, not a real English problem." },
  { id: 'g22', cat: 'grammar', emoji: '🖐️', subject: "Grammar — Comma Splices", diff: 2, hook: "A comma can't hold two complete sentences together.", fact: "A comma splice happens when two complete sentences are joined with just a comma. 'I was tired, I went home.' (wrong). Fix it with: a period, semicolon, or a coordinating conjunction (and, but, or, etc.) after the comma.", tip: "🧠 Two full sentences need more than a comma. Period, semicolon, or 'and/but'." },
  { id: 'g23', cat: 'grammar', emoji: '🧠', subject: "Grammar — Singular 'They'", diff: 2, hook: "Singular 'they' is not new — Shakespeare used it.", fact: "'They' as a singular pronoun has been used in English for over 600 years. Shakespeare, Chaucer, and Jane Austen all used it. The 'he or she' construction was invented later by 18th-century grammarians trying to formalise the language.", tip: "🧠 Singular 'they': older than Shakespeare. The grammarians who objected came centuries later." },
  { id: 'g24', cat: 'grammar', emoji: '📚', subject: "Grammar — Capitalisation", diff: 1, hook: "English is one of few major languages that capitalises the personal pronoun 'I'.", fact: "Most languages don't capitalise 'I'. English does — likely because lowercase 'i' alone looked too tiny in early manuscripts and got missed. The capital was a practical visual fix that became permanent.", tip: "🧠 Capital 'I': a medieval visual fix that stuck. Most languages don't bother." },
  { id: 'g25', cat: 'grammar', emoji: '✍️', subject: "Grammar — Synonyms", diff: 1, hook: "English has more synonyms than any other language — by a long way.", fact: "English borrowed heavily from Latin, French, Greek, German, and Norse, often keeping multiple words for the same idea. 'Big', 'large', 'huge', 'enormous', 'immense', 'gigantic', 'massive' — all synonyms with subtle differences.", tip: "🧠 English = synonym-rich because it borrowed from everyone. Why a thesaurus is so thick." },

  // ============ PSYCHOLOGY (existing 6 + new 19 = 25) ============
  { id: 'psy1', cat: 'psychology', emoji: '🧠', subject: 'Psychology — Bias', diff: 2, hook: "You are far more irrational than you believe — science has proved it.", fact: "Confirmation bias: the tendency to seek and favour information confirming existing beliefs, while ignoring contradictory evidence. It affects everyone regardless of intelligence. Social media algorithms exploit it deliberately.", tip: "🧠 Confirmation bias: believe first, find 'proof' second. Antidote: actively seek evidence against your own position." },
  { id: 'psy2', cat: 'psychology', emoji: '😊', subject: 'Psychology — Happiness', diff: 1, hook: "Money buys happiness — but only up to a precise point.", fact: "Research found emotional wellbeing increases with income up to ~$100,000/year, after which daily happiness plateaus. However, life satisfaction — how you evaluate your life overall — continues increasing with wealth beyond that.", tip: "🧠 Day-to-day happiness: plateaus ~$100k. Life satisfaction: keeps rising. Two different types of happy." },
  { id: 'psy3', cat: 'psychology', emoji: '👥', subject: 'Psychology — Obedience', diff: 2, hook: "65% of ordinary people will harm someone if an authority figure tells them to.", fact: "Stanley Milgram's experiments (1961) showed 65% of participants would administer what they believed were dangerous electric shocks simply because a scientist instructed them. The study revealed how powerfully authority overrides ethics.", tip: "🧠 Milgram: 65% harmed someone on authority's orders. Explains how ordinary people participate in atrocities." },
  { id: 'psy4', cat: 'psychology', emoji: '🎯', subject: 'Psychology — Memory', diff: 1, hook: "Your memory is not a recording — it gets things wrong every time you access it.", fact: "Human memory is reconstructive, not reproductive. Every retrieval slightly alters the memory. Eyewitness testimony is notoriously unreliable. Elizabeth Loftus demonstrated that false memories can be implanted through suggestion alone.", tip: "🧠 Memory ≠ video playback. It rebuilds each time and changes slightly. 'I clearly remember' ≠ accurate." },
  { id: 'psy5', cat: 'psychology', emoji: '🌊', subject: 'Psychology — Flow', diff: 1, hook: "Athletes call it 'the zone'. Psychologists have studied it for decades.", fact: "'Flow' (coined by Csikszentmihalyi) is complete absorption in a challenging task where time distorts and performance peaks. It occurs when skill and difficulty closely match — too easy = boredom, too hard = anxiety.", tip: "🧠 Flow = skill matches challenge. Boredom = too easy. Anxiety = too hard. Sweet spot = peak performance." },
  { id: 'psy6', cat: 'psychology', emoji: '😴', subject: 'Psychology — Dreams', diff: 2, hook: "You forget 90% of your dreams within 10 minutes of waking up.", fact: "Dreaming occurs primarily during REM sleep. The average person has 4–6 dreams per night but forgets almost all. The prefrontal cortex is less active during REM, so memory encoding is weak — dreams evaporate quickly.", tip: "🧠 Write dreams down immediately on waking — within 2 minutes. After 10 minutes, 90% is gone permanently." },
  { id: 'psy7', cat: 'psychology', emoji: '🪞', subject: 'Psychology — Self-Image', diff: 2, hook: "You don't really know what your own face looks like.", fact: "We see our faces almost exclusively in mirrors — a flipped image. Photographs show us as others see us, which often feels 'wrong'. The 'mere exposure effect' means we slightly prefer the version we see most: our mirror image.", tip: "🧠 You see yourself flipped daily. Photos show the real you — and often look 'off' for that reason." },
  { id: 'psy8', cat: 'psychology', emoji: '👀', subject: 'Psychology — Halo Effect', diff: 2, hook: "If we like one trait in someone, we assume they have other good ones too.", fact: "The halo effect: a positive impression in one area (looks, charisma) leads us to assume other positive traits (intelligence, kindness). Politicians, salespeople, and TV news anchors are picked partly with this in mind.", tip: "🧠 Halo effect: one good trait → assumed others. Why attractive defendants get lighter sentences." },
  { id: 'psy9', cat: 'psychology', emoji: '🎭', subject: 'Psychology — Cognitive Dissonance', diff: 3, hook: "When your beliefs and actions conflict, your brain rewrites the beliefs.", fact: "Cognitive dissonance (Festinger, 1957): mental discomfort when holding contradictory beliefs or behaviour. Rather than change behaviour, people typically change beliefs to match. Smokers, for example, often downplay health risks.", tip: "🧠 Dissonance: brain alters beliefs to match actions, not vice versa. Easier to lie to yourself than change." },
  { id: 'psy10', cat: 'psychology', emoji: '💭', subject: 'Psychology — Anchoring', diff: 2, hook: "The first number you hear influences every estimate that follows.", fact: "Anchoring bias: the first number presented unconsciously skews subsequent judgments. Negotiators use it deliberately. If the first house you see is $500k, $400k seems cheap — even if both are overpriced.", tip: "🧠 Anchoring: first number frames the rest. Why opening offers matter so much in negotiation." },
  { id: 'psy11', cat: 'psychology', emoji: '🤝', subject: 'Psychology — Reciprocity', diff: 1, hook: "We feel a near-unstoppable urge to return favours.", fact: "Reciprocity is one of the strongest social norms. Even small gifts (free samples, restaurant mints with the bill) measurably increase compliance and tipping. Charities use it via 'free' address labels in donation requests.", tip: "🧠 Reciprocity: small gifts trigger return obligation. Why free samples and restaurant mints work." },
  { id: 'psy12', cat: 'psychology', emoji: '💔', subject: 'Psychology — Loss Aversion', diff: 2, hook: "Losing $100 hurts about twice as much as gaining $100 feels good.", fact: "Loss aversion (Kahneman & Tversky): losses are psychologically about 2x more powerful than gains of equal size. This drives risk-averse decision-making, holding losing investments too long, and reluctance to give up sunk costs.", tip: "🧠 Losses sting ~2x more than gains feel good. Why we cling to losing investments." },
  { id: 'psy13', cat: 'psychology', emoji: '👯', subject: 'Psychology — Conformity', diff: 2, hook: "75% of people will give a knowingly wrong answer to fit in with a group.", fact: "Asch's conformity experiments (1951) showed 75% of subjects conformed to a group's obviously wrong answer at least once. Most people will sacrifice accuracy for social belonging — even on trivial perception tasks.", tip: "🧠 Asch: 75% of people went along with the wrong group. Belonging beats truth, often." },
  { id: 'psy14', cat: 'psychology', emoji: '⏳', subject: 'Psychology — Procrastination', diff: 2, hook: "Procrastination isn't laziness — it's emotional regulation.", fact: "Modern psychology defines procrastination as a mood-management strategy, not a time-management problem. We avoid tasks that produce negative emotion (anxiety, boredom, self-doubt). The fix isn't more discipline — it's addressing the underlying feeling.", tip: "🧠 Procrastination = emotional avoidance, not laziness. Address the feeling, not the schedule." },
  { id: 'psy15', cat: 'psychology', emoji: '🌅', subject: 'Psychology — Hedonic Adaptation', diff: 2, hook: "We get used to good things faster than bad things.", fact: "Hedonic adaptation: humans return to a baseline of happiness regardless of major life events. Lottery winners and accident victims report similar life satisfaction within ~1 year of their event. Joy from new purchases fades within weeks.", tip: "🧠 We adapt to anything — good or bad. Lottery wins fade. Tragedy heals. Both faster than expected." },
  { id: 'psy16', cat: 'psychology', emoji: '👶', subject: 'Psychology — Attachment', diff: 2, hook: "Your earliest relationships shape your adult ones — measurably.", fact: "Attachment theory (Bowlby & Ainsworth): infant bonds with caregivers form one of three styles — secure, anxious, or avoidant — that significantly predict adult relationship patterns. About 60% of adults are securely attached.", tip: "🧠 Attachment styles: secure, anxious, avoidant. Set in infancy, shape adult relationships." },
  { id: 'psy17', cat: 'psychology', emoji: '🎁', subject: 'Psychology — Generosity', diff: 1, hook: "Spending money on others makes you happier than spending it on yourself.", fact: "Studies (Dunn et al., 2008) show prosocial spending — giving gifts, donating, treating others — produces greater and longer-lasting happiness than spending the same amount on yourself. The effect is consistent across cultures.", tip: "🧠 Spend on others = more happiness than spending on yourself. Counter-intuitive but well-replicated." },
  { id: 'psy18', cat: 'psychology', emoji: '😨', subject: 'Psychology — Fear of Failure', diff: 2, hook: "Fear of failure often outweighs the actual cost of failing.", fact: "Studies show people commonly overestimate the long-term emotional impact of failure. The 'affective forecasting' error: we predict negative events will hurt longer and more deeply than they actually do. We rebound faster than we expect.", tip: "🧠 You bounce back faster than you fear. The dread of failure exceeds the actual sting." },
  { id: 'psy19', cat: 'psychology', emoji: '🤖', subject: 'Psychology — Pareidolia', diff: 1, hook: "Why you see a face in your toast.", fact: "Pareidolia is the brain's tendency to find patterns — especially faces — in random stimuli. We evolved to over-detect faces because missing one (a predator hiding in foliage) was costlier than seeing one that wasn't there.", tip: "🧠 Pareidolia: face-spotting in clouds, toast, and electrical sockets. Better safe than sorry, evolutionarily." },
  { id: 'psy20', cat: 'psychology', emoji: '🔍', subject: 'Psychology — Selective Attention', diff: 2, hook: "You can be looking right at something and completely fail to see it.", fact: "The famous 'invisible gorilla' experiment: when asked to count basketball passes, half of viewers fail to notice a person in a gorilla suit walking through. This is 'inattentional blindness' — focused attention can erase obvious objects.", tip: "🧠 Focus = blindness to the unexpected. Half of people miss the gorilla on first viewing." },
  { id: 'psy21', cat: 'psychology', emoji: '⏰', subject: 'Psychology — Planning Fallacy', diff: 2, hook: "We always think we'll finish things faster than we actually do.", fact: "The planning fallacy: humans systematically underestimate the time, costs, and risks of future tasks while overestimating their benefits. Even people warned about it still fall for it. Major construction projects average ~50% over budget for this reason.", tip: "🧠 Planning fallacy: we always think it'll be faster than it is. Add 50%, then add some more." },
  { id: 'psy22', cat: 'psychology', emoji: '🌧️', subject: 'Psychology — Mood', diff: 1, hook: "The weather affects your judgment more than you think.", fact: "Studies show stock market returns, university admissions decisions, and even job interview ratings correlate with weather. Sunny days produce more lenient and optimistic decisions. Cloudy days produce more cautious ones.", tip: "🧠 Sunny day = more generous decisions. Even university admissions lean weather-warm." },
  { id: 'psy23', cat: 'psychology', emoji: '😱', subject: 'Psychology — Stress', diff: 2, hook: "A small amount of stress actually improves performance.", fact: "The Yerkes-Dodson law: performance increases with arousal/stress up to an optimum, then declines. Too little stress = boredom and apathy. Too much = panic and freeze. Peak performance lives in the 'productive stress' zone.", tip: "🧠 Yerkes-Dodson: a little stress helps, too much hurts. Sweet spot = peak performance." },
  { id: 'psy24', cat: 'psychology', emoji: '🔮', subject: 'Psychology — Hindsight Bias', diff: 2, hook: "After something happens, we always think we 'knew it all along'.", fact: "Hindsight bias: people retroactively believe past events were more predictable than they actually were. After elections, market crashes, or sports upsets, almost everyone claims they 'saw it coming'. They didn't.", tip: "🧠 Hindsight bias: 'I knew it' after the fact. Almost no one actually predicted it." },
  { id: 'psy25', cat: 'psychology', emoji: '🧘', subject: 'Psychology — Mindfulness', diff: 1, hook: "8 weeks of meditation measurably changes your brain structure.", fact: "Studies (Harvard, 2011) showed 8 weeks of mindfulness meditation produced measurable increases in grey matter density in regions linked to learning, memory, and emotion regulation — and decreases in the amygdala (fear centre).", tip: "🧠 8 weeks of meditation = visible brain changes. Less amygdala (fear), more learning regions." },

  // ============ ECONOMICS (existing 5 + new 20 = 25) ============
  { id: 'eco1', cat: 'economics', emoji: '💰', subject: 'Economics — Inflation', diff: 1, hook: "Your money is losing value right now — even sitting still in your wallet.", fact: "Inflation = the rate at which prices rise, reducing purchasing power. If inflation is 5%, something costing €100 last year costs €105 today. Central banks target ~2% annual inflation as healthy for a growing economy.", tip: "🧠 Inflation = money buys less over time. 2% = healthy. Above 5% = problem. Cash idle loses value yearly." },
  { id: 'eco2', cat: 'economics', emoji: '📈', subject: 'Economics — Supply & Demand', diff: 1, hook: "Every price you've ever paid was determined by this one law.", fact: "Supply up + demand same = prices fall. Demand up + supply same = prices rise. This law of supply and demand underpins all market economics — from house prices to concert tickets to petrol.", tip: "🧠 Scarce + wanted = expensive. Abundant + unwanted = cheap. Every market price = supply meeting demand." },
  { id: 'eco3', cat: 'economics', emoji: '🏦', subject: 'Economics — Interest Rates', diff: 2, hook: "When central banks change one number, every mortgage on Earth is affected.", fact: "Central banks set base interest rates — the cost of borrowing. Higher rates = expensive loans = less spending = inflation cools. Lower rates = cheap borrowing = more spending = economic stimulus.", tip: "🧠 Rates up = borrowing costs more = less spending = inflation drops. Rates down = more growth." },
  { id: 'eco4', cat: 'economics', emoji: '📊', subject: 'Economics — GDP', diff: 1, hook: "One number attempts to measure the entire economic output of a country.", fact: "GDP = total monetary value of all goods and services produced in a country per year. USA leads (~$27 trillion), China is second (~$18 trillion). Two consecutive quarters of shrinking GDP = recession.", tip: "🧠 GDP shrinks 2 quarters in a row = recession (official definition). USA: ~$27T. China: ~$18T." },
  { id: 'eco5', cat: 'economics', emoji: '💸', subject: 'Economics — Compound Interest', diff: 1, hook: "Einstein allegedly called this the eighth wonder of the world.", fact: "Compound interest = earning interest on principal AND previously earned interest. €1,000 at 7% annual return doubles to €2,000 in ~10 years, €4,000 in 20, €8,000 in 30 — without adding a cent.", tip: "🧠 Rule of 72: divide 72 by the interest rate = years to double. 72 ÷ 7% = ~10 years to double." },
  { id: 'eco6', cat: 'economics', emoji: '📉', subject: 'Economics — Recessions', diff: 2, hook: "Recessions are technically defined — but informally judged.", fact: "The technical definition: 2 consecutive quarters of negative GDP growth. The US National Bureau of Economic Research (NBER) uses a broader definition including employment, income, and industrial production. So a country can be 'in recession' by one measure and not the other.", tip: "🧠 Recession: technical = 2 quarters negative GDP. Real-world = broader picture. Both definitions exist." },
  { id: 'eco7', cat: 'economics', emoji: '💵', subject: 'Economics — Currency', diff: 1, hook: "Most modern money exists only as numbers in databases.", fact: "Roughly 90% of money in modern economies exists only as digital entries in bank accounts — never printed as physical cash. The remaining ~10% is physical currency. When you 'transfer money', a database entry changes — no actual movement happens.", tip: "🧠 90% of money = digital only. Bank transfers = database edits, not movement of cash." },
  { id: 'eco8', cat: 'economics', emoji: '🏠', subject: 'Economics — Housing Markets', diff: 2, hook: "House prices have outpaced wages in most developed countries for decades.", fact: "Since the 1980s, house price growth has significantly outpaced wage growth in the US, UK, Canada, Australia, and most of Europe. Causes include low interest rates, restricted supply, foreign investment, and demographic pressure.", tip: "🧠 Houses got expensive faster than salaries. Decades of imbalance, multiple causes." },
  { id: 'eco9', cat: 'economics', emoji: '🌐', subject: 'Economics — Globalisation', diff: 2, hook: "Most products you use crossed at least 3 countries before reaching you.", fact: "A typical iPhone involves design (USA), components from Japan, Korea, Taiwan, China, and assembly in China. Global supply chains spread production across dozens of countries to optimise cost, expertise, and proximity.", tip: "🧠 Most products = multi-country journeys. iPhone alone touches dozens of nations before sale." },
  { id: 'eco10', cat: 'economics', emoji: '⚖️', subject: 'Economics — Inequality', diff: 2, hook: "The wealthiest 1% of the world owns more than the bottom 50% combined.", fact: "Oxfam research consistently shows the top 1% of global wealth holders own more than the entire bottom 50%. Wealth concentration has accelerated since the 1980s, particularly through asset ownership (stocks, property).", tip: "🧠 Top 1% > bottom 50% in global wealth. Driven by asset ownership concentration." },
  { id: 'eco11', cat: 'economics', emoji: '🪙', subject: 'Economics — Bitcoin', diff: 2, hook: "There will only ever be 21 million Bitcoin — and that's hardcoded.", fact: "Bitcoin's protocol limits the total supply to exactly 21 million coins. The final coin is projected to be mined around the year 2140. This artificial scarcity (vs unlimited fiat printing) is central to its value proposition.", tip: "🧠 Bitcoin: 21M total, ever. Last one mined ~2140. Scarcity is a design feature." },
  { id: 'eco12', cat: 'economics', emoji: '📦', subject: 'Economics — Specialisation', diff: 2, hook: "No single human alive could make a pencil from scratch.", fact: "Leonard Read's famous 1958 essay 'I, Pencil' showed that producing a single pencil requires the coordinated work of thousands of people across many countries — loggers, miners, chemists, factory workers, etc. No one knows how to do it all alone.", tip: "🧠 Even a pencil = global coordination of thousands. Specialisation is what makes everything possible." },
  { id: 'eco13', cat: 'economics', emoji: '🧾', subject: 'Economics — Taxes', diff: 1, hook: "Income tax is a relatively recent invention.", fact: "Britain introduced the world's first modern income tax in 1799 to fund the Napoleonic Wars. The US permanently introduced one in 1913 (16th Amendment). Most countries adopted it during the 20th century.", tip: "🧠 Income tax: invented 1799 (UK, war funding). US permanent: 1913. Modern norm — historically new." },
  { id: 'eco14', cat: 'economics', emoji: '🏭', subject: 'Economics — Industrial Revolution', diff: 2, hook: "The biggest economic shift in history happened in just 100 years.", fact: "Between 1750 and 1850, GDP per capita more than doubled in Britain and Western Europe — after staying nearly flat for ~1,000 years. Mechanisation, coal, and factory production transformed agriculture-based economies into industrial ones.", tip: "🧠 Industrial Revolution: per-capita wealth doubled in 100 years after staying flat for 1,000." },
  { id: 'eco15', cat: 'economics', emoji: '🪙', subject: 'Economics — Hyperinflation', diff: 2, hook: "Hungary once had banknotes for 100 quintillion pengő.", fact: "Post-WW2 Hungary suffered the worst hyperinflation in history. By July 1946, prices doubled every ~15 hours. The largest banknote ever printed was the 100 quintillion (10²⁰) pengő note. The currency was eventually replaced by the forint.", tip: "🧠 Worst hyperinflation: Hungary 1946. Prices doubled every 15 hours. 100 quintillion-pengő note." },
  { id: 'eco16', cat: 'economics', emoji: '🏬', subject: 'Economics — Monopolies', diff: 2, hook: "Standard Oil controlled 90% of US oil refining — until the government broke it up.", fact: "John D. Rockefeller's Standard Oil controlled ~90% of US oil refining by 1880. The 1911 Supreme Court ruling broke it into 34 separate companies — including ancestors of today's ExxonMobil and Chevron.", tip: "🧠 Standard Oil: 90% market share, broken up 1911. ExxonMobil and Chevron descend from the pieces." },
  { id: 'eco17', cat: 'economics', emoji: '🛢️', subject: 'Economics — OPEC', diff: 2, hook: "Twelve countries control over a third of world oil production.", fact: "OPEC (Organization of Petroleum Exporting Countries) — currently 12 member states — controls about 35–40% of global oil production. Decisions to cut or raise output cause major swings in global oil prices.", tip: "🧠 OPEC: 12 countries, ~35%+ of world oil. Their meetings move global prices." },
  { id: 'eco18', cat: 'economics', emoji: '💼', subject: 'Economics — Unemployment', diff: 1, hook: "Some unemployment is considered necessary for a healthy economy.", fact: "Most economists consider 3–5% unemployment 'natural' — accounting for people moving between jobs and short-term mismatches. Below this can cause inflation; above can signal economic distress.", tip: "🧠 'Natural' unemployment: 3–5%. Lower = inflation pressure. Higher = recession risk." },
  { id: 'eco19', cat: 'economics', emoji: '📉', subject: 'Economics — Stock Market', diff: 2, hook: "The US stock market has gone up about 7% per year on average — for over 100 years.", fact: "Since 1900, the US S&P 500 has averaged ~7% annual real return (after inflation). Despite huge crashes (1929, 1987, 2008, 2020), the long-term trend has consistently been upward. Time in the market beats timing the market.", tip: "🧠 S&P 500 long-term average: ~7% real return per year. Time beats timing." },
  { id: 'eco20', cat: 'economics', emoji: '💎', subject: 'Economics — Diamonds', diff: 2, hook: "Diamonds aren't actually rare — their price is artificially maintained.", fact: "Diamonds are relatively common geologically. The De Beers cartel created the impression of scarcity in the 20th century by tightly controlling supply and launching the famous 'A Diamond is Forever' campaign in 1947 to drive demand.", tip: "🧠 Diamonds: not rare. The price was engineered by De Beers in the 20th century." },
  { id: 'eco21', cat: 'economics', emoji: '🚢', subject: 'Economics — Containers', diff: 2, hook: "The shipping container quietly transformed global trade.", fact: "Before standardised containers (1956 onward), cargo was loaded item-by-item. Containerisation cut shipping costs by ~90% and time to load/unload by similar margins. It's arguably the single biggest enabler of modern globalisation.", tip: "🧠 Container shipping (1956): cut shipping cost ~90%. Quiet revolution behind globalisation." },
  { id: 'eco22', cat: 'economics', emoji: '☕', subject: 'Economics — Coffee Trade', diff: 2, hook: "Coffee is the second-most traded commodity in the world after oil.", fact: "Approximately 2.25 billion cups of coffee are consumed daily worldwide. The global coffee market is worth over $100 billion annually. Brazil produces about 40% of the world's coffee.", tip: "🧠 Coffee: 2.25 billion cups/day. Brazil = 40% of supply. 2nd most-traded commodity after oil." },
  { id: 'eco23', cat: 'economics', emoji: '💳', subject: 'Economics — Credit Cards', diff: 1, hook: "The first credit card was invented because someone forgot their wallet.", fact: "In 1949, businessman Frank McNamara forgot his wallet at a New York restaurant. He devised the Diners Club card — the first credit card — in 1950. By 1951 it had 20,000 members. Universal payment cards followed.", tip: "🧠 First credit card: Diners Club, 1950. Sparked by a forgotten wallet at a restaurant." },
  { id: 'eco24', cat: 'economics', emoji: '🏠', subject: 'Economics — Mortgages', diff: 2, hook: "The word 'mortgage' literally means 'death pledge' in Old French.", fact: "'Mortgage' comes from Old French 'mort' (dead) + 'gage' (pledge). The 'death' refers to the pledge dying when either the debt is paid off, or the property is forfeited. Originally a literal way to describe its all-or-nothing nature.", tip: "🧠 Mortgage = 'death pledge'. The pledge dies when you pay off — or you do." },
  { id: 'eco25', cat: 'economics', emoji: '⚙️', subject: 'Economics — Productivity', diff: 2, hook: "An hour of human work produces ~50x more economic output than it did in 1800.", fact: "Since 1800, productivity per worker hour has multiplied roughly 50-fold in developed countries. Drivers: machinery, electricity, computers, education, and now automation. Real wages have risen — though not always proportionally.", tip: "🧠 Productivity per hour ≈ 50x higher than in 1800. Wages rose, but not by as much." },

  // ============ INVENTIONS (existing 6 + new 19 = 25) ============
  { id: 'inv1', cat: 'inventions', emoji: '💡', subject: 'Inventions — Light Bulb', diff: 1, hook: "Thomas Edison did not invent the light bulb — he commercialised it.", fact: "Humphry Davy demonstrated electric light in 1802. Joseph Swan patented a working bulb in Britain in 1878. Edison patented his improved version in 1879 and built the entire electrical distribution infrastructure to make it practical.", tip: "🧠 Edison: didn't invent the bulb, made it practical, built the grid. The system was the innovation." },
  { id: 'inv2', cat: 'inventions', emoji: '🌐', subject: 'Inventions — Internet vs Web', diff: 1, hook: "The internet and the World Wide Web are not the same thing.", fact: "The internet originated from ARPANET in 1969. The World Wide Web — websites and browsers — was invented by Tim Berners-Lee in 1989 at CERN. The web runs on the internet, but the internet existed 20 years before the web.", tip: "🧠 Internet = infrastructure (1969). Web = websites (1989). Berners-Lee invented the Web, not the internet." },
  { id: 'inv3', cat: 'inventions', emoji: '✈️', subject: 'Inventions — Flight', diff: 1, hook: "The Wright Brothers' first flight covered less than the wingspan of a Boeing 747.", fact: "The Wright Brothers achieved the first powered flight on 17 December 1903 at Kitty Hawk. It lasted 12 seconds and covered 37 metres. A Boeing 747 wingspan is 68 metres. They were bicycle mechanics with no engineering degrees.", tip: "🧠 First flight: 1903, 12 seconds, 37 metres. 747 wingspan > entire first flight. Bicycle mechanics." },
  { id: 'inv4', cat: 'inventions', emoji: '💊', subject: 'Inventions — Penicillin', diff: 1, hook: "One of medicine's greatest discoveries happened because a scientist left a dish dirty.", fact: "Alexander Fleming discovered penicillin in 1928 when mould contaminated a bacteria culture and killed surrounding bacteria. He noticed and investigated. Penicillin mass-produced in WW2 has since saved over 200 million lives.", tip: "🧠 Fleming, 1928, accidental discovery. 200 million lives saved. The lucky dirty dish changed medicine." },
  { id: 'inv5', cat: 'inventions', emoji: '🖨️', subject: 'Inventions — Printing Press', diff: 2, hook: "One machine in 1440 directly caused the Renaissance, the Reformation, and the Scientific Revolution.", fact: "Gutenberg invented the movable-type printing press around 1440. Before it, books were hand-copied and expensive. Within 50 years, over 20 million books circulated across Europe. Mass literacy and the spread of ideas trace back to this machine.", tip: "🧠 Gutenberg press: 1440. Before: books = luxury. After: ideas at scale. The internet of the 15th century." },
  { id: 'inv6', cat: 'inventions', emoji: '🧲', subject: 'Inventions — Radio', diff: 2, hook: "Marconi is credited with inventing radio — but a court ruled someone else did it first.", fact: "Marconi sent the first transatlantic radio signal in 1901. But the US Supreme Court ruled in 1943 that Nikola Tesla's earlier patents predated Marconi's core claims. The ruling came months after Tesla's death.", tip: "🧠 Marconi: credited with radio, 1901. Tesla: original patents, 1893. Court ruled for Tesla after he died." },
  { id: 'inv7', cat: 'inventions', emoji: '📱', subject: 'Inventions — Mobile Phone', diff: 1, hook: "The first mobile phone call was made in 1973 — on a phone that weighed over a kilogram.", fact: "Motorola engineer Martin Cooper made the first mobile phone call on 3 April 1973, in New York. The Motorola DynaTAC weighed ~1.1 kg, took 10 hours to charge, and gave just 30 minutes of talk time. He famously called his rival at Bell Labs.", tip: "🧠 First mobile call: 1973, Motorola DynaTAC. 1.1 kg, 30 min talk time, 10 hour charge." },
  { id: 'inv8', cat: 'inventions', emoji: '🚗', subject: 'Inventions — Car', diff: 1, hook: "Karl Benz built the first true automobile — and his wife took it on the world's first road trip.", fact: "Karl Benz patented the Motorwagen in 1886 — generally considered the first true automobile. In 1888, his wife Bertha Benz took it on a 106 km journey to demonstrate practicality, becoming the first long-distance driver in history.", tip: "🧠 Karl Benz: first car, 1886. Bertha Benz: first road trip, 1888. The Benzes did both." },
  { id: 'inv9', cat: 'inventions', emoji: '📷', subject: 'Inventions — Photography', diff: 2, hook: "The first photograph took 8 hours of exposure to capture a single image.", fact: "Joseph Nicéphore Niépce took the world's first surviving photograph in 1826 — 'View from the Window at Le Gras'. It required 8 hours of exposure. By 1839, Daguerreotypes shortened that to minutes. Modern phones do it in microseconds.", tip: "🧠 First photo: 1826, 8 hours of exposure. Modern phone: ~1/1000 of a second. Same idea, vastly faster." },
  { id: 'inv10', cat: 'inventions', emoji: '🎬', subject: 'Inventions — Film', diff: 2, hook: "The Lumière Brothers screened the first film to a paying audience in 1895.", fact: "On 28 December 1895, the Lumière Brothers held the first commercial public film screening in Paris. Audiences reportedly fled the theatre during 'L'Arrivée d'un Train' (The Arrival of a Train), believing the train would crash into them.", tip: "🧠 First commercial film: Lumières, 1895. Audiences allegedly fled the train scene. New medium, real shock." },
  { id: 'inv11', cat: 'inventions', emoji: '⚙️', subject: 'Inventions — Steam Engine', diff: 2, hook: "The steam engine quite literally powered the Industrial Revolution.", fact: "Thomas Newcomen built the first practical steam engine in 1712. James Watt's improvements (1765–1776) made it efficient enough to drive factories, trains, and ships. The steam age transformed manufacturing, transport, and society for ~150 years.", tip: "🧠 Newcomen: 1712 first. Watt: 1776 efficient. The engine that powered industry for 150 years." },
  { id: 'inv12', cat: 'inventions', emoji: '🔌', subject: 'Inventions — Electricity Grid', diff: 2, hook: "The 'War of the Currents' decided how the world would be powered.", fact: "In the 1880s–90s, Edison (DC current) battled Tesla and Westinghouse (AC current). AC won because it transmits power over long distances efficiently. The 1893 Chicago World's Fair ran on AC — sealing the verdict.", tip: "🧠 Edison: DC. Tesla/Westinghouse: AC. AC won — efficient over distance. Why our grid is AC today." },
  { id: 'inv13', cat: 'inventions', emoji: '🛰️', subject: 'Inventions — Satellite', diff: 1, hook: "The world's first satellite was about the size of a beach ball.", fact: "Sputnik 1, launched by the USSR on 4 October 1957, was the first artificial satellite. ~58 cm wide, ~83 kg. It transmitted simple beeps for 22 days. Its launch shocked the US and triggered the Space Race.", tip: "🧠 Sputnik 1: 1957, beach-ball-sized, just beeped. Sparked the Space Race." },
  { id: 'inv14', cat: 'inventions', emoji: '🔬', subject: 'Inventions — Microscope', diff: 2, hook: "The microscope revealed an entire world that nobody knew existed.", fact: "Antonie van Leeuwenhoek refined the microscope in the 1670s and was first to observe bacteria, single-celled organisms, sperm cells, and red blood cells. He called them 'animalcules'. Until then, microscopic life was completely unknown.", tip: "🧠 Leeuwenhoek (1670s): first to see bacteria. Whole worlds were invisible until then." },
  { id: 'inv15', cat: 'inventions', emoji: '🖥️', subject: 'Inventions — Computer', diff: 2, hook: "The first general-purpose electronic computer weighed 30 tonnes.", fact: "ENIAC (1945) was the first programmable, general-purpose electronic digital computer. It weighed ~30 tonnes, used 18,000 vacuum tubes, occupied a 167 m² room, and consumed 150 kW of power. A modern smartphone is millions of times faster.", tip: "🧠 ENIAC, 1945: 30 tonnes, room-sized, 150 kW. Phone in your pocket = millions of times faster." },
  { id: 'inv16', cat: 'inventions', emoji: '🧊', subject: 'Inventions — Refrigeration', diff: 1, hook: "Before fridges, ice was harvested from frozen lakes and shipped around the world.", fact: "Mechanical refrigeration was invented in the 1830s but didn't reach homes until the 1920s. Before that, the 'ice trade' shipped enormous blocks of harvested lake ice across continents — even from New England to India and the Caribbean.", tip: "🧠 Before fridges: literal blocks of lake ice shipped globally. Fridges in homes only post-1920s." },
  { id: 'inv17', cat: 'inventions', emoji: '🚿', subject: 'Inventions — Plumbing', diff: 2, hook: "Indoor plumbing existed in ancient Rome — and was then forgotten for 1,500 years.", fact: "Roman aqueducts, public baths, and indoor plumbing were widespread by 50 AD. After Rome's fall, most of Europe lost the technology. Reliable indoor plumbing didn't return widely until the 19th century — a 1,500 year gap.", tip: "🧠 Romans had plumbing. Europe forgot it for 1,500 years. Hygiene took a long detour." },
  { id: 'inv18', cat: 'inventions', emoji: '🧠', subject: 'Inventions — AI', diff: 2, hook: "The term 'Artificial Intelligence' was coined in 1956 — at a single workshop.", fact: "The Dartmouth Workshop of summer 1956 — proposed by John McCarthy — coined the term 'Artificial Intelligence' and launched the field. Many of the foundational ideas (neural networks, machine learning, natural language) trace back to that summer.", tip: "🧠 'AI' coined 1956 at the Dartmouth Workshop. The field officially started there." },
  { id: 'inv19', cat: 'inventions', emoji: '🚂', subject: 'Inventions — Trains', diff: 1, hook: "The first public passenger railway opened almost 200 years ago.", fact: "The Stockton and Darlington Railway in England opened on 27 September 1825 — the world's first public passenger steam railway. Within 50 years, railways had revolutionised global trade, travel, time zones, and city growth.", tip: "🧠 First public railway: 1825, England. Railways even forced the invention of standard time zones." },
  { id: 'inv20', cat: 'inventions', emoji: '🩻', subject: 'Inventions — X-Rays', diff: 2, hook: "X-rays were discovered by accident in 1895 — and the first human X-ray was of a hand.", fact: "Wilhelm Röntgen accidentally discovered X-rays in 1895 while experimenting with cathode rays. The first medical X-ray ever was of his wife's hand, showing her wedding ring. Within months, X-rays were being used in hospitals.", tip: "🧠 X-rays: discovered by accident, 1895. First human X-ray: Mrs Röntgen's hand and ring." },
  { id: 'inv21', cat: 'inventions', emoji: '🧬', subject: 'Inventions — DNA Discovery', diff: 2, hook: "The structure of DNA was figured out in 1953 — partly thanks to a researcher who didn't get credit.", fact: "Watson and Crick proposed the DNA double helix in 1953 — using crucial X-ray diffraction images taken by Rosalind Franklin (without her knowledge). Watson, Crick, and Wilkins shared the Nobel Prize. Franklin had died of cancer 4 years earlier.", tip: "🧠 DNA structure: Watson & Crick 1953 — using Franklin's data. Nobel given posthumously couldn't include her." },
  { id: 'inv22', cat: 'inventions', emoji: '🚀', subject: 'Inventions — Rockets', diff: 2, hook: "Modern rockets descend directly from a 13th-century Chinese invention.", fact: "Chinese alchemists invented gunpowder around the 9th century AD. By the 13th century, military rockets were used in warfare. The basic principle — burning fuel for thrust — directly underlies every modern rocket from Saturn V to Falcon 9.", tip: "🧠 Rockets started as 13th-century Chinese weapons. Same physics powers SpaceX today." },
  { id: 'inv23', cat: 'inventions', emoji: '💾', subject: 'Inventions — Hard Drive', diff: 2, hook: "The first commercial hard drive in 1956 stored 5 MB — and was the size of two fridges.", fact: "IBM's RAMAC 305 (1956) was the first commercial computer with a hard disk drive. It stored 5 MB of data on 50 stacked 24-inch disks. It weighed over a tonne and cost ~$50,000/year to lease. Today: a tiny chip stores ~1 million times more.", tip: "🧠 First HDD: 1956, 5 MB, fridge-sized, $50k/year. Today's chip = a million times denser." },
  { id: 'inv24', cat: 'inventions', emoji: '🔐', subject: 'Inventions — Encryption', diff: 3, hook: "The encryption protecting your bank details was invented in 1977.", fact: "RSA encryption — the foundation of modern internet security — was invented by Rivest, Shamir, and Adleman at MIT in 1977. It enables secure online banking, e-commerce, and private messaging by using mathematical operations almost impossible to reverse.", tip: "🧠 RSA encryption: 1977, MIT. The math behind every secure HTTPS connection you use." },
  { id: 'inv25', cat: 'inventions', emoji: '🦠', subject: 'Inventions — Vaccines', diff: 2, hook: "The first vaccine was made from cow pus.", fact: "Edward Jenner created the first vaccine in 1796 by deliberately infecting a boy with cowpox (a mild disease). The boy then proved immune to smallpox (a deadly one). 'Vaccine' comes from 'vacca' = cow. Smallpox was eradicated in 1980 — the only human disease ever eliminated.", tip: "🧠 First vaccine: cowpox, 1796. 'Vaccine' = from 'cow' (Latin). Smallpox: eradicated 1980." },

  // ============ FOOD SCIENCE (existing 6 + new 19 = 25) ============
  { id: 'food1', cat: 'food', emoji: '🍕', subject: 'Food Science — Taste', diff: 1, hook: "Your nose does about 80% of the tasting — your tongue only contributes 20%.", fact: "Humans have 5 basic tastes: sweet, salty, sour, bitter, and umami. But ~80% of what we perceive as flavour is actually smell. This is why food tastes bland with a blocked nose. Flavour = taste + smell + texture.", tip: "🧠 5 tastes: sweet, salty, sour, bitter, umami. Block nose while eating = almost no flavour. Taste ≠ flavour." },
  { id: 'food2', cat: 'food', emoji: '🌶️', subject: 'Food Science — Spice', diff: 1, hook: "Chilli heat isn't a taste — it's literally pain.", fact: "Capsaicin in chillies triggers TRPV1 pain receptors, not taste receptors. The brain releases endorphins in response — why spicy food feels addictive. Milk neutralises capsaicin (fat-soluble). Water spreads it (not water-soluble).", tip: "🧠 Spice = pain receptors, not taste. Milk kills the burn. Water spreads it. Endorphins = the spicy high." },
  { id: 'food3', cat: 'food', emoji: '🍫', subject: 'Food Science — Chocolate', diff: 1, hook: "White chocolate technically isn't chocolate at all.", fact: "Dark and milk chocolate contain cocoa solids — ground cacao. White chocolate contains only cocoa butter, sugar, and milk — zero cocoa solids. Dark chocolate (70%+) contains flavanols that measurably improve cardiovascular health.", tip: "🧠 White chocolate = no cocoa solids = not really chocolate. Dark 70%+ = real health benefits." },
  { id: 'food4', cat: 'food', emoji: '🥑', subject: 'Food Science — Ethylene', diff: 2, hook: "Putting a banana next to an avocado makes it ripen faster — there's a scientific reason.", fact: "Many fruits produce ethylene gas as they ripen, triggering ripening in nearby fruit. Bananas are high ethylene emitters. Sealing an unripe avocado with a banana speeds ripening. Keeping bananas away from other fruit slows their ripening.", tip: "🧠 Ethylene = ripening gas. Banana with avocado = faster ripe. Store bananas separately to slow ripening." },
  { id: 'food5', cat: 'food', emoji: '☕', subject: 'Food Science — Caffeine', diff: 1, hook: "Caffeine doesn't give you energy — it just blocks the signal that tells you you're tired.", fact: "Caffeine blocks adenosine receptors. Adenosine builds up throughout the day and signals tiredness. Caffeine blocks the same receptors so fatigue signals can't reach the brain. When it wears off, the adenosine floods back — the crash.", tip: "🧠 Caffeine blocks tiredness — doesn't create energy. The crash = adenosine flood when caffeine clears." },
  { id: 'food6', cat: 'food', emoji: '🍞', subject: 'Food Science — Fermentation', diff: 2, hook: "Bread dough is alive — right up until you put it in the oven.", fact: "Leavened bread uses yeast — a living microorganism. Yeast consumes dough sugars and produces CO₂ and alcohol. CO₂ bubbles cause the dough to rise. The oven kills the yeast. Beer and bread use identical biology.", tip: "🧠 Yeast eats sugar → CO₂ + alcohol → dough rises → oven kills yeast → bread. Same process as beer." },
  { id: 'food7', cat: 'food', emoji: '🍷', subject: 'Food Science — Wine', diff: 2, hook: "Red wine, white wine, and rosé all start from grapes that are technically the same colour inside.", fact: "Almost all grape juice is clear, regardless of grape skin colour. Red wine gets its colour from soaking the skins with the juice during fermentation. White wine: skins removed early. Rosé: brief skin contact only.", tip: "🧠 Wine colour = skin contact during fermentation. The juice itself is nearly clear in all grapes." },
  { id: 'food8', cat: 'food', emoji: '🧀', subject: 'Food Science — Cheese', diff: 1, hook: "Cheese is essentially a way to preserve milk — for thousands of years.", fact: "Cheese-making is at least 7,000 years old. Milk left in animal-stomach containers naturally curdled (the rennet enzyme is in stomach lining). Cheese let early agricultural societies store dairy long-term. Today: ~1,800+ varieties worldwide.", tip: "🧠 Cheese = milk preservation, ~7,000 years old. Originally accidental — animal-stomach storage." },
  { id: 'food9', cat: 'food', emoji: '🍅', subject: 'Food Science — Tomatoes', diff: 1, hook: "Tomatoes are technically fruits — but legally vegetables in the US.", fact: "Botanically, tomatoes are berries (a type of fruit). But the US Supreme Court ruled in 1893 (Nix v. Hedden) that for tariff purposes, tomatoes are vegetables — based on culinary usage. Both classifications are technically correct depending on context.", tip: "🧠 Tomato: fruit by botany, vegetable by US law. Settled in court, 1893." },
  { id: 'food10', cat: 'food', emoji: '🍯', subject: 'Food Science — Honey', diff: 2, hook: "Honey is essentially bee vomit — and that's a compliment to the bee.", fact: "Honey forms when bees swallow nectar, partially digest it, and regurgitate it for fellow bees, who repeat the process. Enzymes break down the sugars during this exchange. The result is a microbially-stable substance that lasts indefinitely.", tip: "🧠 Honey = nectar regurgitated multiple times. The enzyme work makes it last forever." },
  { id: 'food11', cat: 'food', emoji: '🥚', subject: 'Food Science — Eggs', diff: 1, hook: "Brown and white eggs are nutritionally identical — only the chicken differs.", fact: "Egg shell colour depends entirely on the breed of hen. White-feathered hens with white earlobes lay white eggs; brown-feathered hens with red earlobes lay brown eggs. Nutritional content is essentially identical between them.", tip: "🧠 Brown vs white eggs: same nutrition. Just a different breed of chicken." },
  { id: 'food12', cat: 'food', emoji: '🧂', subject: 'Food Science — Salt', diff: 2, hook: "Salt was once so valuable it was used as currency.", fact: "Roman soldiers were sometimes paid in salt — possibly the origin of the word 'salary' (from Latin 'salarium'). The salt trade built cities and shaped trade routes for millennia. Modern industrial production made it cheap.", tip: "🧠 'Salary' = Latin 'salarium' = salt money. Salt was once true wealth." },
  { id: 'food13', cat: 'food', emoji: '🥛', subject: 'Food Science — Lactose', diff: 2, hook: "Most adults in the world cannot digest milk properly.", fact: "About 65–70% of the world's adults have some level of lactose intolerance — the inability to fully digest milk sugar. Adult lactose tolerance is a relatively recent genetic adaptation, common mainly in northern European populations.", tip: "🧠 65%+ of adults globally are lactose intolerant. Adult tolerance = a fairly recent mutation." },
  { id: 'food14', cat: 'food', emoji: '🥓', subject: 'Food Science — Maillard Reaction', diff: 2, hook: "The browning that makes seared steak taste amazing is the same chemistry as toasted bread.", fact: "The Maillard reaction (1912, Louis-Camille Maillard) is a chemical reaction between amino acids and reducing sugars at high heat (~140°C+). It produces browning and hundreds of flavour compounds. Same reaction in seared steak, toast, roasted coffee, and dark beer.", tip: "🧠 Maillard reaction = browning + flavour. Steak, toast, coffee, beer all share it." },
  { id: 'food15', cat: 'food', emoji: '🍓', subject: 'Food Science — Strawberries', diff: 1, hook: "Strawberries aren't actually berries.", fact: "Strawberries are 'aggregate accessory fruits' — formed from many ovaries of a single flower, with the seeds on the outside. True berries (botanically) come from a single ovary with seeds inside. Bananas, grapes, and tomatoes qualify as berries; strawberries don't.", tip: "🧠 Strawberries: not technically berries. Bananas: yes. Botanical naming is counterintuitive." },
  { id: 'food16', cat: 'food', emoji: '🍿', subject: 'Food Science — Popcorn', diff: 2, hook: "Popcorn pops because of trapped water turning into steam.", fact: "Popcorn kernels have a hard outer hull and a starchy interior with ~14% water. Heat turns the water into steam, building pressure inside the kernel. At ~180°C, the hull bursts, the starch puffs, and instantly cools — into popcorn.", tip: "🧠 Popcorn: trapped steam explodes the hull. Other corn lacks the right hull and water content." },
  { id: 'food17', cat: 'food', emoji: '🍦', subject: 'Food Science — Ice Cream', diff: 2, hook: "Ice cream is technically a foam, an emulsion, and a frozen suspension all at once.", fact: "Ice cream is a complex food: ice crystals (frozen suspension), fat globules in water (emulsion), and air bubbles (foam) all suspended together. Up to 50% of premium ice cream by volume can be air. The structure is delicate — and sensitive to thawing.", tip: "🧠 Ice cream: foam + emulsion + frozen suspension. Re-freezing destroys the structure." },
  { id: 'food18', cat: 'food', emoji: '🍷', subject: 'Food Science — Champagne', diff: 2, hook: "Champagne bubbles only exist because the bottle traps CO₂ under pressure.", fact: "Champagne undergoes a second fermentation inside the bottle — yeast eats sugar and releases CO₂, which dissolves under pressure (~6 atm). Once opened, the gas escapes as bubbles. The pressure inside an unopened bottle equals roughly 3 car tires.", tip: "🧠 Champagne: 2nd fermentation in bottle, 6 atm pressure. Pop = trapped CO₂ escaping fast." },
  { id: 'food19', cat: 'food', emoji: '🥩', subject: 'Food Science — Aging Meat', diff: 2, hook: "Aged beef tastes better because it's partially decomposing — controlled and contained.", fact: "Dry-aged beef is hung for 14–60 days in cold, controlled conditions. Natural enzymes break down muscle tissue, intensifying flavour and tenderness. The outer crust is trimmed off; the result is significantly more flavourful — and significantly more expensive.", tip: "🧠 Dry-aged beef: enzymes literally break it down. Cold + time + trim = legendary flavour." },
  { id: 'food20', cat: 'food', emoji: '🍶', subject: 'Food Science — Soy Sauce', diff: 2, hook: "Traditional soy sauce takes years to make properly.", fact: "Authentic soy sauce ferments soybeans, wheat, salt, and koji mould for 6 months to 2+ years. Cheap commercial brands speed this with chemicals and finish in days. The slow process develops hundreds of flavour compounds.", tip: "🧠 Real soy sauce: 6 months to 2+ years of fermentation. Cheap version: chemical shortcut, days." },
  { id: 'food21', cat: 'food', emoji: '🍌', subject: 'Food Science — Bananas', diff: 2, hook: "The bananas you eat today are not the same bananas your grandparents ate.", fact: "Until the 1950s, the dominant banana variety was the Gros Michel — wiped out by Panama disease. The modern Cavendish replaced it. The Cavendish is now also threatened by a new strain of Panama disease — a slow extinction is unfolding.", tip: "🧠 Old banana: Gros Michel (extinct commercially). Today: Cavendish — also under fungal threat." },
  { id: 'food22', cat: 'food', emoji: '🍣', subject: 'Food Science — Sushi Rice', diff: 2, hook: "Sushi was originally invented as a way to preserve fish — not to eat fresh.", fact: "Early sushi (8th century) was a fish preservation method: fish layered with rice and salt, fermented for months. The rice was discarded before eating. Modern nigiri sushi (raw fish on rice) only emerged in the 19th century in Edo (now Tokyo).", tip: "🧠 Original sushi: fish-preservation, rice discarded. Modern sushi: just 200 years old." },
  { id: 'food23', cat: 'food', emoji: '☕', subject: 'Food Science — Coffee Origins', diff: 1, hook: "Legend says coffee was discovered when goats started dancing.", fact: "An Ethiopian legend credits a 9th-century goatherd, Kaldi, with discovering coffee. He noticed his goats becoming energetic and 'dancing' after eating red berries from a particular bush. He tried them, felt energised, and reported it to local monks.", tip: "🧠 Coffee origin myth: 9th-century Ethiopian goats danced. Probably partly fiction, partly true." },
  { id: 'food24', cat: 'food', emoji: '🥖', subject: 'Food Science — Sourdough', diff: 2, hook: "Sourdough bread uses wild yeast captured from the air.", fact: "Unlike commercial bread (industrial yeast), sourdough is leavened by wild yeasts and lactobacilli captured naturally from the environment. Each starter develops a slightly different microbe community, which is why San Francisco sourdough tastes different from Paris sourdough.", tip: "🧠 Sourdough: wild yeast + bacteria from your local air. Why each city's sourdough is unique." },
  { id: 'food25', cat: 'food', emoji: '🍯', subject: 'Food Science — Maple Syrup', diff: 2, hook: "It takes about 40 litres of sap to make 1 litre of maple syrup.", fact: "Maple sap from sugar maple trees is only about 2% sugar. To produce 1 litre of finished syrup, you need to boil down ~40 litres of sap. The process concentrates the sugar to ~66% and develops the characteristic flavour through caramelisation.", tip: "🧠 Maple syrup: 40 litres sap → 1 litre syrup. Mostly water, slowly boiled away." },

  // ============ MATHS (existing 5 + new 20 = 25) ============
  { id: 'm1', cat: 'math', emoji: '♾️', subject: 'Maths — Infinity', diff: 3, hook: "Not all infinities are equal — mathematicians proved this rigorously.", fact: "There are different sizes of infinity. The set of whole numbers is infinite, but the set of all decimals between just 0 and 1 is a provably larger infinity. Georg Cantor demonstrated this in the 1870s. His peers called him a 'corruptor of youth'. He was later proved completely right.", tip: "🧠 Whole number infinity < decimal infinity. Even 'forever' has different sizes. Cantor proved it." },
  { id: 'm2', cat: 'math', emoji: '🔢', subject: 'Maths — Zero', diff: 2, hook: "Ancient Romans could conquer the world but couldn't do arithmetic we teach 8-year-olds.", fact: "Zero was developed in India (~5th century AD) and transmitted to Europe via Arab mathematicians. Without zero, positional number systems (10, 100, 1000) collapse. Roman numerals had no zero, making multiplication and division incredibly cumbersome.", tip: "🧠 Try XIV × IX in Roman numerals. It's a nightmare. Zero made modern maths, banking, and computing possible." },
  { id: 'm3', cat: 'math', emoji: '🌀', subject: 'Maths — Golden Ratio', diff: 2, hook: "One number appears in sunflowers, nautilus shells, the Parthenon, and Renaissance paintings.", fact: "The golden ratio (φ ≈ 1.618) appears throughout nature and art. Sunflower seed spirals, nautilus shells, and the Parthenon's proportions all approximate phi. Your height divided by your navel height is approximately 1.618.", tip: "🧠 φ ≈ 1.618. Height ÷ navel height ≈ golden ratio. Nature finds this proportion structurally efficient." },
  { id: 'm4', cat: 'math', emoji: '🎲', subject: 'Maths — Probability', diff: 2, hook: "Every properly shuffled deck is almost certainly unique in the history of the universe.", fact: "52! (52 factorial) = possible deck arrangements = a 68-digit number dwarfing atoms on Earth (~10⁵⁰). If every person ever shuffled a deck every second since the Big Bang, they'd cover a vanishingly small fraction of arrangements.", tip: "🧠 52! ≈ 8×10⁶⁷. Atoms on Earth ≈ 10⁵⁰. Your shuffled deck is almost certainly unprecedented in history." },
  { id: 'm5', cat: 'math', emoji: '📐', subject: 'Maths — Pythagoras', diff: 1, hook: "A theorem from 570 BC is still used in GPS, architecture, and video game engines today.", fact: "In any right-angled triangle: a² + b² = c² (c = hypotenuse). Classic: 3² + 4² = 5². Works every time without exception. Used in construction, navigation, 3D graphics, physics, and GPS. Also: Pythagoras banned his followers from eating beans.", tip: "🧠 Classic triples: 3-4-5, 5-12-13, 8-15-17. Pythagoras also banned beans. Both facts may appear in a quiz." },
  { id: 'm6', cat: 'math', emoji: '🥧', subject: 'Maths — Pi', diff: 1, hook: "Pi never repeats and never ends — and we've calculated trillions of its digits.", fact: "π (pi) is the ratio of any circle's circumference to its diameter, approximately 3.14159. It's irrational (never repeats) and transcendental. As of 2024, π has been calculated to over 100 trillion digits. Most engineering uses just 5–6 digits.", tip: "🧠 π ≈ 3.14159. Never repeats, never ends. 100 trillion digits known — but barely needed." },
  { id: 'm7', cat: 'math', emoji: '🧮', subject: 'Maths — Prime Numbers', diff: 2, hook: "Prime numbers are the building blocks of every other integer.", fact: "A prime number is divisible only by 1 and itself. Examples: 2, 3, 5, 7, 11, 13... Every other whole number is a product of primes. Euclid proved (~300 BC) that there are infinitely many primes. Modern internet encryption relies on the difficulty of factorising large primes.", tip: "🧠 Primes: 2, 3, 5, 7, 11, 13... building blocks of all numbers. Infinitely many. RSA encryption depends on them." },
  { id: 'm8', cat: 'math', emoji: '🌪️', subject: 'Maths — Chaos Theory', diff: 3, hook: "A butterfly flapping its wings in Brazil could theoretically cause a tornado in Texas.", fact: "Chaos theory studies systems where tiny initial differences lead to vastly different outcomes — formally called sensitive dependence on initial conditions. Edward Lorenz coined the 'butterfly effect' in the 1960s while modelling weather. It explains why long-range forecasting is fundamentally limited.", tip: "🧠 Butterfly effect: tiny causes, huge effects. Why weather forecasts fail beyond ~10 days." },
  { id: 'm9', cat: 'math', emoji: '🎂', subject: 'Maths — Birthday Paradox', diff: 2, hook: "In a room of just 23 people, there's a 50% chance two share a birthday.", fact: "Most people guess you'd need ~180 people. But the maths counts pairings, not people. With 23 people there are 253 possible pairs — enough that the probability of a match exceeds 50%. With 70 people, the probability is 99.9%.", tip: "🧠 23 people = 50% chance of birthday match. 70 people = 99.9%. Counter-intuitive but provable." },
  { id: 'm10', cat: 'math', emoji: '🚪', subject: 'Maths — Monty Hall Problem', diff: 3, hook: "A famous game show problem fooled even maths professors.", fact: "Three doors, one prize. You pick door 1. The host (knowing locations) opens door 3 — empty. Stick or switch? Counterintuitively, switching wins 2/3 of the time. Most people insist it's 50/50. The maths is rock solid — and verified by simulation.", tip: "🧠 Monty Hall: switch doors. Wins 2/3 of the time. Rock-solid maths, deeply unintuitive." },
  { id: 'm11', cat: 'math', emoji: '🌍', subject: 'Maths — Earth Measurement', diff: 2, hook: "Eratosthenes calculated Earth's circumference around 240 BC — and got it almost exactly right.", fact: "Eratosthenes measured shadow angles at Alexandria and Syene during the summer solstice and used geometry to estimate Earth's circumference at ~40,000 km. The actual figure is 40,075 km. He achieved this 1,800 years before Columbus — using sticks, sunlight, and trigonometry.", tip: "🧠 Eratosthenes: 240 BC, calculated Earth's circumference within 1% — using shadows." },
  { id: 'm12', cat: 'math', emoji: '∞', subject: 'Maths — Googol', diff: 2, hook: "A googol is so large the universe doesn't contain enough atoms to write it out.", fact: "A googol = 10¹⁰⁰ (1 followed by 100 zeros). It exceeds the estimated number of atoms in the observable universe (~10⁸⁰). The term was coined by 9-year-old Milton Sirotta in 1920. Google's name is a deliberate misspelling of 'googol'.", tip: "🧠 Googol = 10¹⁰⁰. More than atoms in the universe. Google = misspelled googol." },
  { id: 'm13', cat: 'math', emoji: '🔺', subject: 'Maths — Triangles', diff: 1, hook: "The angles of any triangle on a flat surface always add up to 180°.", fact: "On a flat (Euclidean) surface, triangle angles always sum to exactly 180°. On a sphere (like Earth), they sum to more than 180°. On a saddle shape, less. The sum reveals the curvature of the underlying space.", tip: "🧠 Flat triangle = 180°. Sphere = more. Saddle = less. The sum tells you about the surface." },
  { id: 'm14', cat: 'math', emoji: '🌽', subject: 'Maths — Fibonacci', diff: 2, hook: "Sunflower seeds and pine cones grow in a precise mathematical sequence.", fact: "The Fibonacci sequence: 1, 1, 2, 3, 5, 8, 13, 21... each term is the sum of the previous two. Sunflower seed spirals, pinecone scales, and pineapple skin all follow Fibonacci counts. The ratio between consecutive Fibonacci numbers approaches the golden ratio (φ).", tip: "🧠 Fibonacci: 1,1,2,3,5,8,13... appears in plants. Ratio → golden ratio (1.618)." },
  { id: 'm15', cat: 'math', emoji: '🪜', subject: 'Maths — Exponential Growth', diff: 2, hook: "If you fold a piece of paper 42 times, it'd reach the Moon.", fact: "Each fold doubles the paper's thickness. Standard paper (~0.1 mm) folded 42 times = ~440,000 km — past the Moon (384,000 km). In reality, paper can only be folded ~7-8 times because the layers compound rapidly in size and rigidity.", tip: "🧠 42 paper folds = past the Moon (theoretically). Real-world limit: ~7–8 folds." },
  { id: 'm16', cat: 'math', emoji: '🎰', subject: 'Maths — Gambler\s Fallacy', diff: 2, hook: "After 10 reds at the roulette table, the next spin still has the same odds.", fact: "The gambler's fallacy: believing past random outcomes affect future ones. They don't (for independent events). A fair coin flipped 10 heads in a row still has 50/50 odds on flip 11. The Monte Carlo casino in 1913 saw 26 black spins in a row — gamblers lost millions betting against it.", tip: "🧠 Gambler's fallacy: past random results don't shift future odds. The wheel has no memory." },
  { id: 'm17', cat: 'math', emoji: '🌐', subject: 'Maths — Topology', diff: 3, hook: "Mathematicians say a coffee mug and a doughnut are essentially the same shape.", fact: "Topology studies properties preserved under continuous deformation (stretching, bending, but not tearing). A mug and a doughnut both have exactly one hole — making them topologically equivalent. A sphere has zero holes; a pretzel has multiple.", tip: "🧠 Topology: shapes by holes only. Mug = doughnut (1 hole each). Sphere = ball (0 holes)." },
  { id: 'm18', cat: 'math', emoji: '👉', subject: 'Maths — Counting', diff: 1, hook: "Most languages have number words — but a few don't.", fact: "Most cultures developed number systems independently. But some Amazonian languages (like the Pirahã) have words only for 'one', 'two', and 'many' — no precise counting beyond. Studies show speakers struggle with exact arithmetic outside their linguistic toolkit.", tip: "🧠 Some languages have no exact numbers beyond 'two'. Counting is partly a linguistic ability." },
  { id: 'm19', cat: 'math', emoji: '🎵', subject: 'Maths — Music', diff: 2, hook: "Music is essentially mathematics in motion — Pythagoras was the first to spot it.", fact: "Pythagoras discovered (~500 BC) that musical harmony depends on simple integer ratios. Strings whose lengths form ratios like 2:1 (octave), 3:2 (fifth), 4:3 (fourth) sound consonant. Modern Western music is built on these mathematical relationships.", tip: "🧠 Music = integer ratios. 2:1 = octave. 3:2 = perfect fifth. Pythagoras saw it first." },
  { id: 'm20', cat: 'math', emoji: '🌗', subject: 'Maths — Half-Life', diff: 2, hook: "Half-life is why nuclear waste lasts thousands of years.", fact: "Half-life = the time for half of a radioactive substance to decay. Carbon-14: ~5,730 years (used in archaeological dating). Uranium-238: 4.5 billion years. Plutonium-239: 24,000 years. Multiple half-lives must pass before radioactivity becomes negligible.", tip: "🧠 Half-life: time for half to decay. C-14 = 5,730 yr (dating). U-238 = 4.5 billion yr." },
  { id: 'm21', cat: 'math', emoji: '🎯', subject: 'Maths — Precision', diff: 2, hook: "An extra digit of pi gives no useful precision for most engineering.", fact: "Just 15 digits of pi (3.141592653589793) is enough to calculate the circumference of the entire observable universe to within the diameter of a single hydrogen atom. NASA uses 15 digits. Calculating trillions more is purely about computational benchmarking.", tip: "🧠 15 digits of π = universe-spanning precision. More is just computer benchmarking." },
  { id: 'm22', cat: 'math', emoji: '🪜', subject: 'Maths — Logarithms', diff: 3, hook: "Earthquakes, decibels, and pH all use the same trick — logarithmic scales.", fact: "Logarithmic scales compress huge ranges of values. The Richter scale: each whole number = 10x stronger earthquake. Decibels: each 10 dB = 10x more sound energy. pH: each unit = 10x more acidic. They tame numbers that would otherwise be unwieldy.", tip: "🧠 Log scale: each step = 10x. Richter, decibels, pH all use it. Compress huge ranges to manageable numbers." },
  { id: 'm23', cat: 'math', emoji: '🏛️', subject: 'Maths — Ancient Greeks', diff: 2, hook: "Euclid's geometry textbook was used in schools for over 2,000 years.", fact: "Euclid's Elements (~300 BC) is one of the most influential textbooks in history. It systematised geometry for over 2,000 years and was used essentially unchanged in mathematics education until the late 19th century. Only the Bible has been more widely printed.", tip: "🧠 Euclid's Elements: ~300 BC, textbook for 2,000+ years. Geometry's foundation." },
  { id: 'm24', cat: 'math', emoji: '🧩', subject: 'Maths — Game Theory', diff: 3, hook: "Game theory uses maths to predict how people behave in conflicts.", fact: "Game theory (formalised by John von Neumann, 1928) uses mathematical models of strategic interaction. The Prisoner's Dilemma is the most famous example. Used in economics, politics, biology (evolutionary stable strategies), and even AI design.", tip: "🧠 Game theory: maths of strategy. Prisoner's Dilemma = its most famous problem. Touches every social science." },
  { id: 'm25', cat: 'math', emoji: '🤖', subject: 'Maths — Algorithms', diff: 2, hook: "The word 'algorithm' comes from the name of a 9th-century mathematician.", fact: "'Algorithm' derives from al-Khwarizmi, a 9th-century Persian mathematician whose Latin-translated name became 'Algoritmi'. He also gave us 'algebra' (from his book's title). The maths underpinning modern computing is partly named after one Baghdad scholar.", tip: "🧠 'Algorithm' + 'algebra' both come from al-Khwarizmi (9th-century Baghdad)." },

  { id: 'pq76', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Only one country in the world has a flag that is not rectangular or square.", fact: "Nepal\'s flag is a double-pennant shape — two stacked triangles. All 194 other national flags are rectangular or square. It\'s been Nepal\'s official flag since 1962.", tip: "🧠 Nepal = only non-rectangular flag. Double-pennant. One of the most common pub quiz gotchas." },
  { id: 'pq77', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The inventor of the World Wide Web gave it away for free.", fact: "Tim Berners-Lee invented the WWW in 1989 at CERN and deliberately chose not to patent it, giving it freely to the world. He was knighted in 2004. He has expressed concerns about how the web has evolved.", tip: "🧠 Berners-Lee: invented web, gave it away free, later knighted. No patent = no billionaire." },
  { id: 'pq78', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "A group of flamingos is called a flamboyance.", fact: "The collective noun for flamingos is a \'flamboyance\'. Other unusual animal group names: a murder of crows, a parliament of owls, a crash of rhinos, an ambush of tigers.", tip: "🧠 Flamingo group = flamboyance. Crows = murder. Owls = parliament. Rhinos = crash." },
  { id: 'pq79', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The human nose can detect over 1 trillion different smells.", fact: "A 2014 Science study found humans can distinguish at least 1 trillion different odours — far more than the previously assumed 10,000. The nose has ~400 types of smell receptors that combine to detect vast variety.", tip: "🧠 Human nose: 1 trillion detectable smells. 400 receptor types combine for huge variety." },
  { id: 'pq80', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The Great Fire of London in 1666 destroyed most of the city but killed very few people.", fact: "The Great Fire of London burned for 4 days (2–6 September 1666), destroying ~13,200 houses, 87 churches, and St Paul\'s Cathedral. Official death toll: just 6 people — though historians suspect more perished undocumented.", tip: "🧠 Great Fire 1666: 13,000+ houses, 87 churches destroyed. Official deaths: only 6." },
  { id: 'pq81', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The shortest commercial flight in the world lasts under 2 minutes.", fact: "Loganair\'s flight between Westray and Papa Westray in Orkney, Scotland, officially lasts 1 minute 14 seconds in still air conditions — the world\'s shortest scheduled commercial flight. Distance: about 2.7 km.", tip: "🧠 Shortest commercial flight: Westray to Papa Westray, Orkney. ~74 seconds. 2.7 km." },
  { id: 'pq82', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "A \'jiffy\' is a real unit of time in physics.", fact: "In physics, a jiffy = the time light takes to travel one centimetre — about 33.4 picoseconds. In electronics it\'s 1/60 of a second. In computing, 1/100 of a second. Casual usage = unspecified short time.", tip: "🧠 Jiffy: physics = 33 picoseconds. Electronics = 1/60 sec. Computing = 1/100 sec." },
  { id: 'pq83', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The inventor of dynamite funded the Nobel Prizes.", fact: "Alfred Nobel invented dynamite in 1867 and became enormously wealthy from munitions. Horrified by a premature obituary calling him \'the merchant of death\', he left his fortune to fund the Nobel Prizes. He died in 1896.", tip: "🧠 Nobel: invented dynamite, horrified by \'merchant of death\' label, funded the prizes." },
  { id: 'pq84', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Cleopatra was not Egyptian by descent.", fact: "Cleopatra VII was Macedonian Greek — a descendant of Ptolemy I, one of Alexander the Great\'s generals. She was reportedly the first ruler of her dynasty to actually learn the Egyptian language. Her family ruled Egypt for ~300 years.", tip: "🧠 Cleopatra = Greek (Macedonian), not Egyptian. First of her dynasty to speak Egyptian." },
  { id: 'pq85', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The Colosseum in Rome could be flooded for mock naval battles.", fact: "The Colosseum had an elaborate drainage system and could be flooded with water for \'naumachiae\' — staged naval battles. This practice was common in the early years but was later abandoned when the underground hypogeum was constructed.", tip: "🧠 Colosseum: once flooded for mock sea battles (naumachiae). Abandoned when basement was built." },
  { id: 'pq86', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Oxford University is older than the Aztec Empire.", fact: "Teaching at Oxford began around 1096–1167 AD. The Aztec city of Tenochtitlan was founded in 1325. Oxford predates the Aztec civilisation by roughly 200 years.", tip: "🧠 Oxford: ~1096. Aztecs founded Tenochtitlan: 1325. Oxford is 200+ years older than the Aztecs." },
  { id: 'pq87', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A crocodile cannot stick out its tongue.", fact: "Crocodilians have a membrane that holds their tongue firmly to the roof of their mouth — they physically cannot extend it. Alligators have the same constraint. This is one of the few anatomical limits unique to this group.", tip: "🧠 Crocodiles: tongue permanently fixed to mouth floor. Cannot stick it out." },
  { id: 'pq88', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The first item ever bought and sold on the internet was a bag of marijuana.", fact: "In 1971–72, Stanford students used ARPANET (the internet\'s predecessor) to arrange a marijuana deal with MIT students. The transaction predates the first \'official\' e-commerce by over 20 years. The first legal online sale was a Sting CD in 1994.", tip: "🧠 First internet transaction: marijuana deal, Stanford to MIT, ~1972. First legal sale: Sting CD, 1994." },
  { id: 'pq89', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Honey bees can recognise human faces.", fact: "Research shows honey bees can learn to identify human faces using the same \'configural processing\' technique humans use — recognising the overall arrangement of features rather than individual parts. They can be trained to match faces to rewards.", tip: "🧠 Bees can recognise human faces. They use similar pattern-matching to how we do it." },
  { id: 'pq90', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "France was still using the guillotine when Star Wars came out.", fact: "The last guillotine execution in France was on 10 September 1977 — the same year Star Wars Episode IV was released (May 1977). France abolished the death penalty in 1981.", tip: "🧠 France\'s last guillotine: September 1977 — same year as Star Wars. Death penalty abolished 1981." },
  { id: 'pq91', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The shortest war in recorded history lasted 38 minutes.", fact: "The Anglo-Zanzibar War (27 August 1896) lasted between 38 and 45 minutes. Britain demanded the new Sultan stand down; he refused. British ships shelled the palace; the Sultan surrendered in under an hour.", tip: "🧠 Shortest war: Anglo-Zanzibar, 1896, 38–45 minutes. The sultan surrendered before lunch." },
  { id: 'pq92', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "There are more possible iterations of a game of chess than atoms in the observable universe.", fact: "The Shannon Number estimates ~10^120 possible chess games. Observable universe atoms: ~10^80. Chess has 40 orders of magnitude more possible games than atoms in everything we can see.", tip: "🧠 Chess possibilities: 10^120. Universe atoms: 10^80. Chess wins by 40 zeros." },
  { id: 'pq93', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A shrimp\'s heart is in its head.", fact: "A shrimp\'s heart is located in its thorax — which is part of what we\'d consider its \'head\' region (the cephalothorax). Similarly, a shrimp\'s brain wraps around its oesophagus, so technically it thinks around its throat.", tip: "🧠 Shrimp heart: in the head region. Brain: wraps around its oesophagus." },
  { id: 'pq94', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The world\'s largest living organism is a fungus in Oregon.", fact: "Armillaria ostoyae (honey fungus) in Malheur National Forest, Oregon, covers ~9.6 km² and is estimated to be 2,000–8,000 years old. It exists mostly underground. Blue whales are the largest animals but this fungus dwarfs them in mass.", tip: "🧠 Largest organism: Armillaria fungus, Oregon, 9.6 km², up to 8,000 years old." },
  { id: 'pq95', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The word \'nerd\' was first used by Dr. Seuss.", fact: "\'Nerd\' first appeared in Dr. Seuss\'s 1950 book \'If I Ran the Zoo\' as the name of a fictional creature. By the 1960s it had become slang for an unfashionable, studious person. Seuss coined the word entirely by accident.", tip: "🧠 \'Nerd\': first appeared in Dr. Seuss\'s \'If I Ran the Zoo\' (1950) as a creature name." },
  { id: 'pq96', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The Eiffel Tower was supposed to be dismantled after 20 years.", fact: "Built for the 1889 Paris World\'s Fair, the Eiffel Tower was intended as a temporary structure, to be torn down in 1909. It survived because it was repurposed as a radio transmission tower — making it militarily and commercially valuable.", tip: "🧠 Eiffel Tower: meant to be demolished 1909. Saved by being useful as a radio antenna." },
  { id: 'pq97', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Elephants are the only animals that cannot jump.", fact: "Adult elephants are the only mammals physically incapable of jumping. Their bone structure and weight (~6 tonnes) make it impossible. They can run up to 25 km/h but all four feet never leave the ground simultaneously.", tip: "🧠 Elephants: only mammals that can\'t jump. Run at 25 km/h but never fully airborne." },
  { id: 'pq98', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Nintendo was founded in 1889 — as a playing card company.", fact: "Nintendo was founded on 23 September 1889 in Kyoto by Fusajiro Yamauchi, making hand-crafted Hanafuda playing cards. It didn\'t enter the video game business until the 1970s. The company is over 130 years old.", tip: "🧠 Nintendo: founded 1889, made playing cards. Video games didn\'t come until the 1970s." },
  { id: 'pq99', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A bolt of lightning contains enough energy to toast 100,000 slices of bread.", fact: "A lightning bolt carries approximately 1–5 billion joules of energy. However, it lasts only microseconds, so the usable power is tiny. The total energy could toast about 100,000 slices but the delivery speed makes it impractical.", tip: "🧠 Lightning: ~1 billion joules. Enough energy to toast 100,000 slices. Delivery too fast to use." },
  { id: 'pq100', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The world\'s most expensive spice by weight is saffron — worth more than gold.", fact: "Saffron costs £5,000–£10,000 per kilogram, exceeding gold (~£50,000/kg by weight — though gold wins overall). Each saffron crocus produces just 3 stigmas, and they must be hand-harvested. 150,000 flowers yield ~1 kg of saffron.", tip: "🧠 Saffron: £5,000–10,000/kg. 150,000 hand-harvested flowers per kilogram." },
  { id: 'pq101', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The name \'Google\' was a spelling mistake.", fact: "The founders intended to name the search engine \'Googol\' (10^100, representing vast amounts of data). When checking if the domain was available, investor Sean Anderson misspelled it as \'Google\' — and the name stuck.", tip: "🧠 Google = accidental misspelling of \'Googol\' (10^100). The typo became a trillion-dollar brand." },
  { id: 'pq102', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Cats were worshipped as gods in ancient Egypt — and they haven\'t forgotten it.", fact: "Ancient Egyptians worshipped the cat goddess Bastet from around 2900 BC. Killing a cat was punishable by death. When a household cat died, the family shaved off their eyebrows in mourning. Thousands of mummified cats have been found.", tip: "🧠 Egyptian cat worship: from ~2900 BC. Killing one = death penalty. Mourning = shave eyebrows." },
  { id: 'pq103', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The Pacific Ocean is wider than the Moon.", fact: "The Pacific Ocean spans approximately 19,800 km at its widest point. The Moon\'s diameter is 3,474 km. The Pacific is about 5.7 times wider than the Moon\'s full diameter.", tip: "🧠 Pacific Ocean width: ~19,800 km. Moon diameter: 3,474 km. Pacific is 5.7x wider." },
  { id: 'pq104', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The phrase \'rule of thumb\' may come from an old law about wife-beating.", fact: "One theory traces \'rule of thumb\' to an 18th-century legal principle allowing men to beat their wives with a stick no thicker than their thumb. Historians dispute this origin, but it remains one of the most debated etymologies in English.", tip: "🧠 \'Rule of thumb\': disputed origin possibly from wife-beating law. Etymology remains contested." },
  { id: 'pq105', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "More people die from vending machine accidents than shark attacks annually.", fact: "Vending machines kill approximately 13 people per year in the US — usually from people rocking them to dislodge stuck items. Sharks kill 5–10 people globally per year. Vending machines are statistically more dangerous.", tip: "🧠 Vending machines kill ~13/year in US. Sharks kill 5–10 globally. Choose your enemy." },
  { id: 'pq106', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The human body contains enough iron to make a 3-inch nail.", fact: "An adult body contains roughly 3–4 grams of iron — mostly in red blood cells as haemoglobin. That\'s enough iron to forge a small nail of about 7–8 cm. Other metals in your body: ~2g zinc, ~0.2g copper.", tip: "🧠 Body iron: ~3–4g — enough for a 3-inch nail. Also contains zinc, copper, manganese." },
  { id: 'pq107', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Winston Churchill was born in a ladies\' cloakroom.", fact: "Churchill was born prematurely on 30 November 1874 at Blenheim Palace during a party. His mother went into labour unexpectedly, and the nearest available room was a small ladies\' cloakroom. The rest is history.", tip: "🧠 Churchill: born prematurely in a ladies\' cloakroom at Blenheim Palace, 1874." },
  { id: 'pq108', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The entire internet weighs about the same as a strawberry.", fact: "The electrons in motion carrying internet data have a collective mass of approximately 50 grams — roughly the weight of a strawberry. This was calculated by physicist Russell Seitz based on the energy/mass of moving electrons.", tip: "🧠 All the data on the internet weighs ~50g in electron mass. Same as a strawberry." },
  { id: 'pq109', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Alaska is simultaneously the most northern, western, AND eastern US state.", fact: "Alaska contains the westernmost point of the US (Attu Island) and — because the Aleutian Islands cross the 180° meridian — also the easternmost point. It\'s also the northernmost. Alaska holds three directional records simultaneously.", tip: "🧠 Alaska: most northern, most western, AND most eastern US state. Aleutians cross the date line." },
  { id: 'pq110', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The inventor of the frisbee was turned into a frisbee after he died.", fact: "Walter Morrison invented the Frisbee in the 1940s. When he died in 2010, his family honoured his wishes and had his ashes mixed into a batch of Frisbees, which were distributed to friends and family.", tip: "🧠 Frisbee inventor Walter Morrison: ashes turned into Frisbees after his death in 2010." },
  { id: 'pq111', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A group of porcupines is called a prickle.", fact: "The collective noun for porcupines is a \'prickle\'. Other unusual animal group names: a bloat of hippos, a tower of giraffes, a conspiracy of lemurs, a flamboyance of flamingos, a murder of crows.", tip: "🧠 Porcupines = prickle. Hippos = bloat. Giraffes = tower. Lemurs = conspiracy." },
  { id: 'pq112', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The original Monopoly was invented to teach people about the dangers of monopolies.", fact: "Elizabeth Magie patented \'The Landlord\'s Game\' in 1903 to demonstrate how landlords enrich themselves while tenants get poorer. Charles Darrow later claimed credit for a similar game, which became Monopoly in 1935. Magie received $500 and no royalties.", tip: "🧠 Monopoly origin: 1903 anti-monopoly teaching tool. Magie got $500. Darrow became a millionaire." },
  { id: 'pq113', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "It is impossible to hum while holding your nose closed.", fact: "Try it — the moment you close your nostrils, humming stops. Humming requires air to flow through the nasal passage. When you block the nose, airflow stops and the sound can\'t be produced.", tip: "🧠 Can\'t hum with nose closed. Needs nasal airflow. Try it right now." },
  { id: 'pq114', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The Great Wall of China has trees growing out of it.", fact: "Sections of the Great Wall that have fallen into disrepair have trees and plants growing through the stonework — their roots breaking up the structure. Conservation teams actively manage vegetation on protected sections but many remote areas are reclaimed by nature.", tip: "🧠 Great Wall: abandoned sections have trees growing through them. Nature reclaiming stone." },
  { id: 'pq115', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Penguins live exclusively in the Southern Hemisphere — except for one species.", fact: "The Galápagos penguin lives near the equator on the Galápagos Islands — slightly north of it in places, making it the only penguin species that lives (partially) in the Northern Hemisphere.", tip: "🧠 Galápagos penguin: only penguin species found in the Northern Hemisphere." },
  { id: 'pq116', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Amelia Earhart and Walt Disney were born in the same year.", fact: "Both Amelia Earhart and Walt Disney were born in 1901. Earhart became the first woman to fly solo across the Atlantic in 1932. Disney founded his studio in 1923. Two cultural icons, same birth year.", tip: "🧠 Earhart and Disney: both born 1901. First female solo Atlantic crossing and Mickey Mouse — same generation." },
  { id: 'pq117', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A group of cats is called a clowder.", fact: "The collective noun for cats is a \'clowder\'. A group of kittens is a \'kindle\'. A group of wild cats is a \'destruction\'. Most people only know \'litter\' for kittens, but \'kindle\' is the correct collective noun.", tip: "🧠 Cats = clowder. Kittens = kindle. Wild cats = destruction. Now you know." },
  { id: 'pq118', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The inventor of the intermittent windscreen wiper was denied royalties and fought for years.", fact: "Robert Kearns invented intermittent windscreen wipers in the 1960s. Ford and Chrysler copied his design without credit or payment. He sued and eventually won ~$30 million in settlements — but spent decades fighting and the stress cost him his marriage and mental health.", tip: "🧠 Kearns: invented intermittent wipers, fought Ford for decades, won $30M but lost everything else." },
  { id: 'pq119', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The hashtag symbol has a proper name — it\'s called an octothorpe.", fact: "The # symbol is officially called an octothorpe. \'Octo\' = eight (for its eight points), \'thorpe\' = obscure origin. It was used on telephone keypads before Twitter made it a cultural phenomenon in 2007.", tip: "🧠 The # symbol = octothorpe. Eight points = octo. Twitter made it famous 2007." },
  { id: 'pq120', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Rome and Beijing are at almost exactly the same latitude.", fact: "Rome sits at ~41.9°N. Beijing sits at ~39.9°N. They\'re less than 2 degrees of latitude apart — putting two of history\'s greatest capital cities at virtually the same distance from the equator, despite being vastly different culturally.", tip: "🧠 Rome (41.9°N) and Beijing (39.9°N): almost identical latitude. Two great capitals, same distance from equator." },
  { id: 'pq121', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The first tweet was sent on 21 March 2006 by Twitter\'s co-founder.", fact: "Jack Dorsey sent the first ever tweet: \'just setting up my twttr\' on 21 March 2006. The original tweet sold as an NFT in 2021 for $2.9 million. By 2023 its value had dropped to offers of under $20,000.", tip: "🧠 First tweet: Jack Dorsey, \'just setting up my twttr\', 21 March 2006. Sold as NFT for $2.9M." },
  { id: 'pq122', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The smallest bone and the largest bone in the body differ in size by a factor of about 200.", fact: "The stapes (ear bone): ~3mm. The femur (thigh bone): ~50cm. Ratio: roughly 1:200. One is critical for hearing, the other supports your entire body weight and connects to the most powerful muscles.", tip: "🧠 Stapes: 3mm (smallest). Femur: ~50cm (largest). Ratio of ~200:1." },
  { id: 'pq123', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A cat has 32 muscles in each ear.", fact: "Cats have 32 muscles controlling each ear, allowing them to rotate their ears 180° independently of each other to pinpoint sounds. Humans have about 6 ear muscles and most people can barely move them at all.", tip: "🧠 Cats: 32 ear muscles each, rotate 180°. Humans: ~6 ear muscles, mostly useless." },
  { id: 'pq124', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Abraham Lincoln was a licensed bartender.", fact: "Before entering politics, Lincoln co-owned a tavern called Berry and Lincoln in New Salem, Illinois, in 1833. He was issued a tavern keeper\'s licence and served alcohol. The business failed within a year.", tip: "🧠 Lincoln: licensed bartender and tavern co-owner in 1833. The business failed." },
  { id: 'pq125', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The longest English word that can be typed using only the top row of a keyboard is \'typewriter\'.", fact: "QWERTY top row: Q, W, E, R, T, Y, U, I, O, P. \'Typewriter\' (10 letters) uses only those keys and is the longest common English word achievable. This is sometimes called one of the original typewriter marketing demonstrations.", tip: "🧠 Longest word using only QWERTY top row: TYPEWRITER. All 10 letters on the top row." },
  { id: 'pq126', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The first person convicted of speeding was doing 8 mph.", fact: "Walter Arnold of East Peckham, Kent, was fined for speeding on 28 January 1896 — going 8 mph (13 km/h) in a 2 mph zone. He was caught by a policeman who had to chase him on a bicycle.", tip: "🧠 First speeding conviction: Walter Arnold, 1896. Was doing 8 mph. Chased by a cyclist." },
  { id: 'pq127', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Venus is the only planet that rotates clockwise when viewed from above the North Pole.", fact: "All planets rotate counter-clockwise when viewed from above the North Pole — except Venus, which rotates clockwise (retrograde). Uranus also has an unusual rotation, tilted almost 98° on its side.", tip: "🧠 Venus: only planet with clockwise rotation from North Pole view. Uranus: tilted 98°." },
  { id: 'pq128', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The \'Spanish Flu\' of 1918 may not have originated in Spain.", fact: "The 1918–1919 influenza pandemic was dubbed \'Spanish Flu\' not because it started there but because Spain — neutral in WW1 — had a free press that reported deaths openly. Warring nations censored their own outbreaks. True origin is disputed (possibly USA, China, or France).", tip: "🧠 Spanish Flu: not Spanish. Spain reported freely. Warring nations censored outbreaks." },
  { id: 'pq129', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A day on Mars is only slightly longer than a day on Earth.", fact: "A Martian day (sol) = 24 hours, 39 minutes, 35 seconds — just 40 minutes longer than an Earth day. This is one of the most convenient similarities between the two planets for potential future colonists.", tip: "🧠 Mars day (sol) = 24h 39m — only 40 minutes longer than Earth. Most convenient overlap." },
  { id: 'pq130', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The first product ever advertised on television in the UK was toothpaste.", fact: "On 22 September 1955, the UK\'s first commercial TV broadcast (ITV) aired its first advertisement — for Gibbs SR toothpaste. The advert showed a block of ice with a tube of toothpaste and urged viewers to keep their teeth \'tingling fresh\'.", tip: "🧠 First UK TV advert: Gibbs SR toothpaste, 22 September 1955, ITV\'s first commercial broadcast." },
  { id: 'pq131', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The average person walks the equivalent of five times around the Earth in their lifetime.", fact: "The average person takes about 7,500 steps per day. Over 80 years, that\'s roughly 216 million steps — equivalent to walking ~177,000 km or about 4.5 times around the Earth\'s circumference.", tip: "🧠 Average lifetime walking: ~177,000 km = ~4–5 times around the Earth." },
  { id: 'pq132', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The word \'quarantine\' comes from the Italian for \'forty days\'.", fact: "During the Black Death, Venice required ships arriving from infected ports to anchor offshore for 40 days before landing. The Italian \'quarantina\' or \'quaranta giorni\' = forty days. The specific 40-day period has Biblical and medical roots.", tip: "🧠 Quarantine = Italian \'quaranta giorni\' = 40 days. Originated during Black Death in Venice." },
  { id: 'pq133', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The loudest animal on Earth relative to its size is a tiny insect.", fact: "The water boatman (Micronecta scholtzi) produces sound at 99.2 decibels relative to its body size — the loudest animal on Earth proportionally. It creates noise by rubbing its penis against its abdomen. The blue whale is louder in absolute terms.", tip: "🧠 Loudest animal relative to size: water boatman insect, 99.2 dB. Method: rubbing penis on abdomen." },
  { id: 'pq134', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "During WW2, the US military trained bats to carry incendiary bombs.", fact: "\'Project X-Ray\' (1943): the US Army attached tiny incendiary bombs to thousands of Mexican free-tailed bats, planning to release them over Japanese cities to roost in wooden buildings and start fires. The project was cancelled when the atomic bomb took priority.", tip: "🧠 Project X-Ray: WW2 bat bomb project. Bats would roost in wooden buildings and combust. Cancelled for nukes." },
  { id: 'pq135', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Butterflies taste with their feet.", fact: "Butterflies have chemoreceptors (taste sensors) on their tarsi (feet). When they land on a surface, they immediately taste it — helping them identify food sources and suitable plants for laying eggs. They \'taste\' before they eat.", tip: "🧠 Butterflies taste with their feet. Chemoreceptors on tarsi identify food and egg-laying sites." },
  { id: 'pq136', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The longest recorded flight of a chicken is 13 seconds.", fact: "The longest officially recorded flight of a chicken is 13 seconds. Despite having wings, chickens are too heavy relative to their wing size for sustained flight. They can briefly flutter to escape predators or reach low roosts.", tip: "🧠 Longest chicken flight: 13 seconds. Too heavy for real flight but can flutter short distances." },
  { id: 'pq137', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "More Monopoly money is printed each year than real US currency.", fact: "Hasbro prints approximately $30 billion in Monopoly money per year. The US Bureau of Engraving and Printing produces about $700 million to $1.5 billion in new bills annually. Monopoly outprints the Fed in dollar terms.", tip: "🧠 Monopoly money printed per year: ~$30 billion. Real US dollar printing: ~$1–1.5 billion." },
  { id: 'pq138', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The Romans used crushed mouse brains as toothpaste.", fact: "Ancient Roman dental hygiene included recipes using powdered mouse brain, rabbit heads, urine, and ground oyster shells. Urine (containing ammonia) was actually somewhat effective for cleaning. Crushed charcoal was also common.", tip: "🧠 Roman toothpaste: crushed mouse brain, rabbit heads, and urine. The urine actually worked." },
  { id: 'pq139', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A jiffy was once the term for exactly 1/100th of a second in computing.", fact: "In early computing, a \'jiffy\' was standardised at 1/100 of a second (10 milliseconds) — the interval between system clock ticks on many operating systems. Unix systems later used 1/60 or 1/1000 of a second depending on the platform.", tip: "🧠 Computing jiffy: 1/100 second (10ms). The origin of casual \'I\'ll be there in a jiffy\'." },
  { id: 'pq140', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The Pythagorean cup punishes greedy drinkers.", fact: "The Pythagorean cup (or Tantalus cup) looks normal but contains a hidden siphon. Fill it to the line — fine. Fill it past the line — all the liquid drains out through the bottom. Pythagoras allegedly used them to enforce moderation.", tip: "🧠 Pythagorean cup: fill past the line = loses everything. Siphon mechanism, moderation enforced." },
  { id: 'pq141', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The letter \'E\' is the most common letter in English text.", fact: "E accounts for approximately 11–13% of all letters in standard English text. This is why the letter E is given the highest frequency in Scrabble and why Morse code assigns E the shortest signal (a single dot).", tip: "🧠 Most common English letter: E (~12%). Hence shortest Morse code signal = single dot." },
  { id: 'pq142', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Japan has vending machines that sell used underwear.", fact: "Japan\'s vending machine culture is legendary — estimated 5 million machines nationwide. Beyond drinks, they dispense: fresh ramen, canned bread, umbrellas, ties, live crabs, and yes — used schoolgirl underwear (now largely illegal but still occasionally found).", tip: "🧠 Japan: ~5M vending machines. Sell: ramen, canned bread, live crabs, and previously used underwear." },
  { id: 'pq143', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The first emoji was created in 1999 by a Japanese designer.", fact: "Shigetaka Kurita designed the original 176 emoji in 1999 for NTT DoCoMo\'s mobile internet service. Each was 12x12 pixels. The original set is now in the Museum of Modern Art (MoMA) collection in New York.", tip: "🧠 First emoji: 1999, Shigetaka Kurita, Japan. 12x12 pixels, 176 icons. Now in MoMA." },
  { id: 'pq144', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The world\'s first traffic light exploded.", fact: "The world\'s first traffic light was installed in London in December 1868 outside the Houses of Parliament. It used gas lamps (red and green). It exploded on 2 January 1869, injuring the police officer operating it, and wasn\'t used again for decades.", tip: "🧠 First traffic light: London 1868, gas-powered, exploded January 1869, injured the operator." },
  { id: 'pq145', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Lobsters were once considered food fit only for prisoners and the poor.", fact: "In colonial New England, lobsters were so abundant they washed ashore in piles. Feeding servants lobster more than 3 times a week was considered cruel and unusual. Laws were passed against it. Today a single lobster costs more than a day\'s minimum wage.", tip: "🧠 Lobster: once poor-person food, fed to prisoners, laws against overfeeding servants. Now a luxury." },
  { id: 'pq146', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The world\'s oldest joke is about a Sumerian farmer and flatulence — from 1900 BC.", fact: "The oldest recorded joke comes from ancient Sumer (~1900 BC): \'Something which has never occurred since time immemorial; a young woman did not fart in her husband\'s lap.\' The second oldest (1600 BC Egyptian) is also scatological.", tip: "🧠 World\'s oldest joke: Sumerian, ~1900 BC, about a woman not farting on her husband. Comedy is timeless." },
  { id: 'pq147', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A blue whale\'s heart is so large, a human could crawl through its arteries.", fact: "The blue whale\'s heart weighs ~180 kg and is the size of a small car. Its main aorta is wide enough for a human to crawl through. The heart beats 4–8 times per minute and pumps blood through the 30-metre, 150-tonne body.", tip: "🧠 Blue whale heart: ~180 kg, car-sized. Aorta: wide enough for a human to crawl through." },
  { id: 'pq148', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The sun makes a sound but we cannot hear it.", fact: "The Sun constantly produces sound waves from its convecting plasma — \'solar music\'. These waves are at around 0.003 mHz — far below human hearing range (20 Hz minimum). Scientists can speed up the recordings to make them audible.", tip: "🧠 The Sun makes sound. Frequency too low for humans to hear. Sped-up recordings exist." },
  { id: 'pq149', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Turtles can breathe through their butts.", fact: "Painted turtles and some other species can absorb oxygen through their cloaca (posterior opening) during winter hibernation — a process called cloacal bursae respiration. It allows them to stay submerged under ice for months without breathing.", tip: "🧠 Turtles: breathe through their cloaca (butt) in winter under ice. Cloacal bursae respiration." },
  { id: 'pq150', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The world\'s most expensive coffee is made from cat droppings.", fact: "Kopi Luwak is made from coffee beans that have been eaten and excreted by Asian palm civets. The digestive process supposedly alters the beans\' flavour. It sells for $100–$600 per kg. Elephant-processed Black Ivory Coffee from Thailand is even more expensive.", tip: "🧠 Kopi Luwak: cat-dropping coffee, $100–600/kg. Elephant version (Black Ivory) costs even more." },

  { id: 's29', cat: 'science', emoji: '🔬', subject: 'Science — Physics', diff: 2, hook: "Nothing can travel faster than light — except space itself.", fact: "Einstein\'s special relativity states nothing with mass can reach light speed. However, space itself can expand faster than light. This is how distant galaxies recede faster than light — space expands, not the galaxies moving through it.", tip: "🧠 Speed of light: unbreakable for matter. Space expansion: no speed limit. Different rules." },
  { id: 's30', cat: 'science', emoji: '🧪', subject: 'Science — Elements', diff: 1, hook: "Hydrogen is the most abundant element in the universe — by a huge margin.", fact: "Hydrogen makes up ~75% of all normal matter in the universe by mass. Helium accounts for ~24%. All heavier elements combined make up less than 1%. We are made of rare heavy elements forged in stars.", tip: "🧠 Universe: 75% hydrogen, 24% helium, 1% everything else. We are the rare 1%." },
  { id: 's31', cat: 'science', emoji: '🌡️', subject: 'Science — Temperature', diff: 1, hook: "The coldest natural temperature ever recorded on Earth was in Antarctica.", fact: "The lowest natural surface temperature recorded: -89.2°C at Vostok Station, Antarctica, on 21 July 1983. By comparison, the average temperature on Mars is -65°C.", tip: "🧠 Coldest natural temp: -89.2°C, Vostok Station, Antarctica, 21 July 1983." },
  { id: 's32', cat: 'science', emoji: '🌊', subject: 'Science — Ocean', diff: 2, hook: "The ocean produces more oxygen than all the world\'s forests combined.", fact: "Marine phytoplankton produce approximately 50-80% of Earth\'s oxygen. The Amazon produces roughly 20%. The ocean is Earth\'s true oxygen factory, not the rainforests.", tip: "🧠 Ocean phytoplankton: 50-80% of Earth\'s oxygen. Amazon: 20%. Ocean wins." },
  { id: 's33', cat: 'science', emoji: '🦠', subject: 'Science — Microbiology', diff: 2, hook: "A teaspoon of healthy soil contains more microorganisms than there are people on Earth.", fact: "A single gram of fertile soil contains ~1 billion bacteria and ~1 million fungi. That is more living things than all 8 billion humans — in a pinch of dirt.", tip: "🧠 1 gram of soil: ~1 billion bacteria. More life in a pinch of dirt than all humans on Earth." },
  { id: 's34', cat: 'science', emoji: '🧬', subject: 'Science — Genetics', diff: 2, hook: "You have about 2% Neanderthal DNA if you are non-African.", fact: "Modern non-African humans carry ~1-4% Neanderthal DNA from interbreeding ~50,000 years ago. Some East Asians also carry Denisovan DNA. These ancient genes influence immune function and skin traits.", tip: "🧠 Non-Africans: 1-4% Neanderthal DNA. Ancient mixing is still in every non-African person." },
  { id: 's35', cat: 'science', emoji: '🔭', subject: 'Science — Astronomy', diff: 1, hook: "There are more stars in the universe than grains of sand on all Earth\'s beaches.", fact: "Estimated stars: ~10^24. Estimated beach sand grains: ~10^20. Stars outnumber sand by a factor of roughly 10,000. The universe is incomprehensibly vast.", tip: "🧠 Stars: ~10^24. Beach sand: ~10^20. Stars outnumber sand grains 10,000 to 1." },
  { id: 's36', cat: 'science', emoji: '🧪', subject: 'Science — Reactions', diff: 2, hook: "Mixing bleach and ammonia creates a toxic gas.", fact: "Bleach plus ammonia produces chloramine gas, which is highly toxic. Never mix cleaning products. Other dangerous combos: bleach plus vinegar makes chlorine gas.", tip: "🧠 Bleach + ammonia = chloramine gas. Toxic. Never mix cleaning products." },
  { id: 's37', cat: 'science', emoji: '🦋', subject: 'Science — Biology', diff: 2, hook: "Caterpillars completely dissolve inside their chrysalis before becoming butterflies.", fact: "During metamorphosis, the caterpillar\'s body breaks down into an undifferentiated soup of cells inside the chrysalis. These cells then completely reorganise into the butterfly body plan. It is not a slow transformation — it is total dissolution and rebuilding.", tip: "🧠 Butterfly metamorphosis: caterpillar dissolves into cell soup, then rebuilds entirely as butterfly." },
  { id: 's38', cat: 'science', emoji: '⚛️', subject: 'Science — Quantum', diff: 3, hook: "Particles can be in two places at once — until you look at them.", fact: "Quantum superposition: a particle exists in multiple states simultaneously until measured. This is not philosophy — it is experimentally confirmed physics that underpins modern semiconductors and lasers.", tip: "🧠 Quantum superposition: particles in multiple states until observed. Confirmed physics, not theory." },
  { id: 's39', cat: 'science', emoji: '🌋', subject: 'Science — Earth', diff: 2, hook: "Earth has a solid inner core and a liquid outer core.", fact: "Earth structure from outside: crust, mantle, liquid outer core (iron/nickel), solid inner core. The temperature at Earth\'s centre is ~5,000-6,000°C — similar to the Sun\'s surface temperature.", tip: "🧠 Earth\'s core: liquid outer, solid inner. Centre temp: ~5,000°C — same as the Sun\'s surface." },
  { id: 's40', cat: 'science', emoji: '🌊', subject: 'Science — Waves', diff: 2, hook: "Sound travels nearly 5 times faster in water than in air.", fact: "Speed of sound in air: ~343 m/s. In water: ~1,480 m/s. In steel: ~5,960 m/s. Denser, less compressible media transmit sound faster. This is why sonar works over vast ocean distances.", tip: "🧠 Sound: air 343 m/s, water 1,480 m/s, steel 5,960 m/s. Denser = faster." },
  { id: 's41', cat: 'science', emoji: '💧', subject: 'Science — Chemistry', diff: 1, hook: "Oil and water don\'t mix because of molecular polarity.", fact: "Water is a polar molecule. Oil is non-polar. Polar molecules attract other polar molecules. Soap works by having one polar end and one non-polar end, bridging both.", tip: "🧠 Water = polar. Oil = non-polar. Like attracts like. Soap bridges both." },
  { id: 's42', cat: 'science', emoji: '🌙', subject: 'Science — Moon', diff: 1, hook: "The Moon is moving away from Earth at about 3.8 cm per year.", fact: "The Moon recedes due to tidal interactions. Four billion years ago, the Moon was about 15 times closer. The tides would have been enormous.", tip: "🧠 Moon drifts away 3.8 cm/year. Was 15x closer 4 billion years ago." },
  { id: 's43', cat: 'science', emoji: '⚗️', subject: 'Science — Chemistry', diff: 2, hook: "Gallium melts in your hand — its melting point is just above room temperature.", fact: "Gallium is a metal that melts at 29.76°C. Since human body temperature is ~37°C, gallium melts in your palm within minutes. It is completely safe to hold briefly.", tip: "🧠 Gallium: melts at 29.76°C. Hold it and watch it liquify. Completely safe." },
  { id: 's44', cat: 'science', emoji: '🧬', subject: 'Science — Biology', diff: 2, hook: "The mitochondria truly is the powerhouse of the cell.", fact: "Mitochondria convert glucose and oxygen into ATP — the cell\'s energy currency. Each cell has hundreds to thousands of mitochondria. They have their own DNA, suggesting they were once separate organisms absorbed by cells 2 billion years ago.", tip: "🧠 Mitochondria: make ATP from glucose and oxygen. Own DNA = were once separate bacteria." },
  { id: 's45', cat: 'science', emoji: '🌪️', subject: 'Science — Meteorology', diff: 2, hook: "Lightning strikes Earth approximately 100 times per second.", fact: "Earth is struck by lightning about 8 million times per day. Around 1,800 thunderstorms are active at any moment. Lightning heats air to ~30,000°C — 5 times hotter than the Sun\'s surface.", tip: "🧠 Lightning: 100 strikes/second worldwide. Heats air to 30,000°C — hotter than the Sun\'s surface." },
  { id: 's46', cat: 'science', emoji: '🔭', subject: 'Science — Space', diff: 2, hook: "We have sent only five spacecraft beyond our solar system.", fact: "Pioneer 10, Pioneer 11, Voyager 1, Voyager 2, and New Horizons. Voyager 1 is the furthest human-made object — about 24 billion km from Earth in 2024 — launched in 1977.", tip: "🧠 5 spacecraft left the solar system. Voyager 1 is furthest (~24 billion km). Launched 1977." },
  { id: 's47', cat: 'science', emoji: '⚡', subject: 'Science — Energy', diff: 2, hook: "The energy in a single bolt of lightning could power a 100-watt bulb for 3 months.", fact: "A lightning bolt contains roughly 250 kWh of energy. A 100W bulb uses 2.4 kWh per day — about 104 days of light per bolt. However, delivery in microseconds makes it impossible to harvest.", tip: "🧠 Lightning: 250 kWh per bolt = ~3 months of a 100W bulb. Too fast to harvest." },
  { id: 's48', cat: 'science', emoji: '🌈', subject: 'Science — Light', diff: 1, hook: "White light contains every colour you have ever seen.", fact: "White light is a mix of all visible wavelengths. A prism splits it into the spectrum. Beyond visible light: infrared (remotes), ultraviolet (sunburn), microwaves, X-rays, gamma rays.", tip: "🧠 White light = all colours mixed. Prism splits them. Same physics as rainbows." },
  { id: 's49', cat: 'science', emoji: '🧲', subject: 'Science — Materials', diff: 2, hook: "Spider silk is stronger than steel by weight and tougher than Kevlar.", fact: "Spider silk has tensile strength ~1,000-1,500 MPa — comparable to high-grade steel but at a fraction of the weight. It is also more elastic, absorbing more energy before breaking.", tip: "🧠 Spider silk: as strong as steel by weight, tougher than Kevlar. Incredible natural material." },
  { id: 's50', cat: 'science', emoji: '💊', subject: 'Science — Medicine', diff: 1, hook: "The placebo effect works even when patients know they are taking a placebo.", fact: "Open-label placebo trials show patients can experience real symptom relief even when told the pill contains no active ingredients. The ritual of taking medicine triggers genuine physiological responses.", tip: "🧠 Placebos work even when patients know. Ritual and expectation drive real effects." },
  { id: 's51', cat: 'science', emoji: '🔬', subject: 'Science — Biology', diff: 2, hook: "Trees communicate with each other through underground fungal networks.", fact: "Mycorrhizal fungi form networks between tree roots — the \'Wood Wide Web\'. Trees use these to share nutrients and chemical distress signals. A mother tree can preferentially feed her own offspring through the network.", tip: "🧠 Wood Wide Web: fungal networks let trees share nutrients and warn neighbours of threats." },
  { id: 's52', cat: 'science', emoji: '🦠', subject: 'Science — Biology', diff: 1, hook: "Your body contains roughly as many bacteria cells as human cells.", fact: "Your gut contains ~38 trillion bacteria — nearly equal to your total human cell count. These bacteria aid digestion, produce vitamins, regulate immunity, and influence mood via the gut-brain axis.", tip: "🧠 38 trillion gut bacteria = your human cell count. Gut health affects mood and immunity." },
  { id: 's53', cat: 'science', emoji: '🌡️', subject: 'Science — Biology', diff: 2, hook: "Tardigrades can survive in space, extreme cold, radiation, and near-vacuum.", fact: "Tardigrades (water bears) are ~0.5mm animals that survive: vacuum of space, radiation 1,000 times lethal to humans, temperatures from -272°C to +150°C, and 30 years of desiccation. They enter a \'tun\' state where metabolism drops to 0.01%.", tip: "🧠 Tardigrades: survive space, radiation 1000x lethal dose, -272°C to +150°C. Basically unkillable." },
  { id: 's54', cat: 'science', emoji: '🧬', subject: 'Science — Evolution', diff: 1, hook: "All life on Earth shares the same genetic code.", fact: "Every living organism uses the same 4-base DNA code (A, T, G, C). This near-universal code is the strongest evidence that all life shares a common ancestor — from bacteria to blue whales.", tip: "🧠 Universal genetic code: all life uses same 4-base DNA. Strongest evidence for common ancestry." },
  { id: 's55', cat: 'science', emoji: '⚡', subject: 'Science — Physics', diff: 1, hook: "The static electricity in a single thundercloud can reach 300 million volts.", fact: "A large thundercloud builds up ~300 million volts between cloud and ground. Lightning is the discharge — a massive spark equalising the charge. The discharge creates temperatures hotter than the Sun\'s surface.", tip: "🧠 Thundercloud voltage: up to 300 million volts. Lightning = giant spark equalising charge." },
  { id: 's56', cat: 'science', emoji: '🔭', subject: 'Science — Astronomy', diff: 2, hook: "Every atom heavier than iron was made in a supernova or neutron star collision.", fact: "Hydrogen and helium formed in the Big Bang. Elements up to iron are forged in stars. Everything heavier — gold, silver, uranium, iodine in your thyroid — was created in stellar explosions. You are literally made of stardust.", tip: "🧠 Gold, silver, uranium: all made in supernovas. You contain stardust from stellar explosions." },
  { id: 's57', cat: 'science', emoji: '🌍', subject: 'Science — Atmosphere', diff: 2, hook: "Without the greenhouse effect, Earth\'s average temperature would be -18°C.", fact: "The greenhouse effect traps heat via atmospheric gases. Without it, Earth\'s average temperature would be -18°C instead of +15°C. The issue is enhancement by human emissions, not the effect itself.", tip: "🧠 Without greenhouse effect: Earth = -18°C. Natural warming adds 33°C. Human emissions enhance it." },
  { id: 's58', cat: 'science', emoji: '🧪', subject: 'Science — Chemistry', diff: 1, hook: "The smell of rain has a name — it is called petrichor.", fact: "Petrichor is the earthy smell when rain hits dry earth. Caused by plant oil absorbed into soil plus geosmin (produced by bacteria), released when rain hits. Named by Australian scientists in 1964.", tip: "🧠 Petrichor: smell of rain on dry earth. Plant oil + bacterial geosmin. Named 1964." },
  { id: 's59', cat: 'science', emoji: '⚗️', subject: 'Science — States', diff: 2, hook: "At extremely high pressures, hydrogen becomes a metal.", fact: "At pressures above ~400 GPa, hydrogen transitions into a metallic state where electrons flow freely. This metallic hydrogen likely exists inside Jupiter and Saturn. Scientists produced it briefly in labs in 2017.", tip: "🧠 Metallic hydrogen: exists inside gas giants. Briefly made in a lab in 2017." },
  { id: 's60', cat: 'science', emoji: '🦴', subject: 'Science — Evolution', diff: 1, hook: "Whales evolved from a small four-legged land animal that walked into the sea.", fact: "Whales descend from Pakicetus, a wolf-sized hoofed mammal that lived ~50 million years ago. Over millions of years its descendants returned to water — limbs became flippers, nostrils migrated to the top of the head becoming a blowhole.", tip: "🧠 Whales evolved from land mammals. Closest living relative: hippos. They chose the ocean." },

  { id: 'h29', cat: 'history', emoji: '🏰', subject: 'History — Medieval', diff: 2, hook: "The Black Death killed up to 60% of Europe in just 7 years.", fact: "The Black Death (1347-1351) killed an estimated 30-60% of Europe\'s population — 25-50 million people. Caused by Yersinia pestis bacteria spread by fleas on rats. Europe\'s population took ~200 years to recover.", tip: "🧠 Black Death: 1347-51, killed up to 60% of Europe. 200 years to recover." },
  { id: 'h30', cat: 'history', emoji: '🗡️', subject: 'History — Ancient', diff: 1, hook: "Julius Caesar was never Roman Emperor — he was a dictator.", fact: "Julius Caesar was Dictator Perpetuo, not emperor. The first Roman Emperor was Augustus (his adopted son), who took power in 27 BC after Caesar was assassinated in 44 BC.", tip: "🧠 Caesar: never emperor. First emperor was Augustus, 27 BC. Caesar was \'Dictator Perpetuo\'." },
  { id: 'h31', cat: 'history', emoji: '🌍', subject: 'History — Empires', diff: 2, hook: "The British Empire at its peak covered 24% of the world\'s land area.", fact: "At its greatest extent in the 1920s, the British Empire covered ~35.5 million km2 — about 24% of Earth\'s land — and contained ~412 million people, roughly 23% of the world population at the time.", tip: "🧠 British Empire peak (1920s): 24% of land, 23% of world population. Largest empire in history." },
  { id: 'h32', cat: 'history', emoji: '📜', subject: 'History — Documents', diff: 2, hook: "The Magna Carta was annulled within 10 weeks of being signed.", fact: "King John signed it on 15 June 1215 under pressure from rebellious barons. He lobbied Pope Innocent III to annul it, which the Pope did on 24 August 1215 — just 10 weeks later. Civil war resumed immediately.", tip: "🧠 Magna Carta: signed June 1215, annulled August 1215 — just 10 weeks later." },
  { id: 'h33', cat: 'history', emoji: '⚔️', subject: 'History — Battles', diff: 1, hook: "The Battle of Waterloo ended Napoleon\'s empire in just one day.", fact: "On 18 June 1815, Napoleon met Wellington\'s forces near Waterloo, Belgium. The battle lasted about 9 hours. Napoleon\'s defeat ended his rule and led to exile on Saint Helena, where he died in 1821.", tip: "🧠 Waterloo: 18 June 1815, ~9 hours long. Ended Napoleon\'s rule. Exile and death followed." },
  { id: 'h34', cat: 'history', emoji: '🏛️', subject: 'History — Ancient Greece', diff: 2, hook: "The ancient Greeks knew the Earth was round — and calculated its circumference.", fact: "Eratosthenes calculated Earth\'s circumference around 240 BC to within 1% accuracy using shadow angles. The flat Earth myth about ancient people is largely false — educated Greeks knew Earth was spherical.", tip: "🧠 Eratosthenes calculated Earth\'s circumference in 240 BC — accurate to within 1%." },
  { id: 'h35', cat: 'history', emoji: '🚢', subject: 'History — Exploration', diff: 2, hook: "Magellan didn\'t complete the first circumnavigation — he was killed halfway through.", fact: "Ferdinand Magellan led the expedition but was killed in the Philippines in 1521. His navigator Juan Sebastian Elcano brought the surviving ship home to Spain in September 1522, completing the first circumnavigation.", tip: "🧠 First circumnavigation: Magellan started it, was killed. Elcano finished it. 1519-1522." },
  { id: 'h36', cat: 'history', emoji: '🌍', subject: 'History — Colonialism', diff: 2, hook: "The scramble for Africa carved up the entire continent at one conference.", fact: "The Berlin Conference of 1884-85 had 14 European nations divide Africa among themselves — with no African representatives. By 1914, only Ethiopia and Liberia remained independent.", tip: "🧠 Berlin Conference 1884: 14 nations divided all Africa. No Africans present." },
  { id: 'h37', cat: 'history', emoji: '🏯', subject: 'History — Japan', diff: 2, hook: "The last samurai died in 1877 — the year after most people think.", fact: "The Satsuma Rebellion of 1877 was the last samurai uprising, led by Saigo Takamori. He was defeated and died at Shiroyama. The 2003 film \'The Last Samurai\' is loosely based on this real event.", tip: "🧠 Last real samurai uprising: Saigo Takamori, Satsuma Rebellion, 1877." },
  { id: 'h38', cat: 'history', emoji: '⚗️', subject: 'History — Science', diff: 2, hook: "Isaac Newton spent more time on alchemy and theology than on physics.", fact: "Newton wrote over a million words on alchemy and 1.3 million on theology — more than on physics and mathematics combined. He searched for the philosopher\'s stone and tried to decode the Book of Revelation.", tip: "🧠 Newton: more words on alchemy and theology than physics. History remembers the apple, not the alchemy." },
  { id: 'h39', cat: 'history', emoji: '🌍', subject: 'History — Trade', diff: 1, hook: "The Silk Road was not a single road — it was a network of routes.", fact: "The Silk Road was a collection of overland and sea trade routes connecting China, Central Asia, India, the Middle East, and Europe from ~200 BC to the 1450s. It spread trade, religions, diseases, and technologies.", tip: "🧠 Silk Road: not one road — a network. 200 BC to 1450s. Trade, religion, disease all spread via it." },
  { id: 'h40', cat: 'history', emoji: '🏛️', subject: 'History — Rome', diff: 2, hook: "The Roman calendar originally had only 10 months — starting in March.", fact: "The original Roman calendar had 10 months and 304 days, beginning in March. January and February were added later. Julius Caesar reformed the calendar in 46 BC. The Gregorian calendar of 1582 corrected the remaining error.", tip: "🧠 Roman calendar: originally 10 months, started March. Caesar fixed it in 46 BC." },
  { id: 'h41', cat: 'history', emoji: '🗽', subject: 'History — Revolution', diff: 1, hook: "The French Revolution began with a bread riot.", fact: "The Women\'s March on Versailles on 5 October 1789 began as a protest over the price and scarcity of bread. Thousands of women marched 12 miles to Versailles, forcing the royal family back to Paris.", tip: "🧠 French Revolution: started with a bread riot. Women marched 12 miles to Versailles for bread." },
  { id: 'h42', cat: 'history', emoji: '🚀', subject: 'History — Cold War', diff: 2, hook: "The Soviet Union won the first decade of the Space Race.", fact: "Yuri Gagarin became the first human in space on 12 April 1961. The Soviets also launched the first satellite (Sputnik, 1957), first animal in space (Laika, 1957), and first spacewalk (Leonov, 1965). The US won the Moon race in 1969.", tip: "🧠 Space Race: USSR won first 10 years. USA won the Moon. Gagarin first: 12 April 1961." },
  { id: 'h43', cat: 'history', emoji: '⚖️', subject: 'History — Law', diff: 2, hook: "Trial by combat was a legal option in England until 1819.", fact: "\'Wager of battle\' was on the books until 1819. In 1817, Abraham Thornton demanded the right to trial by combat against his accuser. The court could not deny it — so Parliament abolished the practice the following year.", tip: "🧠 Trial by combat: legal in England until 1819. Abolished only after someone actually demanded it." },
  { id: 'h44', cat: 'history', emoji: '🌍', subject: 'History — Geography', diff: 2, hook: "Constantinople fell in 1453 — ending 1,100 years of the Eastern Roman Empire.", fact: "Constantinople (modern Istanbul) fell to Ottoman Sultan Mehmed II on 29 May 1453, ending the Byzantine (Eastern Roman) Empire that had survived since Rome\'s western fall. The date often marks the start of the Early Modern period.", tip: "🧠 Constantinople fell 29 May 1453. End of 1,100 years of Eastern Rome." },
  { id: 'h45', cat: 'history', emoji: '🏰', subject: 'History — Castles', diff: 1, hook: "Most medieval castles were not grey — they were painted white.", fact: "Medieval stone castles were typically plastered and whitewashed, gleaming white for miles. The bare grey stone we see today is the result of centuries of weathering. The White Tower at the Tower of London is named for this reason.", tip: "🧠 Medieval castles: originally white-plastered. The grey stone we see today = weathering." },
  { id: 'h46', cat: 'history', emoji: '⚔️', subject: 'History — WW1', diff: 2, hook: "The Christmas Truce of 1914 really happened — soldiers played football in no man\'s land.", fact: "On Christmas Eve 1914, German and British soldiers spontaneously stopped fighting, sang carols, and met in no man\'s land. Eyewitnesses confirm football matches took place. High command on both sides disapproved.", tip: "🧠 Christmas Truce 1914: real. Football in no man\'s land. Never officially repeated." },
  { id: 'h47', cat: 'history', emoji: '🌍', subject: 'History — Ancient', diff: 2, hook: "The ancient city of Pompeii was buried and forgotten for 1,700 years.", fact: "Vesuvius erupted on 24 August 79 AD, burying Pompeii under 4-6 metres of ash. The city was completely forgotten until excavations began in 1748. The preserved buildings revealed Roman daily life in extraordinary detail.", tip: "🧠 Pompeii: buried 79 AD, forgotten 1,700 years, rediscovered 1748. Time capsule of Roman life." },
  { id: 'h48', cat: 'history', emoji: '🏛️', subject: 'History — Democracy', diff: 2, hook: "The world\'s oldest parliament still in operation is in Iceland.", fact: "The Althing was established in 930 AD in Iceland — the world\'s oldest continuously operating parliament. It met at Thingvellir until 1798. Iceland used it to resolve disputes and make laws as a republic with no king.", tip: "🧠 World\'s oldest parliament: Althing, Iceland, founded 930 AD. Still operating today." },
  { id: 'h49', cat: 'history', emoji: '🌍', subject: 'History — Disease', diff: 2, hook: "The 1918 Spanish Flu killed more people than World War One.", fact: "WW1 deaths (1914-1918): ~20 million. Spanish Flu deaths (1918-1920): ~50-100 million globally. The flu killed more people in 25 weeks than AIDS killed in 25 years.", tip: "🧠 Spanish Flu: 50-100M dead vs WW1\'s 20M. More deaths in 25 weeks than AIDS in 25 years." },
  { id: 'h50', cat: 'history', emoji: '🚢', subject: 'History — Naval', diff: 1, hook: "The Titanic sank only 2 hours and 40 minutes after hitting the iceberg.", fact: "Titanic struck the iceberg at 11:40 PM on 14 April 1912 and sank at 2:20 AM on 15 April. Of 2,224 aboard, 1,517 died. There were only 20 lifeboats — capacity for 1,178 people.", tip: "🧠 Titanic: 2h 40m from iceberg to sinking. 1,517 dead. Only 20 lifeboats for 2,224 people." },
  { id: 'h51', cat: 'history', emoji: '📜', subject: 'History — Books', diff: 1, hook: "The Bible is the best-selling book in history.", fact: "The Bible has sold an estimated 5-7 billion copies. The Quran (800 million+) and Mao\'s Little Red Book (~900 million) follow. Don Quixote (~500 million) is the best-selling novel.", tip: "🧠 Best-selling book: Bible (5-7B copies). Then Little Red Book and Quran." },
  { id: 'h52', cat: 'history', emoji: '🏛️', subject: 'History — Religion', diff: 2, hook: "The Catholic Church once had three popes simultaneously.", fact: "The Western Schism (1378-1417) produced up to three competing claimants to the papacy — from Rome, Avignon, and Pisa. The Council of Constance resolved it by deposing all three and electing a new pope.", tip: "🧠 Western Schism 1378-1417: three simultaneous popes. Council of Constance sorted it out." },
  { id: 'h53', cat: 'history', emoji: '🌍', subject: 'History — Migration', diff: 2, hook: "Humans reached Australia ~65,000 years ago — crossing open ocean before anyone else.", fact: "Indigenous Australians crossed open sea from Southeast Asia ~65,000 years ago. This was the first long-distance ocean crossing in human history — achieved without agriculture, writing, or metal tools.", tip: "🧠 Indigenous Australians: crossed open ocean ~65,000 years ago. First ocean crossing in history." },
  { id: 'h54', cat: 'history', emoji: '🏰', subject: 'History — Buildings', diff: 2, hook: "The Great Pyramid was the tallest man-made structure for 3,800 years.", fact: "Built ~2560 BC, the Great Pyramid (146.5m) held the record until Lincoln Cathedral surpassed it around 1300 AD. The pyramid was the tallest for roughly 3,800 years — an unbroken record never matched.", tip: "🧠 Great Pyramid: tallest structure for 3,800 years. Beaten around 1300 AD by Lincoln Cathedral." },
  { id: 'h55', cat: 'history', emoji: '🚀', subject: 'History — Technology', diff: 2, hook: "The Apollo Guidance Computer had less power than a modern calculator.", fact: "Apollo 11\'s computer had 4 KB of RAM and 72 KB of ROM. A basic calculator has more. A modern smartphone is billions of times more powerful. Yet the Apollo computer landed humans on the Moon.", tip: "🧠 Apollo computer: 4 KB RAM, less than a calculator. Still landed humans on the Moon." },
  { id: 'h56', cat: 'history', emoji: '🌍', subject: 'History — Wars', diff: 1, hook: "The Vietnam War lasted 20 years — and the US was only involved for the last 8.", fact: "Vietnam conflict began in 1955. US military involvement escalated from 1965-1973. The war killed an estimated 3.5 million Vietnamese (military and civilian) and 58,000 Americans.", tip: "🧠 Vietnam War: started 1955, ended 1975. US involvement 1965-1973. 3.5M Vietnamese deaths." },
  { id: 'h57', cat: 'history', emoji: '🌍', subject: 'History — Independence', diff: 2, hook: "India and Pakistan became independent on consecutive days in 1947.", fact: "British India was partitioned on 14-15 August 1947. Pakistan: 14 August; India: 15 August. The partition triggered one of history\'s largest mass migrations — 10-20 million people displaced.", tip: "🧠 India (Aug 15) and Pakistan (Aug 14): independent on consecutive days. 10-20M people displaced." },
  { id: 'h58', cat: 'history', emoji: '⚗️', subject: 'History — Alchemy', diff: 2, hook: "Alchemy failed its goals but accidentally created modern chemistry.", fact: "Alchemists tried to turn lead into gold and create the elixir of life — and failed. But in the process they discovered sulphuric acid, phosphorus, ether, and processes that became the foundation of modern chemistry.", tip: "🧠 Alchemy: failed at gold and immortality, accidentally invented modern chemistry." },
  { id: 'h59', cat: 'history', emoji: '📜', subject: 'History — Language', diff: 2, hook: "Latin never died — it evolved into five living languages.", fact: "Latin did not disappear — regional dialects evolved into Italian, Spanish, French, Portuguese, and Romanian. All five Romance languages descend from spoken (Vulgar) Latin, not the classical written form.", tip: "🧠 Latin became: Italian, Spanish, French, Portuguese, and Romanian. Still alive in 5 forms." },
  { id: 'h60', cat: 'history', emoji: '⚔️', subject: 'History — Medieval', diff: 2, hook: "The Mongol Empire was the largest contiguous land empire in history.", fact: "At its peak in the 1270s, the Mongol Empire covered ~24 million km2 — stretching from Poland to Korea, from Siberia to Vietnam. It was the largest single land mass ever under one government.", tip: "🧠 Mongol Empire: largest contiguous land empire. Poland to Korea. 13th century." },
  { id: 'h61', cat: 'history', emoji: '🏛️', subject: 'History — Archaeology', diff: 2, hook: "Troy was thought to be mythical until 1868 when excavations revealed it was real.", fact: "Heinrich Schliemann began excavating in northwest Turkey in 1868, convinced the Iliad was historical. He found nine successive ancient cities stacked on top of each other. Troy VI or VII (~1200 BC) likely corresponds to the Trojan War.", tip: "🧠 Troy: thought mythical until Schliemann excavated it in 1868. Nine cities stacked on each other." },
  { id: 'h62', cat: 'history', emoji: '🌍', subject: 'History — Modern', diff: 1, hook: "The Cold War ended without a single direct armed conflict between the USA and USSR.", fact: "The Cold War lasted 44 years (1947-1991). The two superpowers never directly fought each other militarily despite both having thousands of nuclear weapons. They competed through proxy wars, espionage, and propaganda.", tip: "🧠 Cold War: 44 years, zero direct US-USSR combat. Proxy wars and espionage only." },
  { id: 'h63', cat: 'history', emoji: '🌍', subject: 'History — Trade', diff: 2, hook: "The East India Company was once more powerful than most countries.", fact: "At its peak in the mid-1800s, the British East India Company controlled almost all of India, had its own army (larger than Britain\'s), collected taxes, and ran courts. It was effectively a private colonial government.", tip: "🧠 East India Company: private company that ruled India, had its own army, and collected taxes." },
  { id: 'h64', cat: 'history', emoji: '🗺️', subject: 'History — Exploration', diff: 2, hook: "Antarctica was the last continent to be discovered — as recently as 1820.", fact: "Antarctica was not sighted until 1820 — by three expeditions almost simultaneously (Russian, British, and American). It was the last continent discovered. No humans had ever set eyes on it before that year.", tip: "🧠 Antarctica: last continent discovered, sighted first in 1820. Never seen by humans before." },
  { id: 'h65', cat: 'history', emoji: '🏰', subject: 'History — Sieges', diff: 2, hook: "The Siege of Stalingrad was the deadliest battle in human history.", fact: "The Battle of Stalingrad (1942-1943) resulted in ~2 million casualties on both sides — the most of any battle in history. The German defeat marked the turning point of World War 2 on the Eastern Front.", tip: "🧠 Stalingrad: ~2 million casualties. Deadliest battle in history. Turned WW2 in the East." },
  { id: 'h66', cat: 'history', emoji: '🌍', subject: 'History — Economics', diff: 2, hook: "The Dutch East India Company was the world\'s first publicly traded company.", fact: "The VOC (Vereenigde Oost-Indische Compagnie), founded in 1602, was the first company to issue shares to the public on a stock exchange — the Amsterdam Stock Exchange. It was also the world\'s first multinational corporation.", tip: "🧠 VOC (1602): world\'s first publicly traded company and first multinational. Founded the stock exchange." },
  { id: 'h67', cat: 'history', emoji: '🏛️', subject: 'History — Ancient Egypt', diff: 2, hook: "Cleopatra lived closer in time to the Moon landing than to the building of the pyramids.", fact: "Cleopatra died in 30 BC. The Great Pyramid was built ~2560 BC — about 2,530 years before Cleopatra. The Moon landing was 1969 — only 2,000 years after Cleopatra. The pyramids are ancient even to ancient Egypt.", tip: "🧠 Cleopatra was closer to the Moon landing than to the building of the pyramids. The pyramids are that old." },
  { id: 'h68', cat: 'history', emoji: '⚔️', subject: 'History — WW2', diff: 2, hook: "D-Day was the largest seaborne invasion in history — and almost failed.", fact: "On 6 June 1944, ~156,000 Allied troops crossed the English Channel to land in Normandy. It was the largest amphibious assault ever. The operation had over 10,000 Allied casualties on the first day alone.", tip: "🧠 D-Day: 6 June 1944, 156,000 troops, largest seaborne invasion ever. 10,000 casualties day one." },

  { id: 'geo27', cat: 'geo', emoji: '🌍', subject: 'Geography — Countries', diff: 1, hook: "There are 195 countries in the world — but only 193 in the UN.", fact: "The UN has 193 member states. Vatican City and Palestine are observer states. Taiwan is not a UN member. Kosovo is recognised by ~100 countries but not others. Counting countries depends on who is counting.", tip: "🧠 UN members: 193. Vatican and Palestine: observers. Taiwan and Kosovo: complicated." },
  { id: 'geo28', cat: 'geo', emoji: '🗺️', subject: 'Geography — Borders', diff: 2, hook: "There is a point in the US where four states meet simultaneously.", fact: "Four Corners is the only place in the US where four states meet: Arizona, Utah, Colorado, and New Mexico. You can stand in all four states at once. It is managed as a national monument.", tip: "🧠 Four Corners: only US quadripoint. Arizona, Utah, Colorado, New Mexico all meet at one point." },
  { id: 'geo29', cat: 'geo', emoji: '⛰️', subject: 'Geography — Height', diff: 1, hook: "Mauna Kea is taller than Everest when measured from base to summit.", fact: "Everest is highest above sea level (8,849m). Mauna Kea rises only 4,205m above sea but extends ~6,000m below — total height ~10,200m from its base on the ocean floor.", tip: "🧠 Mauna Kea: 4,205m above sea but 10,200m total from seafloor. Taller than Everest by that measure." },
  { id: 'geo30', cat: 'geo', emoji: '🌊', subject: 'Geography — Seas', diff: 2, hook: "The Dead Sea is not a sea — it is a lake.", fact: "The Dead Sea is a hypersaline lake between Israel and Jordan — 10 times saltier than ocean water. Water flows in from the Jordan River but has nowhere to drain. At 430m below sea level, it is Earth\'s lowest surface point.", tip: "🧠 Dead Sea: a lake, not a sea. 10x ocean saltiness. Earth\'s lowest point: 430m below sea level." },
  { id: 'geo31', cat: 'geo', emoji: '🗺️', subject: 'Geography — Rivers', diff: 1, hook: "The Amazon discharges more water than the next seven largest rivers combined.", fact: "The Amazon discharges ~209,000 cubic metres per second — about 20% of all freshwater entering the world\'s oceans. One river alone delivers more than the next seven largest rivers combined.", tip: "🧠 Amazon: 20% of all river freshwater into the ocean. More than next 7 largest rivers combined." },
  { id: 'geo32', cat: 'geo', emoji: '🏔️', subject: 'Geography — Volcanoes', diff: 2, hook: "Iceland sits on two tectonic plates and gets wider every year.", fact: "Iceland straddles the Mid-Atlantic Ridge — the boundary between the Eurasian and North American plates. The island grows ~2 cm wider per year as plates separate. It has ~130 volcanoes, about 30 active.", tip: "🧠 Iceland: on two tectonic plates, grows 2 cm/year. ~130 volcanoes, 30 active." },
  { id: 'geo33', cat: 'geo', emoji: '🌡️', subject: 'Geography — Climate', diff: 1, hook: "The Sahara was a green savanna just 6,000 years ago.", fact: "During the African Humid Period (~11,000-5,000 years ago), the Sahara had lakes, rivers, hippos, and human settlements. Rock art in current desert shows the abundant wildlife. It dried out due to orbital cycles.", tip: "🧠 Green Sahara: 6,000 years ago had lakes and hippos. Rock art in current desert proves it." },
  { id: 'geo34', cat: 'geo', emoji: '🏝️', subject: 'Geography — Islands', diff: 2, hook: "Indonesia has more than 17,000 islands — and only 6,000 are inhabited.", fact: "Indonesia consists of ~17,508 islands. It spans ~5,100 km east to west — as wide as the US. It has the world\'s 4th largest population (~278 million) spread across this vast archipelago.", tip: "🧠 Indonesia: 17,508 islands, 6,000 inhabited. As wide as the USA." },
  { id: 'geo35', cat: 'geo', emoji: '🌍', subject: 'Geography — Africa', diff: 1, hook: "Nigeria has more people than all of Russia.", fact: "Nigeria\'s population is ~220 million and growing rapidly. Russia has ~145 million. Nigeria is projected to become the world\'s 3rd most populous country by 2100, overtaking the US.", tip: "🧠 Nigeria: 220M people vs Russia\'s 145M. Projected 3rd largest country by 2100." },
  { id: 'geo36', cat: 'geo', emoji: '🗺️', subject: 'Geography — Borders', diff: 2, hook: "France shares a border with Brazil and Suriname.", fact: "French Guiana is an overseas department of France located in South America. This makes France border Brazil (~730 km) and Suriname (~510 km) — making it one of the most geographically surprising borders.", tip: "🧠 France borders Brazil and Suriname — via French Guiana in South America." },
  { id: 'geo37', cat: 'geo', emoji: '⛰️', subject: 'Geography — Desert', diff: 1, hook: "The Sahara desert is roughly the same size as the United States.", fact: "The Sahara covers approximately 9.2 million km2. The contiguous US covers ~8 million km2. The Sahara is the largest hot desert and third largest overall (after Antarctica and the Arctic).", tip: "🧠 Sahara: ~9.2 million km2 — roughly the same size as the USA." },
  { id: 'geo38', cat: 'geo', emoji: '🌊', subject: 'Geography — Tides', diff: 2, hook: "Some places have barely any tides while others have tides over 16 metres.", fact: "Bay of Fundy (Canada) has tidal ranges up to 16.3 metres — the highest in the world. The Mediterranean Sea has almost no tides (often under 30cm) due to its nearly enclosed geography.", tip: "🧠 Bay of Fundy: 16.3m tides — world\'s highest. Mediterranean: barely any tides at all." },
  { id: 'geo39', cat: 'geo', emoji: '🌍', subject: 'Geography — Population', diff: 2, hook: "More people live in the Philippines than in the entire continent of Australia.", fact: "The Philippines has ~115 million people. Australia has ~26 million — on a continent 26 times larger. The Philippines packs more than four times as many people into a much smaller space.", tip: "🧠 Philippines: 115M people. Australia: 26M on a continent 26x bigger." },
  { id: 'geo40', cat: 'geo', emoji: '🗺️', subject: 'Geography — Capitals', diff: 1, hook: "The capital of Australia is Canberra — not Sydney or Melbourne.", fact: "Most people guess Sydney (largest city) or Melbourne (former capital). Canberra was purpose-built as a compromise between the two. It became the capital in 1927.", tip: "🧠 Australia capital: Canberra, purpose-built compromise between Sydney and Melbourne. Capital since 1927." },
  { id: 'geo41', cat: 'geo', emoji: '🌋', subject: 'Geography — Ring of Fire', diff: 2, hook: "90% of the world\'s earthquakes occur along the Pacific Ring of Fire.", fact: "The Ring of Fire is a ~40,000 km horseshoe of tectonic activity around the Pacific Ocean. It accounts for ~90% of earthquakes and ~75% of active volcanoes globally.", tip: "🧠 Ring of Fire: 40,000 km horseshoe. 90% of earthquakes, 75% of active volcanoes." },
  { id: 'geo42', cat: 'geo', emoji: '🏔️', subject: 'Geography — Ice', diff: 1, hook: "Greenland holds 80% of the world\'s freshwater ice.", fact: "The Greenland Ice Sheet contains ~2.85 million km3 of ice — about 80% of Earth\'s freshwater ice. If it all melted, sea levels would rise ~7 metres. Antarctica holds enough for +61 metres.", tip: "🧠 Greenland: 80% of Earth\'s freshwater ice. If melted: sea level rises 7m. Antarctica: +61m." },
  { id: 'geo43', cat: 'geo', emoji: '🌍', subject: 'Geography — Landlocked', diff: 2, hook: "The only doubly landlocked country in the world is Liechtenstein.", fact: "A doubly landlocked country is surrounded entirely by landlocked countries — you cross two borders to reach the sea. Liechtenstein (between Switzerland and Austria) and Uzbekistan are the only two.", tip: "🧠 Doubly landlocked: Liechtenstein and Uzbekistan. Surrounded entirely by landlocked neighbours." },
  { id: 'geo44', cat: 'geo', emoji: '🗺️', subject: 'Geography — Remoteness', diff: 1, hook: "New Zealand is the most remote inhabited country on Earth.", fact: "New Zealand is over 2,000 km from the nearest large landmass (Australia). It sits on two tectonic plates and was one of the last places settled by humans, around 1300 AD by Maori ancestors.", tip: "🧠 New Zealand: most remote country. 2,000 km from Australia. Settled by humans only ~1300 AD." },
  { id: 'geo45', cat: 'geo', emoji: '⛰️', subject: 'Geography — Mountains', diff: 1, hook: "The Andes is the world\'s longest mountain range above sea level.", fact: "The Andes stretches ~7,000 km along South America\'s western coast. It is the world\'s longest above-water mountain range. The underwater Mid-Ocean Ridge system (~65,000 km) is far longer but mostly submerged.", tip: "🧠 Andes: 7,000 km, world\'s longest above-water range. Mid-ocean ridges: 65,000 km but underwater." },
  { id: 'geo46', cat: 'geo', emoji: '🌊', subject: 'Geography — Oceans', diff: 2, hook: "Less than 20% of the ocean floor has been mapped in detail.", fact: "Only about 20-21% of the world\'s ocean floor has been mapped at high resolution as of 2023. We have better maps of Mars and the Moon than of our own seafloor.", tip: "🧠 Ocean floor: only 20% mapped in detail. We know Mars better than our own seafloor." },
  { id: 'geo47', cat: 'geo', emoji: '🌊', subject: 'Geography — Pacific', diff: 2, hook: "The Pacific Ocean is so wide it has its own hemisphere.", fact: "The \'Pacific Hemisphere\' centred at 0 latitude and 180 longitude is dominated by ocean — land covers only ~10% of its area. The Pacific alone contains more water than all other oceans combined.", tip: "🧠 Pacific: has its own hemisphere. Contains more water than all other oceans combined." },
  { id: 'geo48', cat: 'geo', emoji: '🌍', subject: 'Geography — Languages', diff: 2, hook: "Papua New Guinea has more languages than any other country.", fact: "Papua New Guinea has ~840 distinct languages — about 12% of all the world\'s languages in a country of just 10 million people. The extreme diversity reflects isolated mountainous terrain.", tip: "🧠 Papua New Guinea: ~840 languages, 12% of all world\'s languages. Population: just 10 million." },
  { id: 'geo49', cat: 'geo', emoji: '🏔️', subject: 'Geography — Glaciers', diff: 2, hook: "Alaska has more glaciers than the rest of the world combined (outside poles).", fact: "Alaska contains approximately 100,000 glaciers covering ~75,000 km2. This is more than the rest of the world\'s non-polar glaciers combined. Alaska\'s glaciers hold ~13% of global glacial ice outside the poles.", tip: "🧠 Alaska: 100,000 glaciers — more than the rest of the non-polar world combined." },
  { id: 'geo50', cat: 'geo', emoji: '🌊', subject: 'Geography — Caspian', diff: 1, hook: "The Caspian Sea is actually the world\'s largest lake.", fact: "The Caspian Sea is an enclosed body of saltwater with no outlet to any ocean — technically a lake, not a sea. At ~371,000 km2 it is the world\'s largest lake by surface area, larger than Germany.", tip: "🧠 Caspian \'Sea\': actually a lake. Largest lake in the world at ~371,000 km2 — larger than Germany." },
  { id: 'geo51', cat: 'geo', emoji: '🗺️', subject: 'Geography — Rivers', diff: 2, hook: "The Nile flows north — and rivers flow toward the sea, not toward the top of a map.", fact: "The Nile flows northward because the land in Ethiopia and Uganda slopes downhill toward the north. Rivers flow by gravity — map direction is irrelevant. North is just an arbitrary direction on maps.", tip: "🧠 Nile flows north because land slopes that way. Rivers follow gravity, not map directions." },
  { id: 'geo52', cat: 'geo', emoji: '🌍', subject: 'Geography — South America', diff: 2, hook: "South America contains the world\'s largest river by volume and longest mountain range.", fact: "The Amazon (largest river by volume) and the Andes (longest mountain range above sea) are both in South America. The continent also has the driest place on Earth — the Atacama Desert.", tip: "🧠 South America: Amazon (biggest river), Andes (longest range), Atacama (driest place). Record continent." },
  { id: 'geo53', cat: 'geo', emoji: '⛰️', subject: 'Geography — Naming', diff: 1, hook: "Everest was named after a man who never climbed it and thought naming it was inappropriate.", fact: "Sir George Everest was the British Surveyor General of India who mapped the region. He actually opposed naming the mountain after himself, believing local names should be used. The local Tibetan name is Chomolungma.", tip: "🧠 Everest: named after a man who never climbed it and protested the naming. Tibetan name: Chomolungma." },
  { id: 'geo54', cat: 'geo', emoji: '🌊', subject: 'Geography — Oceans', diff: 1, hook: "There is technically only one global ocean — all seas are connected.", fact: "The Atlantic, Pacific, Indian, Arctic, and Southern Oceans are all connected. There are no physical barriers between them. \'Five oceans\' is a convention of geography, not a physical reality. Water circulates between all of them.", tip: "🧠 There is one global ocean. The five named oceans are connected — water circulates between them all." },
  { id: 'geo55', cat: 'geo', emoji: '🌍', subject: 'Geography — Density', diff: 2, hook: "Half of humanity lives within a circle centred on the Bay of Bengal.", fact: "A circle centred roughly on Bangladesh encompasses China, India, Southeast Asia, and parts of East Asia — containing over 50% of Earth\'s 8 billion people. South and East Asia are extraordinarily densely populated.", tip: "🧠 Half of humanity fits inside a circle around the Bay of Bengal: China, India, SE Asia." },

  { id: 'b27', cat: 'body', emoji: '🧠', subject: 'Body — Neurons', diff: 2, hook: "Your brain generates about 70,000 thoughts per day.", fact: "Neuroscientists estimate humans have 50,000-70,000 thoughts daily — most repetitive and subconscious. The brain processes ~11 million bits of information per second but conscious awareness handles only ~40 bits.", tip: "🧠 Brain: ~70,000 thoughts/day. Processes 11M bits/sec but consciousness handles only 40 bits." },
  { id: 'b28', cat: 'body', emoji: '💪', subject: 'Body — Strength', diff: 1, hook: "The jaw muscle is the strongest muscle relative to its size.", fact: "The masseter can exert over 90 kg of force on the molars — more than any other muscle relative to its size. Chewing is one of the most mechanically powerful activities the body performs regularly.", tip: "🧠 Strongest muscle (relative to size): masseter (jaw). Can exert 90 kg of force." },
  { id: 'b29', cat: 'body', emoji: '🫀', subject: 'Body — Circulation', diff: 2, hook: "Blood takes about 20 seconds to circulate through your entire body.", fact: "The heart pumps blood through ~100,000 km of vessels. At rest, one complete circulation takes ~20 seconds. The average adult heart pumps ~5 litres per minute.", tip: "🧠 Complete blood circulation: ~20 seconds at rest. 100,000 km of vessels. Heart pumps 5L/min." },
  { id: 'b30', cat: 'body', emoji: '🦷', subject: 'Body — Development', diff: 1, hook: "Your skull is made of 22 separate bones fused together.", fact: "The skull consists of 8 cranial bones and 14 facial bones — 22 total. Babies have soft spots (fontanelles) where they have not fused yet, allowing the skull to compress during birth and the brain to grow rapidly.", tip: "🧠 Skull: 22 bones fused together. Babies have fontanelles where they are not yet fused." },
  { id: 'b31', cat: 'body', emoji: '🩸', subject: 'Body — Stomach', diff: 2, hook: "Your stomach produces a new lining every 3-4 days to avoid digesting itself.", fact: "Stomach acid (pH ~1.5) is strong enough to dissolve metal. Without constant renewal of the mucus lining every 3-4 days, the stomach would digest itself.", tip: "🧠 Stomach acid: pH 1.5, can dissolve metal. New lining every 3-4 days or it digests itself." },
  { id: 'b32', cat: 'body', emoji: '💤', subject: 'Body — Sleep', diff: 2, hook: "Your body temperature drops about 1°C when you fall asleep.", fact: "Sleep is initiated partly by a core temperature drop. Your body dissipates heat through the hands and feet. Keeping a room cool (~18-20°C) promotes better sleep by facilitating this heat loss.", tip: "🧠 Sleep: core temp drops ~1°C. Cool room (18°C) helps — supports the body\'s heat dissipation." },
  { id: 'b33', cat: 'body', emoji: '👁️', subject: 'Body — Vision', diff: 1, hook: "You have a dominant eye just as you have a dominant hand.", fact: "Test it: make a circle with your fingers, aim at a distant object, close each eye in turn. The eye where the object stays centred is your dominant eye. Most right-handed people are right-eye dominant.", tip: "🧠 Dominant eye test: finger circle, aim at object, close each eye — object stays in dominant eye." },
  { id: 'b34', cat: 'body', emoji: '🫁', subject: 'Body — Breathing', diff: 2, hook: "You breathe about 20,000 times per day and move roughly 11,000 litres of air.", fact: "At rest: ~15 breaths per minute x 0.5L = ~7.5 L per minute, ~11,000 L per day. You absorb only ~5% of each breath\'s oxygen — your lungs are about 25% efficient at extraction.", tip: "🧠 Daily: 20,000 breaths, 11,000 litres of air. Lungs extract only ~25% of available oxygen." },
  { id: 'b35', cat: 'body', emoji: '🧬', subject: 'Body — Immune System', diff: 2, hook: "Your immune system remembers pathogens and responds faster the second time.", fact: "Adaptive immunity: B and T cells specific to a pathogen persist as memory cells for years. Re-exposure triggers a much faster, stronger response. This is the principle behind vaccines.", tip: "🧠 Memory cells: immune system learns pathogens. Second exposure = faster, stronger response. Basis of vaccines." },
  { id: 'b36', cat: 'body', emoji: '🧠', subject: 'Body — Emotions', diff: 1, hook: "Emotions are physically felt in different body regions — this has been mapped scientifically.", fact: "Finnish researchers mapped where people feel different emotions. Fear and anxiety: chest tightening. Love: warm chest and head. Anger: flushed face and chest. The maps were consistent across cultures.", tip: "🧠 Body maps of emotion: fear (chest), love (chest and head), anger (face and chest). Cross-cultural." },
  { id: 'b37', cat: 'body', emoji: '💪', subject: 'Body — Muscles', diff: 2, hook: "Muscle memory is not stored in muscles — it is stored in the cerebellum.", fact: "Procedural memory — riding a bike, typing, playing an instrument — is stored in the cerebellum and basal ganglia, not the muscles. Once learned, these motor patterns are remarkably persistent.", tip: "🧠 Muscle memory: in the cerebellum, not muscles. Once learned, nearly impossible to fully forget." },
  { id: 'b38', cat: 'body', emoji: '🫀', subject: 'Body — Heart', diff: 2, hook: "The heart can continue beating outside the body if given oxygen.", fact: "The heart has its own electrical system (the sinoatrial node) that generates beats independently of the brain. Removed and placed in oxygenated solution, it keeps beating — why donor hearts survive brief transport.", tip: "🧠 Heart has its own electrical pacemaker. Keeps beating outside the body if oxygenated." },
  { id: 'b39', cat: 'body', emoji: '🦴', subject: 'Body — Growth', diff: 1, hook: "You are about 1 cm taller in the morning than at night.", fact: "Gravity compresses cartilage between spinal discs during the day. During sleep they rehydrate and expand. The difference is ~1 cm. Astronauts in microgravity can grow up to 5 cm taller.", tip: "🧠 You are ~1 cm taller in the morning. Spinal discs compress during the day, rehydrate overnight." },
  { id: 'b40', cat: 'body', emoji: '🧬', subject: 'Body — Twins', diff: 2, hook: "Identical twins have the same DNA but different fingerprints.", fact: "Identical twins share ~100% of their DNA. But fingerprints form during fetal development and are influenced by random factors — womb position, fluid pressure, movement. No two fingerprints are ever identical.", tip: "🧠 Identical twins: same DNA, different fingerprints. Prints formed by random fetal factors." },
  { id: 'b41', cat: 'body', emoji: '💊', subject: 'Body — Caffeine', diff: 2, hook: "Regular coffee drinkers do not get a real boost from caffeine — just withdrawal prevention.", fact: "Regular coffee consumption causes the brain to grow more adenosine receptors. Caffeine then just restores you to a normal baseline rather than providing genuine stimulation. Occasional drinkers get the real stimulant effect.", tip: "🧠 Regular coffee: just prevents withdrawal. Occasional drinkers: genuine stimulant effect." },
  { id: 'b42', cat: 'body', emoji: '🧠', subject: 'Body — Pain', diff: 1, hook: "Laughing can temporarily relieve pain by releasing endorphins.", fact: "Laughter triggers the release of endorphins — the brain\'s natural painkillers. Research shows even 15 minutes of genuine laughter can significantly increase pain tolerance.", tip: "🧠 Laughter releases endorphins — real painkillers. 15 minutes measurably increases pain tolerance." },
  { id: 'b43', cat: 'body', emoji: '👀', subject: 'Body — Sleep', diff: 2, hook: "Your eyes move rapidly during REM sleep — that is what REM means.", fact: "Rapid Eye Movement sleep involves eyes darting back and forth under closed lids while brain activity rises to near-waking levels. Dreaming, memory consolidation, and emotional processing primarily happen here.", tip: "🧠 REM sleep: eyes move rapidly, near-waking brain activity. Dreaming and memory consolidation here." },
  { id: 'b44', cat: 'body', emoji: '🦷', subject: 'Body — Taste', diff: 2, hook: "You have ~10,000 taste buds — and they are completely replaced every 10 days.", fact: "Taste buds are not just on the tongue — also on the palate, throat, and epiglottis. Each has 50-100 receptor cells and is fully replaced every 10-14 days. Smoking and age reduce taste bud sensitivity.", tip: "🧠 10,000 taste buds — replaced every 10 days. Also on palate and throat, not just tongue." },
  { id: 'b45', cat: 'body', emoji: '🧠', subject: 'Body — Dopamine', diff: 2, hook: "Dopamine is not the pleasure chemical — it is the wanting chemical.", fact: "Dopamine is released in anticipation of rewards, not during them. It drives seeking and motivation. The pleasure itself involves opioid receptors. This is why addiction is a cycle of craving, not just pleasure.", tip: "🧠 Dopamine = wanting/seeking, not pleasure. Pleasure = opioid receptors. Addiction is about craving." },
  { id: 'b46', cat: 'body', emoji: '💪', subject: 'Body — Exercise', diff: 1, hook: "Exercise is as effective as antidepressants for mild to moderate depression.", fact: "Multiple studies including a 2023 BMJ meta-analysis found that vigorous exercise is comparable in effect size to antidepressants and psychotherapy for mild to moderate depression, with fewer side effects.", tip: "🧠 Exercise vs antidepressants for mild depression: comparable effectiveness. Fewer side effects." },
  { id: 'b47', cat: 'body', emoji: '🫀', subject: 'Body — Aging', diff: 2, hook: "Your heart muscle cells barely replicate at all during your lifetime.", fact: "Most heart cardiomyocytes formed before birth persist your whole life. Only ~1% are renewed annually at age 25, declining to ~0.5% at age 75. Heart attack damage is mostly permanent as a result.", tip: "🧠 Heart muscle cells: barely renewed (~1%/year). Heart attack damage is mostly permanent." },
  { id: 'b48', cat: 'body', emoji: '🦷', subject: 'Body — Enamel', diff: 1, hook: "Tooth enamel is the hardest tissue in the human body — harder than bone.", fact: "Enamel is harder than bone but less flexible. Unlike bone, it has no living cells and cannot regenerate. Once damaged by decay or acid, only dental fillings or crowns can replace it.", tip: "🧠 Enamel: hardest body tissue, harder than bone. No living cells — cannot regenerate naturally." },
  { id: 'b49', cat: 'body', emoji: '🧬', subject: 'Body — Circadian', diff: 2, hook: "Every cell in your body has its own internal clock.", fact: "Nearly every cell has its own circadian clock genes, not just the brain. Eating and sleep timing signals all these peripheral clocks. Jet lag disrupts all of them at different rates — why it feels so disorienting.", tip: "🧠 Every cell has a circadian clock. Jet lag disrupts them all at different speeds." },
  { id: 'b50', cat: 'body', emoji: '💉', subject: 'Body — Blood', diff: 1, hook: "Blood types are not distributed equally worldwide.", fact: "O+ is the most common blood type globally (~38%). AB- is the rarest (~1%). Type B is more common in Asia; Type A more common in Europe. Blood type varies significantly by population.", tip: "🧠 Blood types: O+ most common (38%), AB- rarest (1%). Distribution varies by region." },
  { id: 'b51', cat: 'body', emoji: '🧠', subject: 'Body — Language', diff: 2, hook: "The brain processes language in multiple areas simultaneously — not one language centre.", fact: "Broca\'s area handles speech production; Wernicke\'s area processes comprehension. But modern neuroimaging shows language is distributed across far more of the brain. The old single-centre model was too simple.", tip: "🧠 Language: distributed across the brain, not one centre. Broca and Wernicke were just the start." },
  { id: 'b52', cat: 'body', emoji: '🫁', subject: 'Body — Yawning', diff: 2, hook: "Nobody fully understands why we yawn — and contagious yawning is linked to empathy.", fact: "Theories include brain cooling and arousal transitions. Studies show contagious yawning is linked to empathy — sociopaths and young children, who lack developed empathy, are less susceptible to it.", tip: "🧠 Yawning: still not understood. Contagious yawning linked to empathy. Sociopaths and toddlers less affected." },
  { id: 'b53', cat: 'body', emoji: '🧬', subject: 'Body — Genetics', diff: 2, hook: "You share 99.9% of your DNA with every other human on Earth.", fact: "The genetic difference between any two humans is only about 0.1%. The visible diversity of all 8 billion people — skin, hair, height, face — is encoded in a tiny fraction of the genome.", tip: "🧠 All humans: 99.9% identical DNA. All our diversity fits in 0.1% of the genome." },
  { id: 'b54', cat: 'body', emoji: '🦴', subject: 'Body — Bones', diff: 1, hook: "Babies are born with around 270 bones — adults have only 206.", fact: "Infants have more bones because many have not yet fused. As children grow, bones merge. Most major fusions are complete by early adulthood, around age 25. The last to fuse is usually the clavicle.", tip: "🧠 Babies: ~270 bones. Adults: 206. Bones fuse during childhood. Last to fuse: clavicle (~25)." },
  { id: 'b55', cat: 'body', emoji: '🧠', subject: 'Body — Memory', diff: 2, hook: "Your memory is not like a video recording — it is reconstructed every time you recall it.", fact: "Each time you remember something, your brain rebuilds the memory from fragments, and it can be altered in the process. This is why eyewitness testimony is unreliable and why memories change over time.", tip: "🧠 Memory is reconstructed, not replayed. Every recall slightly alters it. Eyewitnesses are unreliable." },

  { id: 'g26', cat: 'grammar', emoji: '✍️', subject: 'Grammar — Em Dash', diff: 1, hook: "The em dash is the most versatile punctuation mark in English.", fact: "The em dash (—) can replace commas, parentheses, or colons. It signals a pause stronger than a comma, adds an aside, or introduces a list. Unlike hyphens, it has no spaces around it.", tip: "🧠 Em dash (—): replaces commas, parentheses, colons. Most versatile mark. No spaces around it." },
  { id: 'g27', cat: 'grammar', emoji: '📝', subject: 'Grammar — Prefixes', diff: 2, hook: "The prefix \'un-\' and \'dis-\' are not interchangeable — they work differently.", fact: "\'Un-\' reverses a state: unhappy = not happy, untie = reverse tying. \'Dis-\' reverses an action or means absence: disconnect = undo connecting. Misuse causes subtle but real differences in meaning.", tip: "🧠 Un- reverses state (unhappy). Dis- reverses action or signals absence (disconnect)." },
  { id: 'g28', cat: 'grammar', emoji: '💬', subject: 'Grammar — Sentences', diff: 1, hook: "Every sentence needs a subject and a verb — with one exception.", fact: "Imperative sentences (commands) omit the subject because it is implied: \'Sit down!\' means \'[You] sit down.\' This is why \'Run!\' is a grammatically complete sentence.", tip: "🧠 Imperative sentences omit the subject: \'Run!\' = \'[You] run!\' Complete sentence." },
  { id: 'g29', cat: 'grammar', emoji: '✒️', subject: 'Grammar — Tense', diff: 2, hook: "English technically has no future tense as a verb form.", fact: "English has no dedicated future conjugation. We express future time using: will plus infinitive, going to, present simple, or present continuous. French and Spanish have distinct future conjugations — English does not.", tip: "🧠 English: no true future tense — only future expressions. \'Will go\' is not a conjugated tense." },
  { id: 'g30', cat: 'grammar', emoji: '📖', subject: 'Grammar — Etymology', diff: 2, hook: "Over 60% of English words have Latin or French roots.", fact: "The Norman Conquest of 1066 flooded English with French vocabulary. Many English word pairs exist: one Anglo-Saxon (simple), one French/Latin (formal). Ask versus enquire. Start versus commence.", tip: "🧠 60%+ English words from French/Latin. Anglo-Saxon = casual (ask). French/Latin = formal (enquire)." },
  { id: 'g31', cat: 'grammar', emoji: '✍️', subject: 'Grammar — Clarity', diff: 1, hook: "Ambiguous pronoun reference is one of the most common writing errors.", fact: "\'John told Mark that he was wrong.\' Who was wrong — John or Mark? When a pronoun could refer to multiple people, rewrite to clarify: \'John told Mark that Mark was wrong.\'", tip: "🧠 Ambiguous pronouns: rewrite to make clear. \'He\' must point to one person only." },
  { id: 'g32', cat: 'grammar', emoji: '📝', subject: 'Grammar — Nominalisation', diff: 2, hook: "Nominalisations weaken writing — convert them back to verbs.", fact: "Nominalisation turns a verb into a noun: \'make a decision\' instead of \'decide\', \'conduct an investigation\' instead of \'investigate\'. This inflates word count and reduces clarity. Direct verbs are stronger.", tip: "🧠 Nominalisation: \'make a decision\' vs just \'decide\'. Verbs are stronger and shorter. Always prefer them." },
  { id: 'g33', cat: 'grammar', emoji: '💬', subject: 'Grammar — Dialogue', diff: 1, hook: "Dialogue punctuation follows strict rules most people get wrong.", fact: "Punctuation goes inside quotation marks: \'I am tired,\' she said. Not: \'I am tired\', she said. If the tag interrupts: \'I am tired,\' she said, \'but I will manage.\' Capital after comma only if starting a new sentence.", tip: "🧠 Dialogue: punctuation inside quotes. \'Like this,\' she said. Not: \'Like this\', she said." },
  { id: 'g34', cat: 'grammar', emoji: '📖', subject: 'Grammar — Spelling', diff: 1, hook: "I before E except after C has more exceptions than examples.", fact: "The rule has so many exceptions — weird, seize, leisure, protein, foreign, science, ancient — that linguists say it barely qualifies as a rule at all.", tip: "🧠 \'I before E\': more exceptions than examples. Weird, seize, foreign, ancient all break it." },
  { id: 'g35', cat: 'grammar', emoji: '✍️', subject: 'Grammar — Paragraphs', diff: 1, hook: "A paragraph should contain one main idea.", fact: "The topic sentence states the main point. Supporting sentences expand and evidence it. One idea per paragraph — two ideas means two paragraphs. This rule alone will improve most writing immediately.", tip: "🧠 Paragraph = one idea. Topic sentence + support. Two ideas = split into two paragraphs." },
  { id: 'g36', cat: 'grammar', emoji: '💬', subject: 'Grammar — Metaphor', diff: 2, hook: "Metaphors and similes both compare unlike things but work differently.", fact: "Simile uses \'like\' or \'as\': \'life is like a box of chocolates.\' Metaphor is a direct equation: \'life is a box of chocolates.\' Metaphors are generally more powerful because they assert identity, not similarity.", tip: "🧠 Simile: \'life is like...\' Metaphor: \'life is...\' Metaphor asserts identity — stronger." },
  { id: 'g37', cat: 'grammar', emoji: '✒️', subject: 'Grammar — Formal Writing', diff: 2, hook: "Using \'I\' in formal writing is perfectly acceptable by modern standards.", fact: "The myth that \'I\' should be avoided in formal writing is outdated. APA, Chicago, and most modern style guides allow first person. Avoiding \'I\' often produces awkward passive constructions instead.", tip: "🧠 Using \'I\' in formal writing: fine by modern standards. Old \'avoid I\' rule is outdated." },
  { id: 'g38', cat: 'grammar', emoji: '📝', subject: 'Grammar — Redundancy', diff: 1, hook: "Many common phrases say the same thing twice.", fact: "Redundant phrases: \'past history\' (history is always past), \'free gift\' (gifts are free by definition), \'advance planning\', \'added bonus\'. Cutting them tightens writing instantly without losing meaning.", tip: "🧠 Redundant: \'past history\', \'free gift\', \'advance planning\'. Cut every one. Always." },
  { id: 'g39', cat: 'grammar', emoji: '🔠', subject: 'Grammar — Numbers', diff: 1, hook: "Numbers under ten are usually spelled out — but not always.", fact: "Common rule: spell out one to nine, use figures from 10 onward. Exceptions: always figures for percentages (5%), units (3 km), dates (7 March), and time (8pm). Never start a sentence with a figure.", tip: "🧠 Numbers: spell 1-9, figures 10+. Exceptions: percentages, units, dates always as figures." },
  { id: 'g40', cat: 'grammar', emoji: '💬', subject: 'Grammar — Tone', diff: 2, hook: "Tone in writing is created entirely through word choice.", fact: "Tone — formal, informal, warm, cold — comes from vocabulary and sentence length, not punctuation. \'I require your assistance\' versus \'can you help me\' — same meaning, different tone. The words do all the work.", tip: "🧠 Tone = word choice. \'Require\' vs \'need\' create entirely different registers." },
  { id: 'g41', cat: 'grammar', emoji: '✍️', subject: 'Grammar — Transitions', diff: 1, hook: "Transition words signal the relationship between ideas — not just connection.", fact: "Each transition signals a specific relationship: \'however\' (contrast), \'therefore\' (consequence), \'moreover\' (addition). Using \'and\' for everything flattens the logic. Specific transitions clarify how ideas relate.", tip: "🧠 Transitions signal logic: however=contrast, therefore=consequence, moreover=addition." },
  { id: 'g42', cat: 'grammar', emoji: '📖', subject: 'Grammar — Passive Voice', diff: 2, hook: "Passive voice is sometimes the correct choice — not always a weakness.", fact: "Passive: \'the window was broken.\' Active: \'she broke the window.\' Active is usually stronger. But passive is appropriate when the actor is unknown, irrelevant, or deliberately hidden.", tip: "🧠 Passive: usually weaker, but correct when actor is unknown, irrelevant, or hidden." },
  { id: 'g43', cat: 'grammar', emoji: '✒️', subject: 'Grammar — Prepositions', diff: 1, hook: "Ending a sentence with a preposition is perfectly grammatical in English.", fact: "This \'rule\' came from 17th-century attempts to apply Latin grammar to English. Latin prepositions cannot end sentences; English ones can. Churchill\'s alleged quip: \'This is nonsense up with which I will not put.\'", tip: "🧠 Ending with a preposition: fine in English. The rule came from misapplied Latin grammar." },
  { id: 'g44', cat: 'grammar', emoji: '📝', subject: 'Grammar — Wordiness', diff: 1, hook: "Most sentences can be cut by 25% without losing meaning.", fact: "Weak: \'in order to achieve success in this endeavour, it will be necessary to consider all factors.\' Strong: \'to succeed, consider all factors.\' Cut \'in order to\', \'it will be necessary\', \'take into consideration\'.", tip: "🧠 Cut 25% from most writing. \'In order to\' becomes \'to\'. \'Take into consideration\' becomes \'consider\'." },
  { id: 'g45', cat: 'grammar', emoji: '💬', subject: 'Grammar — Register', diff: 2, hook: "Register is the level of formality matched to your audience.", fact: "Register: informal (texts), neutral (emails), formal (reports), academic (papers). Using the wrong register is more disruptive than most grammar errors. Casual language in a formal report signals incompetence.", tip: "🧠 Register = formality level. Mismatched register (too casual in formal writing) = bigger error than grammar." },
  { id: 'g46', cat: 'grammar', emoji: '✍️', subject: 'Grammar — Irony', diff: 2, hook: "Verbal irony and sarcasm are technically different things.", fact: "Verbal irony: saying the opposite of what you mean. \'Oh great, another Monday.\' Sarcasm: verbal irony used to mock or wound. \'Oh brilliant, you finally showed up.\' All sarcasm is irony — not all irony is sarcasm.", tip: "🧠 Irony = opposite of meaning. Sarcasm = irony used to wound. All sarcasm is irony, not vice versa." },
  { id: 'g47', cat: 'grammar', emoji: '📖', subject: 'Grammar — Plural', diff: 1, hook: "The plural of \'datum\' is \'data\' — making \'data is\' technically incorrect.", fact: "\'Data\' is the Latin plural of \'datum\'. Strictly it should be \'the data are\'. In practice, \'data is\' is widely accepted. Academic and scientific writing still usually treats it as plural.", tip: "🧠 \'Data\' = plural of \'datum\'. Technically: \'data ARE\'. Widely accepted as singular in everyday use." },
  { id: 'g48', cat: 'grammar', emoji: '✒️', subject: 'Grammar — Starting with But', diff: 2, hook: "Starting a sentence with \'But\' or \'And\' is perfectly grammatical.", fact: "The rule against coordinating conjunctions at sentence-start is entirely invented. Shakespeare, Hemingway, and the King James Bible all do it. These words at sentence-start create emphasis and rhythm.", tip: "🧠 Starting with \'But\' or \'And\': completely grammatical. Shakespeare did it constantly." },
  { id: 'g49', cat: 'grammar', emoji: '🔠', subject: 'Grammar — Hyphens', diff: 2, hook: "Compound modifiers before a noun need a hyphen — but not after a verb.", fact: "\'A well-known actor\' (hyphen — modifier before noun). \'The actor is well known\' (no hyphen — after verb). Position determines whether to hyphenate. Most writers either always or never hyphenate — both are wrong.", tip: "🧠 Compound modifiers: hyphenate BEFORE noun (well-known), not AFTER verb (is well known)." },
  { id: 'g50', cat: 'grammar', emoji: '💬', subject: 'Grammar — Euphemism', diff: 2, hook: "Euphemisms gradually lose their softening effect — requiring new replacements.", fact: "The euphemism treadmill (Steven Pinker): new polite words for taboo concepts gradually take on the stigma of the word they replaced, requiring new substitutes in turn. Each generation needs fresh vocabulary for the same things.", tip: "🧠 Euphemism treadmill: polite words gradually become offensive too, requiring new replacements." },
  { id: 'g51', cat: 'grammar', emoji: '📝', subject: 'Grammar — Sentences', diff: 2, hook: "A sentence fragment can be intentional — and highly effective.", fact: "A fragment lacks a subject or verb but can be a powerful stylistic choice. \'No way.\' \'Never.\' \'Not a chance.\' These work in informal writing and fiction. In formal writing, fragments require deliberate intent.", tip: "🧠 Sentence fragments: grammatically wrong but stylistically powerful. Use deliberately or not at all." },
  { id: 'g52', cat: 'grammar', emoji: '✍️', subject: 'Grammar — Concision', diff: 1, hook: "The most common writing problem is not grammar — it is wordiness.", fact: "More words rarely means clearer meaning. Most professional editors say the average draft can be cut 20-30% without losing anything. Delete filler: \'very\', \'quite\', \'really\', \'in order to\', \'the fact that\'.", tip: "🧠 Most common writing problem: wordiness. Delete: \'very\', \'quite\', \'really\', \'in order to\'." },
  { id: 'g53', cat: 'grammar', emoji: '🔠', subject: 'Grammar — Capitalisation', diff: 2, hook: "Job titles are only capitalised when they precede a name.", fact: "\'President Biden spoke.\' (capital — before name). \'The president spoke.\' (lowercase — general reference). Many writers overcapitalise out of respect — grammatically incorrect.", tip: "🧠 Titles: capitalised before a name (President Biden), lowercase otherwise (the president spoke)." },
  { id: 'g54', cat: 'grammar', emoji: '💬', subject: 'Grammar — Active vs Passive', diff: 1, hook: "Active voice: the subject does the action. Passive voice: the subject receives it.", fact: "Active: \'The dog bit the man.\' Passive: \'The man was bitten by the dog.\' Active is clearer and more direct. Passive hides the actor — useful when the actor is unknown or you want to avoid blame.", tip: "🧠 Active: subject acts. Passive: subject receives. Active = clearer. Passive = hides who did it." },
  { id: 'g55', cat: 'grammar', emoji: '📖', subject: 'Grammar — Apostrophes', diff: 1, hook: "The apostrophe is the most misused punctuation mark in English.", fact: "Two uses only: possession (the cat\'s bowl) and contraction (it\'s = it is). Common errors: its versus it\'s, and plurals with apostrophes (apples not apple\'s). Apostrophes never indicate a plural.", tip: "🧠 Apostrophe: possession (cat\'s) and contraction (it\'s). Never plurals. Its vs it\'s = most common error." },
  { id: 'psy26', cat: 'psychology', emoji: '🧠', subject: 'Psychology — Motivation', diff: 2, hook: "Rewarding someone for what they already love can destroy their motivation.", fact: "The overjustification effect: rewarding an intrinsically enjoyable activity can reduce motivation once the reward is removed. Children who love drawing but receive gold stars may stop drawing when the stars disappear.", tip: "🧠 Overjustification effect: external rewards kill intrinsic motivation when removed." },
  { id: 'psy27', cat: 'psychology', emoji: '😊', subject: 'Psychology — Smiling', diff: 1, hook: "Forced smiling actually makes you feel slightly happier.", fact: "The facial feedback hypothesis: adopting the physical expression of an emotion can mildly induce that emotion. Smiling — even artificially — activates some neural circuits associated with happiness.", tip: "🧠 Facial feedback: forced smiling mildly activates happiness circuits. The face leads the brain." },
  { id: 'psy28', cat: 'psychology', emoji: '👥', subject: 'Psychology — Bystanders', diff: 2, hook: "Bystanders are less likely to help in emergencies when more people are present.", fact: "The bystander effect (Darley and Latane, 1968): the more witnesses present, the less likely any individual is to help. Two mechanisms: diffusion of responsibility (\'someone else will\') and pluralistic ignorance (\'if no one acts, it must be fine\').", tip: "🧠 Bystander effect: more people = less help. Diffusion of responsibility + pluralistic ignorance." },
  { id: 'psy29', cat: 'psychology', emoji: '🎯', subject: 'Psychology — Goals', diff: 2, hook: "Telling people your goals can make you less likely to achieve them.", fact: "Peter Gollwitzer\'s research: sharing goals with others who affirm them creates a social reality that makes the goal feel more achieved before it is. This premature satisfaction reduces motivation to actually do the work.", tip: "🧠 Announcing goals: creates false sense of achievement. Reduces motivation. Keep goals private." },
  { id: 'psy30', cat: 'psychology', emoji: '🌊', subject: 'Psychology — Stress', diff: 1, hook: "Moderate stress improves performance — the Yerkes-Dodson law.", fact: "The Yerkes-Dodson law (1908): performance increases with stress up to an optimal point, then decreases. Zero stress = underperformance. Peak stress = peak performance. Too much stress = breakdown.", tip: "🧠 Yerkes-Dodson: moderate stress = best performance. Too little = boredom. Too much = breakdown." },
  { id: 'psy31', cat: 'psychology', emoji: '🧠', subject: 'Psychology — Learning', diff: 1, hook: "Spaced repetition is the most effective way to retain information long-term.", fact: "The spacing effect (Ebbinghaus, 1885): memories consolidated over multiple spaced sessions are stronger than the same time in a single session. Review after 1 day, then 3, then 7, then 14 days for maximum retention.", tip: "🧠 Spacing effect: review at 1, 3, 7, 14 days. Far better than cramming the same total time." },
  { id: 'psy32', cat: 'psychology', emoji: '😴', subject: 'Psychology — Sleep', diff: 2, hook: "Sleep deprivation impairs judgment as severely as being drunk — and you cannot tell.", fact: "17-19 hours without sleep produces impairment equivalent to a blood alcohol level of 0.05%. Crucially, sleep-deprived people consistently overestimate their performance. They cannot tell how impaired they are.", tip: "🧠 17-19 hours awake = legally drunk level of impairment. And you cannot detect it in yourself." },
  { id: 'psy33', cat: 'psychology', emoji: '🎭', subject: 'Psychology — Personality', diff: 2, hook: "The Big Five personality traits are the most scientifically supported model.", fact: "The Big Five (OCEAN): Openness, Conscientiousness, Extraversion, Agreeableness, Neuroticism. These predict life outcomes better than any other model, including Myers-Briggs, which has poor predictive validity.", tip: "🧠 Big Five (OCEAN): best-validated personality model. Myers-Briggs has weak scientific support." },
  { id: 'psy34', cat: 'psychology', emoji: '💭', subject: 'Psychology — Mind-Wandering', diff: 2, hook: "The average person spends ~47% of waking time mind-wandering.", fact: "A Harvard study using a smartphone app found minds wandered 46.9% of the time. Mind-wandering consistently predicted lower happiness, regardless of what the person was nominally doing.", tip: "🧠 Minds wander ~47% of waking time. Mind-wandering correlates with unhappiness." },
  { id: 'psy35', cat: 'psychology', emoji: '🧠', subject: 'Psychology — Habit', diff: 2, hook: "Habits are cue-routine-reward loops — changing them requires swapping only the routine.", fact: "Charles Duhigg\'s habit loop: cue (trigger) then routine (behaviour) then reward (reinforcement). To change a habit, keep the cue and reward but substitute the routine. Willpower alone rarely works.", tip: "🧠 Habit loop: cue → routine → reward. Change: keep cue and reward, swap only the routine." },
  { id: 'psy36', cat: 'psychology', emoji: '😊', subject: 'Psychology — Gratitude', diff: 1, hook: "Keeping a gratitude journal measurably improves mental health.", fact: "Studies by Emmons and McCullough (2003) showed writing three things you are grateful for each week significantly increased wellbeing, optimism, and even physical health markers over 10 weeks.", tip: "🧠 Gratitude journal: 3 things per week measurably improves wellbeing, optimism, and health." },
  { id: 'psy37', cat: 'psychology', emoji: '👥', subject: 'Psychology — Loneliness', diff: 2, hook: "Loneliness is as dangerous to health as smoking 15 cigarettes a day.", fact: "A meta-analysis by Holt-Lunstad (2015) covering 3.4 million people found social isolation increased mortality risk by ~26-29% — comparable to obesity and exceeding physical inactivity.", tip: "🧠 Loneliness mortality risk: comparable to smoking 15 cigarettes/day. As dangerous as obesity." },
  { id: 'psy38', cat: 'psychology', emoji: '🎯', subject: 'Psychology — Willpower', diff: 2, hook: "Willpower is a limited resource that depletes with use.", fact: "Ego depletion (Baumeister): making decisions and resisting impulses draws on a shared resource that weakens over the day. Sleep and rest replenish it. This is why decisions made late in the day tend to be poorer.", tip: "🧠 Ego depletion: willpower shrinks with use. Late-day decisions are worse. Sleep restores it." },
  { id: 'psy39', cat: 'psychology', emoji: '🧠', subject: 'Psychology — Memory', diff: 2, hook: "Memories are reconstructed every time you recall them — and can be altered in the process.", fact: "Each recall rebuilds memory from fragments. The process can introduce distortions. This is why eyewitness testimony is unreliable and why memories change subtly over time, even when you are confident they are accurate.", tip: "🧠 Memory = reconstruction, not replay. Each recall can alter it. Eyewitnesses are unreliable." },
  { id: 'psy40', cat: 'psychology', emoji: '😨', subject: 'Psychology — Phobias', diff: 1, hook: "Phobias are the most common mental health condition worldwide.", fact: "Approximately 10-12% of people have a specific phobia — irrational fear of a specific object or situation. Most common: arachnophobia, social phobia, claustrophobia, acrophobia. CBT is the most effective treatment.", tip: "🧠 Phobias: most common mental health condition globally. 10-12% of people affected." },
  { id: 'psy41', cat: 'psychology', emoji: '💭', subject: 'Psychology — Decision', diff: 2, hook: "People make better decisions when they expect to have to justify them.", fact: "Accountability effect: when people know they will need to explain their decisions, they think more carefully, consider more perspectives, and show less bias. Expecting to justify a choice before making it improves reasoning.", tip: "🧠 Accountability improves decisions: expecting to justify your reasoning makes you reason better." },
  { id: 'psy42', cat: 'psychology', emoji: '🧠', subject: 'Psychology — Intelligence', diff: 2, hook: "IQ measures something real — but intelligence is broader than IQ captures.", fact: "IQ tests reliably predict academic and professional performance. Howard Gardner\'s multiple intelligences theory proposes at least 8 types: linguistic, logical, musical, spatial, bodily, interpersonal, intrapersonal, naturalistic.", tip: "🧠 IQ: predicts academic success but only measures 2-3 of Gardner\'s 8 types of intelligence." },
  { id: 'psy43', cat: 'psychology', emoji: '🌊', subject: 'Psychology — Resilience', diff: 1, hook: "Resilience is not a fixed trait — it is built through adversity.", fact: "Research shows resilience is dynamic, not fixed. It builds through manageable challenge, strong social support, and practiced coping strategies. Post-traumatic growth — becoming stronger through difficulty — is a documented phenomenon.", tip: "🧠 Resilience = built, not innate. Manageable challenge plus support plus practice." },
  { id: 'psy44', cat: 'psychology', emoji: '🧠', subject: 'Psychology — Reward', diff: 2, hook: "Variable rewards are more addictive than predictable ones — the slot machine principle.", fact: "Variable ratio reinforcement (Skinner): rewards given unpredictably are more powerful than fixed ones at maintaining behaviour. Slot machines, social media likes, and loot boxes all use this principle deliberately.", tip: "🧠 Variable rewards: more addictive than predictable ones. Social media uses this exact mechanism." },
  { id: 'psy45', cat: 'psychology', emoji: '💭', subject: 'Psychology — Creativity', diff: 2, hook: "Creativity peaks when you are slightly tired — not fully alert.", fact: "Problems requiring insight and non-linear thinking are more often solved when slightly drowsy. Loosened inhibition allows more remote associations. Analytical problems are better tackled when fully alert.", tip: "🧠 Insight and creativity: peak when slightly tired. Analytical thinking: peak when fully alert." },
  { id: 'psy46', cat: 'psychology', emoji: '👥', subject: 'Psychology — Leadership', diff: 2, hook: "People follow leaders based on two dimensions: warmth and competence.", fact: "Research by Amy Cuddy: people evaluate leaders on warmth (trustworthy, caring) and competence (capable, skilled). High warmth and high competence is ideal. High competence with low warmth creates respect but not trust.", tip: "🧠 Leaders need both warmth and competence. High competence with low warmth = respected but feared." },
  { id: 'psy47', cat: 'psychology', emoji: '🧠', subject: 'Psychology — Neuroplasticity', diff: 1, hook: "The adult brain can grow new neurons — discovered only in the 1990s.", fact: "Neurogenesis in adults was considered impossible until the 1990s. It occurs in the hippocampus and is driven by exercise, learning, sleep, and reduced stress.", tip: "🧠 Adult brain grows new neurons. Discovered 1990s. Exercise, sleep, and learning promote it." },
  { id: 'psy48', cat: 'psychology', emoji: '😊', subject: 'Psychology — Happiness', diff: 2, hook: "Most people optimise for pleasure — which is the least durable form of happiness.", fact: "Martin Seligman\'s PERMA model: Positive emotion, Engagement (flow), Relationships, Meaning, Accomplishment. Optimising for pleasure alone is the weakest strategy. Meaning and relationships are the strongest predictors of lasting wellbeing.", tip: "🧠 PERMA: Positive emotion, Engagement, Relationships, Meaning, Accomplishment. Meaning lasts longest." },
  { id: 'psy49', cat: 'psychology', emoji: '🎯', subject: 'Psychology — Comparison', diff: 2, hook: "Comparing yourself to others is unavoidable — but direction matters.", fact: "Social comparison theory (Festinger): we constantly evaluate ourselves against others. Upward comparisons (with better-off people) can motivate or demoralise. Downward comparisons boost self-esteem temporarily but do not drive growth.", tip: "🧠 Upward comparison: can motivate or crush. Downward comparison: boosts ego but not growth." },
  { id: 'psy50', cat: 'psychology', emoji: '💭', subject: 'Psychology — Confirmation Bias', diff: 2, hook: "You are naturally better at finding evidence that confirms what you already believe.", fact: "Confirmation bias: people search for, favour, and remember information that supports existing beliefs. It operates even when people believe they are being objective. The solution is actively seeking disconfirming evidence.", tip: "🧠 Confirmation bias: we naturally seek confirming evidence. Must actively hunt for disconfirming data." },
  { id: 'psy51', cat: 'psychology', emoji: '🧠', subject: 'Psychology — Self-compassion', diff: 2, hook: "Self-compassion predicts success better than high self-esteem.", fact: "Research by Kristin Neff shows self-compassion — treating yourself with the kindness you would show a friend — predicts resilience, motivation, and wellbeing better than high self-esteem, which requires external validation.", tip: "🧠 Self-compassion beats self-esteem for resilience. High self-esteem needs external validation." },
  { id: 'psy52', cat: 'psychology', emoji: '👀', subject: 'Psychology — Pupils', diff: 1, hook: "Pupil dilation is an involuntary sign of interest or attraction.", fact: "The pupil dilates in low light — but also in response to interesting, attractive, or arousing stimuli. You cannot consciously control it. Italian women historically used belladonna eye drops to dilate pupils artificially.", tip: "🧠 Pupil dilation: involuntary signal of interest. Italian women used belladonna to fake it." },
  { id: 'psy53', cat: 'psychology', emoji: '🌊', subject: 'Psychology — Flow', diff: 2, hook: "Flow is a mental state of complete absorption — and it is the source of peak performance.", fact: "Mihaly Csikszentmihalyi\'s flow state: complete absorption in a challenging but achievable task, loss of self-consciousness, time distortion. Flow requires a task at the edge of your ability — not too easy, not too hard.", tip: "🧠 Flow: complete absorption, time distortion, peak performance. Requires edge-of-skill challenge." },
  { id: 'psy54', cat: 'psychology', emoji: '🧠', subject: 'Psychology — Emotion', diff: 2, hook: "You cannot choose your emotions — only your response to them.", fact: "Emotions arise automatically from the brain\'s appraisal of a situation. The feeling of anger or fear precedes conscious awareness. What you can choose is how you respond, through cognitive reappraisal and regulation.", tip: "🧠 Emotions: automatic and pre-conscious. You choose responses, not the feelings themselves." },
  { id: 'psy55', cat: 'psychology', emoji: '💭', subject: 'Psychology — Anchoring', diff: 2, hook: "The first number you hear disproportionately influences all subsequent judgments.", fact: "Anchoring bias: when shown an arbitrary number first, subsequent estimates are pulled toward it even if the number was random. Salary negotiations, prices, and legal settlements are all heavily influenced by anchoring.", tip: "🧠 Anchoring bias: first number you hear skews all subsequent estimates. Even random numbers work." },
  { id: 'eco26', cat: 'economics', emoji: '💰', subject: 'Economics — Sunk Cost', diff: 2, hook: "People are more likely to keep a bad investment than admit a loss.", fact: "Sunk cost fallacy: continuing to invest in something because of past investment, even when future prospects are poor. Rational economics says ignore sunk costs. Human psychology says do not waste what you already spent.", tip: "🧠 Sunk cost fallacy: continuing because you already invested. Rational response = ignore past costs." },
  { id: 'eco27', cat: 'economics', emoji: '📈', subject: 'Economics — Rule of 70', diff: 1, hook: "Divide 70 by a growth rate to find how long it takes to double.", fact: "Rule of 70: years to double = 70 divided by growth rate. At 7% annual growth: 70 / 7 = 10 years. At 3%: ~23 years. Works for investments, populations, or anything growing at a constant rate.", tip: "🧠 Rule of 70: years to double = 70 / growth rate. 7% growth = doubles in 10 years." },
  { id: 'eco28', cat: 'economics', emoji: '🏦', subject: 'Economics — Banking', diff: 2, hook: "Banks do not lend out deposits — they create money when they issue loans.", fact: "When a bank issues a loan, it creates a new deposit in the borrower\'s account — literally creating new money. Banks are constrained by capital ratios and profitability, not by deposit levels.", tip: "🧠 Banks create money when lending. They do not redistribute existing deposits. Credit creation." },
  { id: 'eco29', cat: 'economics', emoji: '📊', subject: 'Economics — Comparative Advantage', diff: 2, hook: "Countries benefit from trade even if one country is worse at producing everything.", fact: "Comparative advantage (Ricardo, 1817): even if Country A is better at everything, both countries benefit from specialising in what they are relatively best at and trading. Opportunity cost, not absolute cost, drives trade.", tip: "🧠 Comparative advantage: even the worse producer gains from trade by specialising relatively." },
  { id: 'eco30', cat: 'economics', emoji: '💸', subject: 'Economics — Debt', diff: 1, hook: "Government debt is fundamentally different from household debt.", fact: "Governments can roll over debt indefinitely, create currency, and outlive their creditors. A government with its own currency technically never needs to default. The household analogy for national debt is deeply misleading.", tip: "🧠 Government debt is not like household debt. Governments can print money and roll over debt indefinitely." },
  { id: 'eco31', cat: 'economics', emoji: '🌐', subject: 'Economics — Poverty', diff: 1, hook: "Extreme global poverty has fallen from 90% to about 10% since 1820.", fact: "In 1820, ~90% of the world lived in extreme poverty (under $1.90/day). By 2019 it was ~10%. Despite population growing from 1 billion to 8 billion, hundreds of millions more people escaped poverty than at any time in history.", tip: "🧠 Extreme poverty: 90% of world in 1820, ~10% today. Despite 8x population growth. Historic progress." },
  { id: 'eco32', cat: 'economics', emoji: '📉', subject: 'Economics — Bubbles', diff: 2, hook: "Economic bubbles follow a predictable psychological pattern every time.", fact: "The Minsky pattern: asset prices rise, optimism grows, credit expands, speculation increases, a trigger causes panic, prices collapse, credit contracts. Dutch Tulip Mania (1637), South Sea Bubble (1720), Dot-com (2000), Housing (2008).", tip: "🧠 Economic bubbles: optimism → credit → speculation → trigger → crash. Pattern repeats every generation." },
  { id: 'eco33', cat: 'economics', emoji: '💸', subject: 'Economics — Money', diff: 2, hook: "The concept of money was invented independently in at least five civilisations.", fact: "Money emerged independently in Mesopotamia, ancient China, Egypt, India, and pre-Columbian Americas. The common driver: facilitating trade when barter becomes inefficient. Cowrie shells, metal rings, grain, and salt all served as early currencies.", tip: "🧠 Money invented independently in 5+ civilisations. Cowrie shells, grain, metal — same problem everywhere." },
  { id: 'eco34', cat: 'economics', emoji: '📊', subject: 'Economics — GDP', diff: 2, hook: "GDP can grow while most people get poorer.", fact: "If the wealthiest 1% take 100% of GDP growth, the mean income rises even as the median income stays flat. This is why economists increasingly use median income and inequality metrics alongside GDP.", tip: "🧠 GDP growth can leave most people behind if gains concentrate at the top. Always check median." },
  { id: 'eco35', cat: 'economics', emoji: '💰', subject: 'Economics — Opportunity Cost', diff: 1, hook: "Opportunity cost is the most important concept in economics.", fact: "Every choice costs you the next best alternative you did not take. Working costs you leisure time. Spending costs you saving. Most people count only explicit costs and ignore what they give up.", tip: "🧠 Opportunity cost: the real cost of anything = what you gave up to get it." },
  { id: 'eco36', cat: 'economics', emoji: '🏭', subject: 'Economics — Automation', diff: 2, hook: "Automation has historically created more jobs than it destroyed — but not the same jobs.", fact: "The Industrial Revolution displaced farm workers but created far more factory jobs. Digital automation displaces routine cognitive tasks while creating new roles. The disruption is real even if the net outcome is positive.", tip: "🧠 Automation: historically creates more jobs than it destroys. Problem = transition pain and retraining." },
  { id: 'eco37', cat: 'economics', emoji: '🏦', subject: 'Economics — Central Banks', diff: 1, hook: "Central banks are independent of governments in most developed countries.", fact: "Central banks like the Fed, ECB, and Bank of England have operational independence from political control — to prevent governments inflating away debts for electoral gain. Their mandate: price stability and full employment.", tip: "🧠 Central bank independence: prevents political misuse of monetary policy." },
  { id: 'eco38', cat: 'economics', emoji: '📈', subject: 'Economics — Markets', diff: 2, hook: "The stock market and the economy are not the same thing.", fact: "The stock market reflects expectations about future corporate profits. The economy measures current output and employment. They regularly diverge: markets rose in 2020 during the worst months of the pandemic.", tip: "🧠 Stock market = expectations about future. GDP = current reality. They often move in opposite directions." },
  { id: 'eco39', cat: 'economics', emoji: '💸', subject: 'Economics — Remittances', diff: 1, hook: "Migrant workers send more money home than all global foreign aid combined.", fact: "Global remittances: ~$800 billion per year — over 4 times total foreign aid ($180B). For countries like the Philippines, Nepal, and El Salvador, remittances exceed 20-30% of GDP.", tip: "🧠 Global remittances: ~$800B/year. 4x foreign aid. For some countries, 30% of GDP." },
  { id: 'eco40', cat: 'economics', emoji: '🌐', subject: 'Economics — Trade', diff: 2, hook: "Free trade increases total wealth but creates losers as well as winners.", fact: "Stolper-Samuelson theorem: free trade benefits abundant production factors and harms scarce ones. In developed countries: helps capital and high-skilled workers, potentially harms low-skilled workers.", tip: "🧠 Free trade: increases total wealth but creates losers. Capital and skilled workers win; low-skilled may lose." },
  { id: 'eco41', cat: 'economics', emoji: '📊', subject: 'Economics — Inequality', diff: 2, hook: "The Gini coefficient measures income inequality on a scale of 0 to 1.", fact: "Gini of 0 = perfect equality. Gini of 1 = one person has everything. Real range: Norway ~0.26 (very equal), South Africa ~0.63 (very unequal), USA ~0.39, UK ~0.35.", tip: "🧠 Gini: 0 = perfect equality, 1 = total inequality. Norway 0.26. South Africa 0.63. USA 0.39." },
  { id: 'eco42', cat: 'economics', emoji: '💰', subject: 'Economics — Inflation', diff: 2, hook: "Deflation is often more dangerous than inflation for an economy.", fact: "Falling prices can cause: consumers to delay purchases (waiting for lower prices), businesses to cut investment, and debt burdens to grow in real terms. Japan\'s lost decade of the 1990s demonstrates the damage.", tip: "🧠 Deflation often worse than inflation: consumers wait to buy, investment freezes, real debt burden grows." },
  { id: 'eco43', cat: 'economics', emoji: '💸', subject: 'Economics — Welfare', diff: 2, hook: "Most welfare spending in developed countries goes to the elderly, not the working-age poor.", fact: "In OECD countries, pensions and healthcare for the elderly consume 60-70% of all social spending. Working-age poverty benefits are a small minority of total social expenditure.", tip: "🧠 Welfare spending: 60-70% goes to elderly (pensions and healthcare). Working-age poor get the minority." },
  { id: 'eco44', cat: 'economics', emoji: '📈', subject: 'Economics — Startups', diff: 2, hook: "90% of startups fail — but the successful ones generate outsized returns.", fact: "Venture capital economics: most investments return nothing. A few produce 10-100x returns. One Google pays for hundreds of failures. This power-law distribution makes VC viable despite high failure rates.", tip: "🧠 VC power law: 90% fail, a few win huge. One Google pays for hundreds of failures." },
  { id: 'eco45', cat: 'economics', emoji: '🌐', subject: 'Economics — Resources', diff: 2, hook: "Countries with abundant natural resources often have worse development than resource-poor ones.", fact: "The resource curse: oil and diamond wealth often produces corruption, poor institutions, and Dutch Disease (resource sector crowding out other industries). Norway is the exception — not the rule.", tip: "🧠 Resource curse: oil-rich countries often develop worse. Institutions matter more than resources." },
  { id: 'eco46', cat: 'economics', emoji: '💰', subject: 'Economics — Price Signals', diff: 1, hook: "Prices coordinate billions of economic decisions without any central planner.", fact: "Friedrich Hayek (1945): prices aggregate dispersed knowledge about supply, demand, and costs across society. Price increases signal scarcity; decreases signal abundance — spontaneously directing resources more efficiently than any planner could.", tip: "🧠 Hayek: prices coordinate billions of decisions without central planning. Markets process distributed knowledge." },
  { id: 'eco47', cat: 'economics', emoji: '📉', subject: 'Economics — Poverty Trap', diff: 2, hook: "Poverty traps exist when being poor makes it harder to escape poverty.", fact: "Poor families cannot afford nutritious food, school fees, or healthcare — each limitation reinforcing the others. Micro-credit, conditional cash transfers, and basic income aim to break these interlocking constraints.", tip: "🧠 Poverty trap: poor nutrition leads to low productivity leads to low income. Interlocking constraints." },
  { id: 'eco48', cat: 'economics', emoji: '📊', subject: 'Economics — Productivity', diff: 1, hook: "Productivity growth is the only sustainable source of rising living standards.", fact: "GDP per person can only grow long-term through productivity — producing more output per hour worked. This requires: technology, education, infrastructure, and institutions. Without productivity growth, one person\'s gain is another\'s loss.", tip: "🧠 Productivity growth = only sustainable source of rising living standards. Everything else is redistribution." },
  { id: 'eco49', cat: 'economics', emoji: '💸', subject: 'Economics — Fiscal Policy', diff: 2, hook: "Government spending multiplies through the economy — by more than the original spend.", fact: "The fiscal multiplier: when government spends £1, it becomes income for someone, who spends part of it, creating income for another, and so on. A multiplier above 1 means spending creates more GDP than its face value.", tip: "🧠 Fiscal multiplier: government spending of £1 creates more than £1 of GDP as it circulates." },
  { id: 'eco50', cat: 'economics', emoji: '🌐', subject: 'Economics — Global', diff: 1, hook: "The entire world economy grew more in the last 100 years than in all previous history.", fact: "Global GDP in 1900: ~$3 trillion (2011 dollars). Global GDP in 2023: ~$100 trillion. A 33-fold increase in 120 years — more than in all prior human history.", tip: "🧠 World GDP: grew 33x in 120 years. More growth than all of human history before 1900." },
  { id: 'eco51', cat: 'economics', emoji: '💰', subject: 'Economics — Incentives', diff: 1, hook: "Incentives explain most human behaviour — including behaviour that seems irrational.", fact: "Economists assume people respond predictably to incentives. When you change an incentive, behaviour changes. This is why: tax credits boost behaviour, fines reduce it, and unintended consequences follow whenever incentives are poorly designed.", tip: "🧠 Incentives drive behaviour. Change the incentive = change the behaviour. The core of economics." },
  { id: 'eco52', cat: 'economics', emoji: '📈', subject: 'Economics — Compound Growth', diff: 2, hook: "Compound growth makes small rate differences enormous over time.", fact: "At 2% annual growth, an economy doubles in 35 years. At 4%, it doubles in 17.5 years. After 100 years: 2% gives 7x original size; 4% gives 50x. Tiny rate differences compound into massive divergence.", tip: "🧠 Compound growth: 2% vs 4% rate gives 7x vs 50x after 100 years. Small differences, huge outcomes." },
  { id: 'eco53', cat: 'economics', emoji: '💸', subject: 'Economics — Behavioural', diff: 2, hook: "People treat money differently depending on where it came from.", fact: "Mental accounting (Thaler): people categorise money into separate mental accounts and treat them differently. Lottery winnings feel like \'fun money\' even if you are in debt. Tax refunds are spent differently than wages.", tip: "🧠 Mental accounting: money from different sources feels different. Lottery win = fun money, not debt repayment." },
  { id: 'eco54', cat: 'economics', emoji: '🌐', subject: 'Economics — Trade Balance', diff: 2, hook: "A trade deficit is not necessarily bad — and a surplus is not necessarily good.", fact: "A trade deficit means you import more than you export. This can reflect: a strong domestic economy, high investment attractiveness, or low savings. Germany\'s surplus reflects low domestic consumption, not just competitiveness.", tip: "🧠 Trade deficit = not automatically bad. Surplus = not automatically good. Context determines meaning." },
  { id: 'eco55', cat: 'economics', emoji: '💰', subject: 'Economics — Minimum Wage', diff: 2, hook: "Raising the minimum wage does not always cause the unemployment economists once predicted.", fact: "Classical theory: minimum wage above market rate causes unemployment. Empirical evidence (Card and Krueger, 1994 — Nobel Prize 2021): modest minimum wage rises often have negligible employment effects in low-competition labour markets.", tip: "🧠 Minimum wage: classical theory says job losses. Card and Krueger showed modest rises often have little effect." },
  { id: 'inv26', cat: 'inventions', emoji: '💡', subject: 'Inventions — Safety Pin', diff: 1, hook: "The safety pin was invented in a single afternoon and sold for $400.", fact: "Walter Hunt invented the safety pin in 1849 in about 3 hours using a piece of wire. He sold the patent for $400 to pay off a $15 debt. The buyer made a fortune. Hunt remained poor.", tip: "🧠 Safety pin: invented in 3 hours, sold for $400 to pay off $15 debt. Buyer made a fortune." },
  { id: 'inv27', cat: 'inventions', emoji: '🌐', subject: 'Inventions — GPS', diff: 2, hook: "GPS was a military system — opened to civilians after a plane was shot down.", fact: "GPS was developed by the US military in the 1970s. After Korean Air Lines Flight 007 was shot down in Soviet airspace in 1983, President Reagan opened GPS to civilian use. Fully operational from 1995.", tip: "🧠 GPS: US military system opened to civilians after Korean Airlines shot down in 1983." },
  { id: 'inv28', cat: 'inventions', emoji: '✈️', subject: 'Inventions — Jet Engine', diff: 2, hook: "The jet engine was independently invented by two engineers on opposite sides of World War 2.", fact: "Frank Whittle (UK) and Hans von Ohain (Germany) both developed working jet engines independently in the late 1930s. Von Ohain\'s flew first in August 1939. They met after the war and became friends.", tip: "🧠 Jet engine: invented simultaneously by Whittle (UK) and von Ohain (Germany). Met after the war." },
  { id: 'inv29', cat: 'inventions', emoji: '💊', subject: 'Inventions — Aspirin', diff: 1, hook: "Aspirin is over 120 years old and still irreplaceable — 100 billion tablets consumed annually.", fact: "Aspirin (acetylsalicylic acid) was first synthesised by Felix Hoffmann at Bayer in 1897. It is used for pain, fever, inflammation, heart attack prevention, and possibly cancer prevention.", tip: "🧠 Aspirin: 120+ years old, 100 billion tablets/year. Still one of medicine\'s most versatile drugs." },
  { id: 'inv30', cat: 'inventions', emoji: '🖥️', subject: 'Inventions — Programming', diff: 2, hook: "The world\'s first programmer was a woman who worked a century before computers existed.", fact: "Ada Lovelace wrote the first computer algorithm in 1843 — for Charles Babbage\'s proposed Analytical Engine, which was never built. She also foresaw computers composing music and manipulating symbols beyond numbers.", tip: "🧠 Ada Lovelace: first programmer, 1843. Machine never built, but her algorithms were real." },
  { id: 'inv31', cat: 'inventions', emoji: '🔬', subject: 'Inventions — Telescope', diff: 2, hook: "The telescope did not begin in science — it was a military and maritime tool.", fact: "Dutch lens-maker Hans Lipperhey applied for a patent in 1608. Galileo heard of it and built his own in 1609, then pointed it skyward. He found Jupiter\'s moons — proof that not everything orbited Earth.", tip: "🧠 Telescope: invented 1608 by Lipperhey, pointed at sky by Galileo 1609. Found Jupiter\'s moons." },
  { id: 'inv32', cat: 'inventions', emoji: '💡', subject: 'Inventions — Post-it Notes', diff: 1, hook: "Post-it Notes were invented from a failed super-strong adhesive.", fact: "Spencer Silver at 3M developed a low-tack adhesive in 1968 that was not strong enough for its purpose. It sat unused until colleague Art Fry used it to keep bookmarks in his hymnal in 1974. Post-it Notes launched in 1980.", tip: "🧠 Post-it Notes: failed glue (1968) plus a bookmark idea (1974) = product launch (1980)." },
  { id: 'inv33', cat: 'inventions', emoji: '🌐', subject: 'Inventions — Telephone', diff: 2, hook: "Alexander Graham Bell won the telephone patent by just 2 hours.", fact: "On 14 February 1876, Bell filed his patent just hours before Elisha Gray filed a similar invention. Bell received the patent. Gray contested it for years. One of history\'s most consequential patent races.", tip: "🧠 Bell won the telephone patent ~2 hours ahead of Elisha Gray — 14 February 1876." },
  { id: 'inv34', cat: 'inventions', emoji: '⚙️', subject: 'Inventions — Velcro', diff: 2, hook: "Velcro was invented after a walk in the woods with a dog.", fact: "In 1941, Swiss engineer George de Mestral found burdock burrs on his dog\'s fur. Under a microscope he saw hooks catching loops — and spent 14 years developing the idea. Velcro was patented in 1955.", tip: "🧠 Velcro: inspired by burdock burrs on a dog in 1941. Patent: 1955. 14 years of development." },
  { id: 'inv35', cat: 'inventions', emoji: '🧬', subject: 'Inventions — CRISPR', diff: 3, hook: "CRISPR-Cas9 allows scientists to edit DNA like a word processor.", fact: "CRISPR-Cas9 (2012) is a gene-editing tool derived from bacterial immune systems. It can cut, delete, or insert specific DNA sequences with unprecedented precision. It won the 2020 Nobel Prize in Chemistry.", tip: "🧠 CRISPR: Nobel 2020, edits DNA precisely. Could cure genetic diseases. Raises profound ethical questions." },
  { id: 'inv36', cat: 'inventions', emoji: '💡', subject: 'Inventions — Neon Sign', diff: 1, hook: "Neon signs were first sold in the US in 1923 for $24,000 each.", fact: "Georges Claude demonstrated neon lighting in Paris in 1910. He sold the first neon sign to a Los Angeles Packard dealership in 1923. Crowds gathered in the street to stare. They called it \'liquid fire\'.", tip: "🧠 Neon signs: Paris 1910, LA 1923, $24,000 each. Crowds called it \'liquid fire\'." },
  { id: 'inv37', cat: 'inventions', emoji: '🔌', subject: 'Inventions — Battery', diff: 2, hook: "The first battery was invented in 1800 before anyone understood electricity.", fact: "Alessandro Volta invented the voltaic pile in 1800 by stacking alternating zinc and silver discs separated by brine-soaked cloth. He did not fully understand why it worked. The unit \'volt\' is named after him.", tip: "🧠 Volta: invented the battery in 1800 without fully knowing why it worked. Unit \'volt\' = his name." },
  { id: 'inv38', cat: 'inventions', emoji: '🧪', subject: 'Inventions — Teflon', diff: 2, hook: "Teflon was discovered by accident when a refrigerant experiment went wrong.", fact: "Roy Plunkett at DuPont in 1938 found a gas cylinder that appeared empty but weighed too much. He cut it open and found a white slippery powder — PTFE, later branded Teflon. Patented 1941.", tip: "🧠 Teflon (PTFE): discovered 1938 by accident in a refrigerant experiment gone wrong." },
  { id: 'inv39', cat: 'inventions', emoji: '📱', subject: 'Inventions — Touchscreen', diff: 2, hook: "Touchscreen technology was invented 25 years before the first iPhone.", fact: "The first capacitive touchscreen was developed at the University of Toronto in 1982. Multiple companies developed the technology through the 1990s. Apple\'s 2007 iPhone popularised it but did not invent it.", tip: "🧠 Touchscreen: invented 1982. iPhone (2007) popularised it. Apple did not invent it." },
  { id: 'inv40', cat: 'inventions', emoji: '🚂', subject: 'Inventions — Underground', diff: 2, hook: "London\'s Tube is the world\'s oldest underground railway — it opened in 1863.", fact: "The Metropolitan Railway opened on 10 January 1863 between Paddington and Farringdon — the world\'s first underground railway. It used steam locomotives. Ventilation was supposedly adequate. It was not.", tip: "🧠 London Tube: opened 10 January 1863. First underground railway. Steam trains, terrible ventilation." },
  { id: 'inv41', cat: 'inventions', emoji: '💡', subject: 'Inventions — Microchip', diff: 2, hook: "The microchip was independently invented by two engineers at rival companies.", fact: "Jack Kilby (Texas Instruments) and Robert Noyce (Fairchild Semiconductor) both invented the integrated circuit in 1958-59 independently. Kilby received the 2000 Nobel Prize. Noyce had died in 1990 and was ineligible.", tip: "🧠 Microchip: invented simultaneously by Kilby and Noyce in 1958-59. Nobel went to Kilby alone." },
  { id: 'inv42', cat: 'inventions', emoji: '🌐', subject: 'Inventions — Email', diff: 2, hook: "Email was invented 10 years before the internet — on ARPANET.", fact: "Ray Tomlinson invented electronic mail in 1971 on ARPANET, choosing the @ symbol to separate user from machine. The first email was sent between two computers sitting side by side.", tip: "🧠 Email: invented 1971 by Ray Tomlinson. First used the @ symbol. Computers were side by side." },
  { id: 'inv43', cat: 'inventions', emoji: '⚙️', subject: 'Inventions — Barcode', diff: 1, hook: "The barcode was invented from an idea about sand and Morse code.", fact: "Norman Woodland invented the barcode in 1948 after drawing Morse code dots and dashes in sand with his fingers into lines. Practical barcode scanners did not arrive until laser technology emerged in the 1970s.", tip: "🧠 Barcode: Morse code plus sand equals lines, 1948. Practical scanners only arrived in the 1970s." },
  { id: 'inv44', cat: 'inventions', emoji: '🔬', subject: 'Inventions — MRI', diff: 2, hook: "MRI uses the magnetic properties of hydrogen atoms to image the body.", fact: "MRI aligns hydrogen protons in body water with a magnetic field, then disrupts them with radio waves. As they realign they emit signals processed into images. No radiation. Nobel Prize in Medicine 2003.", tip: "🧠 MRI: uses hydrogen atoms in water, no radiation. Nobel Prize 2003. First human scan: 1977." },
  { id: 'inv45', cat: 'inventions', emoji: '💡', subject: 'Inventions — Zipper', diff: 2, hook: "The zipper took 40 years to gain widespread adoption after its invention.", fact: "Whitcomb Judson patented a zipper-like device in 1893. Gideon Sundback improved it in 1913. Zippers were not widely used in clothing until the 1930s. The US Navy adopted them in WW2, cementing ubiquity.", tip: "🧠 Zipper: invented 1893, improved 1913, widespread only in the 1930s-40s. US Navy sealed it." },
  { id: 'inv46', cat: 'inventions', emoji: '🚗', subject: 'Inventions — Radar', diff: 2, hook: "Multiple countries independently developed radar in the 1930s — Britain just used it fastest.", fact: "Germany, UK, France, US, and Japan all developed radar in the 1930s. Britain\'s Chain Home network, operational by 1939, gave RAF fighters advance warning of Luftwaffe attacks during the Battle of Britain.", tip: "🧠 Radar: developed independently by many nations. Britain\'s Chain Home network (1939) won the Battle of Britain." },
  { id: 'inv47', cat: 'inventions', emoji: '🧬', subject: 'Inventions — PCR', diff: 2, hook: "PCR amplifies a tiny piece of DNA millions of times — and underpins modern medicine.", fact: "Polymerase Chain Reaction was invented by Kary Mullis in 1983 reportedly while driving on a California highway. Nobel Prize in 1993. PCR is the basis of DNA fingerprinting, COVID-19 testing, and countless diagnostics.", tip: "🧠 PCR: invented 1983 (on a highway). Nobel 1993. Basis of DNA fingerprinting and COVID testing." },
  { id: 'inv48', cat: 'inventions', emoji: '⚙️', subject: 'Inventions — Paper', diff: 2, hook: "Paper was invented in China around 105 AD and took 600 years to reach Europe.", fact: "Cai Lun is credited with modern papermaking in ~105 AD using bark, hemp, rags, and fishnets. Paper reached the Islamic world via Chinese prisoners after the Battle of Talas (751 AD). Europe: ~1150 AD.", tip: "🧠 Paper: China ~105 AD, Islamic world 751 AD via prisoners, Europe ~1150 AD." },
  { id: 'inv49', cat: 'inventions', emoji: '💊', subject: 'Inventions — Anaesthesia', diff: 2, hook: "General anaesthesia was first demonstrated publicly in 1846 — changing surgery forever.", fact: "Before anaesthesia, surgery was performed on fully conscious, restrained patients. On 16 October 1846, William Morton demonstrated ether anaesthesia publicly at Massachusetts General Hospital. Surgery changed overnight.", tip: "🧠 Anaesthesia: first public demo 16 October 1846. Before it: surgery on fully conscious patients." },
  { id: 'inv50', cat: 'inventions', emoji: '🚀', subject: 'Inventions — Space Tourism', diff: 2, hook: "The first space tourist paid $20 million for an 8-day trip to the ISS.", fact: "Dennis Tito became the first space tourist in April 2001, paying ~$20 million for 8 days on the International Space Station aboard a Russian Soyuz. NASA initially objected. He was 60 years old.", tip: "🧠 First space tourist: Dennis Tito, April 2001, $20M, 8 days on ISS. NASA tried to stop him." },
  { id: 'inv51', cat: 'inventions', emoji: '💡', subject: 'Inventions — Roman Concrete', diff: 2, hook: "Roman concrete was stronger than modern concrete — and we only figured out why recently.", fact: "Roman concrete used in the Pantheon and aqueducts has lasted 2,000 years. A 2023 analysis found that seawater reacting with the volcanic ash mixture grows new minerals, sealing cracks. Modern concrete cracks more permanently.", tip: "🧠 Roman concrete: self-heals via seawater and volcanic ash reaction. Still standing 2,000 years later." },
  { id: 'inv52', cat: 'inventions', emoji: '⚙️', subject: 'Inventions — Paper Clip', diff: 1, hook: "The paper clip as we know it was invented in 1899 — and nobody is sure exactly who did it.", fact: "The iconic Gem paper clip design appeared around 1899. Both William Middlebrook (US patent holder) and Johan Vaaler (Norwegian) are credited. Norway adopted Vaaler\'s version as a national symbol of resistance in WW2.", tip: "🧠 Paper clip: invented ~1899, disputed inventor. Norway made it a national WW2 resistance symbol." },
  { id: 'inv53', cat: 'inventions', emoji: '🔬', subject: 'Inventions — X-rays', diff: 2, hook: "X-rays were discovered by accident — and the discoverer used his wife\'s hand for the first medical image.", fact: "Wilhelm Roentgen discovered X-rays on 8 November 1895 while experimenting with cathode ray tubes. He used his wife Anna\'s hand for the first medical X-ray image. He won the first ever Nobel Prize in Physics in 1901.", tip: "🧠 X-rays: discovered by accident 1895. First image: Roentgen\'s wife\'s hand. Nobel Prize 1901." },
  { id: 'inv54', cat: 'inventions', emoji: '💡', subject: 'Inventions — Mechanical Clock', diff: 2, hook: "The mechanical clock was the most transformative invention of the Middle Ages.", fact: "Before mechanical clocks (~1280s), time was measured by sun, water, and sand. Mechanical clocks created standardised public time — enabling coordinated work, shipping, military operations, and the concept of punctuality itself.", tip: "🧠 Mechanical clock (~1280): created standardised time. Made industry, coordination, and punctuality possible." },
  { id: 'inv55', cat: 'inventions', emoji: '⚙️', subject: 'Inventions — Gunpowder', diff: 2, hook: "Gunpowder was invented by Chinese alchemists searching for immortality.", fact: "Chinese alchemists discovered gunpowder around 850 AD while experimenting with ingredients for an elixir of immortality. The mixture of sulphur, charcoal, and potassium nitrate proved explosive. It reached Europe via the Silk Road by the 1300s.", tip: "🧠 Gunpowder: discovered ~850 AD by Chinese alchemists searching for immortality. Reached Europe ~1300s." },
  { id: 'food26', cat: 'food', emoji: '🍕', subject: 'Food Science — Pizza', diff: 1, hook: "The pizza Margherita was named after the Queen of Italy.", fact: "In 1889, Neapolitan pizzaiolo Raffaele Esposito created a pizza with tomato (red), mozzarella (white), and basil (green) — representing the Italian flag — for Queen Margherita of Savoy.", tip: "🧠 Pizza Margherita: named for Queen Margherita, 1889. Red, white, green = Italian flag." },
  { id: 'food27', cat: 'food', emoji: '🧅', subject: 'Food Science — Onions', diff: 1, hook: "Onions make you cry because they release sulphur compounds that form acid in your eyes.", fact: "When you cut an onion, alliinase enzymes convert compounds into a lachrymatory factor. When it reaches your eyes it dissolves in tear fluid and forms dilute sulphuric acid. Chilling onions slows the reaction.", tip: "🧠 Onions: release lachrymatory agent that forms sulphuric acid in your eyes. Chill them to reduce it." },
  { id: 'food28', cat: 'food', emoji: '☕', subject: 'Food Science — Tea', diff: 1, hook: "Tea is the most consumed beverage on Earth after water.", fact: "Tea accounts for ~3.7 billion cups per day globally — more than coffee, soft drinks, and juice combined. All true tea — black, green, oolong, white — comes from one plant: Camellia sinensis.", tip: "🧠 Tea: 3.7 billion cups/day globally. All true tea from one plant: Camellia sinensis." },
  { id: 'food29', cat: 'food', emoji: '🍷', subject: 'Food Science — Alcohol', diff: 2, hook: "All alcoholic beverages are produced by the same basic biological process.", fact: "Fermentation: yeast consumes sugar and produces ethanol plus CO2. Wine (grapes), beer (malted grain), cider (apples) all use fermentation. Spirits distil the fermented liquid to concentrate alcohol.", tip: "🧠 All alcohol: yeast plus sugar plus time. Wine, beer, spirits, cider — same basic chemistry." },
  { id: 'food30', cat: 'food', emoji: '🧂', subject: 'Food Science — MSG', diff: 2, hook: "MSG has been scientifically cleared of causing illness.", fact: "\'Chinese Restaurant Syndrome\' (headaches and flushing attributed to MSG) was proposed in 1968. Multiple double-blind studies have failed to confirm symptoms even in self-identified MSG-sensitive people. The FDA classifies MSG as generally recognised as safe.", tip: "🧠 MSG: scientifically cleared. \'Chinese Restaurant Syndrome\' was not replicated in blind trials." },
  { id: 'food31', cat: 'food', emoji: '🍫', subject: 'Food Science — Cacao', diff: 2, hook: "Cacao beans were used as currency by the Aztecs.", fact: "Aztecs used cacao beans as money — a turkey cost 100 beans, a slave cost 500. Chocolate was consumed as a bitter spicy drink. Sugar was not added until Europeans adapted the recipe in the 16th century.", tip: "🧠 Aztecs: cacao as money (turkey = 100 beans). Chocolate was spicy before Europeans added sugar." },
  { id: 'food32', cat: 'food', emoji: '🌽', subject: 'Food Science — Corn', diff: 1, hook: "Maize is the world\'s most widely grown crop by volume.", fact: "Maize production: ~1.2 billion tonnes per year globally. Most goes to animal feed (~40% in the US) and fuel (ethanol ~35%). Only ~15% goes to direct human food consumption.", tip: "🧠 Corn: most produced crop (1.2B tonnes/year). Mostly animal feed and ethanol, not human food." },
  { id: 'food33', cat: 'food', emoji: '🍞', subject: 'Food Science — Gluten', diff: 2, hook: "Only a small fraction of people have a genuine medical reason to avoid gluten.", fact: "Coeliac disease (autoimmune reaction to gluten) affects ~1% of people. About 30% of people buy gluten-free products. For people without coeliac disease, gluten-free diets show no measurable health benefit.", tip: "🧠 Only ~1% have coeliac disease. ~30% buy gluten-free. For most: zero evidence of benefit." },
  { id: 'food34', cat: 'food', emoji: '🍅', subject: 'Food Science — Lycopene', diff: 2, hook: "Cooking tomatoes increases the bioavailability of their most powerful antioxidant.", fact: "Lycopene is more bioavailable when tomatoes are cooked and combined with fat. Tomato sauce with olive oil delivers far more usable lycopene than raw tomatoes. Heat breaks down cell walls, releasing it.", tip: "🧠 Cooked tomato plus fat: more bioavailable lycopene than raw. Pasta sauce beats salad here." },
  { id: 'food35', cat: 'food', emoji: '🍵', subject: 'Food Science — Matcha', diff: 2, hook: "Matcha contains caffeine and L-theanine together — creating calm focus rather than jitters.", fact: "Matcha is shade-grown green tea ground to powder. Shade-growing boosts L-theanine — an amino acid that promotes relaxed alertness and moderates caffeine\'s stimulating effects. Hence calm energy without jitters.", tip: "🧠 Matcha: caffeine plus L-theanine = calm focus. L-theanine moderates caffeine jitters." },
  { id: 'food36', cat: 'food', emoji: '🥚', subject: 'Food Science — Fermentation', diff: 2, hook: "Fermenting vegetables makes them safer than raw ones.", fact: "The lactic acid bacteria that dominate vegetable fermentation (sauerkraut, kimchi, pickles) produce acidic conditions preventing pathogenic bacteria. Traditional fermentation was a reliable food safety technique for thousands of years before refrigeration.", tip: "🧠 Fermented vegetables: safer than raw. Lactic acid bacteria prevent pathogens." },
  { id: 'food37', cat: 'food', emoji: '🫒', subject: 'Food Science — Olive Oil', diff: 1, hook: "Extra virgin olive oil is literally fruit juice — cold-pressed from fresh olives.", fact: "Extra virgin olive oil is just cold-pressed olive juice. It contains polyphenols and vitamin E. \'Light\' olive oil is refined and lacks these benefits. High heat degrades its antioxidants.", tip: "🧠 Extra virgin olive oil = cold-pressed olive juice. Contains polyphenols. High heat degrades them." },
  { id: 'food38', cat: 'food', emoji: '🧃', subject: 'Food Science — Juice', diff: 2, hook: "Fruit juice contains roughly the same sugar as soda — without the fibre.", fact: "Apple juice: ~28g sugar per 330ml. Coca-Cola: ~35g per 330ml. Without fibre (removed by juicing), fruit sugar is rapidly absorbed. Whole fruit is far healthier because fibre slows sugar absorption.", tip: "🧠 Fruit juice: sugar level near soda. Fibre removed. Whole fruit is far healthier." },
  { id: 'food39', cat: 'food', emoji: '🍞', subject: 'Food Science — Yeast', diff: 2, hook: "Baker\'s yeast and brewer\'s yeast are the same species.", fact: "Both bread and beer use Saccharomyces cerevisiae — the same species. Baker\'s strains prioritise CO2 for rising. Brewer\'s strains prioritise alcohol and flavour compounds. Different strains, same organism.", tip: "🧠 Baker\'s and brewer\'s yeast: same species (Saccharomyces cerevisiae). Different strains for different goals." },
  { id: 'food40', cat: 'food', emoji: '🫐', subject: 'Food Science — Blue Foods', diff: 1, hook: "Blue is the rarest natural colour in food.", fact: "Blue foods are extremely rare because there are very few natural blue pigments. Blueberries, purple cabbage, and butterfly pea flower are among the few. Blue M&Ms did not exist until 1995 — created after a public vote.", tip: "🧠 Blue foods: rarest natural colour. Few natural blue pigments exist. Blue M&Ms created by public vote 1995." },
  { id: 'food41', cat: 'food', emoji: '🥩', subject: 'Food Science — Marbling', diff: 2, hook: "Fat marbling in meat improves both flavour and tenderness simultaneously.", fact: "Intramuscular fat melts during cooking, basting the muscle from inside and lubricating protein fibres for tenderness. It also carries fat-soluble flavour compounds. This is why wagyu beef commands premium prices.", tip: "🧠 Marbling: fat melts during cooking, tenderises from inside, carries flavour compounds. That\'s wagyu." },
  { id: 'food42', cat: 'food', emoji: '☕', subject: 'Food Science — Decaf', diff: 1, hook: "Decaf coffee still contains caffeine — just about 3% of the original amount.", fact: "Decaffeination removes ~97% of caffeine. A decaf coffee contains 2-15 mg versus ~95 mg in regular. Someone sensitive to caffeine drinking several decafs could still consume a meaningful amount.", tip: "🧠 Decaf: retains ~3% caffeine (2-15mg vs regular 95mg). Not caffeine-free." },
  { id: 'food43', cat: 'food', emoji: '🥛', subject: 'Food Science — Pasteurisation', diff: 2, hook: "Pasteurisation was invented for wine — not milk.", fact: "Louis Pasteur developed it in 1864 at the request of Napoleon III, who wanted to stop French wine spoiling during transport. It was applied to milk only in the 1880s onwards, after scientists linked unpasteurised milk to tuberculosis.", tip: "🧠 Pasteurisation: invented for wine in 1864. Applied to milk later after the TB connection was found." },
  { id: 'food44', cat: 'food', emoji: '🌶️', subject: 'Food Science — Spice Tolerance', diff: 2, hook: "Spice tolerance is real — capsaicin desensitises your pain receptors at the receptor level.", fact: "Regular chilli consumption desensitises TRPV1 receptors that detect capsaicin. Regular spicy food eaters can genuinely handle higher Scoville ratings over time. The tolerance is receptor-level, not just psychological.", tip: "🧠 Spice tolerance: real, receptor-level. Regular capsaicin genuinely desensitises TRPV1 receptors." },
  { id: 'food45', cat: 'food', emoji: '🧁', subject: 'Food Science — Maillard Reaction', diff: 2, hook: "The Maillard reaction and caramelisation are different processes — both brown food.", fact: "Maillard reaction: amino acids plus reducing sugars, requires protein, starts around 140°C. Creates complex flavours in meat, bread, and coffee. Caramelisation: pure sugar heating at 160-180°C, simpler sweet-bitter flavours. Different chemistry, similar colour.", tip: "🧠 Maillard = protein plus sugar (140°C). Caramelisation = pure sugar (160°C). Different chemistry, same browning." },
  { id: 'food46', cat: 'food', emoji: '🥦', subject: 'Food Science — Broccoli', diff: 2, hook: "Chopping broccoli and waiting 40 minutes before cooking maximises its cancer-fighting compounds.", fact: "Broccoli contains glucosinolates. When cells are damaged by chopping, myrosinase enzyme converts them to sulforaphane — a powerful anticancer compound. Cooking immediately destroys myrosinase. Chop, wait 40 minutes, then cook.", tip: "🧠 Broccoli hack: chop, wait 40 minutes, then cook. Maximises sulforaphane (anticancer compound)." },
  { id: 'food47', cat: 'food', emoji: '🍫', subject: 'Food Science — Dark Chocolate', diff: 1, hook: "Dark chocolate contains more antioxidants per gram than most superfoods.", fact: "Dark chocolate (70%+) has a very high antioxidant score. It also contains flavanols linked to improved blood flow and cognitive function in studies. The cocoa, not the sugar or fat, provides the benefits.", tip: "🧠 Dark chocolate 70%+: high antioxidants, flavanols linked to cardiovascular and brain benefits." },
  { id: 'food48', cat: 'food', emoji: '☕', subject: 'Food Science — Roasting', diff: 2, hook: "Coffee beans are green before roasting — and supermarket coffee is usually months old.", fact: "Raw coffee beans are green with almost no coffee flavour. Roasting at 200-230°C creates hundreds of flavour compounds. Coffee is freshest 3-7 days post-roast. Supermarket coffee may be months old.", tip: "🧠 Coffee beans: green before roasting. Best 3-7 days post-roast. Supermarket coffee = old." },
  { id: 'food49', cat: 'food', emoji: '🧀', subject: 'Food Science — Cheese', diff: 2, hook: "There are over 1,800 distinct varieties of cheese — made from just a few basic processes.", fact: "Cheese is made worldwide from milk (cow, goat, sheep, buffalo, camel) plus cultures and rennet. Over 1,800 named varieties exist. France alone has over 1,200 protected cheese names. Basic process: curdle, separate, age.", tip: "🧠 Over 1,800 cheese varieties. France alone: 1,200+ protected names. Basic process: curdle, separate, age." },
  { id: 'food50', cat: 'food', emoji: '🍕', subject: 'Food Science — Fermented History', diff: 2, hook: "Fermentation predates cooking — humans discovered it before they mastered fire.", fact: "Evidence of fermented beverages dates to 7000 BC in China. Fermentation preserves food, creates alcohol, enhances nutrition, and adds beneficial bacteria. It was humanity\'s first food technology — older than bread or pottery.", tip: "🧠 Fermentation: evidence from 7000 BC China. Older than bread, pottery, or controlled cooking." },
  { id: 'food51', cat: 'food', emoji: '🧂', subject: 'Food Science — Umami', diff: 1, hook: "Parmesan cheese has one of the highest natural glutamate contents of any food.", fact: "Parmigiano-Reggiano contains ~1,200 mg glutamate per 100g — one of the highest naturally occurring umami concentrations. Other umami-rich foods: soy sauce (~1,090mg), anchovies (~670mg), tomato paste (~550mg).", tip: "🧠 Parmesan: highest natural glutamate (~1,200mg/100g). Then soy sauce, anchovies, tomato paste." },
  { id: 'food52', cat: 'food', emoji: '🍯', subject: 'Food Science — Honey', diff: 1, hook: "Honey is the only food that never spoils.", fact: "Honey found in 3,000-year-old Egyptian tombs was still edible. Its low moisture content, acidic pH, and hydrogen peroxide content prevent bacterial growth. Properly sealed honey can last indefinitely.", tip: "🧠 Honey: never spoils. 3,000-year-old Egyptian honey was still edible. Low moisture and acidity preserve it." },
  { id: 'food53', cat: 'food', emoji: '🥩', subject: 'Food Science — Umami Combinations', diff: 2, hook: "Combining two different umami sources creates a flavour stronger than either alone.", fact: "Synergistic umami: glutamate (parmesan, tomatoes, soy) combined with nucleotides (meat, mushrooms, anchovies) produces umami intensity up to 8 times greater than either alone. This is why Bolognese with parmesan tastes so good.", tip: "🧠 Umami synergy: glutamate plus nucleotides = up to 8x stronger umami. Why Bolognese with parmesan works." },
  { id: 'food54', cat: 'food', emoji: '🍞', subject: 'Food Science — Salt', diff: 2, hook: "Salt does not just add saltiness — it suppresses bitterness and enhances other flavours.", fact: "Salt suppresses bitter taste receptors while amplifying sweet, savoury, and aromatic notes. This is why a pinch of salt in coffee or chocolate makes them taste better — not saltier, just more of themselves.", tip: "🧠 Salt: suppresses bitterness and amplifies sweet and savoury. Pinch in coffee enhances flavour." },
  { id: 'food55', cat: 'food', emoji: '🌱', subject: 'Food Science — Plant Protein', diff: 2, hook: "Plant proteins can be complete when combined correctly — rice and beans is one example.", fact: "Most plant proteins are incomplete — missing or low in one or more essential amino acids. Rice (low in lysine) combined with beans (high in lysine) provides all 9 essential amino acids together.", tip: "🧠 Rice plus beans: complete protein. Covers each other\'s missing amino acids. Ancient combination, modern science." },
  { id: 'm26', cat: 'math', emoji: '🔢', subject: 'Maths — Pi and Infinity', diff: 1, hook: "Pi contains every possible sequence of digits — including your birthday.", fact: "Since pi is believed to be a normal number, every possible sequence of digits appears somewhere in its infinite decimal expansion. Your birthday, phone number, and any other combination — all in pi.", tip: "🧠 Pi is believed to contain every possible number sequence including your birthday somewhere in it." },
  { id: 'm27', cat: 'math', emoji: '♾️', subject: 'Maths — Prime Numbers', diff: 2, hook: "There is no largest prime number — Euclid proved this around 300 BC.", fact: "Euclid\'s proof: assume a finite list of primes. Multiply them all and add 1. This number is either prime or has a prime factor not in the list — contradiction. The largest known prime (2024) has 41 million digits.", tip: "🧠 No largest prime. Euclid proved this ~300 BC. Largest known prime (2024): 41 million digits." },
  { id: 'm28', cat: 'math', emoji: '📐', subject: 'Maths — Spheres', diff: 2, hook: "A sphere has the smallest possible surface area for a given volume.", fact: "The isoperimetric inequality: of all shapes enclosing a given volume, the sphere has the minimum surface area. This is why soap bubbles, water droplets, and planets all tend toward spherical form.", tip: "🧠 Sphere = minimum surface area for a given volume. Why bubbles, drops, and planets are round." },
  { id: 'm29', cat: 'math', emoji: '🎲', subject: 'Maths — Correlation', diff: 2, hook: "Correlation does not imply causation — one of the most important principles in statistics.", fact: "Ice cream sales and drowning rates both rise in summer (both caused by hot weather). Shoes and reading ability correlate in children (both caused by age). A third variable explains most spurious correlations.", tip: "🧠 Correlation does not equal causation. Ice cream and drowning: both caused by summer heat." },
  { id: 'm30', cat: 'math', emoji: '🌀', subject: 'Maths — Fractals', diff: 2, hook: "Fractals are shapes that look the same at every scale — and appear throughout nature.", fact: "A fractal repeats its pattern at every level of magnification. Natural fractals: coastlines, fern leaves, snowflakes, lightning, blood vessels, lung passages. The Mandelbrot set is the most famous mathematical example.", tip: "🧠 Fractals: self-similar at every scale. Found in coastlines, ferns, snowflakes, lungs, lightning." },
  { id: 'm31', cat: 'math', emoji: '🔢', subject: 'Maths — Number Bases', diff: 2, hook: "Humans use base 10 because of fingers — computers use base 2 because of switches.", fact: "Binary (base 2) uses only 0 and 1 — perfect for on/off electrical switches. Decimal (base 10) came from finger counting. Base 60 came from Babylon — why time still uses 60 minutes and 60 seconds.", tip: "🧠 Binary = switches. Decimal = fingers. Base 60 = Babylon. Still in our clocks today." },
  { id: 'm32', cat: 'math', emoji: '📐', subject: 'Maths — Pi Universality', diff: 2, hook: "Pi is the same for every circle in the universe — regardless of size.", fact: "Pi (~3.14159) is the ratio of circumference to diameter for any circle. A circle the size of the universe has the same pi as a penny. It is constant across all sizes and scales.", tip: "🧠 Pi is universal: same ratio for any circle, from a penny to the universe." },
  { id: 'm33', cat: 'math', emoji: '🎯', subject: 'Maths — Topology', diff: 2, hook: "The Klein bottle is a mathematical object with no inside or outside.", fact: "A Klein bottle is a non-orientable surface with no distinct inside or outside. It can only exist without self-intersection in four dimensions. 3D glass versions self-intersect and are approximations.", tip: "🧠 Klein bottle: no inside or outside. Exists fully only in 4D. Glass versions are approximations." },
  { id: 'm34', cat: 'math', emoji: '🔢', subject: 'Maths — Riemann Hypothesis', diff: 3, hook: "One of the greatest unsolved problems in maths concerns how prime numbers are distributed.", fact: "The Riemann Hypothesis (1859, still unproven) concerns the distribution of prime numbers. It is one of the Millennium Prize Problems, worth $1 million to whoever proves it. Most mathematicians believe it is true.", tip: "🧠 Riemann Hypothesis: unproven since 1859. About prime distribution. $1 million prize. Believed true." },
  { id: 'm35', cat: 'math', emoji: '📊', subject: 'Maths — Averages', diff: 1, hook: "Mean, median, and mode are three different averages — and they often give very different results.", fact: "Mean: sum divided by count (sensitive to outliers). Median: middle value (robust). Mode: most frequent. If 9 workers earn $30k and 1 earns $1M: mean ~$127k (misleading), median $30k (accurate).", tip: "🧠 Mean, median, mode: very different results. Billionaires inflate the mean. Median is more honest." },
  { id: 'm36', cat: 'math', emoji: '🌀', subject: 'Maths — Fibonacci', diff: 1, hook: "The Fibonacci sequence appears in the branching of plants and the arrangement of flower petals.", fact: "Fibonacci: 1, 1, 2, 3, 5, 8, 13, 21, 34. Flowers have petals in Fibonacci numbers most commonly. Sunflower seeds form spirals counted in Fibonacci numbers. Fibonacci spacing minimises overlap in plant growth.", tip: "🧠 Fibonacci in plants: petal counts, seed spirals. Minimises overlap in growth — evolutionary advantage." },
  { id: 'm37', cat: 'math', emoji: '🎲', subject: 'Maths — Expected Value', diff: 2, hook: "Expected value tells you what to expect on average — not what will happen in one event.", fact: "Expected value = sum of (outcome x probability). Casino games have negative expected value for players — the house wins over time even if any individual player can win short-term.", tip: "🧠 Expected value = long-run average. Casinos have negative EV for players by design." },
  { id: 'm38', cat: 'math', emoji: '♾️', subject: 'Maths — Zenos Paradox', diff: 3, hook: "Zeno\'s paradox suggests motion should be impossible — and the resolution requires calculus.", fact: "Zeno: to cross a room you must first go halfway, then half of that, infinitely. The sum 1/2 + 1/4 + 1/8... converges to exactly 1. Infinite steps, finite total. The paradox is resolved by calculus.", tip: "🧠 Zeno: infinite halves sum to 1, not infinity. Calculus resolves it. Infinite steps, finite total." },
  { id: 'm39', cat: 'math', emoji: '📐', subject: 'Maths — Trigonometry', diff: 1, hook: "Trigonometry was invented for astronomy and navigation — and underpins all modern physics.", fact: "Sine, cosine, and tangent relate angles to side ratios in right triangles. Hipparchus (~150 BC) built the first trig tables for astronomy. Today: engineering, physics, graphics, music synthesis all depend on trig.", tip: "🧠 Trigonometry: Hipparchus ~150 BC for astronomy. Now used in physics, engineering, graphics, music." },
  { id: 'm40', cat: 'math', emoji: '🔢', subject: 'Maths — Negative Numbers', diff: 2, hook: "Negative numbers were rejected by European mathematicians as \'absurd\' until the 1600s.", fact: "Indian mathematicians used negative numbers by the 7th century. Chinese by the 3rd century BC. European mathematicians called them \'false\' and \'absurd\' — unable to conceptualise less than nothing.", tip: "🧠 Negative numbers: used in India and China for centuries. Europeans called them \'absurd\' until 1600s." },
  { id: 'm41', cat: 'math', emoji: '🎯', subject: 'Maths — Coordinates', diff: 1, hook: "The Cartesian coordinate system was reportedly inspired by watching a fly on a ceiling.", fact: "Rene Descartes conceived of the coordinate system while watching a fly on the ceiling — realising he could describe its position using two numbers. XY coordinates are named after him (Cartesian = Descartes).", tip: "🧠 Descartes coordinates: inspired by a ceiling fly. Position = two numbers. Named after him." },
  { id: 'm42', cat: 'math', emoji: '📊', subject: 'Maths — Normal Distribution', diff: 2, hook: "Many natural phenomena follow the bell curve — the normal distribution.", fact: "The normal (Gaussian) distribution: symmetrical, bell-shaped. Height, weight, test scores, and measurement errors are all approximately normally distributed. 68% of values fall within 1 standard deviation of the mean.", tip: "🧠 Normal distribution: bell curve. Height, IQ, errors follow it. 68% within 1 standard deviation." },
  { id: 'm43', cat: 'math', emoji: '♾️', subject: 'Maths — Complex Numbers', diff: 3, hook: "The square root of negative numbers was called imaginary — but is essential to physics.", fact: "Complex numbers (a + bi, where i = sqrt of -1) are essential to quantum mechanics, electrical engineering (AC circuits), signal processing (Fourier transforms), and fluid dynamics. Calling them \'imaginary\' was wrong.", tip: "🧠 \'Imaginary\' numbers: essential to quantum mechanics, electronics, and signal processing." },
  { id: 'm44', cat: 'math', emoji: '🔢', subject: 'Maths — Place Value', diff: 1, hook: "The concept of place value is what makes arithmetic practical.", fact: "In positional notation, a digit\'s value depends on its position. \'123\' = 1 hundred, 2 tens, 3 ones. Without this (Roman numerals had no place value), multiplication and division are nightmares.", tip: "🧠 Place value: India developed it, Arabs spread it to Europe. Roman numerals had none. Transformed maths." },
  { id: 'm45', cat: 'math', emoji: '📐', subject: 'Maths — Symmetry and Physics', diff: 2, hook: "Symmetry in mathematics predicts the laws of physics — via Noether\'s theorem.", fact: "Emmy Noether (1915): every mathematical symmetry corresponds to a conserved physical law. Symmetry in time = conservation of energy. Symmetry in space = conservation of momentum. Einstein called her the greatest mathematical genius.", tip: "🧠 Noether\'s theorem: symmetry in maths = conservation law in physics. Time symmetry = energy conservation." },
  { id: 'm46', cat: 'math', emoji: '🌀', subject: 'Maths — Eulers Identity', diff: 3, hook: "Euler\'s identity is called the most beautiful equation in mathematics.", fact: "Euler\'s identity: e^(i*pi) + 1 = 0. It unites five fundamental constants: e, i, pi, 1, and 0. Mathematicians consistently vote it the most beautiful formula in all of mathematics.", tip: "🧠 Euler\'s identity: e^(i*pi)+1=0. Combines e, i, pi, 1, and 0. Most beautiful equation in maths." },
  { id: 'm47', cat: 'math', emoji: '♾️', subject: 'Maths — Different Infinities', diff: 3, hook: "There are infinitely many different infinities — and some are bigger than others.", fact: "Cantor\'s theorem: for any set, its power set is strictly larger. Since you can always take a power set, infinities form a hierarchy. Countable infinity (aleph-null) is smaller than uncountable infinity (aleph-one). Both are infinite.", tip: "🧠 Infinitely many infinities, each bigger than the last. Cantor proved you can always make a larger one." },
  { id: 'm48', cat: 'math', emoji: '📊', subject: 'Maths — Standard Deviation', diff: 2, hook: "Standard deviation measures how spread out data is — not how large the values are.", fact: "Low SD: data clustered tightly. High SD: data spread widely. Two groups with the same mean but different SD are very different populations — a fact that raw averages completely hide.", tip: "🧠 Standard deviation: measures spread, not size. Same mean, different SD = completely different distributions." },
  { id: 'm49', cat: 'math', emoji: '🎯', subject: 'Maths — Nash Equilibrium', diff: 2, hook: "The Nash Equilibrium predicts stable outcomes in strategic situations.", fact: "Nash Equilibrium (John Nash, 1950): a point where no player can improve their outcome by changing strategy alone. Not necessarily the best outcome for all — see the Prisoner\'s Dilemma. Used in economics, biology, and AI.", tip: "🧠 Nash Equilibrium: no player gains by changing alone. Stable but not always optimal for everyone." },
  { id: 'm50', cat: 'math', emoji: '🔢', subject: 'Maths — Casting Out Nines', diff: 1, hook: "There is a simple mental trick for checking arithmetic using digit sums.", fact: "Casting out nines: add digits of a number until you get a single digit. 123 becomes 6. 456 becomes 6. Then check: 6 x 6 = 36 becomes 9. If the result is 56,088 (becomes 9) then the multiplication is correct.", tip: "🧠 Casting out nines: check arithmetic by reducing numbers to single digits. Quick error detection." },
  { id: 'm51', cat: 'math', emoji: '📐', subject: 'Maths — All Circles Are Similar', diff: 1, hook: "All circles are the same shape — they differ only in size.", fact: "Unlike rectangles or ellipses, all circles are geometrically similar — just scaled versions of each other. This is why one ratio (pi) describes all circles universally. No other curved shape has this property.", tip: "🧠 All circles: same shape, different sizes only. The only 2D shape where all examples are identical." },
  { id: 'm52', cat: 'math', emoji: '🎲', subject: 'Maths — Law of Large Numbers', diff: 1, hook: "The more times you repeat a random event, the closer results get to the true probability.", fact: "Flip a fair coin 10 times: you might get 7 heads. Flip it 10,000 times: you will get very close to 50%. Random variation averages out over many trials. This underpins statistics, insurance, and casinos.", tip: "🧠 Law of Large Numbers: more trials = results closer to true probability. Foundation of statistics." },
  { id: 'm53', cat: 'math', emoji: '♾️', subject: 'Maths — Hilberts Hotel', diff: 3, hook: "A hotel with infinite rooms can always fit more guests — even if it is full.", fact: "Hilbert\'s Hotel paradox: infinite rooms, all occupied. New guest arrives: move guest in room 1 to room 2, room 2 to room 3, and so on. Room 1 is now free. You can always fit more into infinity.", tip: "🧠 Hilbert\'s Hotel: full but always room for more. Infinity plus one equals infinity." },
  { id: 'm54', cat: 'math', emoji: '🎯', subject: 'Maths — Four Colour Theorem', diff: 2, hook: "Any map can be coloured with just four colours so no two adjacent regions share a colour.", fact: "The Four Colour Theorem: proven in 1976 by Appel and Haken — the first major theorem proved with computer assistance. Any flat map, however complex, requires at most 4 colours.", tip: "🧠 Four Colour Theorem: proven 1976. Any map needs max 4 colours. First major computer-assisted proof." },
  { id: 'm55', cat: 'math', emoji: '🔢', subject: 'Maths — Benfords Law', diff: 2, hook: "In naturally occurring data, the digit 1 appears as the first digit about 30% of the time.", fact: "Benford\'s Law: in sets of naturally occurring numbers (populations, stock prices, river lengths), the digit 1 leads ~30% of the time, 2 leads ~18%, and so on down to 9 (~5%). Used to detect financial fraud.", tip: "🧠 Benford\'s Law: in real data, leading digit 1 appears 30% of the time. Used to detect fraud." },

  { id: 'pq151', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The shortest war in recorded history lasted 38 minutes.", fact: "The Anglo-Zanzibar War of 27 August 1896 lasted between 38 and 45 minutes. Britain demanded the new Sultan stand down. He refused. British ships shelled the palace and the Sultan surrendered.", tip: "🧠 Shortest war: Anglo-Zanzibar, 1896, 38-45 minutes. Sultan surrendered before lunch." },
  { id: 'pq152', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Nintendo was founded in 1889 — as a playing card company.", fact: "Nintendo was founded on 23 September 1889 in Kyoto by Fusajiro Yamauchi, making hand-crafted Hanafuda playing cards. It did not enter the video game business until the 1970s.", tip: "🧠 Nintendo: founded 1889, made playing cards. Video games came 80 years later." },
  { id: 'pq153', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The word \'nerd\' was first used by Dr Seuss in 1950.", fact: "\'Nerd\' first appeared in \'If I Ran the Zoo\' (1950) as the name of a fictional creature. By the 1960s it had become slang for an unfashionable, studious person. Seuss coined it accidentally.", tip: "🧠 Nerd: first appeared in Dr Seuss \'If I Ran the Zoo\' (1950) as a creature name." },
  { id: 'pq154', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The Eiffel Tower was supposed to be demolished after 20 years.", fact: "Built for the 1889 Paris World\'s Fair as a temporary structure, it was to be torn down in 1909. It survived because it was repurposed as a radio transmission tower.", tip: "🧠 Eiffel Tower: meant to be demolished 1909. Saved by being useful as a radio antenna." },
  { id: 'pq155', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Elephants are the only animals that cannot jump.", fact: "Adult elephants are the only mammals physically incapable of jumping. Their bone structure and weight (up to 6 tonnes) make it impossible. They can run up to 25 km/h but all four feet never leave the ground together.", tip: "🧠 Elephants: only mammals that cannot jump. Run at 25 km/h but never airborne." },
  { id: 'pq156', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The Pacific Ocean is wider than the Moon.", fact: "The Pacific Ocean spans approximately 19,800 km at its widest point. The Moon is 3,474 km in diameter. The Pacific is about 5.7 times wider than the Moon.", tip: "🧠 Pacific width: ~19,800 km. Moon diameter: 3,474 km. Pacific is 5.7x wider." },
  { id: 'pq157', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "More people die from vending machine accidents than shark attacks annually.", fact: "Vending machines kill approximately 13 people per year in the US — usually from rocking them to dislodge stuck items. Sharks kill 5-10 people globally per year.", tip: "🧠 Vending machines kill ~13/year in US. Sharks kill 5-10 globally. Choose your enemy." },
  { id: 'pq158', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Oxford University is older than the Aztec Empire.", fact: "Teaching at Oxford began around 1096-1167 AD. The Aztec city of Tenochtitlan was founded in 1325. Oxford predates the Aztec civilisation by roughly 200 years.", tip: "🧠 Oxford: teaching from ~1096. Aztecs founded Tenochtitlan: 1325. Oxford is 200 years older." },
  { id: 'pq159', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A group of flamingos is called a flamboyance.", fact: "The collective noun for flamingos is a \'flamboyance\'. Other unusual animal group names: a murder of crows, a parliament of owls, a crash of rhinos.", tip: "🧠 Flamingo group = flamboyance. Crows = murder. Owls = parliament. Rhinos = crash." },
  { id: 'pq160', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The Great Fire of London in 1666 destroyed most of the city but killed very few people.", fact: "The fire burned for 4 days (2-6 September 1666), destroying ~13,200 houses and 87 churches. Official death toll: just 6 people — though historians suspect more perished undocumented.", tip: "🧠 Great Fire 1666: 13,000+ houses, 87 churches destroyed. Official deaths: only 6." },
  { id: 'pq161', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The first tweet was sent in March 2006 by Twitter co-founder Jack Dorsey.", fact: "Jack Dorsey sent the first ever tweet: \'just setting up my twttr\' on 21 March 2006. The original tweet sold as an NFT in 2021 for $2.9 million.", tip: "🧠 First tweet: Jack Dorsey, 21 March 2006. \'just setting up my twttr\'. Sold as NFT for $2.9M." },
  { id: 'pq162', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Cleopatra was not Egyptian by descent — she was Macedonian Greek.", fact: "Cleopatra VII was a descendant of Ptolemy I, one of Alexander the Great\'s generals. She was reportedly the first ruler of her dynasty to learn the Egyptian language.", tip: "🧠 Cleopatra = Greek (Macedonian), not Egyptian. First of her dynasty to speak Egyptian." },
  { id: 'pq163', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A shrimp\'s heart is in its head.", fact: "A shrimp\'s heart is located in its cephalothorax — what we would consider its head region. Its brain wraps around its oesophagus — it literally thinks around its throat.", tip: "🧠 Shrimp heart: in the head. Brain: wraps around its throat. Unusual anatomy throughout." },
  { id: 'pq164', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "There are more possible chess games than atoms in the observable universe.", fact: "The Shannon Number estimates ~10^120 possible chess games. Observable universe atoms: ~10^80. Chess has 40 orders of magnitude more possible games than atoms in everything we can see.", tip: "🧠 Chess possibilities: 10^120. Universe atoms: 10^80. Chess wins by 40 zeros." },
  { id: 'pq165', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Honey bees can recognise human faces.", fact: "Research shows honey bees can learn to identify human faces using configural processing — recognising the overall arrangement of features rather than individual parts. They can be trained to match faces to rewards.", tip: "🧠 Bees can recognise human faces. They use similar pattern-matching to how we process faces." },
  { id: 'pq166', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "France was still using the guillotine when Star Wars came out.", fact: "The last guillotine execution in France was on 10 September 1977 — the same year Star Wars Episode IV was released (May 1977). France abolished the death penalty in 1981.", tip: "🧠 Last French guillotine: September 1977 — same year as Star Wars. Death penalty abolished 1981." },
  { id: 'pq167', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A cat has 32 muscles in each ear.", fact: "Cats have 32 muscles controlling each ear, allowing them to rotate ears 180° independently to locate sounds. Humans have about 6 ear muscles and most people can barely move them.", tip: "🧠 Cats: 32 ear muscles each, rotate 180°. Humans: ~6 ear muscles, mostly useless." },
  { id: 'pq168', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The inventor of the intermittent windscreen wiper fought Ford for decades and won.", fact: "Robert Kearns invented intermittent windscreen wipers in the 1960s. Ford and Chrysler copied his design. He sued and eventually won ~$30 million in settlements but spent decades fighting and lost his marriage.", tip: "🧠 Kearns: invented intermittent wipers, fought Ford for decades, won $30M, lost almost everything else." },
  { id: 'pq169', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The hashtag symbol is officially called an octothorpe.", fact: "The # symbol is officially called an octothorpe. \'Octo\' = eight (for its eight points). It was used on telephone keypads before Twitter made it a cultural phenomenon in 2007.", tip: "🧠 The # symbol = octothorpe. Eight points = octo. Twitter made it famous in 2007." },
  { id: 'pq170', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The first person ever convicted of speeding was doing 8 mph.", fact: "Walter Arnold of Kent was fined for speeding on 28 January 1896 — going 8 mph in a 2 mph zone. He was caught by a policeman who chased him on a bicycle.", tip: "🧠 First speeding conviction: Walter Arnold, 1896. Was doing 8 mph. Chased by a cyclist." },
  { id: 'pq171', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Venus is the only planet that rotates clockwise when viewed from above.", fact: "All planets rotate counter-clockwise when viewed from above the North Pole — except Venus, which rotates clockwise. Uranus is also unusual, tilted almost 98° on its side.", tip: "🧠 Venus: only planet with clockwise rotation from North Pole view. Uranus: tilted 98°." },
  { id: 'pq172', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "A day on Mars is only slightly longer than a day on Earth.", fact: "A Martian day (sol) is 24 hours 39 minutes and 35 seconds — just 40 minutes longer than an Earth day. This is the most convenient overlap between the two planets for potential colonists.", tip: "🧠 Mars day (sol) = 24h 39m — only 40 minutes longer than Earth. Most convenient planet similarity." },
  { id: 'pq173', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The average person walks the equivalent of five times around the Earth in a lifetime.", fact: "About 7,500 steps per day over 80 years equals roughly 216 million steps — equivalent to walking ~177,000 km or about 4-5 times around the Earth.", tip: "🧠 Average lifetime walking: ~177,000 km = about 4-5 times around the Earth." },
  { id: 'pq174', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The word quarantine comes from the Italian for forty days.", fact: "During the Black Death, Venice required ships to anchor offshore for 40 days before landing. The Italian \'quarantina\' means forty days. The period had Biblical and medical roots.", tip: "🧠 Quarantine = Italian for 40 days. Originated during Black Death in Venice." },
  { id: 'pq175', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Butterflies taste with their feet.", fact: "Butterflies have taste sensors (chemoreceptors) on their tarsi (feet). When they land, they immediately taste the surface — helping identify food sources and suitable plants for laying eggs.", tip: "🧠 Butterflies taste with their feet. Chemoreceptors on tarsi identify food and egg-laying sites." },
  { id: 'pq176', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The world\'s most expensive spice by weight is saffron.", fact: "Saffron costs up to £10,000 per kilogram. Each saffron crocus produces just 3 stigmas which must be hand-harvested. About 150,000 flowers are needed to yield 1 kg of saffron.", tip: "🧠 Saffron: up to £10,000/kg. 150,000 hand-harvested flowers per kilogram. World\'s priciest spice." },
  { id: 'pq177', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The name Google was a spelling mistake.", fact: "The founders intended to name it \'Googol\' (10^100). When checking domain availability, investor Sean Anderson misspelled it as \'Google\' — and the name stuck.", tip: "🧠 Google = accidental misspelling of \'Googol\' (10^100). The typo became a trillion-dollar brand." },
  { id: 'pq178', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The world\'s oldest joke is from ancient Sumer, around 1900 BC — and it is about flatulence.", fact: "The oldest recorded joke: \'Something which has never occurred since time immemorial; a young woman did not fart in her husband\'s lap.\' Scatological humour is apparently universal and eternal.", tip: "🧠 World\'s oldest joke: Sumerian, ~1900 BC, about flatulence. Comedy has not changed much." },
  { id: 'pq179', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A blue whale\'s heart is so large a human could crawl through its arteries.", fact: "The blue whale\'s heart weighs ~180 kg and is the size of a small car. Its main aorta is wide enough for a human to crawl through. The heart beats 4-8 times per minute.", tip: "🧠 Blue whale heart: ~180 kg, car-sized. Aorta wide enough to crawl through." },
  { id: 'pq180', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The world\'s most expensive coffee is made from civet droppings.", fact: "Kopi Luwak is made from coffee beans eaten and excreted by Asian palm civets. The digestive process alters the beans. It sells for $100-600 per kg. Elephant-processed Black Ivory Coffee costs even more.", tip: "🧠 Kopi Luwak: civet-dropping coffee, $100-600/kg. Elephant version (Black Ivory) costs even more." },
  { id: 'pq181', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The inventor of the Frisbee was turned into a Frisbee after he died.", fact: "Walter Morrison invented the Frisbee in the 1940s. When he died in 2010, his ashes were mixed into a batch of Frisbees and distributed to friends and family.", tip: "🧠 Frisbee inventor Walter Morrison: ashes turned into Frisbees after his death in 2010." },
  { id: 'pq182', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The original Monopoly was invented to teach people about the dangers of monopolies.", fact: "Elizabeth Magie patented \'The Landlord\'s Game\' in 1903 to show how landlords enrich themselves while tenants get poorer. Charles Darrow later claimed credit and became a millionaire. Magie received $500.", tip: "🧠 Monopoly origin: anti-monopoly teaching tool 1903. Magie got $500. Darrow became a millionaire." },
  { id: 'pq183', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "It is impossible to hum while holding your nose.", fact: "Try it — the moment you close your nostrils, humming stops. Humming requires airflow through the nasal passage. When you block the nose, the sound cannot be produced.", tip: "🧠 Cannot hum with nose closed. Needs nasal airflow. Try it." },
  { id: 'pq184', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Lobsters were once considered food fit only for prisoners and the poor.", fact: "In colonial New England, lobsters were so abundant they washed ashore in piles. Feeding servants lobster more than 3 times a week was considered cruel. Laws were passed against it.", tip: "🧠 Lobster: once poor-person food, fed to prisoners. Laws against overfeeding servants. Now a luxury." },
  { id: 'pq185', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The letter E is the most common letter in English text.", fact: "E accounts for approximately 11-13% of all letters in standard English text. This is why the letter E gets the highest frequency in Scrabble and Morse code assigns E the shortest signal — a single dot.", tip: "🧠 Most common English letter: E (~12%). Morse code: E = one dot. Shortest signal." },
  { id: 'pq186', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The world\'s first traffic light exploded.", fact: "The world\'s first traffic light was installed in London in December 1868 outside the Houses of Parliament. Using gas lamps, it exploded on 2 January 1869, injuring the police officer operating it.", tip: "🧠 First traffic light: London 1868, gas-powered. Exploded January 1869, injured the operator." },
  { id: 'pq187', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "Turtles can breathe through their rear ends.", fact: "Painted turtles can absorb oxygen through their cloaca during winter hibernation — a process called cloacal bursae respiration. It allows them to stay submerged under ice for months without breathing.", tip: "🧠 Turtles: breathe through their cloaca in winter. Stays submerged under ice for months." },
  { id: 'pq188', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The 1918 Spanish Flu did not originate in Spain.", fact: "It was called the Spanish Flu not because it started there but because Spain — neutral in WW1 — had a free press that reported deaths openly. Warring nations censored their own outbreaks. True origin is disputed.", tip: "🧠 Spanish Flu: not Spanish. Spain reported freely. Warring nations censored their outbreaks." },
  { id: 'pq189', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The shortest commercial flight in the world lasts under 2 minutes.", fact: "Loganair\'s flight between Westray and Papa Westray in Orkney, Scotland, officially lasts about 74 seconds in still air conditions. Distance: about 2.7 km.", tip: "🧠 Shortest commercial flight: Westray to Papa Westray, Orkney. ~74 seconds. 2.7 km." },
  { id: 'pq190', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "The world\'s largest living organism is a fungus in Oregon.", fact: "Armillaria ostoyae (honey fungus) in Malheur National Forest, Oregon, covers ~9.6 km2 and is estimated to be 2,000-8,000 years old. It exists mostly underground.", tip: "🧠 Largest organism: Armillaria fungus, Oregon, 9.6 km2, up to 8,000 years old." },
  { id: 'pq191', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A jiffy is a real unit of time in physics.", fact: "In physics, a jiffy equals the time light takes to travel one centimetre — about 33 picoseconds. In computing it is 1/100 of a second. Casual usage just means a short time.", tip: "🧠 Jiffy: physics = 33 picoseconds. Computing = 1/100 second. Casual = unspecified short time." },
  { id: 'pq192', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Benjamin Franklin did not discover electricity — he proved lightning was electrical.", fact: "Electricity had been observed for centuries. Franklin\'s famous 1752 kite experiment proved that lightning was electrical in nature, allowing the invention of the lightning rod.", tip: "🧠 Franklin: did not discover electricity. Proved lightning is electrical and invented the lightning rod." },
  { id: 'pq193', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A group of porcupines is called a prickle.", fact: "Collective nouns: porcupines = a prickle. Hippos = a bloat. Giraffes = a tower. Lemurs = a conspiracy. Flamingos = a flamboyance. Crows = a murder.", tip: "🧠 Porcupines = prickle. Hippos = bloat. Giraffes = tower. Lemurs = conspiracy." },
  { id: 'pq194', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "More Monopoly money is printed each year than real US currency.", fact: "Hasbro prints approximately $30 billion in Monopoly money per year. The US Bureau of Engraving and Printing produces about $1-1.5 billion in new bills annually.", tip: "🧠 Monopoly money printed per year: ~$30 billion. Real US dollar printing: ~$1-1.5 billion." },
  { id: 'pq195', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "A group of cats is called a clowder.", fact: "Collective nouns: cats = clowder. Kittens = kindle. Wild cats = destruction. Most people know \'litter\' for kittens but \'kindle\' is the proper term.", tip: "🧠 Cats = clowder. Kittens = kindle. Wild cats = destruction. Now you know." },
  { id: 'pq196', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Winston Churchill was born in a ladies\' cloakroom.", fact: "Churchill was born prematurely on 30 November 1874 at Blenheim Palace during a party. His mother went into labour unexpectedly and the nearest available room was a small ladies\' cloakroom.", tip: "🧠 Churchill: born prematurely in a ladies\' cloakroom at Blenheim Palace, 1874." },
  { id: 'pq197', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The first emoji was created in Japan in 1999 — each just 12 pixels square.", fact: "Shigetaka Kurita designed the original 176 emoji in 1999 for NTT DoCoMo\'s mobile internet service. Each was 12x12 pixels. The original set is now in MoMA in New York.", tip: "🧠 First emoji: 1999, Japan, 12x12 pixels, 176 icons. Now in MoMA New York." },
  { id: 'pq198', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "Rome and Beijing are at almost exactly the same latitude.", fact: "Rome sits at ~41.9°N. Beijing sits at ~39.9°N. Less than 2 degrees apart — two of history\'s greatest capitals at virtually the same distance from the equator.", tip: "🧠 Rome (41.9°N) and Beijing (39.9°N): almost identical latitude. Two great capitals." },
  { id: 'pq199', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 1, hook: "The human body contains enough iron to make a 3-inch nail.", fact: "An adult body contains roughly 3-4 grams of iron — mostly in red blood cells as haemoglobin. That is enough to forge a small nail of about 7-8 cm.", tip: "🧠 Body iron: ~3-4g — enough for a 3-inch nail. Also contains zinc, copper, manganese." },
  { id: 'pq200', cat: 'pub', emoji: '🍺', subject: 'Pub Quiz', diff: 2, hook: "During WW2 the US military trained bats to carry incendiary bombs.", fact: "Project X-Ray (1943): the US Army attached tiny incendiary bombs to thousands of Mexican free-tailed bats, planning to release them over Japanese cities to start fires. Cancelled when the atomic bomb took priority.", tip: "🧠 Project X-Ray: WW2 bat bomb project. Bats would roost in buildings and combust. Cancelled for nukes." },
  { id: 's61', cat: 'science', emoji: '🌍', subject: 'Science — Climate', diff: 2, hook: "CO2 levels today are higher than at any point in the last 3 million years.", fact: "Current atmospheric CO2 (~420 ppm) has not been this high in at least 3 million years — when global temperatures were 2-3°C warmer and sea levels were 15-25 metres higher.", tip: "🧠 CO2 at 420ppm: last seen 3 million years ago. Humans did not exist then. Sea was 15-25m higher." },
  { id: 's62', cat: 'science', emoji: '🦠', subject: 'Science — Viruses', diff: 2, hook: "Bacteriophages are the most abundant organisms on Earth and they hunt bacteria.", fact: "Bacteriophages (phages) are viruses that infect bacteria. There are an estimated 10^31 phage particles on Earth — vastly outnumbering all bacteria, plants, and animals combined.", tip: "🧠 Phages: 10^31 on Earth. Most abundant form of life. Viruses that kill bacteria." },
  { id: 's63', cat: 'science', emoji: '🌋', subject: 'Science — Geology', diff: 2, hook: "The Himalayan mountain range is young in geological terms — just 50 million years old.", fact: "The Himalayas began forming ~50 million years ago when India collided with Asia. The Appalachians in the US (~480 million years old) were once as tall as the Himalayas are now.", tip: "🧠 Himalayas: ~50 million years old — young. Appalachians: 480M years, once equally tall." },
  { id: 's64', cat: 'science', emoji: '🦎', subject: 'Science — Biology', diff: 2, hook: "Crocodilians are more closely related to birds than to lizards.", fact: "Crocodiles and alligators are archosaurs — the same group as birds and extinct dinosaurs. Lizards and snakes are a completely separate lineage. Crocodilians are actually birds\' closest living non-bird relatives.", tip: "🧠 Crocodiles: closer to birds than lizards. Both are archosaurs. Lizards = entirely different group." },
  { id: 's65', cat: 'science', emoji: '🔭', subject: 'Science — Cosmology', diff: 3, hook: "Dark matter and dark energy make up 95% of the universe — and we have no idea what they are.", fact: "Normal matter we can see and touch = ~5% of the universe. Dark matter (~27%) has gravitational effects but cannot be detected directly. Dark energy (~68%) drives the accelerating expansion of the universe.", tip: "🧠 Universe: 5% normal matter, 27% dark matter, 68% dark energy. We understand only 5% of it." },
  { id: 's66', cat: 'science', emoji: '🧬', subject: 'Science — Genetics', diff: 2, hook: "We share 85% of our genes with a zebrafish and 35% with a daffodil.", fact: "Gene sharing: zebrafish ~85%, fruit fly ~61%, roundworm ~35%, daffodil ~35%, baker\'s yeast ~31%. These similarities reflect the conserved fundamental processes of life shared across all organisms.", tip: "🧠 Human genes shared with: zebrafish 85%, fruit fly 61%, daffodil 35%. Life shares deep roots." },
  { id: 's67', cat: 'science', emoji: '💥', subject: 'Science — Physics', diff: 1, hook: "Einstein\'s most famous equation appeared as a three-page afterthought.", fact: "E=mc2 was not in Einstein\'s main 1905 special relativity paper. It appeared 3 months later in a short follow-up paper as a consequence he had noticed. The paper was only 3 pages long.", tip: "🧠 E=mc2: published in a 3-page afterthought, 3 months after the main relativity paper." },
  { id: 's68', cat: 'science', emoji: '🌊', subject: 'Science — Ocean', diff: 2, hook: "The deepest part of the ocean has been visited by humans fewer times than the Moon.", fact: "Challenger Deep in the Mariana Trench (~10,994m) has been visited by humans fewer than 20 times. The Moon has been walked on 12 times by 12 astronauts. The ocean is genuinely harder to reach.", tip: "🧠 Challenger Deep: visited fewer than 20 times. Harder for humans to reach than the Moon." },
  { id: 's69', cat: 'science', emoji: '🌍', subject: 'Science — Earth', diff: 2, hook: "Earth\'s magnetic poles wander and have reversed hundreds of times in geological history.", fact: "Earth\'s magnetic north pole moves ~55 km per year. The poles have reversed ~183 times in the last 83 million years — roughly one reversal every 450,000 years. We may be overdue.", tip: "🧠 Magnetic poles: move 55 km/year, reverse every ~450,000 years on average. May be overdue." },
  { id: 's70', cat: 'science', emoji: '🧪', subject: 'Science — Chemistry', diff: 2, hook: "There are more ways to arrange a deck of cards than seconds since the Big Bang.", fact: "52 factorial is approximately 8 x 10^67. Seconds since the Big Bang (~13.8 billion years): ~4 x 10^17. Card arrangements outnumber seconds by 50 orders of magnitude.", tip: "🧠 52! card arrangements >> seconds since Big Bang. Your shuffled deck is cosmically unique." },
  { id: 's71', cat: 'science', emoji: '🔬', subject: 'Science — Biology', diff: 2, hook: "Mary Anning discovered some of the most important fossils in history and received almost no credit.", fact: "Mary Anning (1799-1847) discovered the first complete ichthyosaur, the first plesiosaur, and a pterosaur from Dorset, England. Being a woman of limited means, she was excluded from scientific societies.", tip: "🧠 Mary Anning: discovered ichthyosaur, plesiosaur, pterosaur. Almost no credit. Woman. Poor. Genius." },
  { id: 's72', cat: 'science', emoji: '⚗️', subject: 'Science — Chemistry', diff: 1, hook: "Glass is technically an amorphous solid — not a liquid, despite an old myth.", fact: "Glass lacks the crystalline structure of true solids — it is a supercooled liquid that hardened without crystallising. The myth that old windows are thicker at the bottom because glass flows is false — it is manufacturing variation.", tip: "🧠 Glass: amorphous solid. Old window thickness = manufacturing, not flow. The liquid myth is wrong." },
  { id: 's73', cat: 'science', emoji: '💊', subject: 'Science — Medicine', diff: 1, hook: "Aspirin was derived from willow bark — a remedy known for 3,500 years.", fact: "Ancient Egyptians and Greeks used willow bark to relieve fever and pain. The active compound was isolated in 1828. Synthetic aspirin was patented by Bayer in 1899. One of history\'s most-used drugs.", tip: "🧠 Aspirin: from willow bark, known 3,500 years. Purified 1828. Bayer patented 1899." },
  { id: 's74', cat: 'science', emoji: '🧊', subject: 'Science — States', diff: 1, hook: "Water is one of the only substances that expands when it freezes.", fact: "Almost all substances contract when they freeze. Water expands ~9% as it freezes because ice crystals space molecules further apart. This is why ice floats, why pipes burst in winter, and why fish survive under ice.", tip: "🧠 Water expands 9% when freezing. Unique property. Why ice floats, why pipes burst." },
  { id: 's75', cat: 'science', emoji: '🌊', subject: 'Science — Fluid Dynamics', diff: 2, hook: "Ships float because they displace water equal to their weight.", fact: "Archimedes principle: an object floats when it displaces water weighing as much as itself. A 100,000-tonne ship must displace 100,000 tonnes of water — achieved by having a large hollow hull.", tip: "🧠 Archimedes: objects float by displacing their own weight in water. Shape, not material, is key." },
  { id: 's76', cat: 'science', emoji: '⚗️', subject: 'Science — Chemistry', diff: 2, hook: "Neon signs mostly do not contain neon — they use other gases for different colours.", fact: "Neon produces red-orange glow. Most signs use: argon (blue-violet), krypton (white), xenon (blue), or mercury vapour (blue). Only red-orange signs likely contain actual neon.", tip: "🧠 Neon signs: only red-orange ones contain neon. Blue = argon. White = krypton." },
  { id: 's77', cat: 'science', emoji: '🦟', subject: 'Science — Evolution', diff: 2, hook: "Insects make up two-thirds of all known animal species.", fact: "Of ~1.5 million described animal species, insects account for ~1 million (about 67%). Beetles alone (~400,000 species) represent more species than all plants on Earth combined.", tip: "🧠 Insects: ~1 million of 1.5 million animal species. Beetles alone exceed all plant species." },
  { id: 's78', cat: 'science', emoji: '🔬', subject: 'Science — Cells', diff: 2, hook: "Cancer cells are effectively immortal because they rebuild their chromosomal end caps.", fact: "Normal cells divide ~50-70 times then stop (the Hayflick limit). Cancer cells activate telomerase, which rebuilds telomeres that normally shorten with each division. HeLa cells from 1951 are still dividing in labs today.", tip: "🧠 Cancer cells: bypass normal cell death by rebuilding telomeres. HeLa cells from 1951 still alive in labs." },
  { id: 's79', cat: 'science', emoji: '🌍', subject: 'Science — Atmosphere', diff: 1, hook: "The sky is blue because of how air scatters different wavelengths of light.", fact: "Rayleigh scattering: air molecules scatter shorter wavelengths (blue, violet) more than longer ones (red, orange). Blue dominates what we see. At sunset, light travels further through atmosphere, scattering away the blue.", tip: "🧠 Sky is blue: air scatters blue light more than red. Sunset red: light travels further, blue all scattered." },
  { id: 's80', cat: 'science', emoji: '🦠', subject: 'Science — Microbiology', diff: 2, hook: "There are more viruses on Earth than stars in the observable universe.", fact: "The estimated number of viruses on Earth: ~10^31. Stars in the observable universe: ~10^24. Viruses outnumber stars by 10 million times. Most are bacteriophages in the ocean.", tip: "🧠 Viruses on Earth: ~10^31. Stars in universe: ~10^24. Viruses outnumber stars 10 million to one." },
  { id: 's81', cat: 'science', emoji: '🧬', subject: 'Science — Genetics', diff: 1, hook: "Every human cell (except red blood cells) contains your complete DNA.", fact: "Every nucleated cell — skin, liver, brain, muscle — contains the same complete genetic code. A single skin cell theoretically contains all the information to build you. This makes DNA evidence from any tissue possible.", tip: "🧠 Every cell has your full DNA. Any tissue can provide DNA evidence. Skin, hair, saliva — all of you." },
  { id: 's82', cat: 'science', emoji: '💊', subject: 'Science — Medicine', diff: 2, hook: "The discovery of penicillin was an accidental observation of mould killing bacteria.", fact: "Alexander Fleming returned from holiday in September 1928 to find a mould (Penicillium notatum) had contaminated a petri dish and killed surrounding bacteria. He recognised the significance. Penicillin saved millions of lives.", tip: "🧠 Penicillin: discovered by accident in 1928. Fleming noticed mould killing bacteria on his bench." },
  { id: 's83', cat: 'science', emoji: '🔭', subject: 'Science — Space', diff: 2, hook: "Voyager 1 is the most distant human-made object — and still sending data 47 years after launch.", fact: "Voyager 1 launched in September 1977 and is now ~24 billion km from Earth, in interstellar space. It still sends data that takes ~22 hours to reach us. It will drift through the galaxy for billions of years.", tip: "🧠 Voyager 1: launched 1977, ~24 billion km away, still sending data. 22 hours for signals to reach us." },
  { id: 'h69', cat: 'history', emoji: '🌍', subject: 'History — Trade', diff: 2, hook: "The Dutch East India Company was the world\'s first publicly traded company.", fact: "The VOC (Vereenigde Oost-Indische Compagnie), founded in 1602, issued shares on the Amsterdam Stock Exchange — the first in the world. It was also the first multinational corporation.", tip: "🧠 VOC (1602): world\'s first publicly traded company. Founded the Amsterdam Stock Exchange." },
  { id: 'h70', cat: 'history', emoji: '🏛️', subject: 'History — Egypt', diff: 2, hook: "Cleopatra lived closer in time to the Moon landing than to the building of the Great Pyramid.", fact: "Cleopatra died in 30 BC. The Great Pyramid was built ~2560 BC — 2,530 years before her. The Moon landing was 1969 — only 2,000 years after Cleopatra. The pyramids are ancient even to ancient Egypt.", tip: "🧠 Cleopatra was closer to the Moon landing than to the pyramids. The pyramids are that old." },
  { id: 'h71', cat: 'history', emoji: '⚔️', subject: 'History — WW2', diff: 2, hook: "D-Day was the largest seaborne invasion in history — with over 150,000 troops on day one.", fact: "On 6 June 1944, ~156,000 Allied troops crossed the English Channel to land in Normandy. The operation had over 10,000 Allied casualties on the first day. It turned the tide of WW2 in Western Europe.", tip: "🧠 D-Day: 6 June 1944, 156,000 troops, largest seaborne invasion. 10,000 casualties day one." },
  { id: 'h72', cat: 'history', emoji: '🌍', subject: 'History — Exploration', diff: 2, hook: "Antarctica was the last continent to be discovered — as recently as 1820.", fact: "Antarctica was not sighted until 1820, by three expeditions almost simultaneously (Russian, British, and American). No humans had ever laid eyes on it before that year.", tip: "🧠 Antarctica: last continent discovered. First sighted in 1820. Never seen by humans before." },
  { id: 'h73', cat: 'history', emoji: '🏰', subject: 'History — Battles', diff: 2, hook: "The Siege of Stalingrad was the deadliest battle in human history.", fact: "The Battle of Stalingrad (1942-1943) resulted in ~2 million casualties on both sides. The German defeat marked the turning point of World War 2 on the Eastern Front.", tip: "🧠 Stalingrad: ~2 million casualties, deadliest battle in history. Turned WW2 on the Eastern Front." },
  { id: 'h74', cat: 'history', emoji: '🌍', subject: 'History — East India Company', diff: 2, hook: "The East India Company was once more powerful than most nations.", fact: "At its peak in the mid-1800s, the British East India Company controlled almost all of India, had its own army larger than Britain\'s, collected taxes, and ran courts. A private colonial government.", tip: "🧠 East India Company: private company that ruled India, had a bigger army than Britain, collected taxes." },
  { id: 'h75', cat: 'history', emoji: '🏛️', subject: 'History — Rome', diff: 2, hook: "The Roman Empire at its peak covered 5 million square kilometres and 70 million people.", fact: "At its greatest extent under Emperor Trajan (~117 AD), the Roman Empire stretched from Britain to Mesopotamia. It encompassed ~5 million km2 and ~70 million people — about 25% of the world\'s population at the time.", tip: "🧠 Roman Empire at peak: 5 million km2, 70 million people, 25% of world population. ~117 AD." },
  { id: 'h76', cat: 'history', emoji: '🌍', subject: 'History — Population', diff: 2, hook: "The world population reached 1 billion for the first time around 1804.", fact: "For most of human history, global population was under 1 billion. It hit 1 billion around 1804, 2 billion by 1927, and has grown to 8 billion by 2023. The fastest growth was in the 20th century.", tip: "🧠 World population: hit 1 billion (~1804), 2 billion (1927), 8 billion (2023). Fastest growth: 20th century." },
  { id: 'h77', cat: 'history', emoji: '⚗️', subject: 'History — Printing', diff: 2, hook: "The printing press caused a media revolution more disruptive than the internet.", fact: "Gutenberg\'s printing press (~1440) made books affordable and widespread. It fuelled the Protestant Reformation, the Scientific Revolution, and mass literacy within 100 years. Information could no longer be controlled by elites alone.", tip: "🧠 Gutenberg press (~1440): fuelled Reformation, Science Revolution, mass literacy within 100 years." },
  { id: 'h78', cat: 'history', emoji: '🏛️', subject: 'History — Democracy', diff: 2, hook: "Ancient Athenian democracy was direct — citizens voted on every law themselves.", fact: "In ancient Athens (~500-322 BC), eligible citizens voted directly on legislation and court cases — no representatives. About 30,000-60,000 citizens were eligible, though women, slaves, and foreigners were excluded.", tip: "🧠 Athenian democracy: direct, not representative. Citizens voted on every law. Women and slaves excluded." },
  { id: 'geo56', cat: 'geo', emoji: '🌍', subject: 'Geography — Borders', diff: 2, hook: "Russia shares a land border with 14 countries — more than any other nation.", fact: "Russia borders: Norway, Finland, Estonia, Latvia, Lithuania (via Kaliningrad), Poland (via Kaliningrad), Belarus, Ukraine, Georgia, Azerbaijan, Kazakhstan, Mongolia, China, North Korea. Largest country, most neighbours.", tip: "🧠 Russia: borders 14 countries — more than any other nation. Largest country by area." },
  { id: 'geo57', cat: 'geo', emoji: '⛰️', subject: 'Geography — Records', diff: 1, hook: "South America contains both the world\'s driest and one of its wettest places.", fact: "The Atacama Desert in Chile is the driest non-polar place on Earth — some parts have never recorded rainfall. Yet the Amazon basin receives some of the world\'s highest annual rainfall. Same continent.", tip: "🧠 South America: Atacama (driest non-polar place) and Amazon basin (one of wettest). Same continent." },
  { id: 'geo58', cat: 'geo', emoji: '🌊', subject: 'Geography — Rivers', diff: 2, hook: "The Congo River is the deepest river in the world — over 220 metres in places.", fact: "The Congo River reaches depths of over 220 metres in some sections — making it far deeper than any other river. The Amazon has more volume; the Nile is longer; but the Congo is deepest.", tip: "🧠 Congo River: deepest in the world, over 220 metres in places. Amazon has more volume, Nile is longer." },
  { id: 'geo59', cat: 'geo', emoji: '🗺️', subject: 'Geography — Islands', diff: 2, hook: "Greenland is the world\'s largest island — but Australia is larger because it is a continent.", fact: "Greenland covers ~2.17 million km2 — the world\'s largest island. Australia covers ~7.7 million km2 but is classified as a continent, not an island, by convention.", tip: "🧠 Greenland: largest island (2.17M km2). Australia (7.7M km2) is larger but classed as a continent." },
  { id: 'geo60', cat: 'geo', emoji: '🌍', subject: 'Geography — Equator', diff: 2, hook: "The equator passes through 13 countries — but most people only know a few.", fact: "The equatorial countries: Ecuador, Colombia, Brazil, Sao Tome and Principe, Gabon, Republic of Congo, DR Congo, Uganda, Kenya, Somalia, Maldives, Indonesia, Kiribati. Not many people get all 13.", tip: "🧠 Equator passes through 13 countries. Ecuador is named for it. How many can you name?" },
  { id: 'geo61', cat: 'geo', emoji: '🌊', subject: 'Geography — Landlocked Seas', diff: 1, hook: "The Aral Sea was once the fourth largest lake in the world — now mostly desert.", fact: "Soviet irrigation projects diverted the rivers feeding the Aral Sea from the 1960s. By 2007 it had shrunk to 10% of its original size. Ship graveyards sit in what is now desert. One of the worst environmental disasters.", tip: "🧠 Aral Sea: once 4th largest lake, now mostly desert due to Soviet irrigation. Ship graveyards remain." },
  { id: 'geo62', cat: 'geo', emoji: '🗺️', subject: 'Geography — Time Zones', diff: 2, hook: "China spans 4 natural time zones but uses only one — Beijing Standard Time.", fact: "China\'s land mass would naturally span about 4 time zones. But since 1949, the entire country uses Beijing Standard Time (UTC+8). This means sunrise in western China can occur after 10am in winter.", tip: "🧠 China: 4 natural time zones but uses only 1. Sunrise in western China can be after 10am." },
  { id: 'geo63', cat: 'geo', emoji: '⛰️', subject: 'Geography — Volcanoes', diff: 2, hook: "Mauna Loa in Hawaii is the world\'s largest active volcano by volume.", fact: "Mauna Loa covers an area of ~5,200 km2 and its volume is ~74,000 km3 — the largest active volcano on Earth. It last erupted in 2022. Despite its size, it is a shield volcano — gradual slopes, not a steep cone.", tip: "🧠 Mauna Loa: largest active volcano by volume (~74,000 km3). Last erupted 2022." },
  { id: 'geo64', cat: 'geo', emoji: '🌍', subject: 'Geography — Demographics', diff: 2, hook: "More than half the world\'s population lives in Asia.", fact: "Asia is home to approximately 4.7 billion of Earth\'s 8 billion people — about 60%. China and India together account for ~2.8 billion, or about 35% of all humanity.", tip: "🧠 Asia: 4.7 billion people, 60% of humanity. China plus India alone = 35% of all humans." },
  { id: 'geo65', cat: 'geo', emoji: '🗺️', subject: 'Geography — Naming', diff: 2, hook: "The Americas are named after an Italian explorer who was not even the first to map them.", fact: "The Americas are named after Amerigo Vespucci, an Italian merchant who realised the lands Columbus found were a \'new world\'. The name appeared on a 1507 map by Martin Waldseemuller. Columbus never accepted it was a new continent.", tip: "🧠 Americas: named after Amerigo Vespucci, not Columbus. Vespucci recognised it was a new continent." },
  { id: 'b56', cat: 'body', emoji: '🧠', subject: 'Body — Sleep', diff: 2, hook: "You experience small \'microsleeps\' without knowing it when tired.", fact: "Microsleep: brief involuntary sleep episodes lasting 0.5-15 seconds. They happen when the brain is sleep-deprived, even in people who feel awake. Dangerous when driving. The brain essentially switches off for moments.", tip: "🧠 Microsleeps: 0.5-15 second blackouts while awake. Dangerous when driving. Brain switches off briefly." },
  { id: 'b57', cat: 'body', emoji: '🦠', subject: 'Body — Gut', diff: 2, hook: "Your gut has its own nervous system with as many neurons as a cat\'s brain.", fact: "The enteric nervous system in your gut contains ~500 million neurons — comparable to a cat\'s entire brain. It can operate independently of the central nervous system. The gut-brain axis connects them bidirectionally.", tip: "🧠 Gut nervous system: 500 million neurons — a cat brain\'s worth. Can operate independently." },
  { id: 'b58', cat: 'body', emoji: '💧', subject: 'Body — Water', diff: 1, hook: "Your body is about 60% water — but different parts vary enormously.", fact: "Average body: ~60% water. Brain and heart: ~73% water. Lungs: ~83% water. Bones: ~31% water. Blood: ~83% water. Even bones are about one-third water. Nothing in the body is truly dry.", tip: "🧠 Body: 60% water overall. Brain: 73%. Lungs: 83%. Bones: 31%. Nothing is truly dry." },
  { id: 'b59', cat: 'body', emoji: '🧬', subject: 'Body — DNA', diff: 2, hook: "If you unrolled all the DNA in one human body, it would stretch to Pluto and back — twice.", fact: "Each cell nucleus contains ~2 metres of DNA. With ~37 trillion cells, that is ~74 trillion metres total — about 8 billion km, or roughly twice the distance from Earth to Pluto.", tip: "🧠 DNA in one body: ~74 trillion metres — twice the Earth-to-Pluto distance." },
  { id: 'b60', cat: 'body', emoji: '🫀', subject: 'Body — Heartbeats', diff: 1, hook: "Your heart beats about 100,000 times every day.", fact: "At an average resting rate of ~70 beats per minute, the heart beats about 100,800 times per day, 37 million times per year, and about 3 billion times in a 75-year lifetime.", tip: "🧠 Heart: ~100,000 beats/day, 37M/year, 3 billion in a lifetime." },
  { id: 'b61', cat: 'body', emoji: '🧠', subject: 'Body — Multitasking', diff: 2, hook: "True multitasking is impossible for the human brain — it just switches tasks rapidly.", fact: "The brain cannot perform two cognitive tasks simultaneously. What feels like multitasking is rapid task-switching, which carries a cognitive cost. Each switch takes time to reload context. Multitaskers generally perform worse on both tasks.", tip: "🧠 Multitasking: not real. Brain switches rapidly, with a cognitive cost each time. Performance suffers." },
  { id: 'b62', cat: 'body', emoji: '🦴', subject: 'Body — Cartilage', diff: 1, hook: "Cartilage has no blood supply — which is why it heals so slowly when damaged.", fact: "Unlike bone, cartilage receives nutrients by diffusion from surrounding fluid rather than from blood vessels. Without a blood supply to deliver healing cells, cartilage damage (knee injuries etc.) heals very slowly or not at all.", tip: "🧠 Cartilage: no blood supply. Heals extremely slowly because healing cells cannot reach it directly." },
  { id: 'b63', cat: 'body', emoji: '💉', subject: 'Body — Platelets', diff: 2, hook: "Your blood platelets live only 7-10 days and are continuously replaced.", fact: "Platelets (thrombocytes) clot blood and live only 7-10 days before being recycled by the spleen. The bone marrow produces about 150-450 billion new platelets per day in a healthy adult.", tip: "🧠 Platelets: live 7-10 days. Bone marrow produces 150-450 billion new ones per day." },
  { id: 'b64', cat: 'body', emoji: '🧠', subject: 'Body — Pain', diff: 2, hook: "Your perception of pain is heavily influenced by expectation and context.", fact: "The same physical stimulus is felt as more or less painful depending on context. Medical procedure pain feels less intense when explained beforehand. Soldiers in battle often do not feel wounds until the action stops.", tip: "🧠 Pain perception: shaped by expectation and context. Knowing what\'s coming makes it hurt less." },
  { id: 'b65', cat: 'body', emoji: '🦷', subject: 'Body — Growth', diff: 2, hook: "Wisdom teeth are vestigial — our ancestors needed them but modern jaws are too small.", fact: "Wisdom teeth (third molars) helped ancient humans grind tough plant material. As our diet softened and jaws evolved smaller, these teeth often lack room to erupt properly — causing pain and impaction.", tip: "🧠 Wisdom teeth: vestigial relics. Jaws evolved smaller than ancestors\'. Often no room to erupt." },
  { id: 'g56', cat: 'grammar', emoji: '📝', subject: 'Grammar — Comma Splice', diff: 2, hook: "A comma splice is when you join two complete sentences with just a comma.", fact: "Wrong: \'I am tired, I should sleep.\' Correct: \'I am tired; I should sleep.\' Or: \'I am tired, so I should sleep.\' Or: \'I am tired. I should sleep.\' A comma is not strong enough to join two independent clauses alone.", tip: "🧠 Comma splice: two sentences joined by comma alone. Wrong. Use semicolon, conjunction, or full stop." },
  { id: 'g57', cat: 'grammar', emoji: '✍️', subject: 'Grammar — Colons', diff: 1, hook: "A colon introduces — it promises that what follows completes or expands the clause before it.", fact: "Colons introduce: a list (\'I need three things: bread, eggs, milk\'), a quotation, or an explanation. The clause before the colon must be independent. \'I need: bread\' is wrong because \'I need\' is incomplete.", tip: "🧠 Colon = introduces a completion or expansion. Clause before must be complete. \'I need: X\' is wrong." },
  { id: 'g58', cat: 'grammar', emoji: '💬', subject: 'Grammar — Semicolons', diff: 2, hook: "The semicolon is the most misunderstood punctuation mark — but has only two uses.", fact: "Semicolons: 1) join two closely related independent clauses (\'It was cold; we stayed inside\'). 2) separate list items that contain commas (\'We visited Paris, France; Rome, Italy; and London, England\'). No other uses.", tip: "🧠 Semicolon: join related clauses, or separate complex list items. Just two uses." },
  { id: 'g59', cat: 'grammar', emoji: '🔠', subject: 'Grammar — That vs Which', diff: 2, hook: "\'That\' introduces essential clauses; \'which\' introduces non-essential ones.", fact: "\'The car that broke down was mine.\' (essential — tells you which car). \'My car, which is blue, broke down.\' (non-essential — adds information but is parenthetical, set off by commas). American English is stricter on this than British.", tip: "🧠 \'That\' = essential (no comma). \'Which\' = non-essential (with commas). Which is parenthetical." },
  { id: 'g60', cat: 'grammar', emoji: '✒️', subject: 'Grammar — Fewer vs Less', diff: 1, hook: "\'Fewer\' is for countable things; \'less\' is for uncountable quantities.", fact: "Fewer: use when you can count individual items — fewer apples, fewer people. Less: use for quantities you cannot count individually — less water, less time, less noise. Supermarket \'10 items or less\' signs are technically incorrect.", tip: "🧠 Fewer = countable (fewer apples). Less = uncountable (less water). Supermarket signs are wrong." },
  { id: 'g61', cat: 'grammar', emoji: '📝', subject: 'Grammar — Dangling Modifiers', diff: 2, hook: "A dangling modifier describes the wrong thing because it is not placed next to what it modifies.", fact: "\'Running down the street, the house came into view.\' The house was not running. Fix: \'Running down the street, I saw the house.\' The modifier must directly precede the noun it describes.", tip: "🧠 Dangling modifier: modifier must be next to what it describes. \'Running, the house\' = wrong." },
  { id: 'g62', cat: 'grammar', emoji: '✍️', subject: 'Grammar — Affect vs Effect', diff: 1, hook: "\'Affect\' is usually the verb; \'effect\' is usually the noun.", fact: "\'The weather affects my mood.\' (verb). \'The weather has an effect on my mood.\' (noun). Memory trick: RAVEN — Remember, Affect is a Verb, Effect is a Noun. Exceptions exist but this rule covers 95% of cases.", tip: "🧠 Affect = verb (to affect). Effect = noun (an effect). RAVEN: Remember Affect Verb Effect Noun." },
  { id: 'g63', cat: 'grammar', emoji: '💬', subject: 'Grammar — Who vs Whom', diff: 2, hook: "\'Who\' is the subject; \'whom\' is the object — test by substituting \'he\' or \'him\'.", fact: "Test: replace \'who/whom\' with \'he\' or \'him\'. If \'he\' fits, use \'who\'. If \'him\' fits, use \'whom\'. \'Who called?\' = \'He called\' = who. \'To whom did you speak?\' = \'You spoke to him\' = whom.", tip: "🧠 Who vs whom: \'he\' = who, \'him\' = whom. \'Who called?\' (he called). \'To whom?\' (to him)." },
  { id: 'g64', cat: 'grammar', emoji: '🔠', subject: 'Grammar — Possessives with S', diff: 2, hook: "To form a possessive of a singular noun ending in S, add apostrophe-S.", fact: "\'James\'s car\' (not \'James\' car\'). \'The boss\'s office\'. Style guides vary slightly — Chicago recommends adding the extra S; AP Style allows omitting it for proper names. The apostrophe-S is more widely accepted and clearer.", tip: "🧠 Singular possessive ending in S: \'James\'s car\' — add apostrophe-S. Most style guides agree." },
  { id: 'g65', cat: 'grammar', emoji: '📖', subject: 'Grammar — Oxford Comma', diff: 2, hook: "The Oxford comma is the comma before \'and\' in a list — and it prevents ambiguity.", fact: "\'I love my parents, Beyonce and Jay-Z.\' (Are your parents Beyonce and Jay-Z?) Oxford comma version: \'I love my parents, Beyonce, and Jay-Z.\' The Oxford comma clarifies that four separate entities are listed.", tip: "🧠 Oxford comma: comma before final \'and\' in lists. Prevents \'I love my parents, Beyonce and Jay-Z\'." },
  { id: 'psy56', cat: 'psychology', emoji: '🧠', subject: 'Psychology — Priming', diff: 2, hook: "Exposing people to one concept influences how they react to related concepts moments later.", fact: "Priming: prior exposure to a stimulus influences responses to a subsequent related one. Shown the word \'bread\', you will recognise \'butter\' faster than \'doctor\'. This happens below the level of conscious awareness.", tip: "🧠 Priming: prior exposure to a word/concept speeds recognition of related concepts. Unconscious." },
  { id: 'psy57', cat: 'psychology', emoji: '😊', subject: 'Psychology — Hedonic Adaptation', diff: 2, hook: "Humans adapt to positive changes in life faster than they expect to — and happiness returns to baseline.", fact: "Hedonic adaptation: after positive events (raises, new homes, relationships), happiness rises then returns to a setpoint. Lottery winners return to near their pre-win happiness within a year. The same applies to negative events.", tip: "🧠 Hedonic adaptation: happiness returns to baseline after wins. Lottery winners: back to normal within a year." },
  { id: 'psy58', cat: 'psychology', emoji: '👥', subject: 'Psychology — Groupthink', diff: 2, hook: "Cohesive groups often make worse decisions than individuals because members suppress dissent.", fact: "Groupthink (Irving Janis, 1972): highly cohesive groups prioritise consensus over critical thinking, suppress doubts, and pressure dissenters. Classic examples: Bay of Pigs invasion, Challenger launch decision.", tip: "🧠 Groupthink: cohesion kills critical thinking. Dissent is suppressed. Challenger and Bay of Pigs resulted." },
  { id: 'psy59', cat: 'psychology', emoji: '🎯', subject: 'Psychology — Implementation Intentions', diff: 1, hook: "Specifying when and where you will do something dramatically increases follow-through.", fact: "Implementation intentions: \'I will do X at time Y in location Z\' significantly outperform general intentions. Studies show 2-3x higher rates of goal completion when people plan the specific when and where in advance.", tip: "🧠 Implementation intentions: \'I will do X at time Y in place Z\'. 2-3x better follow-through than vague goals." },
  { id: 'psy60', cat: 'psychology', emoji: '💭', subject: 'Psychology — Cognitive Dissonance', diff: 2, hook: "People change their beliefs to match their behaviour — not just the other way around.", fact: "Cognitive dissonance (Festinger, 1957): holding contradictory beliefs or doing things that conflict with beliefs causes discomfort. The easier path is often to change the belief to match the behaviour. Action shapes belief.", tip: "🧠 Cognitive dissonance: contradictory beliefs cause discomfort. Easiest fix = change the belief, not the behaviour." },
  { id: 'psy61', cat: 'psychology', emoji: '🧠', subject: 'Psychology — Labelling', diff: 1, hook: "Labelling an emotion makes it less intense — naming feelings reduces their power.", fact: "Studies by Lieberman et al.: putting feelings into words (\'I feel afraid\') reduces amygdala activity and subjective intensity of the emotion. This is the neuroscientific basis for talk therapy and journalling.", tip: "🧠 Labelling emotions: reduces their intensity. \'I feel afraid\' reduces amygdala activation." },
  { id: 'psy62', cat: 'psychology', emoji: '😊', subject: 'Psychology — Self-perception', diff: 2, hook: "You can change how you feel by changing how you behave — the self-perception theory.", fact: "Bem\'s self-perception theory: people infer their own attitudes and feelings by observing their own behaviour, just as they would observe others. Act confident and you begin to feel confident.", tip: "🧠 Self-perception theory: behaviour shapes beliefs. Act confident → feel confident. Action precedes feeling." },
  { id: 'psy63', cat: 'psychology', emoji: '👀', subject: 'Psychology — Eye Contact', diff: 1, hook: "The optimal duration of eye contact for creating connection is 3-5 seconds.", fact: "Research suggests 3.3 seconds is the average comfortable eye contact duration. Shorter feels evasive; longer becomes threatening. The sweet spot for building trust and connection is around 3-5 seconds.", tip: "🧠 Eye contact sweet spot: 3-5 seconds for connection. Shorter = evasive. Longer = threatening." },
  { id: 'psy64', cat: 'psychology', emoji: '💭', subject: 'Psychology — Negativity Bias', diff: 2, hook: "Bad experiences have roughly twice the psychological impact of equally good ones.", fact: "Negativity bias: negative events (losses, insults, failures) have approximately twice the psychological weight of equivalent positive events (gains, compliments, successes). This is why one criticism can outweigh ten compliments.", tip: "🧠 Negativity bias: bad experiences ~2x the impact of equal good ones. One criticism outweighs ten compliments." },
  { id: 'psy65', cat: 'psychology', emoji: '🌊', subject: 'Psychology — Mindfulness', diff: 2, hook: "Mindfulness meditation physically changes brain structure in 8 weeks.", fact: "Studies (Sara Lazar, Harvard): 8 weeks of mindfulness meditation produces measurable increases in grey matter density in the hippocampus (memory, learning) and decreases in the amygdala (stress). No prior experience needed.", tip: "🧠 8 weeks of mindfulness: measurable brain changes. Hippocampus grows, amygdala shrinks." },
  { id: 'eco56', cat: 'economics', emoji: '💰', subject: 'Economics — Creative Destruction', diff: 2, hook: "Economic progress requires constantly destroying existing industries to build new ones.", fact: "Creative destruction (Schumpeter, 1942): capitalism advances by continuously replacing old technologies, companies, and industries with new ones. The horse-and-buggy industry was destroyed by cars. Typewriters by computers. This is progress.", tip: "🧠 Creative destruction (Schumpeter): old industries must die for new ones to emerge. That is progress." },
  { id: 'eco57', cat: 'economics', emoji: '📈', subject: 'Economics — Network Effects', diff: 2, hook: "Some products become more valuable as more people use them.", fact: "Network effects: a product or service increases in value with each additional user. Classic examples: telephone, social media, payment networks. Why WhatsApp displaced SMS — the more contacts on it, the more valuable it became.", tip: "🧠 Network effects: product value grows with each new user. Why social networks become winner-take-all." },
  { id: 'eco58', cat: 'economics', emoji: '🏦', subject: 'Economics — Moral Hazard', diff: 2, hook: "When people are protected from risk, they take more risk than they otherwise would.", fact: "Moral hazard: when someone is insulated from the consequences of their actions (by insurance, bailouts, or guarantees), they tend to take greater risks. Banks that know they are \'too big to fail\' take more risks.", tip: "🧠 Moral hazard: protection from consequences = more risk taken. Why bank bailouts create future problems." },
  { id: 'eco59', cat: 'economics', emoji: '📊', subject: 'Economics — Externalities', diff: 2, hook: "Market prices do not capture the full cost of many activities — creating externalities.", fact: "Externalities: costs or benefits not reflected in market prices. Negative externality: factory pollution — the cost falls on society, not the factory. Positive externality: vaccinations — your immunity protects others. Markets underprovide positive externalities.", tip: "🧠 Externalities: costs/benefits not in market prices. Pollution = negative. Vaccines = positive." },
  { id: 'eco60', cat: 'economics', emoji: '💸', subject: 'Economics — Universal Basic Income', diff: 2, hook: "UBI has been tested in dozens of countries — results are more positive than critics predicted.", fact: "UBI experiments in Finland, Kenya, Canada, and the US show: recipients do not stop working, mental health improves, and entrepreneurship increases. The main debate is now about affordability, not behavioural effects.", tip: "🧠 UBI trials: recipients work almost as much, mental health improves, entrepreneurship rises." },
  { id: 'eco61', cat: 'economics', emoji: '💰', subject: 'Economics — Time Value', diff: 1, hook: "Money today is worth more than the same money in the future.", fact: "Time value of money: a pound today can be invested and grow; a pound in the future cannot be used now. This is why all financial calculations (mortgages, pensions, valuations) discount future cash flows to present value.", tip: "🧠 Time value of money: £1 now > £1 later. It can grow. Future money is discounted." },
  { id: 'eco62', cat: 'economics', emoji: '📈', subject: 'Economics — Diminishing Returns', diff: 1, hook: "Each additional unit of input produces less additional output — diminishing marginal returns.", fact: "Adding a 3rd employee to a 2-person team adds a lot. Adding a 100th to a 99-person team adds much less. This diminishing returns principle applies to: fertiliser on crops, studying for an exam, investing in advertising.", tip: "🧠 Diminishing marginal returns: each extra unit adds less than the last. The 100th worker adds little." },
  { id: 'eco63', cat: 'economics', emoji: '🌐', subject: 'Economics — Trade Agreements', diff: 2, hook: "Most international trade operates under thousands of bilateral agreements — not free trade.", fact: "\'Free trade\' is a spectrum. Bilateral Free Trade Agreements (FTAs) between two countries are the most common. The WTO provides a multilateral framework. Most trade involves tariffs, quotas, and non-tariff barriers — just lower ones.", tip: "🧠 Most trade: bilateral agreements with reduced but not zero tariffs. \'Free trade\' is a spectrum." },
  { id: 'eco64', cat: 'economics', emoji: '💸', subject: 'Economics — Money Supply', diff: 2, hook: "Central banks can create money by buying assets — called quantitative easing.", fact: "Quantitative easing (QE): central banks create new money and use it to buy government bonds or other assets from banks. This injects liquidity into the economy. Used after the 2008 financial crisis and COVID pandemic.", tip: "🧠 Quantitative easing: central banks create money to buy assets. Used after 2008 crisis and COVID." },
  { id: 'eco65', cat: 'economics', emoji: '💰', subject: 'Economics — Gig Economy', diff: 2, hook: "Gig economy workers often earn less than minimum wage when all costs are included.", fact: "Studies of Uber, Lyft, and Deliveroo workers accounting for vehicle depreciation, fuel, maintenance, and downtime find effective hourly earnings often below minimum wage in many markets. The apparent flexibility comes at a hidden cost.", tip: "🧠 Gig economy: after costs (vehicle, fuel, depreciation), hourly earnings often below minimum wage." },
  { id: 'inv56', cat: 'inventions', emoji: '💡', subject: 'Inventions — Refrigeration', diff: 2, hook: "Refrigeration transformed human diet, agriculture, and global trade.", fact: "Mechanical refrigeration was developed in the 1850s-1870s. Before it, food preservation relied on salt, smoke, fermentation, and ice. Refrigerated shipping (1880s) allowed meat and produce to travel globally, transforming food supply chains.", tip: "🧠 Mechanical refrigeration: developed 1850s-1870s. Refrigerated ships (1880s) transformed global food trade." },
  { id: 'inv57', cat: 'inventions', emoji: '🌐', subject: 'Inventions — Radio', diff: 2, hook: "Radio was independently invented by multiple people and sparked one of history\'s longest patent disputes.", fact: "Guglielmo Marconi is credited with first practical radio transmission (1895). Nikola Tesla had filed related patents earlier. In 1943, the US Supreme Court ruled Tesla\'s patents were prior — just months after his death.", tip: "🧠 Radio: Marconi credited (1895). Tesla\'s patents ruled prior by US Supreme Court — months after Tesla died." },
  { id: 'inv58', cat: 'inventions', emoji: '🚗', subject: 'Inventions — Automobile', diff: 2, hook: "The first practical automobile was powered by petrol — invented in 1885 by Karl Benz.", fact: "Karl Benz is credited with the first true petrol-powered automobile — the Benz Patent-Motorwagen (1885). His wife Bertha Benz made the first long-distance drive in 1888, covering 106 km and demonstrating the car\'s practicality.", tip: "🧠 First car: Karl Benz, 1885. First long-distance drive: his wife Bertha, 1888, 106 km." },
  { id: 'inv59', cat: 'inventions', emoji: '✈️', subject: 'Inventions — Parachute', diff: 2, hook: "The parachute was invented over 100 years before the first aeroplane.", fact: "Andre-Jacques Garnerin made the first parachute jump from a balloon in 1797 — more than a century before the Wright Brothers flew at Kitty Hawk in 1903. Early parachutes were made of silk and had no vents, causing violent oscillation.", tip: "🧠 Parachute: first jump in 1797 — over 100 years before the first aeroplane in 1903." },
  { id: 'inv60', cat: 'inventions', emoji: '🔬', subject: 'Inventions — Vaccination', diff: 2, hook: "The first vaccine was created in 1796 — against smallpox — by Edward Jenner.", fact: "Edward Jenner noticed milkmaids who caught cowpox did not get smallpox. In 1796 he inoculated a boy with cowpox, then exposed him to smallpox. The boy did not get ill. Vaccination was born. Smallpox was eradicated by 1980.", tip: "🧠 First vaccine: Jenner, 1796, cowpox prevents smallpox. Smallpox eradicated 1980 — vaccine\'s greatest triumph." },
  { id: 'inv61', cat: 'inventions', emoji: '💡', subject: 'Inventions — Incandescent Bulb', diff: 2, hook: "Edison did not invent the light bulb — he made it commercially practical.", fact: "Over 20 people developed electric lights before Edison. Edison\'s 1879 breakthrough was finding a practical filament (carbonised bamboo) that could burn for ~1,200 hours. He also built the power distribution infrastructure to make it useful.", tip: "🧠 Edison did not invent the light bulb. He made it last (1,200 hours) and built the power grid for it." },
  { id: 'inv62', cat: 'inventions', emoji: '🌐', subject: 'Inventions — Satellite', diff: 2, hook: "The first satellite was launched by the Soviet Union — and shocked the world.", fact: "Sputnik 1 was launched on 4 October 1957 by the USSR. It was a 58cm sphere that beeped a radio signal. It triggered the Space Race. Americans could hear the beep on civilian radios. The shock was enormous.", tip: "🧠 Sputnik: launched 4 October 1957. 58cm sphere, radio beep. Triggered the Space Race." },
  { id: 'inv63', cat: 'inventions', emoji: '⚙️', subject: 'Inventions — Compass', diff: 2, hook: "The magnetic compass was invented in China around 200 BC — but used for navigation only later.", fact: "The Chinese originally used lodestone compasses for divination and feng shui — not navigation. Maritime navigation use began around the 11th century AD in China and spread to Europe by the 12th century via Islamic traders.", tip: "🧠 Compass: Chinese invention ~200 BC, originally for feng shui. Navigation use: 11th century." },
  { id: 'inv64', cat: 'inventions', emoji: '🔬', subject: 'Inventions — DNA Structure', diff: 2, hook: "The double helix structure of DNA was discovered using X-ray data taken without full consent.", fact: "Watson and Crick\'s 1953 discovery of DNA\'s double helix structure was critically informed by Rosalind Franklin\'s X-ray crystallography image (Photo 51). They accessed it without her direct consent. She died before the Nobel Prize was awarded.", tip: "🧠 DNA double helix: Watson and Crick (1953) used Rosalind Franklin\'s X-ray image without her full knowledge." },
  { id: 'inv65', cat: 'inventions', emoji: '💡', subject: 'Inventions — Antibiotics', diff: 2, hook: "Penicillin\'s full development into a medicine took 12 years after Fleming\'s accidental discovery.", fact: "Fleming discovered penicillin in 1928 but could not purify it for medical use. Howard Florey and Ernst Chain developed a practical form in 1940-41. The first human patient was treated in 1941. Nobel Prize: 1945 to all three.", tip: "🧠 Penicillin: discovered 1928, first human treatment 1941. 12-year gap. Nobel Prize 1945." },
  { id: 'food56', cat: 'food', emoji: '🌾', subject: 'Food Science — Bread', diff: 2, hook: "Bread has been made for at least 14,000 years — predating agriculture.", fact: "Evidence of bread-making was found at Shubayqa 1 in Jordan, dating to ~14,400 years ago — more than 4,000 years before the agricultural revolution. Hunter-gatherers were already grinding grain and baking flatbreads.", tip: "🧠 Bread: made for 14,400 years — 4,000 years before farming even began. Hunter-gatherers baked." },
  { id: 'food57', cat: 'food', emoji: '🍶', subject: 'Food Science — Vinegar', diff: 2, hook: "Vinegar is one of the oldest manufactured substances in the world — over 10,000 years old.", fact: "Vinegar (acetic acid) forms naturally when alcohol is exposed to oxygen and acetobacter bacteria. Evidence of vinegar production dates to ~10,000 BC in ancient Babylon. It was used as medicine, food preservation, and cleaning agent.", tip: "🧠 Vinegar: ~10,000 years old. Used in Babylon as medicine, food preservation, and cleaner." },
  { id: 'food58', cat: 'food', emoji: '🧁', subject: 'Food Science — Baking', diff: 2, hook: "Baking soda and baking powder are not the same — and cannot always be substituted.", fact: "Baking soda (sodium bicarbonate) needs an acid to activate. Baking powder contains baking soda plus a dry acid. Substituting one for the other without adjusting the recipe will cause flat or overly risen results.", tip: "🧠 Baking soda needs acid to activate. Baking powder contains its own acid. Not interchangeable without adjusting." },
  { id: 'food59', cat: 'food', emoji: '🍷', subject: 'Food Science — Terroir', diff: 2, hook: "The taste of wine is influenced by the soil, climate, and topography where grapes were grown.", fact: "Terroir (French for \'land\'): the combination of soil composition, microclimate, aspect, and drainage that gives wine from a specific region its unique character. The same grape variety grown in different locations tastes measurably different.", tip: "🧠 Terroir: soil, climate, topography all change the taste of wine from the same grape variety." },
  { id: 'food60', cat: 'food', emoji: '🥑', subject: 'Food Science — Avocado', diff: 1, hook: "Avocados evolved their large seeds to be eaten by giant ground sloths — now extinct.", fact: "Avocados have seeds far too large to be spread by any modern animal. Evolutionary evidence suggests they co-evolved with megafauna like giant ground sloths (~10,000 years ago) that could swallow them whole. Those animals are extinct.", tip: "🧠 Avocados: seeds evolved to be spread by giant ground sloths. The animal went extinct. Seeds remain." },
  { id: 'food61', cat: 'food', emoji: '🍵', subject: 'Food Science — Green Tea', diff: 2, hook: "Green and black tea come from the same plant — processing determines the type.", fact: "All true tea comes from Camellia sinensis. Green tea: leaves are heated quickly after picking to stop oxidation. Black tea: leaves are fully oxidised. Oolong: partial oxidation. White tea: minimal processing of young leaves.", tip: "🧠 Green, black, oolong, white tea: same plant, different processing. Oxidation is the key variable." },
  { id: 'food62', cat: 'food', emoji: '🍕', subject: 'Food Science — Cheese Ageing', diff: 2, hook: "Aged cheeses are lower in lactose than fresh cheeses — making them more tolerable.", fact: "During ageing, bacteria and enzymes break down lactose into lactic acid. Aged hard cheeses (parmesan, cheddar, gouda) contain very little residual lactose. Most lactose-intolerant people can tolerate them.", tip: "🧠 Aged hard cheeses: very low lactose due to fermentation. Often tolerable for lactose-intolerant people." },
  { id: 'food63', cat: 'food', emoji: '🧂', subject: 'Food Science — Cooking', diff: 2, hook: "The single most important thing you can do to improve cooking is to salt pasta water generously.", fact: "Pasta water should be \'as salty as the sea\' — about 1 tablespoon of salt per litre. Salt seasons pasta from the inside as it absorbs water, not from sauce applied later. Under-salted pasta cannot be fixed at the table.", tip: "🧠 Pasta water: 1 tablespoon of salt per litre. Salt seasons from the inside. Cannot be fixed later." },
  { id: 'food64', cat: 'food', emoji: '🍫', subject: 'Food Science — Cacao', diff: 2, hook: "White chocolate is not actually chocolate — it contains no cocoa solids.", fact: "True chocolate requires cocoa solids (from cacao beans). White chocolate contains only cocoa butter (the fat fraction), sugar, and milk — no cocoa solids. The FDA does not classify it as chocolate in the traditional sense.", tip: "🧠 White chocolate: contains no cocoa solids. Just cocoa butter, sugar, milk. Not technically chocolate." },
  { id: 'food65', cat: 'food', emoji: '🌿', subject: 'Food Science — Herbs', diff: 2, hook: "Dried herbs are more concentrated than fresh but are not equivalent in every recipe.", fact: "Dried herbs are 3-4 times more concentrated than fresh because water is removed. General rule: 1 tsp dried = 1 tablespoon fresh. However, delicate fresh herbs (basil, parsley, coriander) lose flavour compounds when dried and should be added fresh at the end of cooking.", tip: "🧠 Dried herbs: 3-4x more concentrated. 1 tsp dried = 1 tbsp fresh. Delicate herbs should stay fresh." },
  { id: 'm56', cat: 'math', emoji: '🔢', subject: 'Maths — Golden Ratio', diff: 2, hook: "The golden ratio (phi ~1.618) appears in nature, art, and architecture — but its ubiquity is often exaggerated.", fact: "Phi = (1+sqrt(5))/2 ~1.618. Found in: nautilus shells, sunflower seed spirals, Fibonacci sequences. Claimed (often falsely) to appear in the Parthenon, human faces, and Da Vinci. The real occurrences are fascinating; the myths should be discarded.", tip: "🧠 Golden ratio (~1.618): real in Fibonacci sequences and some plant growth. Many claimed appearances are myths." },
  { id: 'm57', cat: 'math', emoji: '🎲', subject: 'Maths — Birthday Problem', diff: 2, hook: "In a group of just 23 people, there is a 50% chance two share a birthday.", fact: "The birthday problem: the probability that at least two people in a group share a birthday reaches 50% with just 23 people and 99.9% with 70 people. Our intuition about probability is badly miscalibrated.", tip: "🧠 Birthday paradox: 23 people = 50% chance of shared birthday. 70 people = 99.9%. Intuition is wrong." },
  { id: 'm58', cat: 'math', emoji: '📐', subject: 'Maths — Pythagoras', diff: 1, hook: "The Pythagorean theorem was known over 1,000 years before Pythagoras.", fact: "Babylonian clay tablets from ~1800 BC show Pythagorean triples (sets of numbers satisfying a2+b2=c2). The Egyptians and Indians used the theorem. Pythagoras (~570 BC) is credited with the first formal proof, not the discovery.", tip: "🧠 Pythagorean theorem: known ~1800 BC in Babylon. Pythagoras (570 BC) gave the first proof." },
  { id: 'm59', cat: 'math', emoji: '🌀', subject: 'Maths — Chaos Theory', diff: 3, hook: "Tiny differences in initial conditions lead to vastly different outcomes — the butterfly effect.", fact: "Chaos theory (Edward Lorenz, 1963): in complex systems, tiny variations in starting conditions lead to dramatically different outcomes. The classic example: a butterfly flapping its wings in Brazil could theoretically affect a tornado in Texas.", tip: "🧠 Butterfly effect: tiny initial differences, massive outcome divergence. Weather prediction is fundamentally limited." },
  { id: 'm60', cat: 'math', emoji: '🔢', subject: 'Maths — Perfect Numbers', diff: 3, hook: "A perfect number equals the sum of all its divisors — only 51 are known.", fact: "A perfect number: the sum of all its proper divisors equals itself. 6 = 1+2+3. 28 = 1+2+4+7+14. 496, 8128 are next. Only 51 are known as of 2024, all even. Whether any odd perfect number exists is an unsolved problem.", tip: "🧠 Perfect numbers: 6, 28, 496... Only 51 known. All even. Odd perfect numbers: unknown if they exist." },
  { id: 'm61', cat: 'math', emoji: '📊', subject: 'Maths — Regression to the Mean', diff: 2, hook: "Extreme results tend to be followed by more average results — and we misattribute the cause.", fact: "Regression to the mean: after an exceptional result (good or bad), subsequent results tend toward the average. A student who aces one test will likely score closer to their average next time — not because of anything they did.", tip: "🧠 Regression to mean: exceptional results tend toward average next time. We falsely credit causes." },
  { id: 'm62', cat: 'math', emoji: '🎯', subject: 'Maths — Prisoners Dilemma', diff: 3, hook: "Two rational actors can end up worse off by each pursuing their own best interest.", fact: "The Prisoner\'s Dilemma: two players each choose to cooperate or defect. Both cooperating = best collective outcome. Both defecting = mutual punishment. Rational self-interest leads both to defect, producing the worst collective result.", tip: "🧠 Prisoner\'s Dilemma: self-interest leads to mutual defection. Cooperation is better but fragile." },
  { id: 'm63', cat: 'math', emoji: '🔢', subject: 'Maths — Zero', diff: 2, hook: "Zero was one of humanity\'s greatest mathematical inventions — and many cultures resisted it.", fact: "Zero as a number was developed in India by Brahmagupta in the 7th century AD. The concept of zero reached Europe via Arabic mathematicians in the 12th century. Many ancient cultures including the Greeks resisted a \'number\' that meant nothing.", tip: "🧠 Zero: invented in India (7th century). Reached Europe via Arabic mathematicians (12th century). Greeks resisted it." },
  { id: 'm64', cat: 'math', emoji: '📐', subject: 'Maths — Non-Euclidean Geometry', diff: 3, hook: "The angles of a triangle can add up to more or less than 180° — depending on the surface.", fact: "Euclidean geometry (flat surface): angles of triangle = 180°. Spherical geometry (positive curvature): angles > 180°. Hyperbolic geometry (negative curvature): angles < 180°. Einstein\'s general relativity uses non-Euclidean geometry.", tip: "🧠 Triangle angles: 180° on flat surface, more on a sphere, less on hyperbolic surface. Einstein used this." },
  { id: 'm65', cat: 'math', emoji: '🎲', subject: 'Maths — Monte Carlo Method', diff: 2, hook: "Complex mathematical problems can be solved by running millions of random simulations.", fact: "Monte Carlo methods: estimate results by running many random simulations. Named after Monaco\'s casino. Used to model financial risk, particle physics, climate, and AI training. If you throw enough random darts at a board, you can estimate pi.", tip: "🧠 Monte Carlo: random simulations solve complex problems. Enough random darts can estimate pi." },

  { id: 'h79', cat: 'history', emoji: '📜', subject: 'History — WWI', diff: 1, hook: "The assassination that triggered WWI happened because the assassin stopped for a sandwich.", fact: "After a failed bomb attack on Archduke Franz Ferdinand, Gavrilo Princip stopped at Schiller\'s Deli in Sarajevo. The Archduke\'s car then took a wrong turn and stalled right in front of him. Princip shot Franz Ferdinand and his wife at point-blank range, triggering WWI.", tip: "🧠 WWI trigger: Princip failed, stopped for food, the Archduke\'s car stalled right in front of him." },
  { id: 'h80', cat: 'history', emoji: '🏛️', subject: 'History — Ancient', diff: 2, hook: "Ancient Romans used urine as mouthwash and laundry detergent.", fact: "The ammonia in urine was used by Romans to whiten teeth and clean clothes. Urine was so valuable that Emperor Vespasian taxed public urinals. The phrase \'money has no smell\' (pecunia non olet) originates from his defence of this tax.", tip: "🧠 Romans: used urine as mouthwash and detergent. Vespasian taxed urinals. \'Money has no smell.\'" },
  { id: 'h81', cat: 'history', emoji: '⚔️', subject: 'History — Medieval', diff: 2, hook: "Medieval knights were not noble heroes — most were professional soldiers paid to fight.", fact: "The romantic image of knights as honourable warriors is largely myth. Most knights were mercenaries loyal to whoever paid them. Knightly codes like chivalry were ideals, not reality. Looting, pillaging, and ransoming prisoners were standard practice.", tip: "🧠 Medieval knights: mostly paid mercenaries. Chivalry was an ideal, not their actual behaviour." },
  { id: 'h82', cat: 'history', emoji: '🌍', subject: 'History — Exploration', diff: 1, hook: "Christopher Columbus died believing he had reached Asia — not a new continent.", fact: "Columbus made four voyages to the Americas (1492-1504) but was convinced he had reached the Indies in Asia. He died in 1506 still believing this. Amerigo Vespucci recognised it as a previously unknown continent — which is why it bears his name.", tip: "🧠 Columbus: died believing he reached Asia. Vespucci recognised the new continent. Americas = Vespucci." },
  { id: 'h83', cat: 'history', emoji: '🏰', subject: 'History — Castles', diff: 2, hook: "The Tower of London has housed a royal menagerie including polar bears and elephants.", fact: "The Tower of London kept exotic animals from the 1200s to 1835 — gifts to monarchs from foreign rulers. Residents included: a polar bear (which fished in the Thames), lions, an elephant, leopards, and a grizzly bear.", tip: "🧠 Tower of London had a zoo: polar bear fishing in the Thames, lions, elephants. Ran 600 years." },
  { id: 'h84', cat: 'history', emoji: '🚢', subject: 'History — Naval', diff: 2, hook: "The Mary Rose sank in 1545 in full view of King Henry VIII — and was raised in 1982.", fact: "Henry VIII\'s flagship Mary Rose capsized and sank during a battle with the French fleet in 1545, killing ~400-500 men. The king reportedly witnessed it from shore. The wreck was raised in 1982 and is now on display in Portsmouth.", tip: "🧠 Mary Rose: sank before Henry VIII\'s eyes in 1545. Raised in 1982. 437 years underwater." },
  { id: 'h85', cat: 'history', emoji: '📜', subject: 'History — Printing', diff: 2, hook: "Gutenberg\'s printing press caused the first information revolution in 1440.", fact: "Johannes Gutenberg invented movable type printing in Europe around 1440. Within 50 years there were 1,000 print shops across Europe producing ~10 million books. The Reformation, Scientific Revolution, and rise of literacy all followed directly from cheap printed information.", tip: "🧠 Gutenberg ~1440: within 50 years, 10 million books printed. Triggered Reformation and Scientific Revolution." },
  { id: 'h86', cat: 'history', emoji: '🌍', subject: 'History — Cold War', diff: 2, hook: "The Cuban Missile Crisis was closer to nuclear war than anyone publicly admitted for decades.", fact: "In October 1962, a Soviet submarine nearly launched a nuclear torpedo at US ships — prevented only by officer Vasili Arkhipov refusing to authorise it. A US U-2 spy plane also strayed into Soviet airspace during the crisis. Multiple near-accidents occurred.", tip: "🧠 Cuban Missile Crisis: Soviet sub nearly fired nuclear torpedo. One officer (Arkhipov) prevented it." },
  { id: 'h87', cat: 'history', emoji: '🏛️', subject: 'History — Democracy', diff: 2, hook: "Ancient Athens only allowed about 10-20% of its population to vote.", fact: "Athenian democracy (5th century BC) excluded women, slaves, and non-citizens — who together made up ~80-90% of the population. Only adult male citizens could vote and hold office. It was radical for its time but far from universal.", tip: "🧠 Athenian democracy: 80-90% excluded. Women, slaves, foreigners couldn\'t vote. Still revolutionary for 500 BC." },
  { id: 'h88', cat: 'history', emoji: '⚔️', subject: 'History — WWII', diff: 1, hook: "D-Day (6 June 1944) involved the largest seaborne invasion in history.", fact: "Operation Overlord: 156,000 Allied troops crossed the English Channel, supported by 6,000 ships and 11,000 aircraft. In the first 24 hours, ~10,000 Allied casualties. It was the turning point of WWII in Western Europe.", tip: "🧠 D-Day: 156,000 troops, 6,000 ships, 11,000 aircraft. Largest seaborne invasion ever. 6 June 1944." },
  { id: 'h89', cat: 'history', emoji: '🌍', subject: 'History — Independence', diff: 1, hook: "India\'s independence in 1947 was achieved largely through non-violent protest.", fact: "Gandhi\'s strategy of non-violent civil disobedience (satyagraha) made violent suppression politically costly for Britain. Key campaigns: Salt March (1930), Quit India (1942). Britain agreed to independence after WWII weakened its imperial capacity.", tip: "🧠 Indian independence: Gandhi\'s non-violence made suppression too costly. Salt March 1930 key turning point." },
  { id: 'h90', cat: 'history', emoji: '📜', subject: 'History — Maps', diff: 2, hook: "The first accurate world map was made by a Muslim geographer in 1154.", fact: "Al-Idrisi created the Tabula Rogeriana for King Roger II of Sicily in 1154 — the most accurate world map for 300 years. It was drawn with south at the top. It covered Europe, Asia, and North Africa in remarkable detail.", tip: "🧠 Most accurate world map for 300 years: Al-Idrisi, 1154, for the King of Sicily. South at the top." },
  { id: 'geo56', cat: 'geo', emoji: '🌍', subject: 'Geography — Records', diff: 1, hook: "Russia is so wide it spans 11 time zones.", fact: "Russia stretches ~9,000 km from west to east, covering 11 time zones — more than any other country. When it is noon in Moscow, it is already 11pm in Kamchatka on the Pacific coast.", tip: "🧠 Russia: 11 time zones. Noon in Moscow = 11pm on the Pacific coast." },
  { id: 'geo57', cat: 'geo', emoji: '🗺️', subject: 'Geography — Borders', diff: 2, hook: "Canada and the USA share the world\'s longest land border.", fact: "The Canada-USA border stretches 8,891 km (5,525 miles) — the longest international land border in the world. It includes the 49th parallel, which runs straight for 2,000 km across the prairies.", tip: "🧠 Canada-USA border: 8,891 km — world\'s longest land border. The 49th parallel is perfectly straight." },
  { id: 'geo58', cat: 'geo', emoji: '⛰️', subject: 'Geography — Altitude', diff: 2, hook: "La Paz in Bolivia is the world\'s highest capital city — at 3,640 metres above sea level.", fact: "La Paz is the administrative capital of Bolivia at 3,640m altitude. Newcomers often experience altitude sickness. The city has the world\'s highest urban cable car system. Nearby Potosi (once the world\'s largest city) sits even higher at 4,090m.", tip: "🧠 La Paz: world\'s highest capital city at 3,640m. Altitude sickness is common for new arrivals." },
  { id: 'geo59', cat: 'geo', emoji: '🌊', subject: 'Geography — Rivers', diff: 1, hook: "The Amazon River contains 20% of all the freshwater that flows into the world\'s oceans.", fact: "The Amazon discharges ~209,000 cubic metres per second — about 20% of all freshwater entering Earth\'s oceans. During flood season, the river widens to over 50 km in places.", tip: "🧠 Amazon River: 20% of all freshwater entering Earth\'s oceans. Widens to 50km in flood season." },
  { id: 'geo60', cat: 'geo', emoji: '🌡️', subject: 'Geography — Extremes', diff: 2, hook: "The driest place on Earth is not the Sahara — it is the Atacama Desert in Chile.", fact: "Parts of the Atacama receive less than 1mm of rain per year. Some weather stations have never recorded rainfall. Despite this, the Atacama is used to test Mars rovers — its conditions are the closest on Earth to the Martian surface.", tip: "🧠 Driest place: Atacama Desert, Chile. Some areas: never recorded rain. Used to test Mars rovers." },
  { id: 'geo61', cat: 'geo', emoji: '🏝️', subject: 'Geography — Oceans', diff: 2, hook: "The Mariana Trench is deep enough to submerge Mount Everest with 2 km to spare.", fact: "Challenger Deep in the Mariana Trench: ~10,994m deep. Mount Everest: 8,849m tall. If placed in the trench, Everest\'s peak would still be 2,145m below the surface. Pressure at the bottom: ~11,000 tonnes per square metre.", tip: "🧠 Mariana Trench: Everest fits inside with 2km to spare. Pressure at bottom: 11,000 tonnes per m²." },
  { id: 'geo62', cat: 'geo', emoji: '🌍', subject: 'Geography — Population', diff: 2, hook: "More people live in Tokyo than in all of Australia.", fact: "Tokyo metropolitan area population: ~37 million. Australia: ~26 million. The Greater Tokyo Area is the world\'s most populous urban agglomeration — more people than most countries.", tip: "🧠 Tokyo metro: 37 million people. Australia: 26 million. One city has more people than the whole continent." },
  { id: 'geo63', cat: 'geo', emoji: '🗺️', subject: 'Geography — Countries', diff: 2, hook: "Vatican City is the smallest country in the world — and the only one with a Latin ATM.", fact: "Vatican City: 0.44 km², ~800 residents — the world\'s smallest country by both area and population. It is the only country in the world where Latin is an official language used on ATM machines.", tip: "🧠 Vatican City: 0.44 km², ~800 people. Only country with Latin ATM machines." },
  { id: 'geo64', cat: 'geo', emoji: '🌋', subject: 'Geography — Volcanoes', diff: 2, hook: "Iceland gets most of its electricity and heating from geothermal energy.", fact: "Iceland sits on the Mid-Atlantic Ridge with abundant volcanic activity. ~70% of its electricity comes from hydropower; ~30% from geothermal. Nearly 90% of homes are heated with geothermal hot water piped directly from the earth.", tip: "🧠 Iceland: 90% of homes heated by geothermal energy piped from the ground." },
  { id: 'geo65', cat: 'geo', emoji: '⛰️', subject: 'Geography — Mountains', diff: 2, hook: "K2 is harder to climb than Everest — and has a much higher death rate.", fact: "Everest (8,849m) has been summited ~10,000 times. K2 (8,611m) has been summited fewer than 500 times. K2\'s death rate: ~25% of those who attempt the summit die. Everest: ~1%. K2 is called the Savage Mountain.", tip: "🧠 K2: 8,611m, 25% death rate. Far harder than Everest\'s 1%. Called the Savage Mountain." },
  { id: 'geo66', cat: 'geo', emoji: '🌍', subject: 'Geography — Africa', diff: 2, hook: "Africa contains more countries than any other continent — 54 in total.", fact: "Africa has 54 recognised sovereign states — more than any other continent. The most recent: South Sudan, which became independent in 2011. Africa also contains the world\'s largest country by area (Algeria) and has the fastest-growing population.", tip: "🧠 Africa: 54 countries — most of any continent. South Sudan newest (2011). Fastest-growing population." },
  { id: 'geo67', cat: 'geo', emoji: '🌊', subject: 'Geography — Lakes', diff: 1, hook: "The Caspian Sea is actually a lake — the world\'s largest by surface area.", fact: "The Caspian Sea (371,000 km²) is the world\'s largest landlocked body of water. It is technically a lake because it has no natural connection to any ocean. It is saltwater due to evaporation concentrating ancient sea salts.", tip: "🧠 Caspian Sea: world\'s largest lake. No ocean connection = technically a lake, despite the name." },
  { id: 'b56', cat: 'body', emoji: '🧠', subject: 'Body — Memory', diff: 2, hook: "Your brain is constantly rewriting your memories every time you recall them.", fact: "Memory reconsolidation: each time you recall a memory, it becomes temporarily unstable and is re-stored slightly altered. Memories are reconstructions, not recordings. Eyewitness testimony is unreliable partly because of this process.", tip: "🧠 Memories: rewritten every time you recall them. Not recordings — reconstructions. Eyewitnesses are unreliable." },
  { id: 'b57', cat: 'body', emoji: '💤', subject: 'Body — Sleep', diff: 1, hook: "Humans spend approximately one third of their life asleep.", fact: "If you live to 75, you will have slept for roughly 25 years. Sleep is not wasted time — it is when the brain consolidates memories, clears metabolic waste, repairs tissue, and resets emotional regulation.", tip: "🧠 25 years of your life: spent asleep. Brain uses it for memory, repair, and emotional reset." },
  { id: 'b58', cat: 'body', emoji: '🫀', subject: 'Body — Heart', diff: 1, hook: "The heart beats about 100,000 times per day — 35 million times per year.", fact: "At ~70 beats per minute, the heart beats 100,800 times per day, ~35 million per year, and ~2.5 billion in a lifetime. Each beat pumps ~70ml of blood. Total lifetime blood pumped: ~1.5 million litres.", tip: "🧠 Heart: 100,000 beats/day, 2.5 billion in a lifetime. Total blood pumped: ~1.5 million litres." },
  { id: 'b59', cat: 'body', emoji: '🦴', subject: 'Body — Bones', diff: 1, hook: "Half of your body\'s bones are in your hands and feet.", fact: "The human body has 206 bones. The hands contain 54 bones (27 per hand) and the feet contain 52 bones (26 per foot) — together 106 bones, more than half the total. This gives hands and feet extraordinary dexterity and range of motion.", tip: "🧠 206 bones total. Hands: 54, feet: 52 — together over half your skeleton." },
  { id: 'b60', cat: 'body', emoji: '🧬', subject: 'Body — DNA', diff: 2, hook: "If you uncoiled all the DNA in your body, it would stretch to the Sun and back 600 times.", fact: "Every cell nucleus contains ~2 metres of DNA. With ~37 trillion cells: ~74 billion km of DNA. The Sun is 150 million km away. Your DNA could go to the Sun and back roughly 246 times. (Some estimates reach 600 times counting both strands.)", tip: "🧠 Your total DNA: enough to reach the Sun and back hundreds of times." },
  { id: 'b61', cat: 'body', emoji: '👁️', subject: 'Body — Vision', diff: 2, hook: "Your eyes make tiny, involuntary movements called microsaccades even when staring still.", fact: "When you focus on a point, your eyes make tiny rapid movements (microsaccades) every few seconds. Without them, the visual system would adapt to the stable image and it would fade. Microsaccades refresh the signal and maintain clear vision.", tip: "🧠 Eyes make tiny involuntary movements constantly — without them, a fixed image would fade from view." },
  { id: 'b62', cat: 'body', emoji: '🫁', subject: 'Body — Hiccups', diff: 2, hook: "Hiccups serve no known purpose in adults — they may be an evolutionary leftover.", fact: "The hiccup reflex (sudden diaphragm contraction + glottis closure) has no known benefit in adult humans. One theory: it is a remnant reflex from aquatic ancestors who needed to clear water from gill slits. Tadpoles still use a similar reflex.", tip: "🧠 Hiccups: no known adult function. Possibly an evolutionary leftover from gill-breathing ancestors." },
  { id: 'b63', cat: 'body', emoji: '🧠', subject: 'Body — Gut', diff: 2, hook: "Your gut has its own nervous system — sometimes called the second brain.", fact: "The enteric nervous system (ENS) contains ~100 million neurons lining the gut — more than the spinal cord. It can function independently of the brain and communicates via the vagus nerve. Gut bacteria influence mood, anxiety, and even decision-making.", tip: "🧠 Gut: 100 million neurons — its own nervous system. Communicates with the brain and influences mood." },
  { id: 'b64', cat: 'body', emoji: '💊', subject: 'Body — Fever', diff: 1, hook: "A fever is not the illness — it is your immune system fighting back.", fact: "Fever (elevated body temperature) is an active immune response. Higher temperatures inhibit bacterial and viral replication, speed up immune cell activity, and trigger heat-shock protein production. Mild fevers (up to 38.5°C) help fight infection faster.", tip: "🧠 Fever = immune weapon, not the illness. Higher temp slows pathogens and speeds immune response." },
  { id: 'b65', cat: 'body', emoji: '🦷', subject: 'Body — Tongue', diff: 1, hook: "No two people have the same tongue print — it is as unique as a fingerprint.", fact: "The tongue has a unique surface geometry — size, shape, texture, and contours differ between individuals. Researchers have proposed tongue prints as a biometric identifier. Unlike fingerprints, the tongue is also protected inside the mouth and harder to forge.", tip: "🧠 Tongue prints: as unique as fingerprints. Harder to forge. Proposed as a biometric identifier." },
  { id: 'b66', cat: 'body', emoji: '🩸', subject: 'Body — Blood', diff: 2, hook: "Blood type O-negative is the universal donor — but only for red blood cells.", fact: "Type O- red blood cells lack the A, B, and Rh antigens that cause rejection reactions, making them safe for any recipient in emergencies. However, plasma (AB+) and platelets have different compatibility rules. O- whole blood is not universal for all components.", tip: "🧠 O-negative: universal red blood cell donor. Plasma and platelet compatibility = different rules." },
  { id: 'b67', cat: 'body', emoji: '🧠', subject: 'Body — Senses', diff: 2, hook: "Humans have far more than five senses — the actual count is closer to 20.", fact: "Beyond sight, hearing, smell, taste, and touch: proprioception (body position), thermoception (temperature), nociception (pain), vestibular sense (balance), interoception (internal organ state), magnetoception (disputed). The five-sense model is a 2,500-year-old oversimplification.", tip: "🧠 Humans have ~20 senses including proprioception, thermoception, balance, and pain. Five is too simple." },
  { id: 'g56', cat: 'grammar', emoji: '✍️', subject: 'Grammar — Apostrophes', diff: 1, hook: "The apostrophe is misused more than any other punctuation mark in English.", fact: "Two main uses: possession (the dog\'s bone) and contraction (don\'t = do not). Common errors: its vs it\'s (its = possessive, no apostrophe; it\'s = it is), and unnecessary apostrophes in plurals (tomato\'s instead of tomatoes).", tip: "🧠 Apostrophe: possession (dog\'s) or contraction (don\'t). Its = possessive. It\'s = it is. No exceptions." },
  { id: 'g57', cat: 'grammar', emoji: '📝', subject: 'Grammar — Sentence Types', diff: 2, hook: "There are four sentence types in English — most people only use two.", fact: "Declarative (statement), interrogative (question), imperative (command), exclamatory (exclamation). Most writing relies on declarative sentences. Varying sentence type creates rhythm and prevents monotony.", tip: "🧠 4 sentence types: declarative, interrogative, imperative, exclamatory. Most writing uses only declarative." },
  { id: 'g58', cat: 'grammar', emoji: '💬', subject: 'Grammar — Active vs Passive', diff: 1, hook: "Active voice is almost always clearer and more direct than passive voice.", fact: "Active: The dog bit the man. Passive: The man was bitten by the dog. Active = subject performs action. Passive = subject receives action. Active is shorter, clearer, and more energetic. Passive hides the actor — useful for politics, bad for clarity.", tip: "🧠 Active: dog bit man. Passive: man was bitten. Active = clearer, shorter, stronger. Always prefer it." },
  { id: 'g59', cat: 'grammar', emoji: '✒️', subject: 'Grammar — Conjunctions', diff: 2, hook: "Coordinating conjunctions can be remembered with FANBOYS.", fact: "FANBOYS: For, And, Nor, But, Or, Yet, So. These are the seven coordinating conjunctions that join clauses of equal weight. Subordinating conjunctions (because, although, when) join clauses of unequal weight.", tip: "🧠 FANBOYS: For And Nor But Or Yet So — the 7 coordinating conjunctions. Easy to memorise." },
  { id: 'g60', cat: 'grammar', emoji: '🔠', subject: 'Grammar — Modifiers', diff: 2, hook: "Dangling modifiers create unintentionally funny sentences.", fact: "A dangling modifier is a phrase that does not clearly modify the intended subject: \'Walking down the street, the trees were beautiful.\' (Trees don\'t walk.) Correct: \'Walking down the street, I found the trees beautiful.\' Always check what your modifying phrase attaches to.", tip: "🧠 Dangling modifier: \'Walking home, the rain started.\' Rain doesn\'t walk. Always attach modifiers clearly." },
  { id: 'g61', cat: 'grammar', emoji: '📖', subject: 'Grammar — Verbs', diff: 1, hook: "Verbs are the most important word in any sentence — you can build a sentence without a noun but not without a verb.", fact: "\'Run.\' \'Sleep.\' \'Think.\' are complete sentences — just a verb. A noun alone (\'Dog.\') is not a sentence. The verb carries the action or state that makes communication possible. Every sentence must have a verb.", tip: "🧠 Verbs are essential — you can have a sentence with just a verb. Nouns alone are not sentences." },
  { id: 'g62', cat: 'grammar', emoji: '✍️', subject: 'Grammar — Colons', diff: 2, hook: "A colon introduces — it always points forward, not backward.", fact: "The colon (:) says \'here comes the explanation, list, or example\': always introduces what follows. It must follow an independent clause. Wrong: \'I bought: milk, eggs, bread.\' Right: \'I bought three things: milk, eggs, bread.\'", tip: "🧠 Colon: must follow a complete clause. Points forward to a list, explanation, or example." },
  { id: 'g63', cat: 'grammar', emoji: '💬', subject: 'Grammar — Semicolons', diff: 2, hook: "The semicolon is stronger than a comma but weaker than a full stop.", fact: "The semicolon (;) joins two independent clauses that are closely related: \'I love coffee; I cannot function without it.\' It can also separate list items that contain commas: \'Paris, France; Rome, Italy; Berlin, Germany.\'", tip: "🧠 Semicolon: links related independent clauses. Also separates list items containing commas." },
  { id: 'g64', cat: 'grammar', emoji: '📝', subject: 'Grammar — Vocabulary', diff: 1, hook: "Using precise verbs eliminates the need for adverbs.", fact: "Weak: \'He walked quickly.\' Strong: \'He strode / hurried / rushed / darted.\' Precise verbs carry meaning that adverbs try to patch onto weaker verbs. George Orwell: \'Never use a long word where a short one will do.\' Specific verbs = stronger writing.", tip: "🧠 Replace adverbs with precise verbs. \'Walked quickly\' → \'strode\'. Specific verbs beat adverbs." },
  { id: 'g65', cat: 'grammar', emoji: '✒️', subject: 'Grammar — Register', diff: 1, hook: "Contractions signal informal register — use them intentionally.", fact: "Contractions (can\'t, won\'t, I\'m) are natural in speech and informal writing. Avoiding them entirely in formal writing can sound stiff. Using them in formal documents (legal, academic) undermines authority. Choose based on your audience and purpose.", tip: "🧠 Contractions: natural in informal writing. Avoid in legal/academic documents. Always intentional." },
  { id: 'g66', cat: 'grammar', emoji: '🔠', subject: 'Grammar — Misused Words', diff: 2, hook: "\'Literally\' is one of the most misused words in English.", fact: "\'Literally\' means: in the exact, actual sense — not figuratively. \'I literally died laughing\' is almost always incorrect. However, dictionaries now accept its use as an intensifier since misuse is so widespread. Pedants and linguists still disagree.", tip: "🧠 \'Literally\' = actually, not figuratively. So widespread in misuse that dictionaries now accept both." },
  { id: 'g67', cat: 'grammar', emoji: '📖', subject: 'Grammar — Paragraphs', diff: 2, hook: "Paragraph length signals pace — short paragraphs speed up, long paragraphs slow down.", fact: "Journalistic writing uses short paragraphs for pace and scanability. Academic writing uses longer ones for depth. Fiction varies paragraph length intentionally: a one-word paragraph creates maximum impact. Vary length to control how your reader experiences time.", tip: "🧠 Short paragraphs = fast pace. Long paragraphs = depth. One-word paragraphs = maximum impact." },
  { id: 'psy56', cat: 'psychology', emoji: '🧠', subject: 'Psychology — Memory', diff: 2, hook: "Working memory can hold only 4 plus or minus 1 items at a time.", fact: "George Miller\'s 1956 paper proposed the \'magic number 7 plus or minus 2\'. Updated research suggests the true limit is closer to 4 items (chunks) for most people. Chunking (grouping information) is how experts appear to have larger working memories.", tip: "🧠 Working memory limit: ~4 chunks. Chunking (grouping) lets experts appear to hold more." },
  { id: 'psy57', cat: 'psychology', emoji: '😊', subject: 'Psychology — Flow', diff: 2, hook: "Peak performance comes from a state called flow — total absorption in a challenge.", fact: "Mihaly Csikszentmihalyi\'s flow theory: optimal experience occurs when challenge level slightly exceeds skill level, producing total absorption, loss of self-consciousness, and distorted time perception. Both too easy (boredom) and too hard (anxiety) break flow.", tip: "🧠 Flow: challenge slightly exceeds skill. Total absorption, time distortion, peak performance." },
  { id: 'psy58', cat: 'psychology', emoji: '👥', subject: 'Psychology — Conformity', diff: 2, hook: "Most people conform to group opinion even when they know the group is wrong.", fact: "Solomon Asch\'s conformity experiments (1951): when confederates gave an obviously wrong answer to a visual task, 75% of participants agreed with the wrong answer at least once. Only 25% never conformed. We are social animals wired for agreement.", tip: "🧠 Asch conformity: 75% agreed with an obviously wrong group answer at least once. Only 25% never caved." },
  { id: 'psy59', cat: 'psychology', emoji: '🎯', subject: 'Psychology — Attribution', diff: 2, hook: "We judge ourselves by our intentions but judge others by their actions — the attribution error.", fact: "Fundamental Attribution Error: when others fail, we blame their character (lazy, careless). When we fail, we blame circumstances (bad day, unfair system). This asymmetry creates persistent misunderstanding between people.", tip: "🧠 Attribution error: others fail = their fault. We fail = circumstances. Universal and mostly unconscious." },
  { id: 'psy60', cat: 'psychology', emoji: '🌊', subject: 'Psychology — Anxiety', diff: 1, hook: "Anxiety and excitement are physiologically identical — only the label differs.", fact: "The physical symptoms of anxiety and excitement are the same: elevated heart rate, faster breathing, adrenaline. Research by Alison Wood Brooks shows reappraising anxiety as excitement (\'I am excited\') improves performance more than trying to calm down.", tip: "🧠 Anxiety and excitement: identical physiology. Reappraise \'I am anxious\' as \'I am excited\' — it works." },
  { id: 'psy61', cat: 'psychology', emoji: '🧠', subject: 'Psychology — Attention', diff: 2, hook: "The brain cannot truly multitask — it rapidly switches between tasks instead.", fact: "What feels like multitasking is rapid task-switching. Each switch has a cognitive cost — the \'switching cost\' reduces performance on both tasks. Studies show multitasking reduces productivity by ~40% and increases error rates significantly.", tip: "🧠 Multitasking is a myth — it is rapid task-switching. Reduces productivity by ~40%." },
  { id: 'psy62', cat: 'psychology', emoji: '💭', subject: 'Psychology — Priming', diff: 2, hook: "Exposure to one idea subtly influences subsequent thoughts and behaviour.", fact: "Priming: reading words related to old age makes people walk more slowly afterwards. Holding warm coffee increases perceived warmth of a stranger. These effects are mostly unconscious and surprisingly powerful. Context shapes perception constantly.", tip: "🧠 Priming: reading about old age slows your walk. Holding warm coffee makes strangers seem warmer." },
  { id: 'psy63', cat: 'psychology', emoji: '😊', subject: 'Psychology — Optimism', diff: 2, hook: "Optimism bias makes humans systematically underestimate risks to themselves.", fact: "Optimism bias: ~80% of people believe they are less likely than average to experience negative events (divorce, cancer, accident). This is statistically impossible but universal. It promotes risk-taking and resilience but leads to poor planning for actual risks.", tip: "🧠 Optimism bias: 80% believe they are below average risk. Statistically impossible. Universal human trait." },
  { id: 'psy64', cat: 'psychology', emoji: '👀', subject: 'Psychology — First Impressions', diff: 1, hook: "First impressions are formed in as little as 100 milliseconds — and are hard to change.", fact: "Research by Janine Willis and Alexander Todorov: people make judgements about trustworthiness, competence, and likability in 100ms from a face photo. These snap judgements are relatively stable even when contradicted by later information.", tip: "🧠 First impressions: formed in 100ms. Hard to override even with contradicting evidence." },
  { id: 'psy65', cat: 'psychology', emoji: '🧠', subject: 'Psychology — Cognitive Dissonance', diff: 2, hook: "Holding two contradictory beliefs simultaneously causes psychological discomfort — and we work hard to resolve it.", fact: "Cognitive dissonance (Festinger, 1957): when beliefs conflict with behaviour or other beliefs, we feel psychological tension and actively work to reduce it — usually by changing the belief rather than the behaviour. Smokers who know smoking is harmful are a classic example.", tip: "🧠 Cognitive dissonance: belief conflicts create tension. We usually change the belief, not the behaviour." },
  { id: 'psy66', cat: 'psychology', emoji: '🎭', subject: 'Psychology — Empathy', diff: 2, hook: "There are two types of empathy — and having too much of one type can be harmful.", fact: "Cognitive empathy: understanding others\' perspective intellectually. Affective empathy: feeling others\' emotions yourself. Too much affective empathy leads to empathy fatigue and burnout — common in caregivers. Effective helpers often use cognitive empathy to stay functional.", tip: "🧠 Cognitive empathy: understand others\' feelings. Affective empathy: feel them yourself. Too much affective = burnout." },
  { id: 'psy67', cat: 'psychology', emoji: '💭', subject: 'Psychology — Mindset', diff: 1, hook: "People with a growth mindset treat failure as information — not identity.", fact: "Carol Dweck\'s research: fixed mindset people believe intelligence and talent are fixed traits. Growth mindset people believe abilities develop through effort. Growth mindset predicts greater resilience, achievement, and willingness to take on challenges.", tip: "🧠 Growth mindset: failure = information. Fixed mindset: failure = identity. Growth mindset wins long-term." },
  { id: 'eco56', cat: 'economics', emoji: '💰', subject: 'Economics — Taxes', diff: 1, hook: "Tax avoidance is legal — tax evasion is illegal. The difference is significant.", fact: "Tax avoidance: legally arranging affairs to minimise tax (using ISAs, pension contributions, business deductions). Tax evasion: illegally hiding income or lying about assets. The line between them is debated — aggressive avoidance schemes are technically legal but may be unethical.", tip: "🧠 Tax avoidance = legal (ISAs, pensions). Tax evasion = illegal (hiding income). Important distinction." },
  { id: 'eco57', cat: 'economics', emoji: '📈', subject: 'Economics — Indices', diff: 2, hook: "The Dow Jones Industrial Average only tracks 30 companies — and is price-weighted, not value-weighted.", fact: "The DJIA uses just 30 large US companies and weights them by share price, not market cap. This means a company with a high share price influences the index more than a larger company with a lower share price. The S&P 500 (500 companies, market-cap weighted) is a much better indicator.", tip: "🧠 Dow Jones: only 30 companies, price-weighted = poor market indicator. S&P 500 is better." },
  { id: 'eco58', cat: 'economics', emoji: '🌐', subject: 'Economics — Globalisation', diff: 2, hook: "The rise of container shipping in the 1950s-60s did more for globalisation than any trade deal.", fact: "Malcom McLean\'s standardised shipping container (1956) reduced cargo handling costs by ~96%. It made global trade so cheap that manufacturing moved to wherever labour was cheapest. No policy decision shaped modern globalisation more than a metal box.", tip: "🧠 Shipping container (1956): cut cargo costs 96%. Created modern globalisation more than any trade deal." },
  { id: 'eco59', cat: 'economics', emoji: '💸', subject: 'Economics — Savings', diff: 1, hook: "Compound interest is the most powerful force in personal finance — over long timeframes.", fact: "Einstein allegedly called compound interest the eighth wonder of the world (disputed attribution). £1,000 at 7% annual return: after 10 years = £1,967. After 30 years = £7,612. After 50 years = £29,457. Time is the key variable, not the rate.", tip: "🧠 Compound interest: £1,000 at 7% = £29,457 after 50 years. Time beats everything else." },
  { id: 'eco60', cat: 'economics', emoji: '📊', subject: 'Economics — Unemployment', diff: 2, hook: "There are multiple types of unemployment — economists distinguish at least four.", fact: "Frictional (between jobs), structural (skills mismatch), cyclical (recession-driven), seasonal (weather/demand cycles). A 4-5% unemployment rate in a healthy economy is mostly frictional — people between jobs voluntarily. Zero unemployment is not a realistic or desirable target.", tip: "🧠 4 types of unemployment: frictional, structural, cyclical, seasonal. ~4% unemployment can be healthy." },
  { id: 'eco61', cat: 'economics', emoji: '💰', subject: 'Economics — Rent-Seeking', diff: 2, hook: "Rent-seeking is when companies gain wealth by manipulating the economic environment rather than creating value.", fact: "Rent-seeking: lobbying for regulations that benefit incumbents, securing patents beyond their useful life, monopolising licences. It transfers wealth without creating it. In contrast, profit from genuine innovation is not rent-seeking. Economists consider rent-seeking economically damaging.", tip: "🧠 Rent-seeking: gaining wealth by manipulating rules, not creating value. Lobbying for unfair regulations." },
  { id: 'eco62', cat: 'economics', emoji: '🏭', subject: 'Economics — Supply Chains', diff: 2, hook: "The 2021 global chip shortage showed how fragile just-in-time supply chains are.", fact: "Just-in-time (JIT) manufacturing holds minimal inventory to cut costs. When COVID disrupted semiconductor production, automakers who had cut chip stockpiles to near zero faced production shutdowns. The efficiency of JIT comes with fragility to disruption.", tip: "🧠 Just-in-time supply chains: maximally efficient, maximally fragile. COVID chip shortage proved it." },
  { id: 'eco63', cat: 'economics', emoji: '🌐', subject: 'Economics — Exchange Rates', diff: 2, hook: "The Big Mac Index measures whether currencies are over or under-valued.", fact: "The Economist\'s Big Mac Index (1986): a Big Mac costs similar amounts to produce everywhere. If a Big Mac costs $5 in the US and £4 in the UK, the implied exchange rate is 0.8. If the actual rate is 1.25, sterling is undervalued by the index.", tip: "🧠 Big Mac Index: compares a globally consistent product to estimate currency over/under-valuation." },
  { id: 'eco64', cat: 'economics', emoji: '💸', subject: 'Economics — Inequality', diff: 1, hook: "The richest 1% own more wealth than the bottom 50% combined — globally.", fact: "Global wealth distribution (Credit Suisse, 2022): the wealthiest 1% own ~46% of global wealth. The bottom 50% own less than 1%. The top 10% own ~76%. This concentration has increased since the 1980s in most developed economies.", tip: "🧠 Richest 1%: own 46% of global wealth. Bottom 50%: own less than 1%. Gap has grown since 1980s." },
  { id: 'eco65', cat: 'economics', emoji: '📈', subject: 'Economics — Interest Rates', diff: 2, hook: "Central banks raise interest rates to slow inflation — but it takes 12-18 months to work.", fact: "Monetary policy operates with a \'long and variable lag\' (Milton Friedman). When a central bank raises rates, it takes 12-18 months to feed through to borrowing, spending, and inflation. This means central banks must act on forecasts, not current data.", tip: "🧠 Rate rises: take 12-18 months to slow inflation. Central banks must act on future forecasts." },
  { id: 'eco66', cat: 'economics', emoji: '💰', subject: 'Economics — Incentives', diff: 1, hook: "Incentives drive nearly all economic behaviour — including unintended consequences.", fact: "The \'Cobra Effect\': British colonial India offered bounties for dead cobras to reduce snake populations. Indians bred cobras to claim bounties. When the scheme ended, the bred cobras were released — increasing the cobra population. Incentives always have unintended effects.", tip: "🧠 Cobra Effect: bounty for cobras → Indians bred cobras. Incentives always have unintended consequences." },
  { id: 'eco67', cat: 'economics', emoji: '🌐', subject: 'Economics — Poverty', diff: 2, hook: "Cash transfers to the poor are often more effective than in-kind aid.", fact: "Evidence from multiple countries shows unconditional cash transfers (giving poor people money directly) produce better outcomes than food aid, vouchers, or goods. People spend cash on what they actually need. The \'GiveDirectly\' programme in Kenya has shown strong results.", tip: "🧠 Cash transfers to poor: more effective than food aid. People spend money on what they actually need." },
  { id: 'inv56', cat: 'inventions', emoji: '🔌', subject: 'Inventions — Electricity Grid', diff: 2, hook: "The War of Currents between Edison and Tesla determined how electricity reaches your home.", fact: "In the 1880s, Thomas Edison promoted DC (direct current) while Nikola Tesla and George Westinghouse pushed AC (alternating current). AC won because it transmits over long distances with lower losses. Edison even electrocuted animals publicly to demonstrate AC\'s \'dangers\'.", tip: "🧠 War of Currents: Edison (DC) vs Tesla/Westinghouse (AC). AC won — better for long-distance transmission." },
  { id: 'inv57', cat: 'inventions', emoji: '💊', subject: 'Inventions — Penicillin', diff: 1, hook: "Penicillin was discovered because Alexander Fleming went on holiday.", fact: "Fleming left a petri dish of Staphylococcus bacteria uncovered before his 1928 holiday. On returning, he noticed a mould (Penicillium notatum) had killed the surrounding bacteria. He identified the antibiotic effect but did not develop it into medicine — that took Howard Florey and Ernst Chain.", tip: "🧠 Penicillin: discovered 1928 by accident (contaminated petri dish). Fleming noticed; Florey and Chain made it medicine." },
  { id: 'inv58', cat: 'inventions', emoji: '🖥️', subject: 'Inventions — Mouse', diff: 2, hook: "The computer mouse was invented in 1964 — but ignored for 20 years.", fact: "Douglas Engelbart demonstrated the first computer mouse at Stanford Research Institute in 1964. He also demonstrated hypertext, video conferencing, and real-time collaboration. It was called the \'Mother of All Demos\'. Mice became mainstream only with the Apple Macintosh in 1984.", tip: "🧠 Computer mouse: invented 1964 by Engelbart. Ignored until Apple Macintosh (1984) popularised it." },
  { id: 'inv59', cat: 'inventions', emoji: '🚀', subject: 'Inventions — Rocketry', diff: 2, hook: "The father of modern rocketry was ridiculed by the New York Times — and vindicated a day after his death.", fact: "Robert Goddard launched the first liquid-fuelled rocket in 1926. The New York Times wrote in 1920 that rockets could not work in a vacuum (factually wrong). On 17 July 1969 — the day after Apollo 11 launch — the Times printed a correction. Goddard died in 1945.", tip: "🧠 Goddard: New York Times mocked his rockets as impossible. NYT printed a correction the day after Apollo 11 launched." },
  { id: 'inv60', cat: 'inventions', emoji: '💡', subject: 'Inventions — Lightbulb', diff: 2, hook: "Edison did not invent the lightbulb — he perfected a commercially viable version.", fact: "At least 22 inventors worked on incandescent bulbs before Edison. Joseph Swan (UK) demonstrated a working bulb months before Edison\'s 1879 version. Edison\'s contribution was making it practical: long-lasting, cheap, and part of a complete electrical distribution system.", tip: "🧠 Edison: did not invent the lightbulb. Made it practical and commercially viable. Swan did it first." },
  { id: 'inv61', cat: 'inventions', emoji: '🌐', subject: 'Inventions — Internet', diff: 2, hook: "The internet was not invented by one person — it emerged from decades of collaborative research.", fact: "ARPANET (1969, US military) was the first packet-switching network. TCP/IP protocol (Vint Cerf and Bob Kahn, 1974) made networks interoperable. Tim Berners-Lee invented the World Wide Web (1989). The \'internet\' is the combination of many inventions by many people.", tip: "🧠 Internet: ARPANET (1969) + TCP/IP (1974) + World Wide Web (1989). Dozens of inventors, decades of work." },
  { id: 'inv62', cat: 'inventions', emoji: '⚙️', subject: 'Inventions — Glasses', diff: 2, hook: "Eyeglasses were invented in 13th century Italy — and were kept secret to protect trade advantages.", fact: "The first wearable eyeglasses appeared in Pisa around 1286. Venetian glass craftsmen kept the technology secret to maintain their commercial edge. Spectacles were initially a luxury for scholars and monks. Bifocals were invented by Benjamin Franklin ~1784.", tip: "🧠 Eyeglasses: invented Pisa ~1286. Venetian craftsmen kept the technology secret. Bifocals: Franklin ~1784." },
  { id: 'inv63', cat: 'inventions', emoji: '🧬', subject: 'Inventions — DNA Double Helix', diff: 2, hook: "The structure of DNA was discovered using data taken without the scientist\'s permission.", fact: "James Watson and Francis Crick determined the double helix structure of DNA in 1953 using X-ray crystallography data from Rosalind Franklin — without her knowledge or consent. Franklin received no Nobel Prize (she died in 1958; Nobels are not awarded posthumously).", tip: "🧠 DNA double helix: Watson and Crick used Rosalind Franklin\'s data without her knowledge. She got no Nobel." },
  { id: 'inv64', cat: 'inventions', emoji: '🚗', subject: 'Inventions — Automobile', diff: 2, hook: "The first car was invented in 1885 — and had a maximum speed of 16 km/h.", fact: "Karl Benz patented the Motorwagen in January 1886 — widely considered the first true automobile. It had three wheels, a single-cylinder engine, and a top speed of ~16 km/h. His wife Bertha made the first long-distance road trip (106 km) in 1888 to prove its practicality.", tip: "🧠 First car: Benz Motorwagen 1886. Top speed: 16 km/h. His wife Bertha proved it worked with a 106km road trip." },
  { id: 'inv65', cat: 'inventions', emoji: '🔬', subject: 'Inventions — Microscope', diff: 1, hook: "The microscope revealed that disease is caused by invisible living organisms.", fact: "Antonie van Leeuwenhoek (1670s) built microscopes powerful enough to see bacteria for the first time — he called them \'animalcules\'. This preceded germ theory by 200 years. Louis Pasteur and Robert Koch later connected specific microorganisms to specific diseases in the 1860s-1880s.", tip: "🧠 Leeuwenhoek (1670s): first to see bacteria (\'animalcules\'). Germ theory followed 200 years later." },
  { id: 'inv66', cat: 'inventions', emoji: '💡', subject: 'Inventions — Radio', diff: 2, hook: "Marconi received the Nobel Prize for radio — but Tesla had patents before him.", fact: "Guglielmo Marconi received the 1909 Nobel Prize in Physics for radio. But Nikola Tesla filed radio patents in 1897. In 1943 (after Tesla\'s death) the US Supreme Court ruled Tesla\'s patents had priority. The credit dispute was resolved legally — Marconi still got the Nobel.", tip: "🧠 Radio: Marconi got the Nobel in 1909. US Supreme Court gave priority to Tesla\'s earlier patents in 1943." },
  { id: 'inv67', cat: 'inventions', emoji: '⚙️', subject: 'Inventions — Bicycle', diff: 2, hook: "The bicycle created a mobility revolution — and helped liberate women in the 1890s.", fact: "Early bicycles (penny-farthings) were impractical. The modern safety bicycle (1885, John Kemp Starley) with two equal wheels and chain drive was transformative. Women could travel independently for the first time without a horse or chaperone. Susan B. Anthony called it \'the freedom machine\'.", tip: "🧠 Safety bicycle (1885): Susan B. Anthony called it \'the freedom machine\'. First independent mobility for women." },
  { id: 'food56', cat: 'food', emoji: '🫚', subject: 'Food Science — Fats', diff: 2, hook: "Not all fats are equal — and saturated fat\'s reputation may have been unfairly tarnished.", fact: "A 2010 meta-analysis found no significant evidence that saturated fat causes heart disease when replacing it with refined carbs. The key villain may be trans fats (industrially produced). Current guidance: replace saturated fat with unsaturated fats (olive oil, nuts, avocado).", tip: "🧠 Saturated fat: vilified since 1960s but evidence is mixed. Trans fats: clearly harmful. Unsaturated: beneficial." },
  { id: 'food57', cat: 'food', emoji: '☕', subject: 'Food Science — Coffee', diff: 1, hook: "Coffee is the world\'s most traded agricultural commodity after crude oil.", fact: "Global coffee trade value: ~$30 billion annually. Over 2 billion cups drunk per day. 70% of the world drinks coffee; 30% drink tea as primary hot drink. Brazil is the world\'s largest producer (~40% of global output).", tip: "🧠 Coffee: ~2 billion cups/day. $30B traded annually. Brazil produces 40% of the world\'s supply." },
  { id: 'food58', cat: 'food', emoji: '🍷', subject: 'Food Science — Wine', diff: 2, hook: "Wine \'breathing\' (letting it aerate) changes the taste measurably.", fact: "Exposing wine to air allows volatile compounds to evaporate, ethanol to dissipate slightly, and tannins to soften. Young red wines with high tannins benefit most. Old wines can deteriorate quickly after opening. Swirling achieves more in minutes than breathing for hours.", tip: "🧠 Wine breathing: evaporates volatiles, softens tannins. Swirling works faster than leaving it open." },
  { id: 'food59', cat: 'food', emoji: '🥗', subject: 'Food Science — Salad Dressing', diff: 2, hook: "Fat is required to absorb most vitamins in salad — fat-free dressing wastes the nutrients.", fact: "Vitamins A, D, E, and K are fat-soluble — they require dietary fat for absorption. Eating salad with fat-free dressing means most of these vitamins pass through unabsorbed. A small amount of olive oil or avocado dramatically increases nutrient absorption.", tip: "🧠 Fat-soluble vitamins (A, D, E, K): need fat to absorb. Fat-free salad dressing wastes most of the nutrition." },
  { id: 'food60', cat: 'food', emoji: '🧄', subject: 'Food Science — Garlic', diff: 2, hook: "Garlic\'s health benefits are destroyed by cooking — unless you crush and wait.", fact: "Crushing or chopping garlic activates alliinase enzyme, producing allicin (the beneficial compound). Heat deactivates alliinase before allicin forms if you cook immediately. Crushing garlic and waiting 10 minutes before cooking preserves most of the allicin.", tip: "🧠 Garlic hack: crush, wait 10 minutes, then cook. Preserves allicin. Immediate cooking destroys the enzyme." },
  { id: 'food61', cat: 'food', emoji: '🍞', subject: 'Food Science — Sourdough', diff: 2, hook: "Sourdough bread is genuinely easier to digest than regular bread — for most people.", fact: "Sourdough fermentation (24-48 hours) breaks down fodmaps, reduces phytic acid (which blocks mineral absorption), and partially digests gluten. The lactic acid produced also lowers the glycaemic index. Even some mild gluten-sensitive people tolerate true sourdough.", tip: "🧠 Sourdough: fermentation breaks down FODMAPs, reduces gluten, lowers GI. More digestible than regular bread." },
  { id: 'food62', cat: 'food', emoji: '🫐', subject: 'Food Science — Frozen Food', diff: 1, hook: "Frozen vegetables are often more nutritious than fresh ones.", fact: "Fresh vegetables lose nutrients rapidly after picking — up to 50% of some vitamins within days. Frozen vegetables are typically processed within hours of harvest, preserving nutrients. \'Fresh\' vegetables in supermarkets may be weeks old by the time you eat them.", tip: "🧠 Frozen veg: often more nutritious than fresh. Frozen within hours of harvest. \'Fresh\' can be weeks old." },
  { id: 'food63', cat: 'food', emoji: '🌾', subject: 'Food Science — Whole Grains', diff: 2, hook: "Whole grains contain three times more nutrients than refined grains — in the parts that get removed.", fact: "Refining grain removes the bran and germ, leaving only the starchy endosperm. The bran contains fibre and B vitamins; the germ contains healthy fats, vitamin E, and minerals. Refined flour loses 25+ nutrients. Only a few (iron, B1, B2, B3, folate) are added back.", tip: "🧠 Refining grain removes bran and germ — losing 25+ nutrients. Only ~5 are added back." },
  { id: 'food64', cat: 'food', emoji: '🥩', subject: 'Food Science — Temperature', diff: 1, hook: "Food safety is about reaching a safe internal temperature — not colour.", fact: "A burger can look brown inside and still harbour live bacteria. The only reliable indicator is internal temperature: 71°C for minced beef, 74°C for poultry. Colour is affected by myoglobin chemistry and is not a safety indicator.", tip: "🧠 Food safety = internal temperature, not colour. Minced beef safe at 71°C. Colour can mislead." },
  { id: 'food65', cat: 'food', emoji: '🍫', subject: 'Food Science — Theobromine', diff: 2, hook: "Chocolate is toxic to dogs because they cannot metabolise theobromine.", fact: "Theobromine in chocolate is metabolised slowly by dogs — it builds up to toxic levels. Dark chocolate is most dangerous (highest theobromine). In humans, theobromine is a mild stimulant and bronchodilator. The lethal dose for humans would require eating ~40kg of milk chocolate.", tip: "🧠 Chocolate + dogs = toxic. Theobromine builds up fatally in dogs. Humans metabolise it fine." },
  { id: 'food66', cat: 'food', emoji: '🫒', subject: 'Food Science — Olive Oil Fraud', diff: 2, hook: "Up to 70% of extra virgin olive oil sold internationally may not meet the legal standard.", fact: "The UC Davis Olive Center (2011) tested imported olive oils and found ~69% failed to meet international extra virgin standards — being adulterated with cheaper oils or being lower-grade olive oil. Italy exports more EVOO than it produces, indicating widespread blending.", tip: "🧠 EVOO fraud: up to 70% of \'extra virgin\' imports may fail the standard. Italy exports more than it grows." },
  { id: 'food67', cat: 'food', emoji: '🍕', subject: 'Food Science — Acids', diff: 2, hook: "The acidity of tomatoes is why pizza and pasta sauce tastes different cooked in aluminium vs stainless steel.", fact: "Tomato sauce cooked in aluminium reacts with the acid, leaching aluminium and producing a metallic off-flavour. Stainless steel, glass, and enamelled pans are non-reactive. The same issue applies to acidic foods like lemon juice, vinegar, and wine.", tip: "🧠 Acidic foods (tomatoes, wine, vinegar) react with aluminium. Use stainless steel or enamel pans." },
  { id: 'm56', cat: 'math', emoji: '🔢', subject: 'Maths — Estimation', diff: 1, hook: "Fermi estimation lets you make surprisingly accurate guesses with almost no information.", fact: "Enrico Fermi could estimate the number of piano tuners in Chicago from almost nothing (population, pianos per household, tuning frequency, time per tuning). This order-of-magnitude thinking is used in physics, engineering, and business — any situation requiring fast reasonable estimates.", tip: "🧠 Fermi estimation: piano tuners in Chicago from population alone. Order-of-magnitude thinking." },
  { id: 'm57', cat: 'math', emoji: '📐', subject: 'Maths — Angles', diff: 1, hook: "A full circle is 360 degrees — because of ancient Babylonian astronomy.", fact: "The Babylonians used a base-60 number system and a 360-day year (approximate). Dividing the circle into 360 degrees matched their calendar and made fractions easy (360 divides evenly by 2, 3, 4, 5, 6, 8, 9, 10, 12). Radians (2π = 360°) are mathematically more natural.", tip: "🧠 360° circle: Babylonian base-60 system and 360-day calendar. Radians (2π) are more natural." },
  { id: 'm58', cat: 'math', emoji: '🎲', subject: 'Maths — Birthday Problem', diff: 2, hook: "In a group of just 23 people, there is a 50% chance two share a birthday.", fact: "The birthday problem: most people guess you need ~180 people for a 50% chance. The actual answer is 23. With 70 people the probability reaches 99.9%. This counterintuitive result occurs because there are 253 possible pairs in a group of 23.", tip: "🧠 Birthday paradox: 23 people = 50% chance of shared birthday. 70 people = 99.9%." },
  { id: 'm59', cat: 'math', emoji: '♾️', subject: 'Maths — Limits', diff: 2, hook: "Calculus was invented simultaneously by Newton and Leibniz — causing the biggest priority dispute in maths history.", fact: "Isaac Newton developed calculus in 1666 (unpublished). Gottfried Wilhelm Leibniz developed it independently in 1675-1676 (published 1684). Most modern notation comes from Leibniz. The priority dispute divided European and British mathematics for a century.", tip: "🧠 Calculus: Newton (1666, unpublished) and Leibniz (1675, published). Biggest priority dispute in maths history." },
  { id: 'm60', cat: 'math', emoji: '🔢', subject: 'Maths — Logarithms', diff: 2, hook: "Logarithms were invented to turn multiplication into addition — in 1614.", fact: "John Napier invented logarithms in 1614 specifically to simplify astronomical calculations. log(ab) = log(a) + log(b). Before calculators, scientists used log tables and slide rules that implemented this principle. Logarithms reduced weeks of calculation to hours.", tip: "🧠 Logarithms (1614): turned multiplication into addition. log(ab) = log(a) + log(b). Reduced weeks to hours." },
  { id: 'm61', cat: 'math', emoji: '📐', subject: 'Maths — Pythagoras', diff: 1, hook: "The Pythagorean theorem was known 1,000 years before Pythagoras.", fact: "Babylonian clay tablets from ~1900 BC list Pythagorean triples (3,4,5; 5,12,13). The Egyptians used 3-4-5 triangles to make right angles in construction. Pythagoras (~570 BC) is credited with the general proof, not the discovery.", tip: "🧠 Pythagorean theorem: known by Babylonians ~1900 BC. Pythagoras proved it generally — 1,000 years later." },
  { id: 'm62', cat: 'math', emoji: '🎯', subject: 'Maths — Ratios', diff: 2, hook: "The Golden Ratio (phi ≈ 1.618) appears in art, architecture, and nature — but is overhyped.", fact: "The Golden Ratio (φ = 1.618...) does appear in Fibonacci spirals and some plant growth patterns. But many claims about the Parthenon, Mona Lisa, and human body ratios are retrospective pattern-matching. The ratio is mathematically interesting; its aesthetic universality is disputed.", tip: "🧠 Golden ratio: real in Fibonacci/plants. Parthenon and Mona Lisa claims: mostly retrospective myth." },
  { id: 'm63', cat: 'math', emoji: '🌀', subject: 'Maths — Topology', diff: 2, hook: "A coffee cup and a doughnut are the same shape — topologically speaking.", fact: "Topology studies properties preserved under continuous deformation. A coffee cup and doughnut both have exactly one hole — you can continuously deform one into the other without cutting or gluing. A sphere and a cube are also topologically identical.", tip: "🧠 Topology: coffee cup = doughnut (both have one hole). Sphere = cube. Holes define shape." },
  { id: 'm64', cat: 'math', emoji: '🔢', subject: 'Maths — Powers', diff: 1, hook: "Doubling something 63 times produces a number larger than the human brain can intuit.", fact: "The legend of the chess inventor asking for wheat: 1 grain on square 1, doubled each square. By square 64: 2^63 = 9.2 quintillion grains — more wheat than has ever been grown in human history. This is why compound growth is so powerful and so unintuitive.", tip: "🧠 Chess wheat problem: 2^63 grains = more wheat than all of human history has ever produced." },
  { id: 'm65', cat: 'math', emoji: '📊', subject: 'Maths — Sampling', diff: 2, hook: "You only need to survey about 1,000 people to accurately represent 300 million — if done correctly.", fact: "Statistical sampling: a well-designed random sample of ~1,000-2,000 people can represent a population of millions with a margin of error of ~3%. Sample size requirements grow with the square root of population, not proportionally. Sample quality matters far more than size.", tip: "🧠 1,000-person sample can represent 300M people with ~3% error — if randomly selected. Quality over quantity." },
  { id: 'm66', cat: 'math', emoji: '♾️', subject: 'Maths — Godel', diff: 3, hook: "Godel proved that any mathematical system powerful enough to include arithmetic must be incomplete.", fact: "Godel\'s Incompleteness Theorems (1931): in any consistent formal system that includes basic arithmetic, there are true statements that cannot be proved within that system. Mathematics cannot fully describe itself. This shook the foundations of mathematics.", tip: "🧠 Godel 1931: any system including arithmetic has true but unprovable statements. Maths is permanently incomplete." },
  { id: 'm67', cat: 'math', emoji: '🔢', subject: 'Maths — Patterns', diff: 2, hook: "The Monty Hall problem is one of the most counterintuitive results in probability.", fact: "You pick 1 of 3 doors. Host opens a losing door. Switch or stay? Switching wins 2/3 of the time; staying wins 1/3. Most people feel switching and staying should be 50/50. Even mathematicians initially got this wrong. The key: the host\'s knowledge changes the probabilities.", tip: "🧠 Monty Hall: always switch. Switching wins 2/3, staying wins 1/3. Even mathematicians got it wrong initially." },

  { id: 'h91', cat: 'history', emoji: '🌍', subject: 'History — Modern', diff: 1, hook: "The Berlin Wall stood for only 28 years — but its fall changed the world overnight.", fact: "The Berlin Wall was built on 13 August 1961 dividing East and West Berlin. It fell on 9 November 1989 when East Germany opened border crossings. By 1990, Germany was reunified. The fall symbolised the collapse of Soviet communism.", tip: "🧠 Berlin Wall: built 1961, fell 9 November 1989. Germany reunified within a year." },
  { id: 'geo68', cat: 'geo', emoji: '🌊', subject: 'Geography — Straits', diff: 1, hook: "The Strait of Gibraltar is only 14 km wide at its narrowest point.", fact: "The Strait of Gibraltar separates Europe (Spain) from Africa (Morocco) and connects the Atlantic Ocean to the Mediterranean Sea. At its narrowest it is just 14 km — you can see Morocco from Spain on a clear day.", tip: "🧠 Gibraltar Strait: 14 km wide. You can see Africa from Europe on a clear day." },
  { id: 'b68', cat: 'body', emoji: '💊', subject: 'Body — Vitamins', diff: 1, hook: "Vitamin D is technically a hormone, not a vitamin — and most people are deficient.", fact: "Vitamins are nutrients obtained from food. But Vitamin D is synthesised by the body from sunlight — making it a hormone by definition. An estimated 40-50% of people worldwide are deficient, linked to weakened immunity, fatigue, and bone density loss.", tip: "🧠 Vitamin D = hormone, not vitamin. Synthesised from sunlight. ~40-50% of people are deficient." },
  { id: 'g68', cat: 'grammar', emoji: '📖', subject: 'Grammar — Clichés', diff: 1, hook: "Clichés became clichés because they were once fresh and effective — then were overused.", fact: "Every cliché was originally a vivid, original expression: \'cold shoulder\', \'at the end of the day\', \'thinking outside the box\'. Overuse drains them of meaning. Good writers avoid them — or use them deliberately, with irony, for effect.", tip: "🧠 Clichés: once vivid, now empty from overuse. Avoid or use deliberately with irony." },
  { id: 'psy68', cat: 'psychology', emoji: '🎭', subject: 'Psychology — Role Effects', diff: 2, hook: "People behave differently when they adopt a role — even an arbitrary one.", fact: "Zimbardo\'s Stanford Prison Experiment (1971): participants randomly assigned as \'guards\' or \'prisoners\' rapidly internalised their roles — guards became authoritarian, prisoners passive. The experiment was stopped after 6 days. Role assignment profoundly shapes identity and behaviour.", tip: "🧠 Stanford Prison Experiment: roles assigned randomly. Guards became cruel, prisoners passive — within days." },
  { id: 'eco68', cat: 'economics', emoji: '💸', subject: 'Economics — Velocity of Money', diff: 2, hook: "The same dollar can generate more or less economic activity depending on how fast it moves.", fact: "The velocity of money: if one dollar is spent, received, and spent again 10 times in a year, it generates $10 of economic activity. During recessions, velocity falls — people save instead of spend. Velocity matters as much as money supply for economic output.", tip: "🧠 Velocity of money: $1 spent 10 times = $10 of economic activity. Falls in recessions when saving increases." },
  { id: 'inv68', cat: 'inventions', emoji: '🔌', subject: 'Inventions — Microwave', diff: 2, hook: "The microwave oven was invented when a scientist noticed his chocolate bar had melted.", fact: "Percy Spencer was testing radar magnetron tubes at Raytheon in 1945 when he noticed a chocolate bar in his pocket had melted. He tested popcorn and eggs (the egg exploded). The first commercial microwave oven (1947) was 1.8 metres tall and cost $5,000.", tip: "🧠 Microwave: discovered 1945 by accident (melted chocolate bar). First oven: 1.8m tall, $5,000." },
  { id: 'food68', cat: 'food', emoji: '🍕', subject: 'Food Science — Salt', diff: 1, hook: "Salt does not actually make water boil faster — but it does make food taste better.", fact: "Adding salt to boiling water raises the boiling point by a tiny, negligible amount (1°C per 58g of salt per litre). Its real purpose is seasoning — salted pasta water seasons the pasta from the inside as it cooks.", tip: "🧠 Salting pasta water: does not speed boiling. Does season the pasta from the inside." },
  { id: 'm68', cat: 'math', emoji: '📐', subject: 'Maths — Measurement', diff: 2, hook: "The metre was originally defined as one ten-millionth of the distance from the equator to the North Pole.", fact: "In 1793, France defined the metre as 1/10,000,000 of the Earth\'s meridian from equator to pole. It took years of survey work. Today the metre is defined by the speed of light: the distance light travels in 1/299,792,458 of a second.", tip: "🧠 Metre: originally 1/10,000,000 of Earth pole-to-equator. Now defined by the speed of light." },
  { id: 's61', cat: 'science', emoji: '🌍', subject: 'Science — Plate Tectonics', diff: 2, hook: "The theory of continental drift was laughed at for 50 years before being proven correct.", fact: "Alfred Wegener proposed in 1912 that continents had once been joined and drifted apart. Geologists ridiculed him for decades. By the 1960s, seafloor spreading evidence proved him right. The continents move at 2-5 cm per year — the speed your fingernails grow.", tip: "🧠 Continental drift: Wegener ridiculed in 1912, proven right by 1960s. Continents move at fingernail speed." },
  { id: 'psy69', cat: 'psychology', emoji: '💭', subject: 'Psychology — Defaults', diff: 2, hook: "Default options are extraordinarily powerful — most people never change them.", fact: "Research shows that whatever option is set as default gets chosen by the overwhelming majority. Opt-in organ donation: ~15% donation rates. Opt-out organ donation: ~90%+ rates. Same policy, opposite default, vastly different outcomes.", tip: "🧠 Opt-in vs opt-out organ donation: 15% vs 90%+ rates. Same policy. Default choice decides everything." },
];

